export function ConnectionsView() {
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [showDiagnostic, setShowDiagnostic] = useState(false);

  const maskSensitiveData = (obj: Record<string, unknown> | null | undefined) => {
    if (!obj) return null;
    const masked = { ...obj };
    const sensitiveKeys = [
      'apikey',
      'key',
      'token',
      'password',
      'secret',
      'base64',
      'qr',
      'qrcode',
      'authorization',
      'session',
      'cookie',
    ];

    const maskValue = (o: Record<string, unknown>): Record<string, unknown> => {
      if (typeof o !== 'object' || o === null) return o;
      for (const key in o) {
        if (sensitiveKeys.some((sk) => key.toLowerCase().includes(sk))) {
          if (typeof o[key] === 'string') {
            const v = o[key] as string;
            o[key] = v.length > 10 ? `${v.substring(0, 4)}...${v.substring(v.length - 4)}` : '****';
          } else {
            o[key] = '****';
          }
        } else if (typeof o[key] === 'object' && o[key] !== null) {
          maskValue(o[key] as Record<string, unknown>);
        }
      }
      return o;
    };

    return maskValue(JSON.parse(JSON.stringify(masked)) as Record<string, unknown>);
  };
  const {
    connections,
    loading,
    isAddDialogOpen,
    setIsAddDialogOpen,
    qrCodeDialog,
    newConnection,
    setNewConnection,
    isCreating,
    syncingHistory,
    setSyncingHistory,
    evolutionLoading,
    handleShowQrCode,
    handleRefreshQrCode,
    handleCopyId,
    handleDisconnect,
    handleSetDefault,
    handleSetApiType,
    handleDelete,
    handleAddConnection,
    closeQrDialog,
  } = useConnectionsManager();

  // Auto-sync Evolution instances not yet in whatsapp_connections
  useEvolutionAutoSync();
  useEvolutionAutoReconnect();

  const [businessHoursDialog, setBusinessHoursDialog] = useState({
    open: false,
    connectionId: '',
    connectionName: '',
  });
  const [queuesDialog, setQueuesDialog] = useState({
    open: false,
    connectionId: '',
    connectionName: '',
  });
  const [settingsDialog, setSettingsDialog] = useState({
    open: false,
    instanceName: '',
    connectionName: '',
  });
  const [integrationsDialog, setIntegrationsDialog] = useState({
    open: false,
    instanceName: '',
    connectionName: '',
  });

  // Deep-link: ?qr=<instance_id> auto-opens the QR dialog for that instance.
  const deepLinkHandledRef = useRef(false);
  useEffect(() => {
    if (deepLinkHandledRef.current || loading || connections.length === 0) return;
    const params = new URLSearchParams(window.location.search);
    const targetInstance = params.get('qr');
    if (!targetInstance) return;
    const conn = connections.find((c) => c.instance_id === targetInstance);
    if (conn) {
      deepLinkHandledRef.current = true;
      handleShowQrCode(conn);
      // Clean URL so refreshing doesn't reopen the dialog unexpectedly.
      const url = new URL(window.location.href);
      url.searchParams.delete('qr');
      url.searchParams.delete('view');
      window.history.replaceState({}, '', url.toString());
    }
  }, [connections, loading, handleShowQrCode]);

  const handleSyncHistory = async (connection: { id: string; instance_id?: string | null }) => {
    if (!connection.instance_id) return;
    setSyncingHistory(connection.id);
    toast({ title: 'Sincronizando histórico...', description: 'Isso pode levar alguns minutos.' });
    try {
      const { data, error } = await supabase.functions.invoke('evolution-sync', {
        body: { action: 'sync-all-messages', instanceName: connection.instance_id },
      });
      if (error) throw error;
      toast({
        title: 'Sincronização concluída!',
        description: `${data?.totalSynced || 0} mensagens sincronizadas de ${data?.totalContacts || 0} contatos.`,
      });
    } catch (e: unknown) {
      toast({
        title: 'Erro na sincronização',
        description: e instanceof Error ? e.message : 'Erro desconhecido',
        variant: 'destructive',
      });
    } finally {
      setSyncingHistory(null);
    }
  };

  return (
    <div className="relative h-full space-y-6 overflow-y-auto bg-background p-6">
      <AuroraBorealis />
      <FloatingParticles />

      <PageHeader
        title="Conexões WhatsApp"
        subtitle="Gerencie suas conexões WhatsApp"
        breadcrumbs={[{ label: 'Configurações' }, { label: 'Conexões' }]}
        actions={
          <Dialog open={isAddDialogOpen} onOpenChange={setIsAddDialogOpen}>
            <DialogTrigger asChild>
              <Button className="bg-whatsapp text-primary-foreground hover:bg-whatsapp-dark">
                <Plus className="mr-2 h-4 w-4" />
                Conectar WhatsApp
              </Button>
            </DialogTrigger>
            <DialogContent className="sm:max-w-md">
              <DialogHeader>
                <DialogTitle>Conectar WhatsApp</DialogTitle>
                <DialogDescription>Configure os dados da conexão</DialogDescription>
              </DialogHeader>
              <div className="grid gap-4 py-4">
                <div className="space-y-2">
                  <Label>Nome (identificação interna)</Label>
                  <Input
                    placeholder="Ex: Vendas, SAC, Financeiro"
                    value={newConnection.name}
                    onChange={(e) => setNewConnection({ ...newConnection, name: e.target.value })}
                  />
                </div>
                <div className="space-y-2">
                  <Label>Número do celular</Label>
                  <PhoneInput
                    value={newConnection.phone_number}
                    onChange={(formatted) =>
                      setNewConnection({ ...newConnection, phone_number: formatted })
                    }
                  />
                </div>
                <div className="space-y-2">
                  <Label>Método de conexão</Label>
                  <Select
                    value={newConnection.api_type}
                    onValueChange={(v) =>
                      setNewConnection({
                        ...newConnection,
                        api_type: v as 'evolution' | 'official',
                      })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Como deseja conectar?" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="evolution">
                        <div className="flex flex-col items-start">
                          <span className="font-medium">Não-oficial (Evolution API)</span>
                          <span className="text-xs text-muted-foreground">
                            Conexão via QR Code (WhatsApp Web)
                          </span>
                        </div>
                      </SelectItem>
                      <SelectItem value="official">
                        <div className="flex flex-col items-start">
                          <span className="font-medium">Oficial (WhatsApp Cloud API)</span>
                          <span className="text-xs text-muted-foreground">
                            Autenticação via Meta — sem QR Code
                          </span>
                        </div>
                      </SelectItem>
                    </SelectContent>
                  </Select>
                  {newConnection.api_type === 'official' && (
                    <p className="text-xs text-muted-foreground">
                      A API oficial não usa QR Code. Após criar, configure as credenciais (Phone
                      Number ID, Access Token) nas configurações da conexão.
                    </p>
                  )}
                </div>
                <div className="flex justify-end gap-2 pt-4">
                  <Button
                    variant="outline"
                    onClick={() => setIsAddDialogOpen(false)}
                    disabled={isCreating}
                  >
                    Cancelar
                  </Button>
                  <Button
                    onClick={handleAddConnection}
                    className="bg-whatsapp hover:bg-whatsapp-dark"
                    disabled={isCreating}
                  >
                    {isCreating ? (
                      <>
                        <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                        Criando...
                      </>
                    ) : (
                      'Adicionar'
                    )}
                  </Button>
                </div>
              </div>
            </DialogContent>
          </Dialog>
        }
      />

      {/* QR Code Dialog */}
      <Dialog open={qrCodeDialog.open} onOpenChange={(open) => !open && closeQrDialog()}>
        <DialogContent className="text-center sm:max-w-md">
          <DialogHeader>
            <DialogTitle
              className="flex items-center justify-center gap-2"
              data-testid="qr-dialog-title"
            >
              {qrCodeDialog.status === 'connected' ? (
                <>
                  <CheckCircle2 className="h-5 w-5 text-status-online" />
                  Conectado!
                </>
              ) : qrCodeDialog.status === 'error' ? (
                <>
                  <XCircle className="h-5 w-5 text-destructive" />
                  Erro
                </>
              ) : (
                <>
                  <QrCode className="h-5 w-5" />
                  Escanear QR Code - {qrCodeDialog.connectionName}
                </>
              )}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-6 py-6">
            {qrCodeDialog.status === 'loading' && (
              <div className="mx-auto flex h-64 w-64 flex-col items-center justify-center gap-4 rounded-xl bg-muted p-6 text-center">
                <Loader2 className="h-12 w-12 animate-spin text-muted-foreground" />
                <div className="space-y-1.5">
                  <p
                    className="animate-pulse text-sm font-medium"
                    data-testid="reconnect-step-loading"
                  >
                    Iniciando sessão...
                  </p>
                  <p
                    className="text-[10px] text-muted-foreground"
                    data-testid="reconnect-step-label"
                  >
                    Etapa 1 de 3: Autenticando com a Evolution API
                  </p>
                </div>
              </div>
            )}
            {qrCodeDialog.status === 'pending' && qrCodeDialog.qrCode && (
              <motion.div
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                className="mx-auto flex h-64 w-64 items-center justify-center rounded-xl bg-background p-2"
                data-testid="qr-code-container"
              >
                <img
                  src={
                    qrCodeDialog.qrCode.startsWith('data:')
                      ? qrCodeDialog.qrCode
                      : `data:image/png;base64,${qrCodeDialog.qrCode}`
                  }
                  alt="QR Code"
                  className="h-full w-full object-contain"
                  data-testid="qr-code-image"
                />
              </motion.div>
            )}
            {qrCodeDialog.status === 'connected' && (
              <motion.div
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                className="mx-auto flex h-64 w-64 flex-col items-center justify-center rounded-xl bg-status-online/10"
              >
                <CheckCircle2 className="mb-4 h-20 w-20 text-status-online" />
                <p className="text-lg font-medium text-status-online">WhatsApp Conectado!</p>
              </motion.div>
            )}
            {qrCodeDialog.status === 'error' && (
              <motion.div
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                className="mx-auto flex h-64 w-64 flex-col items-center justify-center rounded-xl bg-destructive/10 p-4"
              >
                <AlertCircle className="mb-4 h-16 w-16 text-destructive" />
                <p className="text-center text-sm text-destructive">{qrCodeDialog.errorMessage}</p>
              </motion.div>
            )}
            {qrCodeDialog.status === 'pending' && (
              <>
                <div className="space-y-2 text-sm text-muted-foreground">
                  <p>
                    1. Abra o <strong>WhatsApp</strong> no celular deste número
                  </p>
                  <p>
                    2. Toque em <strong>Configurações</strong> (⚙️)
                  </p>
                  <p>
                    3. Toque em <strong>Aparelhos conectados</strong>
                  </p>
                  <p>
                    4. Toque em <strong>Conectar aparelho</strong>
                  </p>
                  <p>5. Aponte a câmera para o QR Code acima</p>
                </div>
                <div className="flex flex-col items-center justify-center gap-2 text-xs text-primary/80">
                  <div className="flex items-center gap-2">
                    <Loader2 className="h-3 w-3 animate-spin" />
                    <span className="font-medium">Aguardando leitura do QR Code...</span>
                  </div>
                  <p
                    className="text-[10px] text-muted-foreground"
                    data-testid="reconnect-step-label"
                  >
                    Etapa 2 de 3: Conectando dispositivo via WhatsApp Web
                  </p>
                  <p className="text-[10px] italic text-muted-foreground">
                    Mantenha o celular próximo e conectado à internet
                  </p>
                </div>
                {qrCodeDialog.expiresAt && <QrCountdown expiresAt={qrCodeDialog.expiresAt} />}
                {qrCodeDialog.ttlSeconds != null && qrCodeDialog.ttlSource && (
                  <QrTtlBadge
                    ttlSeconds={qrCodeDialog.ttlSeconds}
                    source={qrCodeDialog.ttlSource}
                  />
                )}
              </>
            )}
            {(qrCodeDialog.status === 'pending' ||
              qrCodeDialog.status === 'error' ||
              qrCodeDialog.status === 'loading') && (
              <RefreshQrButton
                onRefresh={handleRefreshQrCode}
                loading={evolutionLoading || qrCodeDialog.status === 'loading'}
                status={qrCodeDialog.status}
                label={qrCodeDialog.status === 'pending' ? 'Gerar novo QR' : 'Gerar novo código'}
              />
            )}
            {qrCodeDialog.status === 'connected' && <Button onClick={closeQrDialog}>Fechar</Button>}

            <div className="border-t border-muted/30 pt-4">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setShowDiagnostic(!showDiagnostic)}
                className="gap-1 text-[10px] text-muted-foreground hover:text-primary"
              >
                {showDiagnostic ? 'Ocultar Diagnóstico' : 'Ver Diagnóstico Técnico'}
              </Button>

              <AnimatePresence>
                {showDiagnostic && (
                  <motion.div
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: 'auto', opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    className="mt-2 overflow-hidden"
                  >
                    <div className="space-y-2 rounded-lg bg-muted/50 p-3 text-left">
                      <p className="text-[10px] font-bold uppercase text-muted-foreground">
                        Payload Evolution API (Mascarado)
                      </p>
                      <pre className="max-h-40 overflow-x-auto rounded bg-black/5 p-2 font-mono text-[9px]">
                        {JSON.stringify(maskSensitiveData(qrCodeDialog.rawPayload as Record<string, unknown> | null | undefined), null, 2)}
                      </pre>
                      <p className="text-[8px] italic text-muted-foreground">
                        * Dados sensíveis como chaves de API e strings Base64 foram ocultados por
                        segurança.
                      </p>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>

            {qrCodeDialog.connectionId && (
              <QrAttemptHistory
                connectionId={qrCodeDialog.connectionId}
                refreshKey={`${qrCodeDialog.attemptId ?? 'none'}:${qrCodeDialog.status}`}
              />
            )}
          </div>
        </DialogContent>
      </Dialog>

      <IdempotencyMissBanner />

      <div className="mb-4 flex flex-col items-end justify-between gap-4 md:flex-row md:items-center">
        <div className="flex w-full flex-1 gap-2 md:max-w-md">
          <Input
            placeholder="Buscar por nome ou ID..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="border-secondary/20 bg-card"
          />
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger className="w-[180px] border-secondary/20 bg-card">
              <SelectValue placeholder="Filtrar status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Todos os status</SelectItem>
              <SelectItem value="connected">Online</SelectItem>
              <SelectItem value="pending">Aguardando QR</SelectItem>
              <SelectItem value="disconnected">Desconectado</SelectItem>
              <SelectItem value="disconnecting">Desconectando</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
        {[
          {
            label: 'Total de Conexões',
            value: connections.length,
            color: 'text-primary',
            sub:
              connections.length +
              ' instância' +
              (connections.length !== 1 ? 's' : '') +
              ' configurada' +
              (connections.length !== 1 ? 's' : ''),
          },
          {
            label: 'Online',
            value: connections.filter((c) => c.status === 'connected').length,
            color: 'text-primary',
            sub:
              connections.filter((c) => c.status === 'connected').length > 0
                ? 'Recebendo mensagens'
                : 'Nenhuma ativa',
          },
          {
            label: 'Ações necessárias',
            value: connections.filter((c) => c.status !== 'connected').length,
            color:
              connections.filter((c) => c.status !== 'connected').length > 0
                ? 'text-destructive-foreground'
                : 'text-primary',
            sub:
              connections.filter((c) => c.status !== 'connected').length > 0
                ? 'Precisam reconectar'
                : 'Tudo funcionando ✔',
          },
        ].map((stat, i) => (
          <motion.div
            key={stat.label}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: i * 0.1 }}
          >
            <Card className="border border-secondary/20 bg-card">
              <CardContent className="p-4">
                <p className="text-sm text-muted-foreground">{stat.label}</p>
                <p className={cn('text-3xl font-bold', stat.color)}>{stat.value}</p>
                {stat.sub && <p className="mt-1 text-xs text-muted-foreground">{stat.sub}</p>}
              </CardContent>
            </Card>
          </motion.div>
        ))}
      </div>

      <DegradedQuickActions
        connections={connections as any}
        onShowQrCode={handleShowQrCode as any}
      />

      {/* Connections List */}
      {loading ? (
        <div className="flex items-center justify-center py-8 text-muted-foreground">
          <Loader2 className="mr-2 h-6 w-6 animate-spin" />
          Carregando conexões...
        </div>
      ) : connections.length === 0 ? (
        <EmptyState
          icon={Smartphone}
          title="Conecte seu WhatsApp"
          description="Em poucos passos você estará recebendo e respondendo mensagens dos seus clientes."
          illustration="inbox"
          actionLabel="Conectar WhatsApp"
          onAction={() => setIsAddDialogOpen(true)}
        />
      ) : (
        <StaggeredList className="space-y-4">
          {connections
            .filter((c) => {
              const matchesSearch =
                c.name.toLowerCase().includes(search.toLowerCase()) ||
                (c.instance_id || '').toLowerCase().includes(search.toLowerCase());
              const matchesStatus = statusFilter === 'all' || c.status === statusFilter;
              return matchesSearch && matchesStatus;
            })
            .map((connection) => (
              <StaggeredItem key={connection.id}>
                <ConnectionCard
                  connection={connection}
                  syncingHistory={syncingHistory}
                  onShowQrCode={handleShowQrCode}
                  onCopyId={handleCopyId}
                  onDisconnect={handleDisconnect}
                  onSetDefault={handleSetDefault}
                  onSetApiType={handleSetApiType}
                  onDelete={handleDelete}
                  onBusinessHours={(id, name) =>
                    setBusinessHoursDialog({ open: true, connectionId: id, connectionName: name })
                  }
                  onQueues={(id, name) =>
                    setQueuesDialog({ open: true, connectionId: id, connectionName: name })
                  }
                  onSettings={(inst, name) =>
                    setSettingsDialog({ open: true, instanceName: inst, connectionName: name })
                  }
                  onIntegrations={(inst, name) =>
                    setIntegrationsDialog({ open: true, instanceName: inst, connectionName: name })
                  }
                  onSyncHistory={handleSyncHistory}
                />
              </StaggeredItem>
            ))}
        </StaggeredList>
      )}

      <BusinessHoursDialog
        open={businessHoursDialog.open}
        onOpenChange={(open) => setBusinessHoursDialog((prev) => ({ ...prev, open }))}
        connectionId={businessHoursDialog.connectionId}
        connectionName={businessHoursDialog.connectionName}
      />
      <ConnectionQueuesDialog
        open={queuesDialog.open}
        onOpenChange={(open) => setQueuesDialog((prev) => ({ ...prev, open }))}
        connectionId={queuesDialog.connectionId}
        connectionName={queuesDialog.connectionName}
      />
      <InstanceSettingsDialog
        open={settingsDialog.open}
        onOpenChange={(open) => setSettingsDialog((prev) => ({ ...prev, open }))}
        instanceName={settingsDialog.instanceName}
        connectionName={settingsDialog.connectionName}
        connectionId={connections.find((c) => c.instance_id === settingsDialog.instanceName)?.id}
      />
      <IntegrationsPanel
        open={integrationsDialog.open}
        onOpenChange={(open) => setIntegrationsDialog((prev) => ({ ...prev, open }))}
        instanceName={integrationsDialog.instanceName}
        connectionName={integrationsDialog.connectionName}
      />
      <NumberReputationMonitor />
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useMountedRef } from '@/hooks/useMountedRef';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Button } from '@/components/ui/button';
import { Switch } from '@/components/ui/switch';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { useEvolutionApi } from '@/hooks/useEvolutionApi';
import { supabase } from '@/integrations/supabase/client';
import { safeFrom } from '@/integrations/supabase/safeClient';
import { toast } from 'sonner';
import { Loader2, Settings, Shield, User, Tag, History, RotateCcw } from 'lucide-react';
import { getLogger } from '@/lib/logger';
import {
  SettingsTabContent,
  PrivacyTabContent,
  LabelsTabContent,
} from './InstanceSettingsTabContent';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';

const log = getLogger('InstanceSettingsDialog');

interface ReconnectionLog {
  id: string;
  result: string;
  created_at: string;
  attempt_number: number;
  error_message?: string | null;
}

interface InstanceSettingsDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  instanceName: string;
  connectionName: string;
  connectionId?: string;
}

const SETTINGS_ITEMS = [
  { key: 'rejectCall', label: 'Rejeitar chamadas', desc: 'Rejeita chamadas automaticamente' },
  { key: 'groupsIgnore', label: 'Ignorar grupos', desc: 'Não processar mensagens de grupos' },
  { key: 'alwaysOnline', label: 'Sempre online', desc: 'Mantém o status como online' },
  {
    key: 'readMessages',
    label: 'Leitura automática',
    desc: 'Marca mensagens como lidas automaticamente',
  },
  { key: 'readStatus', label: 'Ver status', desc: 'Marca status/stories como visualizados' },
  {
    key: 'syncFullHistory',
    label: 'Sincronizar histórico',
    desc: 'Baixa todo o histórico de mensagens',
  },
] as const;

const PRIVACY_ITEMS = [
  { key: 'readreceipts', label: 'Confirmação de leitura' },
  { key: 'profile', label: 'Foto de perfil' },
  { key: 'status', label: 'Status/recado' },
  { key: 'online', label: 'Online' },
  { key: 'last', label: 'Visto por último' },
  { key: 'groupadd', label: 'Adicionar em grupos' },
] as const;

const PRIVACY_OPTIONS = [
  { value: 'all', label: 'Todos' },
  { value: 'contacts', label: 'Contatos' },
  { value: 'contact_blacklist', label: 'Contatos exceto...' },
  { value: 'none', label: 'Ninguém' },
];

export function InstanceSettingsDialog({
  open,
  onOpenChange,
  instanceName,
  connectionName,
  connectionId,
}: InstanceSettingsDialogProps) {
  const {
    getSettings,
    setSettings,
    fetchProfile,
    updateProfileName,
    updateProfileStatus,
    updateProfilePicture,
    removeProfilePicture,
    updatePrivacySettings,
    findLabels,
    isLoading,
  } = useEvolutionApi();
  const mountedRef = useMountedRef();

  const [settingsData, setSettingsData] = useState<Record<string, boolean | string>>({
    rejectCall: false,
    msgCall: '',
    groupsIgnore: false,
    alwaysOnline: false,
    readMessages: false,
    readStatus: false,
    syncFullHistory: false,
  });
  const [profile, setProfile] = useState({ name: '', status: '', pictureUrl: '' });
  const [privacy, setPrivacy] = useState<Record<string, string>>({
    readreceipts: 'all',
    profile: 'all',
    status: 'contacts',
    online: 'all',
    last: 'contacts',
    groupadd: 'contacts',
  });
  const [labels, setLabels] = useState<{ id: string; name: string; color: string }[]>([]);

  // Reconnection & Audit state
  const [reconnectConfig, setReconnectConfig] = useState({
    enabled: true,
    interval: 30,
    maxAttempts: 5,
    loopProtection: false,
  });
  const [auditLogs, setAuditLogs] = useState<ReconnectionLog[]>([]);
  const [loadingTab, setLoadingTab] = useState('');

  const loadReconnectConfig = useCallback(async () => {
    if (!connectionId) return;
    try {
      const { data, error } = await safeFrom('whatsapp_connections')
        .select(
          'auto_reconnect_enabled, reconnect_interval_seconds, max_reconnect_attempts, loop_protection_active'
        )
        .eq('id', connectionId)
        .maybeSingle();

      if (!error && data && mountedRef.current) {
        setReconnectConfig({
          enabled: data.auto_reconnect_enabled ?? true,
          interval: data.reconnect_interval_seconds ?? 30,
          maxAttempts: data.max_reconnect_attempts ?? 5,
          loopProtection: data.loop_protection_active ?? false,
        });
      }
    } catch (err) {
      log.error('Error loading reconnect config:', err);
    }
  }, [connectionId, mountedRef]);

  const loadSettings = useCallback(async () => {
    setLoadingTab('settings');
    try {
      const data = (await getSettings(instanceName)) as Record<string, unknown> | null;
      if (data && mountedRef.current)
        setSettingsData({
          rejectCall: (data.rejectCall as boolean) ?? false,
          msgCall: (data.msgCall as string) ?? '',
          groupsIgnore: (data.groupsIgnore as boolean) ?? false,
          alwaysOnline: (data.alwaysOnline as boolean) ?? false,
          readMessages: (data.readMessages as boolean) ?? false,
          readStatus: (data.readStatus as boolean) ?? false,
          syncFullHistory: (data.syncFullHistory as boolean) ?? false,
        });
    } catch (err) {
      log.error('Error loading settings:', err);
    }
    if (mountedRef.current) setLoadingTab('');
  }, [instanceName, getSettings, mountedRef]);

  const loadProfile = useCallback(async () => {
    try {
      const data = (await fetchProfile(instanceName)) as Record<string, unknown> | null;
      if (data && mountedRef.current)
        setProfile({
          name: (data.name as string) ?? '',
          status: (data.status as string) ?? '',
          pictureUrl: (data.profilePictureUrl as string) ?? '',
        });
    } catch (err) {
      log.error('Error loading profile:', err);
    }
  }, [instanceName, fetchProfile, mountedRef]);

  useEffect(() => {
    if (open && instanceName) {
      loadSettings();
      loadProfile();
      if (connectionId) {
        loadReconnectConfig();
      }
    }
  }, [open, instanceName, connectionId, loadSettings, loadProfile, loadReconnectConfig]);

  const saveReconnectConfig = async () => {
    if (!connectionId) return;
    try {
      const { error } = await safeFrom('whatsapp_connections')
        .update({
          auto_reconnect_enabled: reconnectConfig.enabled,
          reconnect_interval_seconds: reconnectConfig.interval,
          max_reconnect_attempts: reconnectConfig.maxAttempts,
          loop_protection_active: reconnectConfig.loopProtection,
        })
        .eq('id', connectionId);

      if (error) throw error;
      toast.success('Política de reconexão salva!');
    } catch (err) {
      log.error('Error saving reconnect config:', err);
      toast.error('Falha ao salvar política');
    }
  };

  const loadAuditLogs = async () => {
    if (!connectionId) return;
    setLoadingTab('audit');
    try {
      const { data, error } = await safeFrom('reconnection_logs')
        .select('*')
        .eq('connection_id', connectionId)
        .order('created_at', { ascending: false })
        .limit(20);

      if (!error && data && mountedRef.current) setAuditLogs(data as unknown as ReconnectionLog[]);
    } catch (err) {
      log.error('Error loading audit logs:', err);
    }
    if (mountedRef.current) setLoadingTab('');
  };

  const loadLabels = async () => {
    setLoadingTab('labels');
    try {
      const data = await findLabels(instanceName);
      if (Array.isArray(data) && mountedRef.current) setLabels(data);
    } catch (err) {
      log.error('Error loading labels:', err);
    }
    if (mountedRef.current) setLoadingTab('');
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-h-[85vh] overflow-y-auto sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Settings className="h-5 w-5 text-primary" />
            Configurações — {connectionName}
          </DialogTitle>
          <DialogDescription>
            Gerencie configurações, perfil, privacidade e etiquetas da instância
          </DialogDescription>
        </DialogHeader>
        <Tabs
          defaultValue="settings"
          onValueChange={(v) => {
            if (v === 'labels') loadLabels();
          }}
        >
          <TabsList className="grid w-full grid-cols-5">
            <TabsTrigger value="settings">
              <Settings className="mr-1 h-4 w-4" /> Config
            </TabsTrigger>
            <TabsTrigger value="profile">
              <User className="mr-1 h-4 w-4" /> Perfil
            </TabsTrigger>
            <TabsTrigger value="privacy">
              <Shield className="mr-1 h-4 w-4" /> Privacid.
            </TabsTrigger>
            <TabsTrigger value="audit" onClick={loadAuditLogs}>
              <History className="mr-1 h-4 w-4" /> Auditoria
            </TabsTrigger>
            <TabsTrigger value="labels">
              <Tag className="mr-1 h-4 w-4" /> Tags
            </TabsTrigger>
          </TabsList>

          <TabsContent value="audit" className="mt-4 space-y-4">
            <div className="rounded-xl border border-border/20 bg-muted/5 p-4">
              <h4 className="mb-4 flex items-center gap-2 text-sm font-semibold">
                <RotateCcw className="h-4 w-4 text-primary" /> Política de Reconexão
              </h4>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>Intervalo (segundos)</Label>
                  <Input
                    type="number"
                    value={reconnectConfig.interval}
                    onChange={(e) =>
                      setReconnectConfig((p) => ({ ...p, interval: parseInt(e.target.value) }))
                    }
                  />
                </div>
                <div className="space-y-2">
                  <Label>Máximo de Tentativas</Label>
                  <Input
                    type="number"
                    value={reconnectConfig.maxAttempts}
                    onChange={(e) =>
                      setReconnectConfig((p) => ({ ...p, maxAttempts: parseInt(e.target.value) }))
                    }
                  />
                </div>
              </div>
              <div className="mt-4 flex items-center justify-between rounded-lg bg-background/50 p-2">
                <div className="space-y-0.5">
                  <Label>Proteção contra Loop</Label>
                  <p className="text-[10px] text-muted-foreground">
                    Pausa automática se houver muitas quedas seguidas
                  </p>
                </div>
                <Switch
                  checked={reconnectConfig.loopProtection}
                  onCheckedChange={(v) => setReconnectConfig((p) => ({ ...p, loopProtection: v }))}
                />
              </div>
              <Button onClick={saveReconnectConfig} size="sm" className="mt-4 h-8 w-full text-xs">
                Salvar Política
              </Button>
            </div>

            <div className="space-y-2">
              <h4 className="text-sm font-semibold">Histórico de Tentativas</h4>
              <ScrollArea className="h-[200px] w-full rounded-md border border-border/20 bg-muted/5 p-2">
                {loadingTab === 'audit' ? (
                  <div className="flex justify-center py-8">
                    <Loader2 className="h-6 w-6 animate-spin" />
                  </div>
                ) : auditLogs.length === 0 ? (
                  <p className="py-8 text-center text-xs text-muted-foreground">
                    Nenhuma tentativa registrada.
                  </p>
                ) : (
                  <div className="space-y-2">
                    {auditLogs.map((log) => (
                      <div
                        key={log.id}
                        className="flex flex-col gap-1 rounded-lg border border-border/10 bg-background p-2 text-[11px]"
                      >
                        <div className="flex items-center justify-between">
                          <Badge
                            variant={log.result === 'success' ? 'default' : 'destructive'}
                            className="h-4 text-[9px]"
                          >
                            {log.result === 'success' ? 'Sucesso' : 'Falha'}
                          </Badge>
                          <span className="text-muted-foreground">
                            {format(new Date(log.created_at), "dd/MM 'às' HH:mm", { locale: ptBR })}
                          </span>
                        </div>
                        <p className="text-muted-foreground">Tentativa #{log.attempt_number}</p>
                        {log.error_message && (
                          <p className="truncate font-mono text-destructive">{log.error_message}</p>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </ScrollArea>
            </div>
          </TabsContent>

          <TabsContent value="settings">
            <SettingsTabContent
              settingsData={settingsData}
              settingsItems={SETTINGS_ITEMS}
              onChange={(k, v) => setSettingsData((p) => ({ ...p, [k]: v }))}
              onSave={async () => {
                try {
                  await setSettings({ instanceName, ...settingsData });
                  toast.success('Configurações salvas!');
                } catch {
                  toast.error('Erro ao salvar');
                }
              }}
              isLoading={isLoading}
            />
          </TabsContent>

          <TabsContent value="profile" className="mt-4 space-y-4">
            {profile.pictureUrl && (
              <div className="flex justify-center">
                <img
                  src={profile.pictureUrl}
                  alt="Profile"
                  className="h-24 w-24 rounded-full border-2 border-primary/30 object-cover"
                />
              </div>
            )}
            <div>
              <Label>Nome</Label>
              <Input
                value={profile.name}
                onChange={(e) => setProfile((p) => ({ ...p, name: e.target.value }))}
                placeholder="Nome do perfil"
              />
            </div>
            <div>
              <Label>Recado (Status)</Label>
              <Input
                value={profile.status}
                onChange={(e) => setProfile((p) => ({ ...p, status: e.target.value }))}
                placeholder="Seu recado aqui..."
              />
            </div>
            <div>
              <Label>Nova foto de perfil (URL)</Label>
              <div className="flex gap-2">
                <Input
                  value={profile.pictureUrl}
                  onChange={(e) => setProfile((p) => ({ ...p, pictureUrl: e.target.value }))}
                  placeholder="https://exemplo.com/foto.jpg"
                />
                <Button
                  variant="outline"
                  size="sm"
                  onClick={async () => {
                    try {
                      if (profile.pictureUrl) {
                        await updateProfilePicture(instanceName, profile.pictureUrl);
                        toast.success('Foto atualizada!');
                      }
                    } catch {
                      toast.error('Erro ao atualizar foto');
                    }
                  }}
                >
                  Aplicar
                </Button>
                <Button
                  variant="destructive"
                  size="sm"
                  onClick={async () => {
                    try {
                      await removeProfilePicture(instanceName);
                      setProfile((p) => ({ ...p, pictureUrl: '' }));
                      toast.success('Foto removida');
                    } catch {
                      toast.error('Erro ao remover foto');
                    }
                  }}
                >
                  Remover
                </Button>
              </div>
            </div>
            <Button
              onClick={async () => {
                try {
                  if (profile.name) await updateProfileName(instanceName, profile.name);
                  if (profile.status) await updateProfileStatus(instanceName, profile.status);
                  toast.success('Perfil atualizado!');
                } catch {
                  toast.error('Erro ao atualizar perfil');
                }
              }}
              disabled={isLoading}
              className="w-full"
            >
              {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}Salvar Perfil
            </Button>
          </TabsContent>

          <TabsContent value="privacy">
            <PrivacyTabContent
              privacy={privacy}
              privacyItems={PRIVACY_ITEMS}
              privacyOptions={PRIVACY_OPTIONS}
              onChange={(k, v) => setPrivacy((p) => ({ ...p, [k]: v }))}
              onSave={async () => {
                try {
                  await updatePrivacySettings({ instanceName, ...privacy });
                  toast.success('Privacidade atualizada!');
                } catch {
                  toast.error('Erro ao atualizar');
                }
              }}
              isLoading={isLoading}
            />
          </TabsContent>

          <TabsContent value="labels">
            <LabelsTabContent labels={labels} loading={loadingTab === 'labels'} />
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );
}

