            {/* Template picker */}
            <MessageTemplates
              onSelectTemplate={(content) => {
                const el = DOMPurify.sanitize(bodyHtml, { ALLOWED_TAGS: [], ALLOWED_ATTR: [] });
                const newContent = el ? el + '\n\n' + content : content;
