function KpiCard({
  label,
  value,
  icon,
  tone = 'default',
}: {
  label: string;
  value: number;
  icon: React.ReactNode;
  tone?: 'default' | 'warning' | 'destructive';
}) {
  return (
    <Card className="rounded-2xl">
      <CardContent className="flex items-center gap-3 p-4">
        <div
          className={cn(
            'flex h-10 w-10 items-center justify-center rounded-xl',
            tone === 'destructive' && 'bg-destructive/10 text-destructive',
            tone === 'warning' && 'bg-warning/10 text-warning',
            tone === 'default' && 'bg-primary/10 text-primary'
          )}
        >
          {icon}
        </div>
        <div>
          <p className="text-xs text-muted-foreground">{label}</p>
          <p className="text-2xl font-bold">{value}</p>
        </div>
      </CardContent>
    </Card>
  );
}

function QueueRow({
  row,
  onUpdate,
}: {
  row: QueueSlaRow;
  onUpdate: (id: string, patch: Partial<QueueSlaRow>) => Promise<boolean>;
}) {
  const [weight, setWeight] = useState(String(row.routing_weight));
  useEffect(() => setWeight(String(row.routing_weight)), [row.routing_weight]);

  return (
    <tr className="border-b hover:bg-muted/30 [&>td]:px-2 [&>td]:py-2">
      <td>
        <div className="flex items-center gap-2">
          <span className="h-2.5 w-2.5 rounded-full" style={{ background: row.color }} />
          <span className="font-medium">{row.queue_name}</span>
        </div>
      </td>
      <td>
        <Select
          value={row.sla_priority}
          onValueChange={(v) =>
            onUpdate(row.queue_id, { sla_priority: v as QueueSlaRow['sla_priority'] })
          }
        >
          <SelectTrigger className="h-8 w-[110px]">
            <Badge className={cn('text-[10px]', PRIORITY_COLOR[row.sla_priority])}>
              {PRIORITY_LABEL[row.sla_priority]}
            </Badge>
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="critical">Crítica</SelectItem>
            <SelectItem value="high">Alta</SelectItem>
            <SelectItem value="medium">Média</SelectItem>
            <SelectItem value="low">Baixa</SelectItem>
          </SelectContent>
        </Select>
      </td>
      <td>
        <Input
          type="number"
          min={0}
          max={100}
          value={weight}
          onChange={(e) => setWeight(e.target.value)}
          onBlur={() => {
            const n = Math.max(0, Math.min(100, Number(weight) || 0));
            if (n !== row.routing_weight) onUpdate(row.queue_id, { routing_weight: n });
          }}
          className="h-8 w-16"
        />
      </td>
      <td>
        <Switch
          checked={row.auto_rebalance_enabled}
          onCheckedChange={(v) => onUpdate(row.queue_id, { auto_rebalance_enabled: v })}
        />
      </td>
      <td>{row.active_agents}</td>
      <td>{row.waiting_count}</td>
      <td>{row.in_progress_count}</td>
      <td>
        {row.at_risk_count > 0 ? (
          <Badge variant="outline" className="border-warning text-warning">
            {row.at_risk_count}
          </Badge>
        ) : (
          '0'
        )}
      </td>
      <td>
        {row.breached_count > 0 ? <Badge variant="destructive">{row.breached_count}</Badge> : '0'}
      </td>
      <td className="tabular-nums">{Math.round(Number(row.oldest_wait_minutes) || 0)}</td>
      <td className="text-xs text-muted-foreground">
        {row.last_routed_at ? new Date(row.last_routed_at).toLocaleTimeString() : '—'}
      </td>
    </tr>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { fetchAbandonmentRateMessages } from '@/hooks/useAbandonmentRateData';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { UserX, MessageSquare } from 'lucide-react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';

/** Abandonment Rate component for the reports section. */
export function AbandonmentRate() {
  const [data, setData] = useState({ total: 0, abandoned: 0, responded: 0 });
  const [period, setPeriod] = useState('7');
  const [loading, setLoading] = useState(true);

  const loadData = useCallback(async () => {
    setLoading(true);
    const since = new Date();
    since.setDate(since.getDate() - parseInt(period));

    const contactMessages = await fetchAbandonmentRateMessages(since);

    if (contactMessages) {
      const contactSet = new Set<string>();
      const respondedSet = new Set<string>();

      contactMessages.forEach((m) => {
        if (!m.contact_id) return;
        if (m.sender === 'contact') contactSet.add(m.contact_id);
        if (m.sender === 'agent') respondedSet.add(m.contact_id);
      });

      const total = contactSet.size;
      const responded = [...contactSet].filter((id) => respondedSet.has(id)).length;
      const abandoned = total - responded;

      setData({ total, abandoned, responded });
    }
    setLoading(false);
  }, [period]);

  useEffect(() => {
    void loadData();
  }, [loadData]);

  const rate = data.total > 0 ? Math.round((data.abandoned / data.total) * 100) : 0;

  const chartData = [
    { name: 'Respondidas', value: data.responded, color: 'hsl(var(--success))' },
    { name: 'Abandonadas', value: data.abandoned, color: 'hsl(var(--destructive))' },
  ].filter((d) => d.value > 0);

  return (
    <Card>
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="flex items-center gap-2 text-sm">
            <UserX className="h-4 w-4 text-destructive" />
            Taxa de Abandono
          </CardTitle>
          <Select value={period} onValueChange={setPeriod}>
            <SelectTrigger className="h-7 w-24 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="1">Hoje</SelectItem>
              <SelectItem value="7">7 dias</SelectItem>
              <SelectItem value="30">30 dias</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </CardHeader>
      <CardContent>
        {loading ? (
          <div className="h-40 animate-pulse rounded-xl bg-muted/20" />
        ) : (
          <div className="grid grid-cols-2 items-center gap-4">
            <div className="space-y-3">
              <div className="text-center">
                <p
                  className={`text-4xl font-bold ${rate > 30 ? 'text-destructive' : rate > 15 ? 'text-warning' : 'text-success'}`}
                >
                  {rate}%
                </p>
                <p className="text-xs text-muted-foreground">taxa de abandono</p>
              </div>
              <div className="space-y-1.5">
                <div className="flex items-center justify-between text-xs">
                  <span className="flex items-center gap-1">
                    <MessageSquare className="h-3 w-3" /> Total
                  </span>
                  <span className="font-medium">{data.total}</span>
                </div>
                <div className="flex items-center justify-between text-xs">
                  <span className="flex items-center gap-1 text-success">✓ Respondidas</span>
                  <span className="font-medium">{data.responded}</span>
                </div>
                <div className="flex items-center justify-between text-xs">
                  <span className="flex items-center gap-1 text-destructive">✗ Abandonadas</span>
                  <span className="font-medium">{data.abandoned}</span>
                </div>
              </div>
            </div>
            <div className="h-40">
              {chartData.length > 0 && (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={chartData}
                      cx="50%"
                      cy="50%"
                      innerRadius={35}
                      outerRadius={60}
                      paddingAngle={3}
                      dataKey="value"
                    >
                      {chartData.map((entry, idx) => (
                        <Cell key={idx} fill={entry.color} />
                      ))}
                    </Pie>
                    <Tooltip formatter={((value: any) => [String(value), 'Conversas']) as any} />
                  </PieChart>
                </ResponsiveContainer>
              )}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { useEffect, useState } from 'react';
