function formatTime(dateStr: string) {
  return format(new Date(dateStr), 'HH:mm');
}
function formatDateSep(dateStr: string) {
  const d = new Date(dateStr);
  if (isToday(d)) return 'Hoje';
  if (isYesterday(d)) return 'Ontem';
  return format(d, "d 'de' MMMM", { locale: ptBR });
}

const MediaContent = memo(function MediaContent({ msg }: { msg: TeamMessage }) {
  if (!msg.media_url) return null;
  switch (msg.media_type) {
    case 'image':
    case 'sticker':
    case 'emoji':
      return (
        <img
          src={msg.media_url}
          alt="media"
          className={cn(
            'max-h-48 cursor-pointer rounded-lg object-contain',
            msg.media_type === 'sticker' || msg.media_type === 'emoji' ? 'h-24 w-24' : 'max-w-full'
          )}
          onClick={() => {
            if (msg.media_url) window.open(msg.media_url, '_blank', 'noopener,noreferrer');
          }}
        />
      );
    case 'video':
      return <video src={msg.media_url} controls className="max-h-48 max-w-full rounded-lg" />;
    case 'audio':
    case 'audio_meme':
      return <audio src={msg.media_url} controls className="max-w-full" />;
    case 'document':
      return (
        <a
          href={msg.media_url}
          target="_blank"
          rel="noopener noreferrer"
          className="flex items-center gap-2 rounded-lg bg-muted/30 p-2 transition-colors hover:bg-muted/50"
        >
          <FileText className="h-5 w-5 shrink-0 text-muted-foreground" />
          <span className="truncate text-sm text-foreground underline">
            {msg.content || 'Documento'}
          </span>
        </a>
      );
    default:
      return null;
  }
});

const MediaTypeIcon = memo(function MediaTypeIcon({ type }: { type: string | null }) {
  switch (type) {
    case 'image':
      return <ImageIcon className="h-3 w-3" />;
    case 'video':
      return <Video className="h-3 w-3" />;
    case 'audio':
    case 'audio_meme':
      return <Music className="h-3 w-3" />;
    case 'document':
      return <FileText className="h-3 w-3" />;
    default:
      return null;
  }
});

interface Props {
  conversation: TeamConversation;
  onBack: () => void;
  onToggleDetails?: () => void;
  showDetails?: boolean;
}

const log = getLogger('TeamChatPanel');

export function TeamChatPanel(props: Props) {
  return (
    <ErrorBoundary
      fallback={
        <div className="p-4 text-center text-destructive">
          Erro ao carregar o chat. Por favor, tente recarregar.
        </div>
      }
      onError={(error) => log.error('TeamChatPanel error:', error)}
    >
      <TeamChatPanelContent {...props} />
    </ErrorBoundary>
  );
}

function TeamChatPanelContent({ conversation, onBack, onToggleDetails, showDetails }: Props) {
  const [showStats, setShowStats] = useState<'participants' | 'performance' | null>(null);
  const s = useTeamChatPanel(conversation);
  const {
    showSearch,
    setShowSearch,
    setSearchQuery,
    filteredMessages,
    profile,
    updateStatusMutation,
    isNearBottomRef,
    scrollRef,
    listRef,
    searchInputRef,
  } = s;
  const { profile: liveProfile } = useAuth();
  const {
    aggregate,
    toggle: toggleReaction,
    isToggling,
  } = useTeamMessageReactions(conversation.id);
  const dynamicRowHeight = useDynamicRowHeight({ defaultRowHeight: 100, key: conversation.id });
  const itemHeights = useRef<Record<number, number>>({});

  // Keyboard shortcuts for chat
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // CMD/CTRL + K to focus search inside chat
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        setShowSearch((prev) => !prev);
      }

      // ESC to close search or go back
      if (e.key === 'Escape') {
        if (showSearch) {
          setShowSearch(false);
          setSearchQuery('');
        } else if (onBack) {
          onBack();
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [showSearch, onBack, setShowSearch, setSearchQuery]);

  const isDeptMember = useMemo(() => {
    if (conversation.type !== 'department') return true;
    if (liveProfile?.role === 'admin') return true;
    return liveProfile?.department_id === conversation.department_id;
  }, [conversation, liveProfile]);

  useEffect(() => {
    if (isNearBottomRef.current && scrollRef.current)
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;

    // Mark unread messages as read
    const unreadIds = filteredMessages
      .filter((m) => m.sender_id !== profile?.id && m.status !== 'read')
      .map((m) => m.id);

    if (unreadIds.length > 0) {
      unreadIds.forEach((id) => {
        updateStatusMutation.mutate({
          messageId: id,
          status: 'read',
          conversationId: conversation.id,
        });
      });
    }
    // reset cache if needed (handled by dynamicRowHeight key mostly)
    itemHeights.current = {};
  }, [filteredMessages, conversation.id, profile, updateStatusMutation]);

  useEffect(() => {
    // If we are at the bottom, stay at the bottom
    if (isNearBottomRef.current && listRef.current) {
      const lastIndex = filteredMessages.length - 1;
      if (lastIndex >= 0) {
        listRef.current.scrollToRow({ index: lastIndex, align: 'end' });
      }
    }
  }, [filteredMessages, conversation.id]);

  // Handle incoming messages while reading old ones
  useEffect(() => {
    if (!filteredMessages.length) return;

    const lastMsg = filteredMessages[filteredMessages.length - 1];
    const isNewMessageFromOthers = lastMsg.sender_id !== profile?.id;

    if (isNewMessageFromOthers && !isNearBottomRef.current && scrollRef.current) {
      // Don't auto-scroll, just keep position.
      // The scroll container naturally stays where it is if content is added at the end,
      // unless we are using a virtualized list that might shift things.
    }
  }, [filteredMessages, profile]);

  useEffect(() => {
    if (showSearch) searchInputRef.current?.focus();
  }, [showSearch]);

  const dateFirstIndexes = useMemo(() => {
    const seen = new Set<string>();
    const result = new Set<number>();
    s.filteredMessages.forEach((msg, idx) => {
      const k = format(new Date(msg.created_at), 'yyyy-MM-dd');
      if (!seen.has(k)) {
        seen.add(k);
        result.add(idx);
      }
    });
    return result;
  }, [s.filteredMessages]);

  return (
    <div className="relative flex h-full w-full flex-col">
      <TeamChatHeader
        conversation={conversation}
        showDetails={showDetails}
        voiceId={s.tts.voiceId}
        speed={s.tts.speed}
        showSearch={s.showSearch}
        isMuted={s.isMuted}
        onBack={onBack}
        onToggleDetails={onToggleDetails}
        onToggleSearch={() => {
          s.setShowSearch(!s.showSearch);
          if (s.showSearch) s.setSearchQuery('');
        }}
        onAddMembers={() => s.setShowAddMembers(true)}
        onVoiceChange={s.tts.setVoiceId}
        onSpeedChange={s.tts.setSpeed}
        onToggleMute={() =>
          s.muteMutation.mutate({ conversationId: conversation.id, muted: !s.isMuted })
        }
        onToggleStats={() => setShowStats(showStats === 'participants' ? null : 'participants')}
        onTogglePerformance={() => setShowStats(showStats === 'performance' ? null : 'performance')}
        showStats={!!showStats}
      />

      <AnimatePresence>
        {s.showSearch && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="border-b border-border bg-card px-3 py-2"
          >
            <div className="flex items-center gap-2">
              <Search className="h-4 w-4 shrink-0 text-muted-foreground" />
              <Input
                ref={s.searchInputRef}
                value={s.searchQuery}
                onChange={(e) => s.syncSearchWithCache(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Escape') {
                    s.setShowSearch(false);
                    s.setSearchQuery('');
                  }
                }}
                placeholder="Buscar nas mensagens..."
                className="h-8 text-sm"
              />
              {s.searchQuery && (
                <span className="whitespace-nowrap text-xs text-muted-foreground">
                  {s.filteredMessages.length} resultado{s.filteredMessages.length !== 1 ? 's' : ''}
                </span>
              )}
              <Button
                aria-label="Fechar busca"
                size="icon"
                variant="ghost"
                className="h-7 w-7 shrink-0"
                onClick={() => {
                  s.setShowSearch(false);
                  s.setSearchQuery('');
                }}
              >
                <X className="h-3.5 w-3.5" />
              </Button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showStats && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="overflow-hidden border-b border-border bg-muted/30"
          >
            <div className="p-4">
              {showStats === 'participants' ? (
                <ParticipantStatsGraph conversationId={conversation.id} />
              ) : (
                <TeamPerformancePanel conversationId={conversation.id} />
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="relative min-h-0 flex-1 bg-background">
        <div
          ref={s.scrollRef}
          className="scrollbar-thin scrollbar-thumb-primary/20 hover:scrollbar-thumb-primary/40 absolute inset-0 overflow-auto"
          onScroll={(e) => {
            s.checkNearBottom();
            const el = e.target as HTMLDivElement;

            // Infinite scroll UP
            if (el.scrollTop < 100 && s.hasNextPage && !s.isFetchingNextPage) {
              s.fetchNextPage();
            }

            s.lastScrollTopRef.current = el.scrollTop;
          }}
          role="log"
          aria-label="Mensagens da conversa"
          aria-live="polite"
        >
          {!isDeptMember ? (
            <div className="flex h-full flex-col items-center justify-center p-8 text-center">
              <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-muted">
                <Lock className="h-8 w-8 text-muted-foreground" />
              </div>
              <h3 className="mb-2 text-lg font-bold">Conteúdo Protegido</h3>
              <p className="mb-6 max-w-sm text-sm text-muted-foreground">
                As mensagens deste departamento são privadas e restritas aos seus membros.
              </p>
              <div className="flex w-full max-w-[280px] flex-col gap-3">
                <div className="rounded-xl border border-border/50 bg-card p-3 text-left shadow-sm">
                  <p className="mb-1 flex items-center gap-1.5 text-xs font-semibold">
                    <Shield className="h-3 w-3 text-primary" /> Solicitar Acesso
                  </p>
                  <p className="text-[11px] leading-normal text-muted-foreground">
                    Contate o administrador do sistema para que ele associe seu perfil a este
                    departamento.
                  </p>
                </div>
                <div className="rounded-xl border border-border/50 bg-card p-3 text-left shadow-sm">
                  <p className="mb-1 flex items-center gap-1.5 text-xs font-semibold">
                    <Link2 className="h-3 w-3 text-primary" /> Entrar via Código
                  </p>
                  <p className="text-[11px] leading-normal text-muted-foreground">
                    Se você recebeu um código de convite, utilize-o para entrar automaticamente
                    através do link oficial.
                  </p>
                </div>
              </div>
            </div>
          ) : s.isLoading && !s.filteredMessages.length ? (
            <div className="space-y-3 p-4">
              {Array.from({ length: 4 }).map((_, i) => (
                <div key={i} className={cn('flex', i % 2 === 0 ? 'justify-start' : 'justify-end')}>
                  <Skeleton className="h-10 rounded-2xl" style={{ width: 120 + (i % 3) * 60 }} />
                </div>
              ))}
            </div>
          ) : s.filteredMessages.length === 0 ? (
            <div className="py-12 text-center text-sm text-muted-foreground">
              {s.searchQuery ? 'Nenhuma mensagem encontrada' : 'Envie a primeira mensagem!'}
            </div>
          ) : (
            <div className="relative flex h-full w-full flex-col">
              <AnimatePresence>
                {s.hasNewMessagesUnseen && (
                  <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: 20 }}
                    className="absolute bottom-4 left-1/2 z-20 -translate-x-1/2"
                  >
                    <Button
                      aria-label="Rolar para o final"
                      size="sm"
                      className="gap-2 rounded-full bg-primary text-primary-foreground shadow-lg hover:bg-primary/90"
                      onClick={s.scrollToBottom}
                    >
                      <ArrowDown className="h-4 w-4 animate-bounce" />
                      Pular para mensagens novas
                    </Button>
                  </motion.div>
                )}
              </AnimatePresence>

              {s.isFetchingNextPage && (
                <div className="animate-pulse p-2 text-center text-xs text-muted-foreground">
                  Carregando mensagens anteriores...
                </div>
              )}
              <div className="relative flex-1">
                <List
                  listRef={s.listRef}
                  rowCount={s.filteredMessages.length}
                  rowHeight={dynamicRowHeight}
                  rowProps={{}}
                  className="scrollbar-none absolute inset-0"
                  overscanCount={10}
                  rowComponent={({ index, style, ariaAttributes }) => {
                    const msg = s.filteredMessages[index];
                    const showDate = dateFirstIndexes.has(index);
                    const isMine = msg.sender_id === s.profile?.id;
                    const isEditing = s.editingId === msg.id;
                    const hasMedia = !!msg.media_url;
                    const repliedMsg = msg.reply_to_id
                      ? s.messages.find((m) => m.id === msg.reply_to_id)
                      : null;
                    const isThisTtsPlaying = s.tts.isPlaying && s.tts.currentMessageId === msg.id;
                    const isThisTtsLoading = s.tts.isLoading && s.tts.currentMessageId === msg.id;
                    const cleanText = msg.content
                      ?.replace(/\[.*?\]/g, '')
                      .replace(/https?:\/\/\S+/g, '')
                      .trim();

                    return (
                      <div
                        style={style}
                        {...ariaAttributes}
                        ref={(el) => {
                          if (el && !itemHeights.current[index]) {
                            const h = el.getBoundingClientRect().height;
                            if (h > 0) {
                              itemHeights.current[index] = h;
                              dynamicRowHeight.setRowHeight(index, h);
                            }
                          }
                        }}
                      >
                        <ContextMenu key={msg.id}>
                          <ContextMenuTrigger asChild>
                            <div
                              data-testid={`message-container-${msg.id}`}
                              className="group/msg relative px-4"
                            >
                              {showDate && (
                                <div className="flex justify-center py-2">
                                  <span className="rounded-full border border-border/10 bg-muted/20 px-3 py-1 text-[11px] font-medium text-muted-foreground">
                                    {formatDateSep(msg.created_at)}
                                  </span>
                                </div>
                              )}
                              <div
                                className={cn(
                                  'relative flex gap-2 py-0.5',
                                  isMine ? 'justify-end' : 'justify-start'
                                )}
                              >
                                {!isMine && (
                                  <Avatar className="mt-1 h-7 w-7 shrink-0">
                                    <AvatarImage src={msg.sender?.avatar_url || undefined} />
                                    <AvatarFallback className="bg-muted text-[10px]">
                                      {msg.sender?.name?.charAt(0) || '?'}
                                    </AvatarFallback>
                                  </Avatar>
                                )}

                                <div className={cn('relative max-w-[70%] space-y-1')}>
                                  <TeamQuickReactionBar
                                    messageId={msg.id}
                                    isMine={isMine}
                                    onToggle={(emoji) =>
                                      toggleReaction({ messageId: msg.id, emoji })
                                    }
                                    reactions={aggregate(msg.id)}
                                  />

                                  <div
                                    className={cn(
                                      'relative rounded-2xl px-3.5 py-2 shadow-none',
                                      isMine
                                        ? 'rounded-br-md bg-primary text-primary-foreground'
                                        : 'rounded-bl-md border border-border/20 bg-muted/30 text-foreground'
                                    )}
                                  >
                                    {!isMine && conversation.type === 'group' && (
                                      <p className="mb-1 text-[11px] font-bold text-primary opacity-90">
                                        {msg.sender?.name}
                                      </p>
                                    )}
                                    {repliedMsg && (
                                      <div
                                        className={cn(
                                          'mb-1.5 rounded border-l-2 px-2 py-1 text-[10px]',
                                          isMine
                                            ? 'border-primary-foreground/30 bg-primary-foreground/10'
                                            : 'border-muted-foreground/30 bg-muted/50'
                                        )}
                                      >
                                        <span className="font-medium">
                                          {repliedMsg.sender?.name}
                                        </span>
                                        <p className="flex items-center gap-1 truncate opacity-80">
                                          {repliedMsg.media_type && (
                                            <MediaTypeIcon type={repliedMsg.media_type} />
                                          )}
                                          {repliedMsg.content || 'Mídia'}
                                        </p>
                                      </div>
                                    )}
                                    {isEditing ? (
                                      <div className="space-y-1.5">
                                        <Input
                                          value={s.editText}
                                          onChange={(e) => s.setEditText(e.target.value)}
                                          onKeyDown={(e) => {
                                            if (e.key === 'Enter') s.handleSaveEdit();
                                            if (e.key === 'Escape') s.handleCancelEdit();
                                          }}
                                          className="h-7 bg-background text-sm text-foreground"
                                          autoFocus
                                        />
                                        <div className="flex justify-end gap-1">
                                          <Button
                                            aria-label="Cancelar edição"
                                            size="icon"
                                            variant="ghost"
                                            className="h-5 w-5"
                                            onClick={s.handleCancelEdit}
                                          >
                                            <X className="h-3 w-3" />
                                          </Button>
                                          <Button
                                            aria-label="Salvar edição"
                                            size="icon"
                                            variant="ghost"
                                            className="h-5 w-5"
                                            onClick={s.handleSaveEdit}
                                          >
                                            <Check className="h-3 w-3" />
                                          </Button>
                                        </div>
                                      </div>
                                    ) : (
                                      <>
                                        {hasMedia && <MediaContent msg={msg} />}
                                        {msg.content &&
                                          (!hasMedia || msg.media_type === 'document') && (
                                            <p className="whitespace-pre-wrap break-words text-sm leading-relaxed">
                                              <MarkdownPreview
                                                text={msg.content}
                                                className="inline"
                                              />
                                            </p>
                                          )}
                                        {msg.content &&
                                          hasMedia &&
                                          msg.media_type !== 'document' &&
                                          ![
                                            '🎨 Figurinha',
                                            '🎵 Áudio meme',
                                            '😀 Emoji',
                                            '🎤 Mensagem de áudio',
                                          ].includes(msg.content) && (
                                            <p className="mt-1 whitespace-pre-wrap break-words text-sm leading-relaxed">
                                              {msg.content}
                                            </p>
                                          )}
                                        <div
                                          className={cn(
                                            'mt-0.5 flex items-center gap-1',
                                            isMine ? 'justify-end' : 'justify-between'
                                          )}
                                        >
                                          {cleanText && (
                                            <button
                                              onClick={() =>
                                                isThisTtsPlaying
                                                  ? s.tts.stop()
                                                  : s.tts.speak(msg.content, msg.id)
                                              }
                                              className={cn(
                                                'rounded-full p-0.5 opacity-0 transition-opacity group-hover/msg:opacity-100',
                                                isMine
                                                  ? 'text-primary-foreground/60 hover:text-primary-foreground'
                                                  : 'text-muted-foreground hover:text-foreground'
                                              )}
                                            >
                                              {isThisTtsLoading ? (
                                                <Loader2 className="h-3 w-3 animate-spin" />
                                              ) : isThisTtsPlaying ? (
                                                <VolumeX className="h-3 w-3" />
                                              ) : (
                                                <Volume2 className="h-3 w-3" />
                                              )}
                                            </button>
                                          )}
                                          <div className="flex items-center gap-1">
                                            <span
                                              className={cn(
                                                'text-[10px]',
                                                isMine
                                                  ? 'text-primary-foreground/60'
                                                  : 'text-muted-foreground'
                                              )}
                                            >
                                              {formatTime(msg.created_at)}
                                              {msg.is_edited && ' · editado'}
                                            </span>
                                            {isMine && (
                                              <MessageStatus
                                                status={msg.status || 'sent'}
                                                className={cn(
                                                  'origin-right scale-75',
                                                  msg.status === 'read'
                                                    ? 'text-info'
                                                    : 'text-primary-foreground/60'
                                                )}
                                              />
                                            )}
                                          </div>
                                        </div>
                                      </>
                                    )}
                                  </div>
                                </div>
                              </div>
                              <MessageReactions
                                messageId={msg.id}
                                reactions={aggregate(msg.id)}
                                isMine={isMine}
                                isToggling={isToggling}
                                onToggle={(emoji) => toggleReaction({ messageId: msg.id, emoji })}
                              />
                            </div>
                          </ContextMenuTrigger>
                          <ContextMenuContent>
                            <ContextMenuSub>
                              <ContextMenuSubTrigger className="gap-2">
                                <SmilePlus className="h-3.5 w-3.5" /> Reagir
                              </ContextMenuSubTrigger>
                              <ContextMenuSubContent>
                                <div className="grid grid-cols-4 gap-1 p-1">
                                  {QUICK_EMOJIS.map((e) => (
                                    <Button
                                      key={e}
                                      size="icon"
                                      variant="ghost"
                                      onClick={() =>
                                        toggleReaction({ messageId: msg.id, emoji: e })
                                      }
                                      className="h-9 w-9 text-xl transition-all hover:scale-125 focus-visible:ring-2 focus-visible:ring-primary"
                                      aria-label={`Reagir com ${e}`}
                                    >
                                      {e}
                                    </Button>
                                  ))}
                                </div>
                              </ContextMenuSubContent>
                            </ContextMenuSub>
                            <ContextMenuItem onClick={() => s.setReplyTo(msg)} className="gap-2">
                              <Reply className="h-3.5 w-3.5" /> Responder
                            </ContextMenuItem>
                            <ContextMenuItem
                              onClick={() => s.handleCopyMessage(msg.content || '')}
                              className="gap-2"
                            >
                              <Copy className="h-3.5 w-3.5" /> Copiar Texto
                            </ContextMenuItem>
                            {isMine && (
                              <>
                                <ContextMenuSeparator />
                                <ContextMenuItem
                                  onClick={() => s.handleStartEdit(msg)}
                                  className="gap-2"
                                >
                                  <Pencil className="h-3.5 w-3.5" /> Editar
                                </ContextMenuItem>
                                <ContextMenuItem
                                  onClick={() => s.handleDelete(msg.id)}
                                  className="gap-2 text-destructive"
                                >
                                  <Trash2 className="h-3.5 w-3.5" /> Excluir
                                </ContextMenuItem>
                              </>
                            )}
                          </ContextMenuContent>
                        </ContextMenu>
                      </div>
                    );
                  }}
                />
              </div>
            </div>
          )}
        </div>
      </div>

      <AnimatePresence>
        {s.showScrollDown && (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 10 }}
            className="absolute bottom-24 left-1/2 z-10 flex -translate-x-1/2 flex-col items-center gap-2"
          >
            {s.hasNewMessagesUnseen && (
              <div className="animate-bounce rounded-full bg-primary px-2 py-0.5 text-[10px] font-bold text-primary-foreground shadow-md">
                Novas mensagens
              </div>
            )}
            <Button
              size="icon"
              variant="secondary"
              className="h-9 w-9 rounded-full border border-primary/20 shadow-lg"
              onClick={s.scrollToBottom}
            >
              <ArrowDown className="h-4 w-4" />
            </Button>
          </motion.div>
        )}
      </AnimatePresence>

      {isDeptMember ? (
        <TeamChatInputArea
          conversationId={conversation.id}
          text={s.text}
          setText={s.setText}
          replyTo={s.replyTo}
          isRecordingAudio={s.isRecordingAudio}
          isPending={s.sendMutation.isPending}
          onSend={s.handleSend}
          onCancelReply={() => s.setReplyTo(null)}
          onRecordToggle={() => s.setIsRecordingAudio(!s.isRecordingAudio)}
          onAudioSend={s.handleAudioSend}
          onSendSticker={s.handleSendSticker}
          onSendAudioMeme={s.handleSendAudioMeme}
          onSendCustomEmoji={s.handleSendCustomEmoji}
          onFileSent={s.handleFileSent}
        />
      ) : (
        <div className="flex flex-col items-center justify-center gap-2 border-t border-border bg-muted/30 p-6 text-center">
          <div className="flex h-10 w-10 items-center justify-center rounded-full bg-destructive/10">
            <Lock className="h-5 w-5 text-destructive" />
          </div>
          <p className="text-sm font-semibold text-foreground">Acesso Restrito ao Departamento</p>
          <p className="mb-4 max-w-xs text-xs text-muted-foreground">
            Você não faz parte deste departamento e não tem permissão para visualizar ou enviar
            mensagens.
          </p>
          <div className="max-w-xs rounded-xl border border-primary/10 bg-primary/5 p-4">
            <p className="mb-1 text-xs font-medium text-primary">Como obter acesso?</p>
            <p className="text-[11px] leading-relaxed text-muted-foreground">
              Solicite ao administrador da sua conta ou ao gestor do departamento que inclua você
              via painel de membros ou enviando um código de convite.
            </p>
          </div>
        </div>
      )}

      <AddMembersDialog
        open={s.showAddMembers}
        onOpenChange={s.setShowAddMembers}
        conversation={conversation}
      />
    </div>
  );
}

import { useState, useRef, useCallback, useEffect, useLayoutEffect } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { getLogger } from '@/lib/logger';
import { useAuth } from '@/features/auth';
import { useTextToSpeech } from '@/hooks/useTextToSpeech';
import { useUserSettings } from '@/hooks/useUserSettings';
import {
  useTeamMessages,
  useSendTeamMessage,
  useDeleteTeamMessage,
  useEditTeamMessage,
  useToggleMuteConversation,
  useUpdateTeamMessageStatus,
  TeamMessage,
  TeamConversation,
} from '@/hooks/useTeamChat';
import { supabase } from '@/integrations/supabase/client';
import { resolvePublicStorageUrl } from '@/lib/mediaUrl';
import { toast } from 'sonner';
import { useDebouncedValue } from '@/hooks/useDebounce';
import { usePerformanceMetrics } from '@/hooks/usePerformanceMonitoring';
import { ListImperativeAPI } from 'react-window';
import { queryKeys } from '@/services/api/queryKeys';

const log = getLogger('useTeamChatPanel');

/** use Team Chat Panel component for the team chat section. */
export function useTeamChatPanel(conversation: TeamConversation) {
  const { profile } = useAuth();
  const queryClient = useQueryClient();

  const [showSearch, setShowSearch] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const debouncedSearch = useDebouncedValue(searchQuery, 400);

  const {
    messages = [],
    isLoading,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
  } = useTeamMessages(conversation.id, debouncedSearch);

  const sendMutation = useSendTeamMessage();
  const deleteMutation = useDeleteTeamMessage();
  const editMutation = useEditTeamMessage();
  const muteMutation = useToggleMuteConversation();
  const updateStatusMutation = useUpdateTeamMessageStatus();

  const currentMember = conversation.members?.find((m) => m.profile_id === profile?.id);
  const isMuted = currentMember?.is_muted ?? false;

  const [text, setText] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editText, setEditText] = useState('');
  const [isRecordingAudio, setIsRecordingAudio] = useState(false);
  const [replyTo, setReplyTo] = useState<TeamMessage | null>(null);
  const [showScrollDown, setShowScrollDown] = useState(false);
  const [hasNewMessagesUnseen, setHasNewMessagesUnseen] = useState(false);
  const [showAddMembers, setShowAddMembers] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const listRef = useRef<ListImperativeAPI>(null); // Reference to react-window List
  const isNearBottomRef = useRef(true);
  const settingsTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const lastScrollTopRef = useRef(0);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const scrollOffsetRef = useRef<number>(0);
  const _anchorMessageIdRef = useRef<string | null>(null);

  // Performance metrics and instrumentation
  usePerformanceMetrics('TeamChatPanel');

  const { settings, updateSettings, saveSettings } = useUserSettings();
  const handleVoiceChange = (v: string) => {
    updateSettings({ tts_voice_id: v });
    if (settingsTimerRef.current) clearTimeout(settingsTimerRef.current);
    settingsTimerRef.current = setTimeout(() => saveSettings(), 100);
  };
  const handleSpeedChange = (s: number) => {
    updateSettings({ tts_speed: s });
    if (settingsTimerRef.current) clearTimeout(settingsTimerRef.current);
    settingsTimerRef.current = setTimeout(() => saveSettings(), 100);
  };
  const tts = useTextToSpeech({
    initialVoiceId: settings.tts_voice_id,
    initialSpeed: settings.tts_speed,
    onVoiceChange: handleVoiceChange,
    onSpeedChange: handleSpeedChange,
  } as any);

  // Unified function to sync search filter with the infinite query cache
  const syncSearchWithCache = useCallback(
    (newQuery: string) => {
      const start = performance.now();
      setSearchQuery(newQuery);

      // If clearing search, we might want to pre-populate or clean up
      if (!newQuery.trim()) {
        void queryClient.invalidateQueries({
          queryKey: queryKeys.teamChat.messages(conversation.id, ''),
        });
      }

      const duration = performance.now() - start;
      log.info(`Search sync duration: ${duration.toFixed(2)}ms`);
    },
    [conversation.id, queryClient]
  );

  const checkNearBottom = useCallback(() => {
    const el = scrollRef.current;
    if (!el) return;
    const threshold = 150;
    const nearBottom = el.scrollHeight - el.scrollTop - el.clientHeight < threshold;
    isNearBottomRef.current = nearBottom;
    setShowScrollDown(!nearBottom);
    if (nearBottom) {
      setHasNewMessagesUnseen(false);
    }
  }, []);

  const scrollToBottom = useCallback(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
      setHasNewMessagesUnseen(false);
      isNearBottomRef.current = true;
    }
  }, []);

  // Monitor new messages from others to show indicator
  useEffect(() => {
    if (!messages.length || isNearBottomRef.current) return;
    const lastMsg = messages[messages.length - 1];
    if (lastMsg && lastMsg.sender_id !== profile?.id) {
      setHasNewMessagesUnseen(true);
      setShowScrollDown(true); // Ensure indicator shows up
    }
  }, [messages, profile?.id]);

  useLayoutEffect(() => {
    // Scroll anchor for infinite scroll UP
    if (scrollRef.current && isFetchingNextPage) {
      scrollOffsetRef.current = scrollRef.current.scrollHeight - scrollRef.current.scrollTop;
      log.debug(`Captured scroll anchor offset: ${scrollOffsetRef.current}`);
    }
  }, [isFetchingNextPage]);

  useLayoutEffect(() => {
    // Apply scroll anchor after new messages are loaded from infinite scroll
    if (scrollOffsetRef.current > 0 && scrollRef.current && !isFetchingNextPage) {
      const newScrollTop = scrollRef.current.scrollHeight - scrollOffsetRef.current;
      scrollRef.current.scrollTop = newScrollTop;
      log.debug(`Applied scroll anchor. New scrollTop: ${newScrollTop}`);
      scrollOffsetRef.current = 0;
    }
  }, [messages.length, isFetchingNextPage]);

  // Keep scroll position when NEW messages arrive while scrolled up
  const lastMessageIdRef = useRef<string | null>(null);
  useLayoutEffect(() => {
    if (!messages.length) return;
    const latestMsg = messages[messages.length - 1];

    // If it's a truly NEW message (not just a reload)
    if (latestMsg.id !== lastMessageIdRef.current) {
      // If we are NOT at the bottom, we want to MAINTAIN current distance from top
      if (!isNearBottomRef.current && scrollRef.current && lastMessageIdRef.current) {
        // The browser usually handles this if adding at bottom, but virtual lists might jump.
        // We ensure it stays put.
        log.debug('Maintaining scroll position for incoming message');
      }
      lastMessageIdRef.current = latestMsg.id;
    }
  }, [messages]);

  const handleSend = useCallback(() => {
    const trimmed = text.trim();
    if (!trimmed || sendMutation.isPending) return;
    sendMutation.mutate(
      { conversationId: conversation.id, content: trimmed, replyToId: replyTo?.id },
      {
        onError: (err) => {
          log.error('Failed to send:', err);
          toast.error('Falha ao enviar mensagem.');
          setText(trimmed);
        },
      }
    );
    setText('');
    setReplyTo(null);
  }, [text, sendMutation, conversation.id, replyTo]);

  const handleSendMedia = useCallback(
    (mediaUrl: string, mediaType: string, content?: string) => {
      sendMutation.mutate(
        {
          conversationId: conversation.id,
          content: content || '',
          mediaUrl,
          mediaType,
          replyToId: replyTo?.id,
        },
        {
          onError: (err) => {
            log.error('Failed to send media:', err);
            toast.error('Falha ao enviar mídia.');
          },
        }
      );
      setReplyTo(null);
    },
    [sendMutation, conversation.id, replyTo]
  );

  const handleSendSticker = useCallback(
    (url: string) => handleSendMedia(url, 'sticker', '🎨 Figurinha'),
    [handleSendMedia]
  );
  const handleSendAudioMeme = useCallback(
    (url: string) => handleSendMedia(url, 'audio_meme', '🎵 Áudio meme'),
    [handleSendMedia]
  );
  const handleSendCustomEmoji = useCallback(
    (url: string) => handleSendMedia(url, 'emoji', '😀 Emoji'),
    [handleSendMedia]
  );
  const handleFileSent = useCallback(
    (mediaUrl: string, mediaType: string, fileName: string) =>
      handleSendMedia(mediaUrl, mediaType, fileName),
    [handleSendMedia]
  );

  const handleAudioSend = useCallback(
    async (blob: Blob) => {
      setIsRecordingAudio(false);
      try {
        const path = `${profile?.id}/${conversation.id}/${Date.now()}.webm`;
        const { error } = await supabase.storage
          .from('team-chat-files')
          .upload(path, blob, { contentType: 'audio/webm' });
        if (error) throw error;
        handleSendMedia(
          resolvePublicStorageUrl('team-chat-files', path) ?? '',
          'audio',
          '🎤 Mensagem de áudio'
        );
      } catch (err) {
        toast.error('Erro ao enviar áudio');
        log.error('Audio upload error:', err);
      }
    },
    [profile?.id, conversation.id, handleSendMedia]
  );

  const handleDelete = useCallback(
    (msgId: string) => {
      deleteMutation.mutate(
        { messageId: msgId, conversationId: conversation.id },
        {
          onError: (err) => {
            log.error('Failed to delete:', err);
            toast.error('Falha ao excluir.');
          },
        }
      );
    },
    [deleteMutation, conversation.id]
  );

  const handleStartEdit = useCallback((msg: TeamMessage) => {
    setEditingId(msg.id);
    setEditText(msg.content);
  }, []);
  const handleSaveEdit = useCallback(() => {
    if (!editingId || !editText.trim()) return;
    editMutation.mutate(
      { messageId: editingId, content: editText.trim(), conversationId: conversation.id },
      {
        onError: (err) => {
          log.error('Failed to edit:', err);
          toast.error('Falha ao editar.');
        },
      }
    );
    setEditingId(null);
    setEditText('');
  }, [editingId, editText, editMutation, conversation.id]);

  const handleCancelEdit = useCallback(() => {
    setEditingId(null);
    setEditText('');
  }, []);
  const handleCopyMessage = useCallback((content: string) => {
    navigator.clipboard
      .writeText(content)
      .then(() => toast.success('Copiado!'))
      .catch(() => toast.error('Erro ao copiar'));
  }, []);

  // Instrumentation for render cost and update time
  useEffect(
    () => () => {
      if (settingsTimerRef.current) clearTimeout(settingsTimerRef.current);
    },
    []
  );

  const renderStartTimeRef = useRef<number>(0);
  useEffect(() => {
    renderStartTimeRef.current = performance.now();
    return () => {
      const duration = performance.now() - renderStartTimeRef.current;
      if (duration > 16) {
        // Only log slow renders (> 1 frame)
        log.debug(`Slow render detected: ${duration.toFixed(2)}ms`);
      }
    };
  });

  return {
    profile,
    messages,
    isLoading,
    isMuted,
    filteredMessages: messages,
    text,
    setText,
    editingId,
    editText,
    setEditText,
    isRecordingAudio,
    setIsRecordingAudio,
    replyTo,
    setReplyTo,
    showScrollDown,
    hasNewMessagesUnseen,
    showAddMembers,
    setShowAddMembers,
    showSearch,
    setShowSearch,
    searchQuery,
    setSearchQuery,
    scrollRef,
    listRef,
    isNearBottomRef,
    searchInputRef,
    lastScrollTopRef,
    scrollOffsetRef,
    tts,
    muteMutation,
    sendMutation,
    updateStatusMutation,
    checkNearBottom,
    scrollToBottom,
    handleSend,
    handleSendSticker,
    handleSendAudioMeme,
    handleSendCustomEmoji,
    handleFileSent,
    handleAudioSend,
    handleDelete,
    handleStartEdit,
    handleSaveEdit,
    handleCancelEdit,
    handleCopyMessage,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
    debouncedSearch,
    syncSearchWithCache,
  };
}

import { queryKeys } from '@/services/api/queryKeys';
import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getLogger } from '@/lib/logger';

const log = getLogger('SicoobBridgeDashboard');
import {
  Building2,
  RefreshCw,
  ArrowDownLeft,
  ArrowUpRight,
  Users,
  MessageSquare,
  CheckCircle,
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { supabase } from '@/integrations/supabase/client';
import { isValidUUID } from '@/utils/uuid';

interface SicoobMapping {
  id: string;
  contact_id: string;
  sicoob_user_id: string;
  sicoob_vendedor_id: string;
  sicoob_singular_id: string;
  zappweb_agent_id: string | null;
  created_at: string;
}

interface SicoobMessage {
  id: string;
  content: string;
  sender: string;
  created_at: string;
  contact_id: string;
  status: string;
}

/** Sicoob Bridge Dashboard component. */
export function SicoobBridgeDashboard() {
  const { data, isFetching, refetch } = useQuery({
    queryKey: queryKeys.adminOps.sicoobBridge(),
    queryFn: async () => {
      try {
        const { data: mappingData } = await supabase
          .from('sicoob_contact_mapping')
          .select('*')
          .order('created_at', { ascending: false })
          .limit(50);

        const mappings = (mappingData || []) as SicoobMapping[];
        const contactIds = mappings.map((m) => m.contact_id).filter(isValidUUID);

        let recentMessages: SicoobMessage[] = [];
        if (contactIds.length > 0) {
          const { data: msgData } = await supabase
            .from('messages')
            .select('id, content, sender, created_at, contact_id, status')
            .in('contact_id', contactIds.slice(0, 20))
            .order('created_at', { ascending: false })
            .limit(30);
          recentMessages = (msgData || []) as SicoobMessage[];
        }

        return { mappings, recentMessages };
      } catch (err) {
        log.warn('Failed to load Sicoob data:', err);
        return { mappings: [] as SicoobMapping[], recentMessages: [] as SicoobMessage[] };
      }
    },
  });

  const mappings = data?.mappings ?? [];
  const recentMessages = data?.recentMessages ?? [];
  const loading = isFetching;
  const loadData = () => {
    void refetch();
  };

  const { inbound, outbound, uniqueSingulars } = useMemo(
    () => ({
      inbound: recentMessages.filter((m) => m.sender === 'contact').length,
      outbound: recentMessages.filter((m) => m.sender === 'agent').length,
      uniqueSingulars: new Set(mappings.map((m) => m.sicoob_singular_id)).size,
    }),
    [recentMessages, mappings]
  );

  return (
    <div className="space-y-6 p-6">
      {/* Header */}
      <div className="flex items-center gap-3">
        <div className="rounded-xl bg-primary/10 p-2">
          <Building2 className="h-5 w-5 text-primary" />
        </div>
        <div>
          <h2 className="text-xl font-bold">Sicoob Bridge</h2>
          <p className="text-sm text-muted-foreground">
            Status da integração Sicoob Gifts → ZappWeb
          </p>
        </div>
        <Button
          variant="outline"
          size="sm"
          className="ml-auto h-8 text-xs"
          onClick={loadData}
          disabled={loading}
        >
          <RefreshCw className={`mr-1 h-3 w-3 ${loading ? 'animate-spin' : ''}`} /> Atualizar
        </Button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 gap-4 md:grid-cols-4">
        <Card>
          <CardContent className="pb-4 pt-4 text-center">
            <p className="text-2xl font-bold text-primary">{mappings.length}</p>
            <p className="text-xs text-muted-foreground">Contatos Mapeados</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pb-4 pt-4 text-center">
            <p className="text-2xl font-bold text-foreground">{uniqueSingulars}</p>
            <p className="text-xs text-muted-foreground">Singulares</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pb-4 pt-4 text-center">
            <div className="flex items-center justify-center gap-1">
              <ArrowDownLeft className="h-4 w-4 text-success" />
              <p className="text-2xl font-bold text-success">{inbound}</p>
            </div>
            <p className="text-xs text-muted-foreground">Recebidas</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pb-4 pt-4 text-center">
            <div className="flex items-center justify-center gap-1">
              <ArrowUpRight className="h-4 w-4 text-info" />
              <p className="text-2xl font-bold text-info">{outbound}</p>
            </div>
            <p className="text-xs text-muted-foreground">Enviadas</p>
          </CardContent>
        </Card>
      </div>

      {/* Bridge Endpoints */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-base">
            <CheckCircle className="h-5 w-5 text-success" /> Endpoints da Bridge
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="space-y-1 rounded-lg border bg-muted/50 p-3 text-xs">
            <p>
              <Badge variant="secondary" className="mr-2 text-[9px]">
                POST
              </Badge>{' '}
              /functions/v1/sicoob-bridge
            </p>
            <p className="pl-16 text-muted-foreground">
              → Recebe mensagens do Sicoob (action: new_message, mark_read)
            </p>
          </div>
          <div className="space-y-1 rounded-lg border bg-muted/50 p-3 text-xs">
            <p>
              <Badge variant="secondary" className="mr-2 text-[9px]">
                AUTO
              </Badge>{' '}
              /functions/v1/sicoob-bridge-reply
            </p>
            <p className="pl-16 text-muted-foreground">
              → Trigger automático ao responder contato Sicoob
            </p>
          </div>
          <p className="text-xs text-muted-foreground">
            Auth: Bearer token via secret{' '}
            <code className="rounded bg-muted px-1">SICOOB_BRIDGE_SECRET</code>
          </p>
        </CardContent>
      </Card>

      {/* Recent Messages */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-base">
            <MessageSquare className="h-5 w-5" /> Mensagens Recentes
            <Badge variant="secondary" className="ml-auto text-[10px]">
              {recentMessages.length}
            </Badge>
          </CardTitle>
        </CardHeader>
        <CardContent>
          {recentMessages.length === 0 ? (
            <p className="py-8 text-center text-sm text-muted-foreground">
              Nenhuma mensagem Sicoob ainda. A bridge registrará atividade aqui.
            </p>
          ) : (
            <div className="max-h-[400px] space-y-2 overflow-auto">
              {recentMessages.map((msg) => (
                <div key={msg.id} className="flex items-start gap-3 rounded-lg border bg-card p-3">
                  {msg.sender === 'contact' ? (
                    <ArrowDownLeft className="mt-0.5 h-4 w-4 shrink-0 text-success" />
                  ) : (
                    <ArrowUpRight className="mt-0.5 h-4 w-4 shrink-0 text-info" />
                  )}
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-sm">{msg.content}</p>
                    <div className="mt-1 flex items-center gap-2">
                      <span className="text-xs text-muted-foreground">
                        {new Date(msg.created_at).toLocaleString('pt-BR')}
                      </span>
                      <Badge variant="outline" className="text-[9px]">
                        {msg.sender === 'contact' ? 'Sicoob → Zapp' : 'Zapp → Sicoob'}
                      </Badge>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Mappings */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-base">
            <Users className="h-5 w-5" /> Mapeamento de Contatos
          </CardTitle>
        </CardHeader>
        <CardContent>
          {mappings.length === 0 ? (
            <p className="py-4 text-center text-sm text-muted-foreground">
              Nenhum mapeamento criado.
            </p>
          ) : (
            <div className="max-h-[300px] overflow-auto">
              <table className="w-full text-xs">
                <thead className="sticky top-0 bg-background">
                  <tr className="border-b">
                    <th scope="col" className="p-2 text-left font-medium text-muted-foreground">
                      Singular ID
                    </th>
                    <th scope="col" className="p-2 text-left font-medium text-muted-foreground">
                      Sicoob User
                    </th>
                    <th scope="col" className="p-2 text-left font-medium text-muted-foreground">
                      Vendedor
                    </th>
                    <th scope="col" className="p-2 text-left font-medium text-muted-foreground">
                      Data
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {mappings.map((m) => (
                    <tr key={m.id} className="border-b hover:bg-muted/30">
                      <td className="p-2">{m.sicoob_singular_id}</td>
                      <td className="max-w-[150px] truncate p-2">{m.sicoob_user_id}</td>
                      <td className="max-w-[150px] truncate p-2">{m.sicoob_vendedor_id}</td>
                      <td className="p-2 text-muted-foreground">
                        {new Date(m.created_at).toLocaleDateString('pt-BR')}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

/**
 * Admin Management Hook — Unified orchestration of all admin panel integrations.
 * Consolidates 7 domain-specific hooks into one comprehensive module.
 *
 * Sections:
 * 1. Automations — Rule management, trigger types, channels, departments
 * 2. Channels — Service channel CRUD, routing, queue binding
 * 3. Queues — Queue management, members, skills, distribution algorithms
 * 4. Departments — Department CRUD, member counts, activation
 * 5. Roles — User role assignment, role-based access control
 * 6. Permissions — Route-level permissions, role filtering
 * 7. Security — HMAC self-tests, webhook validation, audit logging
 * 8. Orchestration — Main hook combining all domains
 */

import { useState, useCallback, useEffect, useMemo } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { safeClient, safeFrom } from '@/integrations/supabase/safeClient';
import { queryKeys } from '@/services/api/queryKeys';
import { toast } from 'sonner';
import { useToast } from '@/hooks/use-toast';
import { log, getLogger } from '@/lib/logger';
import { invalidateRouteRolesCache } from '@/features/auth';
import { normalizeProfileRef, type AdminProfileRef } from '../utils/profileMappers';
import type { AppRole } from '@/features/auth';

// ─── Type Exports ────────────────────────────────────────────────────────────

// Automations
/** Trigger Type type alias. */
export type TriggerType =
  'first_response_pending' | 'inactivity' | 'tag_applied' | 'tag_removed' | 'keyword_match';

/** Trigger Config interface definition. */
export interface TriggerConfig {
  threshold_seconds?: number;
  side?: string;
  keywords?: string[];
  tags?: string[];
  tag?: string;
  [key: string]: unknown;
}

/** Rule Actions interface definition. */
export interface RuleActions {
  suggest_reply?: boolean;
  auto_send?: boolean;
  apply_tags?: string[];
  ai_prompt?: string;
  template?: string;
  escalate_sla?: {
    enabled?: boolean;
    level?: string;
    reason?: string;
  };
  [key: string]: unknown;
}

/** Rule interface definition. */
export interface Rule {
  id: string;
  name: string;
  description: string | null;
  is_active: boolean;
  trigger_type: TriggerType;
  trigger_config: TriggerConfig;
  actions: RuleActions;
