// ---------------------------------------------------------------------------
// Utilitário de timeout para promises — definido no escopo do módulo para
// evitar recriação em cada render do AuthProvider.
//
// Cancela o timer interno quando a promise resolve antes do timeout (evita
// timers órfãos que ficavam ativos por até 5s depois do resultado chegar).
// ---------------------------------------------------------------------------
function withTimeout<T>(promise: Promise<T>, ms: number, label: string): Promise<T> {
  let timerId: ReturnType<typeof setTimeout>;
  const timeoutPromise = new Promise<T>((_, reject) => {
    timerId = setTimeout(() => reject(new Error(`[Auth] Timeout (${ms}ms) em ${label}`)), ms);
  });
  return Promise.race([promise, timeoutPromise]).finally(() => clearTimeout(timerId));
}

// ---------------------------------------------------------------------------
// Leitura SÍNCRONA da sessão persistida (localStorage) para hidratação otimista.
//
// O supabase-js persiste a sessão em `sb-<ref>-auth-token`. No boot, em vez de
// bloquear o first paint numa chamada de rede (getSession() força um refresh de
// token sob o navigator.locks e pode pendurar por segundos quando o lock está
// contido ou o edge trava), lemos a sessão já gravada e renderizamos na hora.
// O onAuthStateChange do supabase-js continua sendo a fonte de verdade: emite
// TOKEN_REFRESHED em sucesso ou SIGNED_OUT se o refresh token for inválido,
// reconciliando o estado no próximo tick. Isto NÃO substitui o refresh — apenas
// impede que uma revalidação lenta transforme uma sessão válida numa tela de erro.
//
// Robusto a: storage inacessível (modo privado), valor em base64 (UTF-8), chunks
// (`...-auth-token.0/.1`), ao shape legado v1 (`{ currentSession }`) e a sessões
// com expires_at malformado (null, string, NaN, Infinity, ≤0).
// ---------------------------------------------------------------------------
function readPersistedSession(): Session | null {
  if (typeof window === 'undefined') return null;
  let raw: string | null = null;
  try {
    const keys = Object.keys(localStorage).filter((k) => k.includes('-auth-token'));
    if (keys.length === 0) return null;
    // Chave-base = a mais curta que casa (chunks acrescentam sufixo `.N`).
    const baseKey =
      keys.filter((k) => /-auth-token$/.test(k)).sort((a, b) => a.length - b.length)[0] ??
      keys.sort((a, b) => a.length - b.length)[0];
    const chunkKeys = keys
      .filter((k) => k.startsWith(`${baseKey}.`))
      .sort((a, b) => Number(a.slice(baseKey.length + 1)) - Number(b.slice(baseKey.length + 1)));
    raw =
      chunkKeys.length > 0
        ? chunkKeys.map((k) => localStorage.getItem(k) ?? '').join('')
        : localStorage.getItem(baseKey);
  } catch {
    // localStorage bloqueado por política do browser — segue o fluxo normal.
    return null;
  }
  if (!raw) return null;

  const tryParse = (text: string): Session | null => {
    try {
      const parsed = JSON.parse(text) as
        (Session & { currentSession?: Session }) | { currentSession?: Session };
      const session = (
        'access_token' in parsed && parsed.access_token
          ? parsed
          : (parsed as { currentSession?: Session }).currentSession
      ) as Session | undefined;
      if (!session?.user || !session?.refresh_token) return null;
      // Valida expires_at: deve ser número positivo finito (rejeita null, strings,
      // NaN, Infinity, 0, negativos — todos indicam sessão corrompida ou inválida).
      const exp = session.expires_at;
      if (typeof exp !== 'number' || !isFinite(exp) || exp <= 0) return null;
      return session;
    } catch {
      return null;
    }
  };

  // Caminho comum (localStorage puro): JSON direto.
  const direct = tryParse(raw);
  if (direct) return direct;

  // Fallback: valor prefixado `base64-` (decodifica UTF-8 corretamente).
  if (raw.startsWith('base64-')) {
    try {
      const bin = atob(raw.slice('base64-'.length));
      const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
      return tryParse(new TextDecoder().decode(bytes));
    } catch {
      return null;
    }
  }
  return null;
}

/**
 * Componente central que fornece o estado de autenticação para toda a aplicação.
 * Encapsula a lógica de sessão do Supabase e sincronização do perfil do usuário.
 */
export function AuthProvider({ children }: { children: ReactNode }) {
  const queryClient = useQueryClient();

  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [roles, setRoles] = useState<string[]>([]);
  const [permissions, setPermissions] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [bootstrapError, setBootstrapError] = useState<'timeout' | 'offline' | null>(null);
  const [bootstrapElapsedMs, setBootstrapElapsedMs] = useState<number | null>(null);

  const fetchProfile = useCallback(async (userId: string) => {
    try {
      const { data, error } = await withTimeout(authService.getProfile(userId), 8000, 'getProfile');
      if (error || !data) {
        log.error('[Auth] Failed to fetch profile for user:', userId, error);
        return;
      }
      setProfile(data);
    } catch (err: unknown) {
      log.error('[Auth] Failed to fetch profile for user:', userId, err);
    }
  }, []);

  const fetchRolesAndPermissions = useCallback(async (userId: string) => {
    try {
      if (!supabase) {
        log.error('[Auth] Supabase client not initialized for user:', userId);
        return;
      }
      const { data: userRoles, error } = await withTimeout(
        Promise.resolve(supabase.from('user_roles').select('role').eq('user_id', userId)),
        8000,
        'fetchRoles'
      );
      if (error || !userRoles) {
        log.error('[Auth] Failed to fetch roles for user:', userId, error);
        return;
      }
      const roleNames = userRoles.map((r) => r.role as string);
      setRoles(roleNames);

      const { data: userPermissions, error: permError } = await withTimeout(
        Promise.resolve(
          supabase
            .from('role_permissions')
            // FIX #1: Schema correto — role_permissions tem (role, permission_id), não 'permission'
            // JOIN com permissions table para resolver nomes das permissões
            .select('permission_id, permissions!inner(name)')
            .in('role', roleNames)
        ),
        8000,
        'fetchPermissions'
      );
      if (permError || !userPermissions) {
        log.error('[Auth] Failed to fetch permissions for user:', userId, permError);
        return;
      }
      const permNames = userPermissions
        .map((p) => {
          // p.permissions pode ser array (PostgREST join) ou objeto
          const perm = Array.isArray(p.permissions) ? p.permissions[0] : p.permissions;
          return (perm as { name?: string } | null)?.name;
        })
        .filter((n): n is string => typeof n === 'string');
      setPermissions(permNames);
    } catch (err: unknown) {
      log.error('[Auth] Failed to fetch roles/permissions for user:', userId, err);
    }
  }, []);

  const fetchRoles = useCallback(
    (userId: string) => fetchRolesAndPermissions(userId),
    [fetchRolesAndPermissions]
  );
  const fetchPermissions = useCallback(
    (userId: string) => fetchRolesAndPermissions(userId),
    [fetchRolesAndPermissions]
  );
  const refreshAll = useCallback(
    async (userId: string, options: { showLoading?: boolean } = {}) => {
      const { showLoading = true } = options;
      if (showLoading) setLoading(true);
      await Promise.all([fetchProfile(userId), fetchRolesAndPermissions(userId)]);
      setLoading(false);
    },
    [fetchProfile, fetchRolesAndPermissions]
  );

  const bootstrapRunRef = useRef(0);
  // Ref para o safety-net timeout de bootstrap — acessível por runBootstrap
  // para cancelar quando o bootstrap resolve ANTES de onAuthStateChange disparar.
  // Sem essa ref, utilizadores sem sessão recebem bootstrapError='timeout'
  // espúrio 10s após o carregamento (BUG C).
  const bootstrapTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const clearBootstrapSafetyNet = useCallback(() => {
    if (bootstrapTimeoutRef.current !== null) {
      clearTimeout(bootstrapTimeoutRef.current);
      bootstrapTimeoutRef.current = null;
    }
  }, []);

  const runBootstrap = useCallback(async () => {
    const runId = ++bootstrapRunRef.current;
    setLoading(true);
    setBootstrapError(null);

    // ── 1) Hidratação otimista a partir da sessão persistida (SEM rede) ──────
    // Se há sessão gravada, renderizamos imediatamente com a identidade em
    // cache. NÃO bloqueamos o first paint numa chamada de rede. O
    // onAuthStateChange reconcilia depois (TOKEN_REFRESHED / SIGNED_OUT).
    const cached = readPersistedSession();
    if (cached?.user) {
      if (runId !== bootstrapRunRef.current) return;
      setSession(cached);
      setUser(cached.user);
      // profile/roles em background — guards internos evitam corrida com o
      // refetch que o onAuthStateChange dispara em seguida.
      void refreshAll(cached.user.id, { showLoading: false }).catch((err) => {
        log.error('[Auth] Erro ao atualizar perfil/roles em background pós-hidratação:', err);
      });
      setLoading(false);
      // Já temos sessão utilizável → o safety-net não deve marcar timeout.
      clearBootstrapSafetyNet();
    } else {
      // ── Offline sem cache: sinaliza para o ProtectedRoute exibir UI de offline ──
      // Sem sessão persistida E sem rede → não há o que fazer além de avisar o utilizador.
      // Quando a rede voltar, o listener 'online' no useEffect dispara retryBootstrap()
      // automaticamente. Com rede: fast-fall para /auth como antes.
      //
      // guard de try/catch: navigator.onLine pode lançar em ambientes restritos
      // (ex.: extensões de browser, workers com políticas estritas).
      const isOffline = (() => {
        try {
          return typeof navigator !== 'undefined' && !navigator.onLine;
        } catch {
          return false;
        }
      })();
      if (isOffline) {
        log.warn('[Auth] Dispositivo offline e sem sessão local — aguardando rede.');
        setLoading(false);
        setBootstrapError('offline');
        setBootstrapElapsedMs(0);
        clearBootstrapSafetyNet();
        return;
      }
      // Sem sessão persistida → não há o que recuperar: pula getSession() e vai
      // direto para a tela de login. (Fast-fall: evita HTTP desnecessário.)
      // Object.keys(localStorage) já é tolerado por readPersistedSession (que
      // trata SecurityError em modo privado retornando null).
      log.info('[Auth] Sem sessão local — indo para login.');
      setLoading(false);
      setBootstrapElapsedMs(0);
      clearBootstrapSafetyNet();
      return;
    }

    // ── 2) Revalidação em BACKGROUND — não bloqueia o app já renderizado ─────
    // getSession() dispara o refresh single-flight sob o navigator.locks do
    // supabase-js. Se travar (lock contido / edge lento), o withTimeout rejeita,
    // mas como já hidratámos do cache isto NÃO é fatal: o onAuthStateChange é a
    // fonte de verdade e promove ou rebaixa a sessão no próximo tick. Nunca mais
    // transformamos uma revalidação lenta numa tela de erro para quem tem sessão.
    const startedAt = typeof performance !== 'undefined' ? performance.now() : Date.now();
    try {
      const result = await withTimeout(supabase.auth.getSession(), 8000, 'getSession');
      if (runId !== bootstrapRunRef.current) return;
      const elapsedMs = Math.round(
        (typeof performance !== 'undefined' ? performance.now() : Date.now()) - startedAt
      );
      setBootstrapElapsedMs(elapsedMs);
      log.info(
        `[Auth] getSession OK em ${elapsedMs}ms — session=${result.data.session ? 'present' : 'null'}`
      );
      // Se o backend confirmar que NÃO há sessão (refresh token revogado/expirado),
      // o supabase-js emite SIGNED_OUT via onAuthStateChange e o app vai para /auth.
    } catch (err) {
      if (runId !== bootstrapRunRef.current) return;
      const elapsedMs = Math.round(
        (typeof performance !== 'undefined' ? performance.now() : Date.now()) - startedAt
      );
      setBootstrapElapsedMs(elapsedMs);
      // Não-fatal: já renderizámos a partir do cache. Apenas registamos.
      log.warn(
        `[Auth] Revalidação em background lenta (${elapsedMs}ms) — mantendo sessão do cache. URL=${SUPABASE_RESOLVED_URL}`,
        err
      );
    }
  }, [refreshAll, clearBootstrapSafetyNet]);

  // Ref (para guards síncronos) + state (para reativos na UI) de retry em andamento.
  const isRetryingRef = useRef(false);
  const [isRetrying, setIsRetrying] = useState(false);

  const retryBootstrap = useCallback(async () => {
    // Idempotência: ignora tap duplo enquanto já há um retry em andamento.
    if (isRetryingRef.current) {
      log.debug('[Auth] retryBootstrap: retry já em andamento — ignorando.');
      return;
    }
    isRetryingRef.current = true;
    setIsRetrying(true);
    // Reseta o safety-net timeout para o retry — sem isso, se getSession
    // travar durante uma retentativa, loading=true fica preso para sempre
    // (bootstrapTimeoutRef foi zerado quando o primeiro erro foi setado).
    if (bootstrapTimeoutRef.current !== null) {
      clearTimeout(bootstrapTimeoutRef.current);
    }
    bootstrapTimeoutRef.current = setTimeout(() => {
      log.error('[Auth] Bootstrap safety-net (10s) no retry — forçando loading=false.');
      setBootstrapError((prev) => prev ?? 'timeout');
      setLoading(false);
      bootstrapTimeoutRef.current = null;
      isRetryingRef.current = false;
      setIsRetrying(false);
    }, 10000);
    try {
      await runBootstrap();
    } finally {
      isRetryingRef.current = false;
      setIsRetrying(false);
    }
  }, [runBootstrap]);

  useEffect(() => {
    let mounted = true;

    if (!verifyHttpOnlyCookieAuth()) {
      log.error('[Auth] Security check failed: httpOnly cookies not properly configured');
    }

    // Safety net final (10s): failsafe para caminhos imprevistos.
    //
    // NOTA DE DESIGN: Em execução normal, clearBootstrapSafetyNet() é chamado
    // SINCRONAMENTE dentro de runBootstrap() (antes do primeiro await) em AMBOS
    // os ramos (cache-hit e no-cache). Logo este timer é sempre cancelado antes
    // de disparar no boot inicial — permanece aqui como proteção contra regressões
    // futuras (ex.: se um caminho novo omitir clearBootstrapSafetyNet).
    //
    // Nos retries via retryBootstrap(), o timer é re-armado intencionalmente
    // para cobrir o getSession() que roda em foreground (pode travar).
    bootstrapTimeoutRef.current = setTimeout(() => {
      if (!mounted) return;
      log.error('[Auth] Bootstrap safety-net (10s) — forçando loading=false.');
      setBootstrapError((prev) => prev ?? 'timeout');
      setLoading(false);
      bootstrapTimeoutRef.current = null;
    }, 10000);

    log.info(`[Auth] Supabase URL em uso: ${SUPABASE_RESOLVED_URL}`);
    void runBootstrap();

    const subscription = authService.onAuthStateChange((event, session) => {
      if (!mounted) return;
      log.info(`[Auth] Event: ${event}`);
      if (bootstrapTimeoutRef.current !== null) {
        clearTimeout(bootstrapTimeoutRef.current);
        bootstrapTimeoutRef.current = null;
      }
      setBootstrapError(null);

      setSession(session);
      setUser(session?.user ?? null);

      if (session?.user) {
        // TOKEN_REFRESHED é renovação silenciosa — não exibir loading (I06).
        // INITIAL_SESSION apenas confirma a sessão que já hidratámos do cache no
        // boot → também silencioso, senão pisca o spinner logo após o first paint.
        // SIGNED_IN, USER_UPDATED etc. implicam mudança de identidade → loading.
        const showLoading = event !== 'TOKEN_REFRESHED' && event !== 'INITIAL_SESSION';
        refreshAll(session.user.id, { showLoading });
      } else {
        setProfile(null);
        setRoles([]);
        setPermissions([]);
        setLoading(false);
      }
    });

    // ── Auto-reconnect: quando a rede volta após estado 'offline' ──────────────
    // O listener 'online' dispara retryBootstrap() automaticamente para que o
    // utilizador não precise recarregar a página manualmente.
    const handleOnline = () => {
      if (!mounted) return;
      log.info('[Auth] Rede restaurada — disparando retry de bootstrap.');
      void retryBootstrap();
    };
    if (typeof window !== 'undefined') {
      window.addEventListener('online', handleOnline);
    }

    return () => {
      mounted = false;
      if (typeof window !== 'undefined') {
        window.removeEventListener('online', handleOnline);
      }
      if (bootstrapTimeoutRef.current !== null) {
        clearTimeout(bootstrapTimeoutRef.current);
        bootstrapTimeoutRef.current = null;
      }
      subscription.unsubscribe();
    };
  }, [refreshAll, runBootstrap, retryBootstrap]);

  useEffect(() => {
    if (!user) return;

    // zapp.profiles / zapp.user_roles são as tabelas físicas.
    // public.profiles / public.user_roles são VIEW proxies → nunca emitem CDC.
    const profileChannel = supabase
      .channel(`profile-updates-${user.id}`)
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'zapp',
          table: 'profiles',
          // profiles.id is a surrogate UUID; auth.uid() lives in profiles.user_id
          filter: `user_id=eq.${user.id}`,
        },
        () => {
          void fetchProfile(user.id);
        }
      )
      .subscribe();

    const rolesChannel = supabase
      .channel(`roles-updates-${user.id}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'zapp',
          table: 'user_roles',
          filter: `user_id=eq.${user.id}`,
        },
        () => {
          void fetchRolesAndPermissions(user.id);
        }
      )
      .subscribe();

    return () => {
      profileChannel.unsubscribe();
      supabase.removeChannel(profileChannel);
      rolesChannel.unsubscribe();
      supabase.removeChannel(rolesChannel);
    };
  }, [user, fetchProfile, fetchRolesAndPermissions]);

  const signIn = useCallback(
    async (email: string, password: string) => {
      try {
        const { data, error } = await authService.signIn(email, password);
        if (error) return { error };
        if (data?.user) {
          await refreshAll(data.user.id);
        }
        return { error: null };
      } catch (e) {
        log.error('[Auth] Sign in error:', e);
        return { error: e as any };
      }
    },
    [refreshAll]
  );

  const signUp = useCallback(
    async (email: string, password: string, name: string) => {
      try {
        const { data, error } = await authService.signUp(email, password, name);
        if (error) return { error };
        if (data?.user) {
          await refreshAll(data.user.id);
        }
        return { error: null };
      } catch (e) {
        log.error('[Auth] Sign up error:', e);
        return { error: e as any };
      }
    },
    [refreshAll]
  );

  const signOut = useCallback(async () => {
    try {
      await authService.signOut();
      setUser(null);
      setSession(null);
      setProfile(null);
      setRoles([]);
      setPermissions([]);
      setLoading(false);
      queryClient.clear();
    } catch (e) {
      log.error('[Auth] Sign out error:', e);
    }
  }, [queryClient]);

  const refreshProfile = useCallback(async () => {
    if (!user) return;
    await fetchProfile(user.id);
  }, [user, fetchProfile]);

  const refreshRoles = useCallback(async () => {
    if (!user) return;
    await fetchRolesAndPermissions(user.id);
  }, [user, fetchRolesAndPermissions]);

  const refreshPermissions = useCallback(async () => {
    if (!user) return;
    await fetchRolesAndPermissions(user.id);
  }, [user, fetchRolesAndPermissions]);

  const contextValue = useMemo(
    () => ({
      user,
      session,
      profile,
      roles,
      permissions,
      loading,
      bootstrapError,
      bootstrapElapsedMs,
      isRetrying,
      retryBootstrap,
      signIn,
      signUp,
      signOut,
      refreshProfile,
      refreshRoles,
      refreshPermissions,
    }),
    [
      user,
      session,
      profile,
      roles,
      permissions,
      loading,
      bootstrapError,
      bootstrapElapsedMs,
      isRetrying,
      retryBootstrap,
      signIn,
      signUp,
      signOut,
      refreshProfile,
      refreshRoles,
      refreshPermissions,
    ]
  );

  return <AuthContext.Provider value={contextValue}>{children}</AuthContext.Provider>;
}

import { useCallback, useMemo } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { getLogger } from '@/lib/logger';
import { isValidUUID } from '@/utils/uuid';

const log = getLogger('useContactCustomFields');

/** Hook: Custom Field. */
export interface CustomField {
  id: string;
  contact_id: string;
  field_name: string;
  field_value: string | null;
  field_type: string;
  created_at: string;
  updated_at: string;
}

/** Hook: use Contact Custom Fields. */
export function useContactCustomFields(contactId: string | undefined) {
  const queryClient = useQueryClient();
  const queryKey = useMemo(() => ['contact-custom-fields', contactId] as const, [contactId]);

  const { data: fields = [], isLoading } = useQuery({
    queryKey,
    queryFn: async (): Promise<CustomField[]> => {
      const { data, error } = await supabase
        .from('contact_custom_fields')
        .select('*')
        .eq('contact_id', contactId!)
        .order('field_name');
      if (error) {
        log.error('Error fetching custom fields:', error);
        throw error;
      }
      return (data || []) as CustomField[];
    },
    enabled: !!contactId && isValidUUID(contactId),
    staleTime: 30_000,
  });

  const addField = useCallback(
    async (fieldName: string, fieldValue: string, fieldType = 'text') => {
      if (!contactId || !isValidUUID(contactId)) return;
      try {
        const { error } = await supabase.from('contact_custom_fields').upsert({
          contact_id: contactId,
          field_name: fieldName,
          field_value: fieldValue,
          field_type: fieldType,
        });
        if (error) throw error;
        void queryClient.invalidateQueries({ queryKey });
      } catch (err) {
        log.error('Error adding custom field:', err);
        throw err;
      }
    },
    [contactId, queryClient, queryKey]
  );

  const removeField = useCallback(
    async (fieldId: string) => {
      try {
        const { error } = await supabase.from('contact_custom_fields').delete().eq('id', fieldId);
        if (error) throw error;
        queryClient.setQueryData<CustomField[]>(queryKey, (prev) =>
          (prev ?? []).filter((f) => f.id !== fieldId)
        );
      } catch (err) {
        log.error('Error removing custom field:', err);
        throw err;
      }
    },
    [queryClient, queryKey]
  );

  const refetch = useCallback(
    () => queryClient.invalidateQueries({ queryKey }),
    [queryClient, queryKey]
  );

  return { fields, isLoading, addField, removeField, refetch };
}

import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { log } from '@/lib/logger';
import {
  MessageSquare,
  Clock,
  CheckCircle2,
  AlertCircle,
  ChevronRight,
  Calendar,
  Loader2,
  History,
  Filter,
} from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { format, subDays } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { dbFrom } from '@/integrations/datasource/db';
import { isValidUUID } from '@/utils/uuid';

interface ConversationHistoryItem {
  id: string;
  date: Date;
  messageCount: number;
  lastMessage: string;
  status: 'resolved' | 'pending' | 'open';
  duration: string;
}

interface ConversationHistoryProps {
  contactId: string;
  contactPhone: string;
  onSelectConversation?: (conversationId: string) => void;
}

type PeriodFilter = '7d' | '30d' | '90d' | 'all';

const periodOptions: { value: PeriodFilter; label: string; days: number | null }[] = [
  { value: '7d', label: 'Últimos 7 dias', days: 7 },
  { value: '30d', label: 'Últimos 30 dias', days: 30 },
  { value: '90d', label: 'Últimos 90 dias', days: 90 },
  { value: 'all', label: 'Todo o histórico', days: null },
];

const statusConfig = {
  resolved: {
    label: 'Resolvido',
    icon: CheckCircle2,
    className: 'bg-success/10 text-success border-success/30',
  },
  pending: {
    label: 'Pendente',
    icon: AlertCircle,
    className: 'bg-warning/10 text-warning border-warning/30',
  },
  open: {
    label: 'Aberto',
    icon: MessageSquare,
    className: 'bg-info/10 text-info border-info/30',
  },
};

/** Conversation History component. */
export function ConversationHistory({
  contactId,
  contactPhone,
  onSelectConversation,
}: ConversationHistoryProps) {
  const [conversations, setConversations] = useState<ConversationHistoryItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isExpanded, setIsExpanded] = useState(false);
  const [periodFilter, setPeriodFilter] = useState<PeriodFilter>('30d');

  const fetchConversationHistory = useCallback(async () => {
    if (!isValidUUID(contactId)) {
      setConversations([]);
      setIsLoading(false);
      return;
    }
    setIsLoading(true);
    try {
      // Get the date filter
      const selectedPeriod = periodOptions.find((p) => p.value === periodFilter);
      const fromDate = selectedPeriod?.days
        ? subDays(new Date(), selectedPeriod.days).toISOString()
        : null;

      // Fetch messages grouped by date to simulate conversation sessions
      let query = dbFrom('messages')
        .select('id, content, created_at, sender')
        .eq('contact_id', contactId)
        .order('created_at', { ascending: false })
        .limit(100);

      if (fromDate) {
        query = query.gte('created_at', fromDate);
      }

      const { data: messages, error } = await query;

      if (error) {
        log.error('Error fetching conversation history:', error);
        setConversations([]);
        return;
      }

      if (!messages || messages.length === 0) {
        setConversations([]);
        return;
      }

      // Group messages by day to create "conversation sessions"
      const groupedByDay: Record<string, typeof messages> = {};
      messages.forEach((msg: any) => {
        const dayKey = format(new Date(msg.created_at), 'yyyy-MM-dd');
        if (!groupedByDay[dayKey]) {
          groupedByDay[dayKey] = [];
        }
        groupedByDay[dayKey].push(msg);
      });

      // Convert to conversation history items
      const historyItems: ConversationHistoryItem[] = Object.entries(groupedByDay)
        .map(([dayKey, dayMessages]) => {
          const firstMsg = dayMessages[dayMessages.length - 1];
          const lastMsg = dayMessages[0];
          const startTime = new Date(firstMsg.created_at);
          const endTime = new Date(lastMsg.created_at);
          const durationMs = endTime.getTime() - startTime.getTime();
          const durationMinutes = Math.max(1, Math.round(durationMs / 60000));

          // Determine status based on last message sender
          let status: 'resolved' | 'pending' | 'open' = 'resolved';
          if (lastMsg.sender === 'contact') {
            status = 'pending';
          } else if (durationMinutes < 5) {
            status = 'open';
          }

          return {
            id: dayKey,
            date: new Date(dayKey),
            messageCount: dayMessages.length,
            lastMessage:
              lastMsg.content.length > 50
                ? `${lastMsg.content.substring(0, 50)}...`
                : lastMsg.content,
            status,
            duration:
              durationMinutes > 60
                ? `${Math.round(durationMinutes / 60)}h ${durationMinutes % 60}min`
                : `${durationMinutes}min`,
          };
        })
        .sort((a, b) => b.date.getTime() - a.date.getTime());

      setConversations(historyItems);
    } catch (error) {
      log.error('Error fetching conversation history:', error);
      setConversations([]);
    } finally {
      setIsLoading(false);
    }
  }, [contactId, periodFilter]);

  useEffect(() => {
    fetchConversationHistory();
  }, [contactId, periodFilter, fetchConversationHistory]);

  const displayedConversations = isExpanded ? conversations : conversations.slice(0, 3);

  return (
    <div className="space-y-3">
      {/* Period Filter */}
      <Select
        value={periodFilter}
        onValueChange={(v) =>
          setPeriodFilter(
            v as PeriodFilter /* ignore-audit: Select/Tabs value string narrowed to union; developer controls option values */
          )
        }
      >
        <SelectTrigger className="h-8 w-full border-border/30 bg-muted/20 text-xs hover:border-primary/30">
          <div className="flex items-center gap-2">
            <Filter className="h-3 w-3 text-muted-foreground" />
            <SelectValue placeholder="Filtrar período" />
          </div>
        </SelectTrigger>
        <SelectContent className="border-border/30 bg-card">
          {periodOptions.map((option) => (
            <SelectItem
              key={option.value}
              value={option.value}
              className="text-xs hover:bg-primary/10"
            >
              {option.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>

      {isLoading ? (
        <div className="flex items-center justify-center py-6">
          <Loader2 className="h-5 w-5 animate-spin text-primary" />
        </div>
      ) : conversations.length === 0 ? (
        <div className="py-6 text-center text-muted-foreground">
          <History className="mx-auto mb-2 h-8 w-8 opacity-50" />
          <p className="text-sm">Nenhuma conversa anterior</p>
          <p className="text-xs">Esta é a primeira interação</p>
        </div>
      ) : (
        <div className="space-y-2">
          <AnimatePresence>
            {displayedConversations.map((conv, index) => {
              const StatusIcon = statusConfig[conv.status].icon;

              return (
                <motion.button
                  key={conv.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -10 }}
                  transition={{ delay: index * 0.05 }}
                  onClick={() => onSelectConversation?.(conv.id)}
                  className="group w-full rounded-lg border border-border/20 bg-muted/20 p-3 text-left transition-all hover:border-primary/30 hover:bg-muted/30"
                >
                  <div className="mb-2 flex items-start justify-between gap-2">
                    <div className="flex items-center gap-2">
                      <Calendar className="h-3.5 w-3.5 text-muted-foreground" />
                      <span className="text-xs font-medium">
                        {format(conv.date, "d 'de' MMM, yyyy", { locale: ptBR })}
                      </span>
                    </div>
                    <Badge
                      variant="outline"
                      className={`text-[10px] ${statusConfig[conv.status].className}`}
                    >
                      <StatusIcon className="mr-1 h-3 w-3" />
                      {statusConfig[conv.status].label}
                    </Badge>
                  </div>

                  <p className="mb-2 line-clamp-1 text-sm text-foreground">{conv.lastMessage}</p>

                  <div className="flex items-center justify-between text-xs text-muted-foreground">
                    <div className="flex items-center gap-3">
                      <span className="flex items-center gap-1">
                        <MessageSquare className="h-3 w-3" />
                        {conv.messageCount} msg
                      </span>
                      <span className="flex items-center gap-1">
                        <Clock className="h-3 w-3" />
                        {conv.duration}
                      </span>
                    </div>
                    <ChevronRight className="h-4 w-4 text-primary opacity-0 transition-opacity group-hover:opacity-100" />
                  </div>
                </motion.button>
              );
            })}
          </AnimatePresence>

          {conversations.length > 3 && (
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setIsExpanded(!isExpanded)}
              className="w-full text-xs text-muted-foreground hover:text-primary"
            >
              {isExpanded ? 'Ver menos' : `Ver mais ${conversations.length - 3} conversas`}
              <ChevronRight
                className={`ml-1 h-4 w-4 transition-transform ${isExpanded ? 'rotate-90' : ''}`}
              />
            </Button>
          )}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import {
  fetchConversationMemory,
  saveConversationMemory,
} from '../hooks/useConversationMemoryData';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Brain, Plus, X, Save, Lightbulb, AlertCircle, Handshake, Clock } from 'lucide-react';
import { toast } from 'sonner';
import { motion } from 'framer-motion';
import { Json } from '@/integrations/supabase/schema';

interface MemoryData {
  id?: string;
  facts: string[];
  objections_handled: string[];
  promises_made: string[];
  pending_items: string[];
  commercial_summary: string;
  cumulative_summary: string;
}

interface ConversationMemoryPanelProps {
  contactId: string;
  profileId?: string | null;
}

const SECTIONS = [
  { key: 'facts' as const, label: 'Fatos relevantes', icon: Lightbulb, color: 'text-primary' },
  {
    key: 'objections_handled' as const,
    label: 'Objeções tratadas',
    icon: AlertCircle,
    color: 'text-warning',
  },
  {
    key: 'promises_made' as const,
    label: 'Promessas feitas',
    icon: Handshake,
    color: 'text-success',
  },
  { key: 'pending_items' as const, label: 'Pendências', icon: Clock, color: 'text-destructive' },
];

/** Conversation Memory Panel component. */
export function ConversationMemoryPanel({ contactId, profileId }: ConversationMemoryPanelProps) {
  const [memory, setMemory] = useState<MemoryData>({
    facts: [],
    objections_handled: [],
    promises_made: [],
    pending_items: [],
    commercial_summary: '',
    cumulative_summary: '',
  });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [newItems, setNewItems] = useState<Record<string, string>>({});

  const loadMemory = useCallback(async () => {
    setLoading(true);
    const data = await fetchConversationMemory(contactId);
    if (data) {
      setMemory({
        id: data.id,
        facts: Array.isArray(data.facts) ? (data.facts as Json[]).map(String) : [],
        objections_handled: Array.isArray(data.objections_handled)
          ? (data.objections_handled as Json[]).map(String)
          : [],
        promises_made: Array.isArray(data.promises_made)
          ? (data.promises_made as Json[]).map(String)
          : [],
        pending_items: Array.isArray(data.pending_items)
          ? (data.pending_items as Json[]).map(String)
          : [],
        commercial_summary: data.commercial_summary || '',
        cumulative_summary: data.cumulative_summary || '',
      });
    }
    setLoading(false);
  }, [contactId]);

  useEffect(() => {
    loadMemory();
  }, [contactId, loadMemory]);

  const addItem = (
    key: keyof Pick<MemoryData, 'facts' | 'objections_handled' | 'promises_made' | 'pending_items'>
  ) => {
    const value = newItems[key]?.trim();
    if (!value) return;
    setMemory((prev) => ({ ...prev, [key]: [...prev[key], value] }));
    setNewItems((prev) => ({ ...prev, [key]: '' }));
  };

  const removeItem = (
    key: keyof Pick<MemoryData, 'facts' | 'objections_handled' | 'promises_made' | 'pending_items'>,
    index: number
  ) => {
    setMemory((prev) => ({
      ...prev,
      [key]: prev[key].filter((_: string, i: number) => i !== index),
    }));
  };

  const saveMemory = async () => {
    setSaving(true);
    const payload = {
      contact_id: contactId,
      facts: memory.facts,
      objections_handled: memory.objections_handled,
      promises_made: memory.promises_made,
      pending_items: memory.pending_items,
      commercial_summary: memory.commercial_summary || null,
      cumulative_summary: memory.cumulative_summary || null,
      updated_by: profileId,
    };

    const { error } = await saveConversationMemory(memory.id, payload as any);

    if (!error) {
      toast.success('Memória salva');
      loadMemory();
    } else {
      toast.error('Erro ao salvar');
    }
    setSaving(false);
  };

  if (loading) {
    return (
      <div className="space-y-2">
        {[1, 2, 3].map((i) => (
          <div key={i} className="h-16 animate-pulse rounded-lg bg-muted/30" />
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Brain className="h-4 w-4 text-primary" />
          <span className="text-sm font-medium">Memória da Conversa</span>
        </div>
        <Button
          size="sm"
          variant="outline"
          className="h-7 text-xs"
          onClick={saveMemory}
          disabled={saving}
        >
          <Save className="mr-1 h-3 w-3" />
          {saving ? 'Salvando...' : 'Salvar'}
        </Button>
      </div>

      {SECTIONS.map(({ key, label, icon: Icon, color }) => (
        <div key={key} className="space-y-1.5">
          <div className="flex items-center gap-1.5">
            <Icon className={`h-3.5 w-3.5 ${color}`} />
            <span className="text-xs font-medium text-muted-foreground">{label}</span>
            <Badge variant="outline" className="h-4 text-[10px]">
              {memory[key].length}
            </Badge>
          </div>
          <div className="space-y-1">
            {memory[key].map((item: string, idx: number) => (
              <motion.div
                key={item}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="group flex items-center gap-1.5 rounded bg-muted/20 px-2 py-1 text-xs"
              >
                <span className="flex-1">{item}</span>
                <button
                  type="button"
                  onClick={() => removeItem(key, idx)}
                  className="opacity-0 group-hover:opacity-100"
                >
                  <X className="h-3 w-3 text-muted-foreground hover:text-destructive" />
                </button>
              </motion.div>
            ))}
          </div>
          <div className="flex gap-1">
            <input
              value={newItems[key] || ''}
              onChange={(e) => setNewItems((prev) => ({ ...prev, [key]: e.target.value }))}
              placeholder="Adicionar..."
              aria-label="Adicionar item à memória"
              className="flex-1 rounded border border-border/30 bg-transparent px-2 py-1 text-xs focus:border-primary/50 focus:outline-none"
              onKeyDown={(e) => e.key === 'Enter' && addItem(key)}
            />
            <Button
              aria-label="Adicionar item"
              variant="ghost"
              size="icon"
              className="h-6 w-6"
              onClick={() => addItem(key)}
            >
              <Plus className="h-3 w-3" />
            </Button>
          </div>
        </div>
      ))}

      <div className="space-y-1.5">
        <span className="text-xs font-medium text-muted-foreground">Resumo comercial</span>
        <Textarea
          value={memory.commercial_summary}
          onChange={(e) => setMemory((prev) => ({ ...prev, commercial_summary: e.target.value }))}
          placeholder="Resumo do contexto comercial..."
          rows={2}
          className="text-xs"
        />
      </div>

      <div className="space-y-1.5">
        <span className="text-xs font-medium text-muted-foreground">Resumo cumulativo</span>
        <Textarea
          value={memory.cumulative_summary}
          onChange={(e) => setMemory((prev) => ({ ...prev, cumulative_summary: e.target.value }))}
          placeholder="Resumo acumulado entre atendentes..."
          rows={2}
          className="text-xs"
        />
      </div>
    </div>
  );
}

