/**
 * Presets de filtros da Inbox: salvar a combinação atual, aplicar, editar e remover.
 *
 * Implementação nativa (botão + painel absoluto) para manter consistência com
 * o FailureCategoryFilter e evitar loops de composição do Radix no sidebar.
 */
import { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Bookmark, Plus, Trash2, ChevronDown, Pencil, Check, X, RefreshCw } from 'lucide-react';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  PRESET_NAME_MAX_LENGTH,
  validatePresetName,
  type InboxFilterPreset,
  type InboxFilterPresetInput,
} from '@/features/inbox/hooks/inboxFilterPresets';
import type { MainTab, SubTab } from '@/features/inbox/components/TicketTabs';


interface Props {
  presets: InboxFilterPreset[];
  onApply: (preset: InboxFilterPreset) => void;
  onSave: (name: string) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, changes: Partial<InboxFilterPresetInput>) => void;
  onUpdateWithCurrent: (id: string) => void;
}

const MAIN_TAB_OPTIONS: { value: MainTab; label: string }[] = [
  { value: 'open', label: 'Abertos' },
  { value: 'resolved', label: 'Resolvidos' },
  { value: 'unread', label: 'Não lidas' },
  { value: 'search', label: 'Busca' },
];

const SUB_TAB_OPTIONS: { value: SubTab; label: string }[] = [
  { value: 'waiting', label: 'Aguardando' },
  { value: 'attending', label: 'Atendendo' },
];

const selectClass =
  'h-7 w-full rounded-md border border-border/60 bg-background px-1.5 text-[11px] focus:outline-none focus:ring-1 focus:ring-ring';

/** Inbox Filter Presets control. */
export const InboxFilterPresets = memo(function InboxFilterPresets({
  presets,
  onApply,
  onSave,
  onDelete,
  onUpdate,
  onUpdateWithCurrent,
}: Props) {
  const [open, setOpen] = useState(false);
  const [name, setName] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [draft, setDraft] = useState<Partial<InboxFilterPresetInput>>({});
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onDocDown = (e: MouseEvent) => {
      if (!containerRef.current?.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setOpen(false);
    };
    document.addEventListener('mousedown', onDocDown);
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('mousedown', onDocDown);
      document.removeEventListener('keydown', onKey);
    };
  }, [open]);

  // Fecha o modo de edição ao fechar o painel, evitando estado órfão.
  useEffect(() => {
    if (!open) {
      setEditingId(null);
      setDraft({});
    }
  }, [open]);

  // Duplicidade no formulário de criação não bloqueia: o preset é sobrescrito.
  const duplicateOnCreate = useMemo(
    () =>
      presets.find((p) => p.name.trim().toLowerCase() === name.trim().toLowerCase()) ?? null,
    [presets, name]
  );

  const saveValidation = useMemo(
    () => validatePresetName(name, presets, duplicateOnCreate?.id),
    [name, presets, duplicateOnCreate]
  );

  const editValidation = useMemo(
    () => validatePresetName(draft.name ?? '', presets, editingId ?? undefined),
    [draft.name, presets, editingId]
  );

  // Só exibe o erro depois que o usuário digitou algo (evita erro no campo vazio).
  const saveError = name.length > 0 ? saveValidation.error : null;
  const editError = editingId && (draft.name ?? '').length > 0 ? editValidation.error : null;

  const handleSave = useCallback(() => {
    if (!saveValidation.ok) return;
    onSave(saveValidation.value);
    setName('');
  }, [saveValidation, onSave]);

  const startEditing = useCallback((preset: InboxFilterPreset) => {
    setEditingId(preset.id);
    setDraft({
      name: preset.name,
      mainTab: preset.mainTab,
      subTab: preset.subTab,
      search: preset.search ?? '',
      showOnlyRetrying: preset.showOnlyRetrying,
    });
  }, []);

  const cancelEditing = useCallback(() => {
    setEditingId(null);
    setDraft({});
  }, []);

  const commitEditing = useCallback(() => {
    if (!editingId || !editValidation.ok) return;
    onUpdate(editingId, { ...draft, name: editValidation.value });
    cancelEditing();
  }, [editingId, draft, editValidation, onUpdate, cancelEditing]);


  return (
    <div ref={containerRef} className="relative shrink-0">
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-label="Presets de filtros da caixa de entrada"
        className={cn(
          'flex h-7 items-center gap-1 rounded-md border border-border/60 bg-muted/40 px-2',
          'text-[11px] text-muted-foreground hover:text-foreground focus:outline-none focus:ring-1 focus:ring-ring'
        )}
      >
        <Bookmark className="h-3 w-3 shrink-0" aria-hidden="true" />
        <span className="truncate">Presets</span>
        {presets.length > 0 && (
          <span className="tabular-nums text-[9px] font-medium">{presets.length}</span>
        )}
        <ChevronDown className="h-3 w-3 shrink-0 opacity-60" aria-hidden="true" />
      </button>

      {open && (
        <div
          role="menu"
          aria-label="Presets salvos"
          className={cn(
            'absolute left-0 z-50 mt-1 max-h-[380px] w-[300px] overflow-y-auto',
            'rounded-md border bg-popover p-2 text-popover-foreground shadow-md'
          )}
        >
          <div className="flex items-center gap-1">
            <Input
              value={name}
              onChange={(e) => setName(e.target.value.slice(0, PRESET_NAME_MAX_LENGTH + 1))}
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  e.preventDefault();
                  handleSave();
                }
              }}
              placeholder="Nome do preset atual"
              aria-label="Nome do novo preset"
              aria-invalid={saveError ? true : undefined}
              aria-describedby={saveError ? 'inbox-preset-name-error' : undefined}
              maxLength={PRESET_NAME_MAX_LENGTH + 1}
              className={cn('h-8 text-[11px]', saveError && 'border-destructive')}
            />
            <Button
              type="button"
              size="sm"
              variant="secondary"
              className="h-8 shrink-0 px-2"
              aria-label="Salvar filtros atuais como preset"
              disabled={!saveValidation.ok}
              onClick={handleSave}
            >
              <Plus className="h-3.5 w-3.5" aria-hidden="true" />
            </Button>
          </div>

          {saveError ? (
            <p
              id="inbox-preset-name-error"
              role="alert"
              className="mt-1 px-0.5 text-[10px] text-destructive"
            >
              {saveError}
            </p>
          ) : duplicateOnCreate ? (
            <p className="mt-1 px-0.5 text-[10px] text-muted-foreground">
              Um preset com esse nome já existe e será substituído.
            </p>
          ) : null}


          <div className="mt-2 space-y-0.5">
            {presets.length === 0 ? (
              <p className="px-1 py-2 text-[11px] text-muted-foreground">
                Nenhum preset salvo ainda.
              </p>
            ) : (
              presets.map((preset) =>
                editingId === preset.id ? (
                  <div
                    key={preset.id}
                    className="space-y-1.5 rounded-sm border border-border/60 bg-muted/30 p-2"
                  >
                    <Input
                      value={draft.name ?? ''}
                      onChange={(e) =>
                        setDraft((d) => ({
                          ...d,
                          name: e.target.value.slice(0, PRESET_NAME_MAX_LENGTH + 1),
                        }))
                      }
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                          e.preventDefault();
                          commitEditing();
                        }
                      }}
                      placeholder="Nome do preset"
                      aria-label={`Renomear preset ${preset.name}`}
                      aria-invalid={editError ? true : undefined}
                      aria-describedby={editError ? 'inbox-preset-edit-error' : undefined}
                      maxLength={PRESET_NAME_MAX_LENGTH + 1}
                      className={cn('h-7 text-[11px]', editError && 'border-destructive')}
                      autoFocus
                    />
                    {editError && (
                      <p
                        id="inbox-preset-edit-error"
                        role="alert"
                        className="px-0.5 text-[10px] text-destructive"
                      >
                        {editError}
                      </p>
                    )}


                    <div className="flex gap-1">
                      <select
                        value={draft.mainTab ?? preset.mainTab}
                        onChange={(e) =>
                          setDraft((d) => ({ ...d, mainTab: e.target.value as MainTab }))
                        }
                        aria-label="Aba do preset"
                        className={selectClass}
                      >
                        {MAIN_TAB_OPTIONS.map((o) => (
                          <option key={o.value} value={o.value}>
                            {o.label}
                          </option>
                        ))}
                      </select>
                      <select
                        value={draft.subTab ?? preset.subTab}
                        onChange={(e) =>
                          setDraft((d) => ({ ...d, subTab: e.target.value as SubTab }))
                        }
                        aria-label="Sub-aba do preset"
                        className={selectClass}
                      >
                        {SUB_TAB_OPTIONS.map((o) => (
                          <option key={o.value} value={o.value}>
                            {o.label}
                          </option>
                        ))}
                      </select>
                    </div>

                    <Input
                      value={draft.search ?? ''}
                      onChange={(e) => setDraft((d) => ({ ...d, search: e.target.value }))}
                      placeholder="Termo de busca (opcional)"
                      aria-label="Busca do preset"
                      className="h-7 text-[11px]"
                    />

                    <label className="flex items-center gap-1.5 px-0.5 text-[11px] text-muted-foreground">
                      <input
                        type="checkbox"
                        checked={draft.showOnlyRetrying ?? preset.showOnlyRetrying}
                        onChange={(e) =>
                          setDraft((d) => ({ ...d, showOnlyRetrying: e.target.checked }))
                        }
                        className="h-3.5 w-3.5 accent-primary"
                      />
                      Somente com falha/reenvio
                    </label>

                    <div className="flex items-center gap-1 pt-0.5">
                      <Button
                        type="button"
                        size="sm"
                        variant="secondary"
                        className="h-7 flex-1 px-2 text-[11px]"
                        disabled={!editValidation.ok}
                        onClick={commitEditing}
                      >
                        <Check className="mr-1 h-3.5 w-3.5" aria-hidden="true" />
                        Salvar
                      </Button>
                      <Button
                        type="button"
                        size="sm"
                        variant="ghost"
                        className="h-7 px-2 text-[11px]"
                        aria-label={`Substituir preset ${preset.name} pelos filtros atuais`}
                        onClick={() => {
                          onUpdateWithCurrent(preset.id);
                          cancelEditing();
                        }}
                      >
                        <RefreshCw className="h-3.5 w-3.5" aria-hidden="true" />
                      </Button>
                      <Button
                        type="button"
                        size="sm"
                        variant="ghost"
                        className="h-7 px-2 text-[11px]"
                        aria-label="Cancelar edição"
                        onClick={cancelEditing}
                      >
                        <X className="h-3.5 w-3.5" aria-hidden="true" />
                      </Button>
                    </div>
                  </div>
                ) : (
                  <div
                    key={preset.id}
                    className="flex items-center gap-1 rounded-sm hover:bg-accent hover:text-accent-foreground"
                  >
                    <button
                      type="button"
                      role="menuitem"
                      onClick={() => {
                        onApply(preset);
                        setOpen(false);
                      }}
                      className="flex-1 truncate px-2 py-1.5 text-left text-[11px] focus:outline-none"
                    >
                      {preset.name}
                    </button>
                    <button
                      type="button"
                      aria-label={`Editar preset ${preset.name}`}
                      onClick={() => startEditing(preset)}
                      className="rounded-sm p-1 text-muted-foreground hover:text-foreground focus:outline-none"
                    >
                      <Pencil className="h-3.5 w-3.5" aria-hidden="true" />
                    </button>
                    <button
                      type="button"
                      aria-label={`Remover preset ${preset.name}`}
                      onClick={() => onDelete(preset.id)}
                      className="mr-1 rounded-sm p-1 text-muted-foreground hover:text-destructive focus:outline-none"
                    >
                      <Trash2 className="h-3.5 w-3.5" aria-hidden="true" />
                    </button>
                  </div>
                )
              )
            )}
          </div>
        </div>
      )}
    </div>
  );
});

import { useState, useMemo, useEffect, useCallback, memo } from 'react';
import { GenericEmptyState } from '@/components/ui/GenericEmptyState';
import { useQuery } from '@tanstack/react-query';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Skeleton } from '@/components/ui/skeleton';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import {
  Image,
  FileVideo,
  FileAudio,
  File,
  Download,
  Search,
  Grid3X3,
  List,
  X,
  Loader2,
  AlertCircle,
  RefreshCw,
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { MediaItem, getMediaType, getFilename } from './media-gallery/mediaUtils';
import { MediaCard } from './media-gallery/MediaCard';
import { MediaPreviewDialog } from './media-gallery/MediaPreviewDialog';
import { MediaGalleryListView } from './media-gallery/MediaGalleryListView';
import { dbFrom } from '@/integrations/datasource/db';
import { queryKeys } from '@/services/api/queryKeys';
import { isValidUUID } from '@/utils/uuid';

const MediaGridItem = memo(function MediaGridItem({
  item,
  isSelected,
  onToggleSelect,
  onPreview,
}: {
  item: MediaItem;
  isSelected: boolean;
  onToggleSelect: (id: string) => void;
  onPreview: (item: MediaItem) => void;
}) {
  const handleSelect = useCallback(() => onToggleSelect(item.id), [onToggleSelect, item.id]);
  const handlePreview = useCallback(() => onPreview(item), [onPreview, item]);
  return (
    <MediaCard
      item={item}
      isSelected={isSelected}
      onSelect={handleSelect}
      onPreview={handlePreview}
    />
  );
});

interface MediaGalleryProps {
  contactId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

/** Media Gallery component. */
export function MediaGallery({ contactId, open, onOpenChange }: MediaGalleryProps) {
  const [filter, setFilter] = useState<'all' | 'image' | 'video' | 'audio' | 'document'>('all');
  const [search, setSearch] = useState('');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [selectedItems, setSelectedItems] = useState<Set<string>>(new Set());
  const [previewItem, setPreviewItem] = useState<MediaItem | null>(null);
  const [isDownloading, _setIsDownloading] = useState(false);
  const [isSlow, setIsSlow] = useState(false);

  const {
    data: messages,
    isLoading,
    isError,
    error,
    isFetching,
    refetch,
  } = useQuery({
    queryKey: queryKeys.mediaGallery.contact(contactId),
    queryFn: async () => {
      const { data, error } = await dbFrom('messages')
        .select('id, media_url, message_type, content, created_at')
        .eq('contact_id', contactId)
        .not('media_url', 'is', null)
        .order('created_at', { ascending: false });
      if (error) throw error;
      return data || [];
    },
    enabled: open && !!contactId && isValidUUID(contactId),
    staleTime: 60_000,
    retry: 1,
  });

  // Mark fetch as "slow" after 1.5s so we can show a friendlier hint.
  useEffect(() => {
    if (!isFetching) {
      setIsSlow(false);
      return;
    }
    const t = setTimeout(() => setIsSlow(true), 1500);
    return () => clearTimeout(t);
  }, [isFetching]);

  const mediaItems = useMemo((): MediaItem[] => {
    if (!messages) return [];
    return messages
      .filter((m: any): m is typeof m & { media_url: string } => Boolean(m.media_url))
      .map((m: any) => ({
        id: m.id,
        url: m.media_url,
        type: getMediaType(m.media_url, m.message_type),
        filename: getFilename(m.media_url),
        created_at: m.created_at,
        message_content: m.content,
      }));
  }, [messages]);

  const filteredItems = useMemo(
    () =>
      mediaItems.filter((item) => {
        const matchesFilter = filter === 'all' || item.type === filter;
        const matchesSearch =
          !search ||
          item.filename.toLowerCase().includes(search.toLowerCase()) ||
          item.message_content.toLowerCase().includes(search.toLowerCase());
        return matchesFilter && matchesSearch;
      }),
    [mediaItems, filter, search]
  );

  const counts = useMemo(
    () => ({
      all: mediaItems.length,
      image: mediaItems.filter((i) => i.type === 'image').length,
      video: mediaItems.filter((i) => i.type === 'video').length,
      audio: mediaItems.filter((i) => i.type === 'audio').length,
      document: mediaItems.filter((i) => i.type === 'document').length,
    }),
    [mediaItems]
  );

  const toggleSelect = useCallback((id: string) => {
    setSelectedItems((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  const handleDownloadSelected = async () => {
    const { toast } = await import('sonner');
    toast.error('🔒 Download bloqueado por política de segurança', {
      description: 'O download de arquivos está desabilitado para proteção de dados.',
    });
  };

  return (
    <>
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="flex max-h-[90vh] max-w-4xl flex-col">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Grid3X3 className="h-5 w-5" />
              Galeria de Mídia<Badge variant="secondary">{counts.all} itens</Badge>
            </DialogTitle>
          </DialogHeader>

          <div className="flex items-center gap-4 py-2">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                placeholder="Buscar mídia..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="pl-10"
              />
            </div>
            <div className="flex items-center gap-1 rounded-md border p-1">
              <Button
                aria-label="Visualização em grade"
                variant={viewMode === 'grid' ? 'secondary' : 'ghost'}
                size="icon"
                className="h-8 w-8"
                onClick={() => setViewMode('grid')}
              >
                <Grid3X3 className="h-4 w-4" />
              </Button>
              <Button
                aria-label="Visualização em lista"
                variant={viewMode === 'list' ? 'secondary' : 'ghost'}
                size="icon"
                className="h-8 w-8"
                onClick={() => setViewMode('list')}
              >
                <List className="h-4 w-4" />
              </Button>
            </div>
          </div>

          <Tabs
            value={filter}
            onValueChange={(v) =>
              setFilter(
                v as typeof filter /* ignore-audit: Select/Tabs value string narrowed to union; developer controls option values */
              )
            }
          >
            <TabsList className="grid grid-cols-5">
              <TabsTrigger value="all" className="gap-1">
                Todos{' '}
                <Badge variant="outline" className="ml-1">
                  {counts.all}
                </Badge>
              </TabsTrigger>
              <TabsTrigger value="image" className="gap-1">
                <Image className="h-3 w-3" />
                <span className="hidden sm:inline">Imagens</span>
                <Badge variant="outline" className="ml-1">
                  {counts.image}
                </Badge>
              </TabsTrigger>
              <TabsTrigger value="video" className="gap-1">
                <FileVideo className="h-3 w-3" />
                <span className="hidden sm:inline">Vídeos</span>
                <Badge variant="outline" className="ml-1">
                  {counts.video}
                </Badge>
              </TabsTrigger>
              <TabsTrigger value="audio" className="gap-1">
                <FileAudio className="h-3 w-3" />
                <span className="hidden sm:inline">Áudios</span>
                <Badge variant="outline" className="ml-1">
                  {counts.audio}
                </Badge>
              </TabsTrigger>
              <TabsTrigger value="document" className="gap-1">
                <File className="h-3 w-3" />
                <span className="hidden sm:inline">Docs</span>
                <Badge variant="outline" className="ml-1">
                  {counts.document}
                </Badge>
              </TabsTrigger>
            </TabsList>
          </Tabs>

          <AnimatePresence>
            {selectedItems.size > 0 && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                exit={{ opacity: 0, height: 0 }}
                className="flex items-center justify-between rounded-lg bg-primary/10 p-2"
              >
                <span className="text-sm">{selectedItems.size} item(s) selecionado(s)</span>
                <div className="flex items-center gap-2">
                  <Button variant="ghost" size="sm" onClick={() => setSelectedItems(new Set())}>
                    <X className="mr-1 h-4 w-4" />
                    Limpar
                  </Button>
                  <Button size="sm" onClick={handleDownloadSelected} disabled={isDownloading}>
                    {isDownloading ? (
                      <Loader2 className="mr-1 h-4 w-4 animate-spin" />
                    ) : (
                      <Download className="mr-1 h-4 w-4" />
                    )}
                    Download
                  </Button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* Background refetch indicator (visível só quando já há dados na tela) */}
          {isFetching && !isLoading && !isError && (
            <div
              role="status"
              aria-live="polite"
              className="flex items-center gap-2 border-b px-2 py-1 text-xs text-muted-foreground"
            >
              <Loader2 className="h-3 w-3 animate-spin" aria-hidden="true" />
              Atualizando galeria…
            </div>
          )}

          <ScrollArea className="min-h-[300px] flex-1">
            {isLoading ? (
              <div role="status" aria-live="polite" aria-label="Carregando mídias" className="p-2">
                <div className="grid grid-cols-4 gap-2">
                  {[...Array(8)].map((_, i) => (
                    <Skeleton key={i} className="aspect-square rounded-lg" />
                  ))}
                </div>
                {isSlow && (
                  <div className="mt-6 flex flex-col items-center gap-2 text-center">
                    <Loader2
                      className="h-4 w-4 animate-spin text-muted-foreground"
                      aria-hidden="true"
                    />
                    <p className="max-w-xs text-xs text-muted-foreground">
                      A busca está demorando mais que o normal. Aguarde ou verifique sua conexão.
                    </p>
                    <Button variant="ghost" size="sm" onClick={() => refetch()} className="gap-2">
                      <RefreshCw className="h-3.5 w-3.5" />
                      Tentar de novo
                    </Button>
                  </div>
                )}
              </div>
            ) : isError ? (
              <div
                role="alert"
                className="flex flex-col items-center justify-center gap-3 px-4 py-12 text-center"
              >
                <div className="flex h-12 w-12 items-center justify-center rounded-full bg-destructive/10">
                  <AlertCircle className="h-6 w-6 text-destructive" />
                </div>
                <div className="space-y-1">
                  <p className="text-sm font-medium text-foreground">
                    Não foi possível carregar a mídia
                  </p>
                  <p className="max-w-sm text-xs text-muted-foreground">
                    {error instanceof Error && error.message
                      ? error.message
                      : 'Verifique sua conexão e tente novamente.'}
                  </p>
                </div>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => refetch()}
                  disabled={isFetching}
                  className="gap-2"
                >
                  {isFetching ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    <RefreshCw className="h-4 w-4" />
                  )}
                  Tentar novamente
                </Button>
              </div>
            ) : filteredItems.length === 0 ? (
              <GenericEmptyState
                icon={Image}
                title="Sem mídias"
                description="Nenhuma mídia encontrada nesta conversa"
                className="py-8"
              />
            ) : viewMode === 'grid' ? (
              <div className="grid grid-cols-4 gap-2 p-2">
                {filteredItems.map((item) => (
                  <MediaGridItem
                    key={item.id}
                    item={item}
                    isSelected={selectedItems.has(item.id)}
                    onToggleSelect={toggleSelect}
                    onPreview={setPreviewItem}
                  />
                ))}
              </div>
            ) : (
              <MediaGalleryListView
                items={filteredItems}
                selectedItems={selectedItems}
                onToggleSelect={toggleSelect}
                onPreview={setPreviewItem}
              />
            )}
          </ScrollArea>
        </DialogContent>
      </Dialog>

      <MediaPreviewDialog
        item={previewItem}
        open={!!previewItem}
        onOpenChange={(open) => !open && setPreviewItem(null)}
      />
    </>
  );
}

import { useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { Loader2, RefreshCw, AlertTriangle, Check, Sparkles } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { ToneSelector } from './ai-tools/ToneSelector';
import { PeriodFilterSelector } from './ai-tools/PeriodFilterSelector';
import { useObjectionDetector } from '@/hooks/useObjectionDetector';
import type { ChatMessage } from '../types/aiChatMessage';
import { ObjectionCard, ShimmerBlock } from './objectionDetectorParts';

interface ObjectionDetectorProps {
  contactId: string;
  contactName?: string;
  lastMessages: string[];
  allMessages?: ChatMessage[];
  onSelectSuggestion?: (text: string) => void;
}

/* ─── Main Component ─── */
/** Detects sales objections in recent chat messages using AI analysis, shows matched objection cards with suggested counter-responses, and supports tone/period filtering. */
export function ObjectionDetector({
  contactId,
  contactName,
  lastMessages,
  allMessages = [],
  onSelectSuggestion,
}: ObjectionDetectorProps) {
  const detector = useObjectionDetector(contactId, contactName, lastMessages, allMessages);

  const handleSelect = useCallback(
    (text: string) => {
      detector.handleSelect(text, onSelectSuggestion);
    },
    [detector.handleSelect, onSelectSuggestion]
  );

  /* ── Pre-analysis state ── */
  if (!detector.analyzed) {
    return (
      <div className="space-y-3">
        {detector.hasPeriodMessages && (
          <PeriodFilterSelector
            period={detector.periodFilter.analysisPeriod}
            onPeriodChange={detector.periodFilter.setAnalysisPeriod}
            customFrom={detector.periodFilter.customDateFrom}
            customTo={detector.periodFilter.customDateTo}
            onCustomFromChange={detector.periodFilter.setCustomDateFrom}
            onCustomToChange={detector.periodFilter.setCustomDateTo}
            onClearCustom={detector.periodFilter.clearCustomDates}
            filteredCount={detector.periodFilter.filteredMessages.length}
            totalCount={allMessages.length}
          />
        )}
        <ToneSelector selected={detector.selectedTone} onChange={detector.setSelectedTone} />
        <Button
          className="h-11 w-full rounded-2xl bg-primary text-[13px] font-bold text-primary-foreground shadow-lg shadow-primary/25 transition-all hover:bg-primary/90 active:scale-[0.98]"
          onClick={() => detector.analyze()}
          disabled={detector.loading || detector.clientMessages.length === 0}
        >
          {detector.loading ? (
            <>
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              Analisando...
            </>
          ) : (
            <>
              <Sparkles className="mr-2 h-4 w-4" />
              Detectar objeções
              {detector.clientMessages.length > 0 && (
                <span className="ml-2 rounded-full bg-primary-foreground/20 px-2 py-0.5 text-[10px] font-bold tabular-nums">
                  {detector.clientMessages.length}
                </span>
              )}
            </>
          )}
        </Button>
        {detector.clientMessages.length === 0 && (
          <p className="text-center text-[10px] italic text-muted-foreground">
            Nenhuma mensagem do cliente no período
          </p>
        )}
      </div>
    );
  }

  /* ── Loading ── */
  if (detector.loading && detector.objections.length === 0) {
    return (
      <div className="space-y-4">
        <div className="flex items-center gap-3 px-1">
          <Loader2 className="h-5 w-5 animate-spin text-primary" />
          <div>
            <p className="text-xs font-semibold text-foreground">Analisando mensagens...</p>
            <p className="text-[10px] text-muted-foreground">
              {detector.clientMessages.length} mensagens em análise
            </p>
          </div>
        </div>
        <div className="space-y-3">
          {[1, 2, 3].map((i) => (
            <div key={i} className="space-y-3 rounded-2xl border border-border/20 p-4">
              <div className="flex items-start gap-3">
                <ShimmerBlock className="h-8 w-8 shrink-0 rounded-xl" />
                <div className="flex-1 space-y-2">
                  <ShimmerBlock className="h-3.5 w-4/5" />
                  <ShimmerBlock className="h-5 w-16 rounded-full" />
                </div>
              </div>
              <ShimmerBlock className="h-16 w-full rounded-xl" />
            </div>
          ))}
        </div>
      </div>
    );
  }

  /* ── Empty / Error ── */
  if (detector.objections.length === 0) {
    return (
      <div className="space-y-4">
        {detector.error ? (
          <div
            role="alert"
            className="bg-destructive/8 flex items-start gap-3 rounded-2xl border border-destructive/15 p-4"
          >
            <AlertTriangle className="h-5 w-5 shrink-0 text-destructive" />
            <div className="min-w-0">
              <p className="mb-1 text-xs font-semibold text-destructive">Erro na análise</p>
              <p className="text-[11px] leading-relaxed text-destructive/80">{detector.error}</p>
            </div>
          </div>
        ) : (
          <motion.div
            initial={{ scale: 0.9, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            className="flex flex-col items-center gap-3 py-8"
          >
            <motion.div
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ type: 'spring', stiffness: 300, damping: 15, delay: 0.1 }}
              className="flex h-16 w-16 items-center justify-center rounded-2xl border border-primary/15 bg-primary/10"
            >
              <Check className="h-7 w-7 text-primary" />
            </motion.div>
            <div className="space-y-1 text-center">
              <p className="text-sm font-semibold text-foreground">Nenhuma objeção!</p>
              <p className="max-w-[260px] text-[11px] text-muted-foreground">
                O cliente não apresentou resistências. Conversa fluindo bem 🎉
              </p>
            </div>
          </motion.div>
        )}
        <Button
          variant="outline"
          className="h-10 w-full rounded-2xl border-border/30 text-xs font-medium"
          onClick={detector.resetAnalysis}
        >
          <RefreshCw className="mr-2 h-3.5 w-3.5" />
          Nova análise
        </Button>
      </div>
    );
  }

  /* ── Results ── */
  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="flex h-9 w-9 items-center justify-center rounded-xl border border-primary/15 bg-primary/10">
            <span className="text-sm font-bold text-primary">{detector.objections.length}</span>
          </div>
          <div>
            <p className="text-[13px] font-bold leading-none text-foreground">
              {detector.objections.length === 1 ? 'Objeção detectada' : 'Objeções detectadas'}
            </p>
            <p className="mt-0.5 text-[11px] text-muted-foreground">Contra-argumentos prontos</p>
          </div>
        </div>
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              className="h-9 w-9 rounded-xl hover:bg-muted/30"
              onClick={() => detector.analyze()}
              disabled={detector.loading}
              aria-label="Analisar objeções"
            >
              <motion.div
                animate={detector.loading ? { rotate: 360 } : {}}
                transition={{
                  duration: 1,
                  repeat: detector.loading ? Infinity : 0,
                  ease: 'linear',
                }}
              >
                <RefreshCw className="h-4 w-4" />
              </motion.div>
            </Button>
          </TooltipTrigger>
          <TooltipContent side="left" className="text-[10px]">
            Reanalisar
          </TooltipContent>
        </Tooltip>
      </div>

      <ToneSelector
        selected={detector.selectedTone}
        onChange={(tone) => {
          detector.setSelectedTone(tone);
          detector.analyze(tone);
        }}
        disabled={detector.loading}
      />

      <div className="relative">
        {detector.loading && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="absolute inset-0 z-10 flex items-center justify-center rounded-2xl bg-background/70 backdrop-blur-sm"
          >
            <div className="flex items-center gap-2.5 rounded-xl border border-border/50 bg-muted/80 px-4 py-2.5 shadow-lg">
              <Loader2 className="h-4 w-4 animate-spin text-primary" />
              <span className="text-xs font-medium text-foreground">Ajustando tom...</span>
            </div>
          </motion.div>
        )}
        <ScrollArea className="h-72 [&>[data-radix-scroll-area-viewport]]:max-h-72">
          <div className="space-y-3 pr-3">
            <AnimatePresence mode="popLayout">
              {detector.objections.map((obj, idx) => (
                <ObjectionCard
                  key={obj.id}
                  obj={obj}
                  idx={idx}
                  isRewriting={detector.rewritingIdx === idx}
                  rewritingAny={detector.rewritingIdx !== null}
                  copiedIdx={detector.copiedIdx}
                  onSelect={handleSelect}
                  onCopy={detector.handleCopy}
                  onRewrite={detector.rewriteSingle}
                />
              ))}
            </AnimatePresence>
          </div>
        </ScrollArea>
      </div>
    </div>
  );
}

import { useEffect, useRef, useCallback, lazy, Suspense } from 'react';
import { useIsMobile } from '@/hooks/use-mobile';
import { usePullToRefresh } from '@/hooks/usePullToRefresh';
import { MiniChatPiP } from '@/components/mobile/MiniChatPiP';
import { NewMessageIndicator } from './NewMessageIndicator';
import { MessageBatcherIndicator } from './MessageBatcherIndicator';
import { InboxEmptyChat } from './InboxEmptyChat';
import { SectionErrorBoundary } from '@/components/ui/section-error-boundary';
import { ConversationListSidebar } from './ConversationListSidebar';
import { useGlobalSearchShortcut } from '@/hooks/useGlobalSearchShortcut';
import { useInboxBulkActions } from '@/features/inbox';
import { useInboxFilters } from '@/features/inbox';
import { useRealtimeInbox } from '@/features/inbox';
import { useRealtimeContacts } from '@/features/inbox';
import { useRealtimeFallbackRefetch } from '@/features/inbox';
import { useSLAAlerts } from '@/features/sla';
import { useDepartmentAgents } from '@/features/auth';
import { useEvolutionAutoReconnect } from '@/hooks/useEvolutionAutoReconnect';
import { useAriaAnnouncer } from '@/hooks/useAriaAnnouncer';
import { isValidUUID } from '@/utils/uuid';
import { WifiOff, RefreshCw, Loader2, MessageSquarePlus } from 'lucide-react';
