import { useState, useCallback, useEffect, useRef } from 'react';
import { log } from '@/lib/logger';
import { supabase } from '@/integrations/supabase/client';
import { safeClient } from '@/integrations/supabase/safeClient';
import { sanitizePostgrestFilter } from '@/lib/sanitize';
import { isExternalConfigured } from '@/integrations/supabase/externalClient';
import { useDebounce } from '@/hooks/useDebounce';
import { useSearchHistory } from '@/hooks/useSearchHistory';
import { subDays, subMonths, startOfDay } from 'date-fns';
import { dbFrom, dbRpc } from '@/integrations/datasource/db';
import { RPC } from '@/integrations/datasource/rpcCatalog';

/** Search Result interface definition. */
export interface SearchResult {
  id: string;
  type: 'message' | 'contact' | 'transcription' | 'action' | 'crm';
  title: string;
  preview: string;
  timestamp: Date;
  contactId?: string;
  contactName?: string;
  messageType?: string;
  tags?: string[];
  action?: () => void;
  crmPhone?: string;
}

/** Result Type type alias. */
export type ResultType = 'message' | 'contact' | 'transcription' | 'action' | 'crm';
/** Date Filter type alias. */
export type DateFilter = 'all' | 'today' | '7days' | '30days' | '90days';
/** Media Type Filter type alias. */
export type MediaTypeFilter = 'all' | 'text' | 'image' | 'video' | 'audio' | 'document' | 'link';

/** Tag Suggestion interface definition. */
export interface TagSuggestion {
  id: string;
  name: string;
  color: string;
}

function getDateFilterStart(filter: DateFilter): Date | null {
  const now = new Date();
  switch (filter) {
    case 'today':
      return startOfDay(now);
    case '7days':
      return subDays(now, 7);
    case '30days':
      return subMonths(now, 1);
    case '90days':
      return subMonths(now, 3);
    default:
      return null;
  }
}

/** use Global Search Data function. */
export function useGlobalSearchData(open: boolean) {
  const [search, setSearch] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [results, setResults] = useState<SearchResult[]>([]);
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [allTags, setAllTags] = useState<TagSuggestion[]>([]);
  const [tagSuggestions, setTagSuggestions] = useState<TagSuggestion[]>([]);
  const [selectedTags, setSelectedTags] = useState<string[]>([]);
  const [activeTypes, setActiveTypes] = useState<Set<ResultType>>(
    new Set(['message', 'transcription', 'contact', 'action', 'crm'])
  );
  const [dateFilter, setDateFilter] = useState<DateFilter>('all');
  const [mediaTypeFilter, setMediaTypeFilter] = useState<MediaTypeFilter>('all');
  const [showFilters, setShowFilters] = useState(false);
  /** Last logged search event id — kept to correlate clicks if needed. */
  const lastSearchEventIdRef = useRef<string | null>(null);
  const searchRef = useRef(search);
  searchRef.current = search;

  const { history, addToHistory, removeFromHistory, clearHistory } = useSearchHistory();

  useEffect(() => {
    if (open) {
      supabase
        .from('tags')
        .select('id, name, color')
        .order('name')
        .then(
          ({ data }) => {
            if (data) setAllTags(data);
          },
          () => {}
        );
    }
  }, [open]);

  useEffect(() => {
    if (search.startsWith('#') || search.includes(' #')) {
      const tagQuery = search.includes(' #')
        ? search.split(' #').pop()?.toLowerCase() || ''
        : search.slice(1).toLowerCase();
      setTagSuggestions(
        allTags
          .filter((t) => t.name.toLowerCase().includes(tagQuery) && !selectedTags.includes(t.id))
          .slice(0, 5)
      );
    } else {
      setTagSuggestions([]);
    }
  }, [search, allTags, selectedTags]);

  const toggleType = useCallback((type: ResultType) => {
    setActiveTypes((prev) => {
      const next = new Set(prev);
      if (next.has(type)) {
        if (next.size > 1) next.delete(type);
      } else {
        next.add(type);
      }
      return next;
    });
  }, []);

  const performSearch = useCallback(
    async (
      query: string,
      types: Set<ResultType>,
      dateRange: DateFilter,
      tags: string[],
      mediaType: MediaTypeFilter = 'all'
    ) => {
      const cleanQuery = query.replace(/#\w*/g, '').trim();
      if (cleanQuery.length < 2 && tags.length === 0 && mediaType === 'all') {
        setResults([]);
        return;
      }

      const safeQuery = sanitizePostgrestFilter(cleanQuery);
      const isLinkSearch = mediaType === 'link';
      setIsLoading(true);
      const dateStart = getDateFilterStart(dateRange);

      try {
        const searchResults: SearchResult[] = [];
        const addedMessageIds = new Set<string>();

        if (types.has('message') && (cleanQuery.length >= 2 || mediaType !== 'all')) {
          let textQuery = dbFrom('messages')
            .select(
              `id, content, message_type, created_at, contact_id, contacts:contact_id (id, name, surname)`
            )
            .order('created_at', { ascending: false })
            .limit(20);

          if (cleanQuery.length >= 2) {
            if (isLinkSearch) {
              textQuery = textQuery.or(
                `content.ilike.%http://%,content.ilike.%https://%,content.ilike.%www.%`
              );
              textQuery = textQuery.ilike('content', `%${safeQuery}%`);
            } else {
              textQuery = textQuery.ilike('content', `%${safeQuery}%`);
            }
          } else if (isLinkSearch) {
            textQuery = textQuery.or(
              `content.ilike.%http://%,content.ilike.%https://%,content.ilike.%www.%`
            );
          }

          if (mediaType !== 'all' && mediaType !== 'link')
            textQuery = textQuery.eq('message_type', mediaType);
          if (dateStart) textQuery = textQuery.gte('created_at', dateStart.toISOString());

          const { data: textMessages } = await textQuery;
          (textMessages as any[])?.forEach((msg: any) => {
            const contact = msg.contacts as unknown as {
              id: string;
              name: string;
              surname: string | null;
            } | null;
            addedMessageIds.add(msg.id);
            searchResults.push({
              id: msg.id,
              type: 'message',
              title: contact
                ? `Conversa com ${contact.name}${contact.surname ? ` ${contact.surname}` : ''}`
                : 'Mensagem',
              preview:
                msg.content.length > 100 ? `${msg.content.substring(0, 100)}...` : msg.content,
              timestamp: new Date(msg.created_at),
              contactId: msg.contact_id || undefined,
              contactName: contact
                ? `${contact.name}${contact.surname ? ` ${contact.surname}` : ''}`
                : undefined,
              messageType: msg.message_type,
            });
          });
        }

        if (types.has('transcription') && cleanQuery.length >= 2) {
          let audioQuery = dbFrom('messages')
            .select(
              `id, content, transcription, message_type, created_at, contact_id, contacts:contact_id (id, name, surname)`
            )
            .not('transcription', 'is', null)
            .ilike('transcription', `%${safeQuery}%`)
            .order('created_at', { ascending: false })
            .limit(15);
          if (dateStart) audioQuery = audioQuery.gte('created_at', dateStart.toISOString());

          const { data: audioMessages } = await audioQuery;
          (audioMessages as any[])?.forEach((msg: any) => {
            if (addedMessageIds.has(msg.id)) return;
            const contact = msg.contacts as unknown as {
              id: string;
              name: string;
              surname: string | null;
            } | null;
            const transcription = msg.transcription || '';
            searchResults.push({
              id: msg.id,
              type: 'transcription',
              title: contact
                ? `Áudio de ${contact.name}${contact.surname ? ` ${contact.surname}` : ''}`
                : 'Áudio transcrito',
              preview:
                transcription.length > 100
                  ? `${transcription.substring(0, 100)}...`
                  : transcription,
              timestamp: new Date(msg.created_at),
              contactId: msg.contact_id || undefined,
              contactName: contact
                ? `${contact.name}${contact.surname ? ` ${contact.surname}` : ''}`
                : undefined,
              messageType: msg.message_type,
            });
          });
        }

        if (types.has('contact')) {
          let contactQuery = dbFrom('contacts').select(
            'id, name, surname, phone, email, created_at, tags'
          );
          if (cleanQuery.length >= 2)
            contactQuery = contactQuery.or(
              `name.ilike.%${safeQuery}%,surname.ilike.%${safeQuery}%,phone.ilike.%${safeQuery}%,email.ilike.%${safeQuery}%`
            );

          const { data: contacts } = await contactQuery
            .order('name', { ascending: true })
            .limit(10);
          if (contacts) {
            let filtered = contacts as any[];
            if (tags.length > 0) {
              const tagNames = allTags.filter((t) => tags.includes(t.id)).map((t) => t.name);
              filtered = (contacts as any[]).filter(
                (c: any) => c.tags && c.tags.some((tag: string) => tagNames.includes(tag))
              );
            }
            filtered.forEach((contact: any) => {
              searchResults.push({
                id: contact.id,
                type: 'contact',
                title: `${contact.name}${contact.surname ? ` ${contact.surname}` : ''}`,
                preview: contact.phone || contact.email || '',
                timestamp: new Date(contact.created_at),
                contactId: contact.id,
                tags: contact.tags,
              });
            });
          }
        }

        if (types.has('crm') && isExternalConfigured && cleanQuery.length >= 3) {
          try {
            const { data: crmDataRaw } = await dbRpc(RPC.searchContactsAdvanced, {
              p_search: cleanQuery,
              p_vendedor: null,
              p_ramo: null,
              p_rfm_segment: null,
              p_estado: null,
              p_cliente_ativado: null,
              p_ja_comprou: null,
              p_sort_by: 'relevance',
              p_page: 0,
              p_page_size: 8,
            });
            const crmData = crmDataRaw as { results?: Record<string, string | null>[] } | null;
            if (crmData?.results) {
              const localPhones = new Set(
                searchResults
                  .filter((r) => r.type === 'contact')
                  .map((r) => r.preview.replace(/\D/g, ''))
              );
              crmData.results.forEach((cr: Record<string, string | null>) => {
                const phone = cr.phone_primary?.replace(/\D/g, '') || '';
                if (phone && localPhones.has(phone)) return;
                searchResults.push({
                  id: `crm-${cr.contact_id}`,
                  type: 'crm',
                  title: cr.full_name || cr.nome_tratamento || 'Sem nome',
                  preview: [cr.company_name, cr.phone_primary, cr.rfm_segment]
                    .filter(Boolean)
                    .join(' • '),
                  timestamp: new Date(),
                  crmPhone: cr.phone_primary || undefined,
                });
              });
            }
          } catch (err) {
            log.error('Unexpected error in useGlobalSearchData:', err);
          }
        }

        searchResults.sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());
        setResults(searchResults);
        if (cleanQuery.length >= 2) {
          addToHistory(cleanQuery, searchResults.length);
          // Fire-and-forget telemetry — never blocks UI.
          safeClient
            .rpc('rpc_log_search_event', {
              p_query: cleanQuery,
              p_entities: Array.from(types),
              p_result_count: searchResults.length,
              p_used_vector: false,
            })
            .then(({ data, error }) => {
              if (error) log.warn('rpc_log_search_event failed', error);
              else if (typeof data === 'string') lastSearchEventIdRef.current = data;
            });
        }
      } catch (error) {
        log.error('Search error:', error);
        setResults([]);
      } finally {
        setIsLoading(false);
      }
    },
    [addToHistory, allTags]
  );

  const debouncedSearch = useDebounce(
    ((...args: unknown[]) => {
      performSearch(args[0] as string, activeTypes, dateFilter, selectedTags, mediaTypeFilter);
    }) as (...args: unknown[]) => unknown,
    300
  );

  const handleSearch = useCallback(
    (query: string) => {
      setSearch(query);
      setSelectedIndex(0);
      debouncedSearch(query);
    },
    [debouncedSearch]
  );

  useEffect(() => {
    if (searchRef.current.length >= 2 || selectedTags.length > 0 || mediaTypeFilter !== 'all') {
      performSearch(searchRef.current, activeTypes, dateFilter, selectedTags, mediaTypeFilter);
    }
  }, [activeTypes, dateFilter, selectedTags, mediaTypeFilter, performSearch]);

  const handleTagSelect = useCallback((tag: TagSuggestion) => {
    setSelectedTags((prev) => [...prev, tag.id]);
    setSearch((prev) => prev.replace(/#\w*$/, '').trim());
    setTagSuggestions([]);
  }, []);

  const removeTag = useCallback((tagId: string) => {
    setSelectedTags((prev) => prev.filter((t) => t !== tagId));
  }, []);

  return {
    search,
    setSearch,
    isLoading,
    results,
    setResults,
    selectedIndex,
    setSelectedIndex,
    allTags,
    tagSuggestions,
    selectedTags,
    activeTypes,
    dateFilter,
    setDateFilter,
    mediaTypeFilter,
    setMediaTypeFilter,
    showFilters,
    setShowFilters,
    history,
    removeFromHistory,
    clearHistory,
    toggleType,
    handleSearch,
    handleTagSelect,
    removeTag,
    performSearch,
    lastSearchEventIdRef,
  };
}

