describe('inboxFilterPipeline — visibilidade de conversas aguardando', () => {
  it('mantém conversas sem responsável na aba Aguardando quando Atendendo está vazio', () => {
    const conversations = [
      buildConversation('c1', null, 1),
      buildConversation('c2', null, 1),
    ];
    const options = buildOptions(conversations, { subTab: 'waiting' });

    const attending = applyInboxFilters({ ...options, subTab: 'attending' });
    const waiting = applyInboxFilters({ ...options, subTab: 'waiting' });
    const counts = computeInboxTabCounts(options);

    expect(attending).toHaveLength(0);
    expect(waiting.map((conversation) => conversation.contact.id)).toEqual(['c1', 'c2']);
    // open reflete o subTab ativo (waiting) para casar 1:1 com a lista visível
    expect(counts).toMatchObject({ open: 2, attending: 0, waiting: 2, unread: 2 });
  });

  it('não mistura conversas aguardando dentro de Atendendo mesmo com escopo global', () => {
    const conversations = [
      buildConversation('c1', 'agent-1', 0),
      buildConversation('c2', null, 0),
      buildConversation('c3', 'agent-2', 0),
    ];
    const options = buildOptions(conversations, { scope: 'all', showAll: true });

    const attending = applyInboxFilters({ ...options, subTab: 'attending' });
    const waiting = applyInboxFilters({ ...options, subTab: 'waiting' });
    const counts = computeInboxTabCounts(options);

    expect(attending.map((conversation) => conversation.contact.id)).toEqual(['c1', 'c3']);
    expect(waiting.map((conversation) => conversation.contact.id)).toEqual(['c2']);
    // subTab default 'attending' → open casa com attending (2), não união
    expect(counts).toMatchObject({ open: 2, attending: 2, waiting: 1 });
  });

  it('preserva conversas carregadas quando permissões de canal ainda estão desidratadas', () => {
    const conversations = [
      buildConversation('c1', null, 1),
      buildConversation('c2', null, 1),
    ];
    const options = buildOptions(conversations, {
      subTab: 'waiting',
      hasPermission: () => false,
      permissionsLoading: false,
      enforceChannelPermissions: false,
    });

    const waiting = applyInboxFilters({ ...options, subTab: 'waiting' });
    const counts = computeInboxTabCounts(options);

    expect(waiting.map((conversation) => conversation.contact.id)).toEqual(['c1', 'c2']);
    expect(counts).toMatchObject({ open: 2, attending: 0, waiting: 2, unread: 2 });
  });

  it('não derruba conversas WhatsApp durante carregamento das permissões de canal', () => {
    const conversations = [
      buildConversation('c1', null, 1),
      buildConversation('c2', null, 1),
    ];
    const options = buildOptions(conversations, {
      subTab: 'waiting',
      hasPermission: () => false,
      permissionsLoading: true,
      enforceChannelPermissions: true,
    });

    const visible = applyInboxFilters(options);
    const counts = computeInboxTabCounts(options);

    expect(visible.map((conversation) => conversation.contact.id)).toEqual(['c1', 'c2']);
    expect(counts).toMatchObject({ open: 2, attending: 0, waiting: 2, unread: 2 });
  });

  it('aplica bloqueio por canal somente quando o gate de permissões está hidratado', () => {
    const conversations = [
      buildConversation('c1', null, 1),
      buildConversation('c2', null, 1),
    ];
    const options = buildOptions(conversations, {
      subTab: 'waiting',
      hasPermission: () => false,
      permissionsLoading: false,
      enforceChannelPermissions: true,
    });

    const visible = applyInboxFilters(options);
    const counts = computeInboxTabCounts(options);

    expect(visible).toHaveLength(0);
    expect(counts).toMatchObject({ open: 0, attending: 0, waiting: 0, unread: 0 });
  });
});

/**
 * Persistência dos filtros da Inbox (aba ativa, sub-aba, busca, tipo de contato,
 * fila e filtros de falha) entre recarregamentos de página e trocas de rota.
 *
 * Estratégia: a URL é a fonte primária (permite compartilhar links); o
 * localStorage é o fallback quando a URL não traz o parâmetro.
 */
import { safeGetJSON, safeSetJSON } from '@/lib/safeStorage';
import type { MainTab, SubTab } from '@/features/inbox/components/TicketTabs';
import type { FailureCategory } from '@/features/inbox';

const STORAGE_KEY = 'inbox_filters_v1';

const MAIN_TABS: MainTab[] = ['open', 'resolved', 'search', 'unread'];
const SUB_TABS: SubTab[] = ['attending', 'waiting'];
const FAILURE_CATEGORIES: (FailureCategory | 'all')[] = [
  'all',
  'auth',
  'http_4xx',
  'http_5xx',
  'network',
  'unknown',
];

export interface PersistedInboxFilters {
  mainTab: MainTab | null;
  subTab: SubTab | null;
  search: string | null;
  contactType: string | null;
  queueId: string | null;
  showOnlyRetrying: boolean | null;
  failureCategory: FailureCategory | 'all' | null;
}

const EMPTY: PersistedInboxFilters = {
  mainTab: null,
  subTab: null,
  search: null,
  contactType: null,
  queueId: null,
  showOnlyRetrying: null,
  failureCategory: null,
};

/** Escopos válidos da Inbox. */
export const INBOX_SCOPES = ['mine', 'department', 'all'] as const;
export type InboxScope = (typeof INBOX_SCOPES)[number];

/** Limite defensivo para o termo de busca vindo da URL (evita URLs abusivas). */
const MAX_SEARCH_LENGTH = 200;
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const CONTACT_TYPE_RE = /^[a-z0-9_]{1,40}$/;

function pick<T extends string>(value: string | null | undefined, allowed: readonly T[]): T | null {
  return value && (allowed as readonly string[]).includes(value) ? (value as T) : null;
}

function sanitizeSearch(value: string | null | undefined): string | null {
  if (typeof value !== 'string') return null;
  const trimmed = value.replace(/[\u0000-\u001f\u007f]/g, '').trim();
  if (!trimmed) return '';
  return trimmed.slice(0, MAX_SEARCH_LENGTH);
}

function sanitizeQueueId(value: string | null | undefined): string | null {
  return typeof value === 'string' && UUID_RE.test(value) ? value : null;
}

function sanitizeContactType(value: string | null | undefined): string | null {
  return typeof value === 'string' && CONTACT_TYPE_RE.test(value) ? value : null;
}

/** Lê os filtros persistidos no localStorage (tolerante a payload inválido). */
export function readStoredInboxFilters(): PersistedInboxFilters {
  const raw = safeGetJSON<Partial<PersistedInboxFilters>>(STORAGE_KEY, {});
  return {
    mainTab: pick(raw.mainTab, MAIN_TABS),
    subTab: pick(raw.subTab, SUB_TABS),
    search: sanitizeSearch(raw.search),
    contactType: sanitizeContactType(raw.contactType),
    queueId: sanitizeQueueId(raw.queueId),
    showOnlyRetrying: typeof raw.showOnlyRetrying === 'boolean' ? raw.showOnlyRetrying : null,
    failureCategory: pick(raw.failureCategory, FAILURE_CATEGORIES),
  };
}

/** Grava os filtros atuais no localStorage. */
export function writeStoredInboxFilters(value: PersistedInboxFilters): void {
  safeSetJSON(STORAGE_KEY, value);
}

/** Lê o escopo da URL/localStorage com fallback seguro para 'mine'. */
export function resolveInitialScope(searchString: string): InboxScope {
  const params = new URLSearchParams(searchString);
  const fromUrl = pick(params.get('scope'), INBOX_SCOPES);
  if (fromUrl) return fromUrl;
  let stored: string | null = null;
  try {
    stored = localStorage.getItem('inbox_scope');
  } catch {
    stored = null;
  }
  return pick(stored, INBOX_SCOPES) ?? 'mine';
}

/** Lê o flag showAll da URL/localStorage aceitando apenas booleanos explícitos. */
export function resolveInitialShowAll(searchString: string): boolean {
  const params = new URLSearchParams(searchString);
  const fromUrl = params.get('showAll');
  if (fromUrl === 'true') return true;
  if (fromUrl === 'false') return false;
  try {
    return localStorage.getItem('inbox_show_all') === 'true';
  } catch {
    return false;
  }
}

/**
 * Remove da query string parâmetros de filtro com valores inválidos
 * (links antigos/manipulados). Retorna a nova query e os nomes removidos.
 */
export function sanitizeInboxUrlParams(searchString: string): {
  search: string;
  removed: string[];
} {
  const params = new URLSearchParams(searchString);
  const removed: string[] = [];
  const drop = (key: string) => {
    params.delete(key);
    removed.push(key);
  };

  const checks: Array<[string, (v: string) => boolean]> = [
    ['tab', (v) => (MAIN_TABS as string[]).includes(v)],
    ['subTab', (v) => (SUB_TABS as string[]).includes(v)],
    ['scope', (v) => (INBOX_SCOPES as readonly string[]).includes(v)],
    ['showAll', (v) => v === 'true' || v === 'false'],
    ['failuresOnly', (v) => v === 'true' || v === 'false'],
    ['failureCategory', (v) => (FAILURE_CATEGORIES as string[]).includes(v)],
    ['queue', (v) => v === 'all' || UUID_RE.test(v)],
    ['type', (v) => v === 'all' || CONTACT_TYPE_RE.test(v)],
    ['q', (v) => v.length <= MAX_SEARCH_LENGTH],
  ];

  for (const [key, isValid] of checks) {
    const value = params.get(key);
    if (value !== null && !isValid(value)) drop(key);
  }

  return { search: params.toString(), removed };
}

/**
 * Resolve o estado inicial combinando URL (prioridade) e localStorage (fallback).
 * Valores inválidos na URL são ignorados e caem no fallback persistido.
 */
export function resolveInitialInboxFilters(searchString: string): PersistedInboxFilters {
  const params = new URLSearchParams(searchString);
  const stored = readStoredInboxFilters();

  const urlType = sanitizeContactType(params.get('type'));
  const urlQueue = sanitizeQueueId(params.get('queue'));
  const urlSearch = sanitizeSearch(params.get('q'));
  const urlFailures = params.get('failuresOnly');
  const rawType = params.get('type');
  const rawQueue = params.get('queue');

  return {
    mainTab: pick(params.get('tab'), MAIN_TABS) ?? stored.mainTab ?? EMPTY.mainTab,
    subTab: pick(params.get('subTab'), SUB_TABS) ?? stored.subTab ?? EMPTY.subTab,
    search: urlSearch !== null ? urlSearch : stored.search,
    contactType: urlType && urlType !== 'all' ? urlType : (rawType === 'all' ? null : stored.contactType),
    queueId: urlQueue ?? (rawQueue === 'all' ? null : stored.queueId),
    showOnlyRetrying:
      urlFailures === 'true' ? true : urlFailures === 'false' ? false : stored.showOnlyRetrying,
    failureCategory:
      pick(params.get('failureCategory'), FAILURE_CATEGORIES) ?? stored.failureCategory,
  };
}

/**
 * Presets de filtros da Inbox.
 *
 * Permite salvar combinações comuns de aba/sub-aba/busca/filtros auxiliares
 * e recarregá-las depois. Persistido em localStorage (por navegador/usuário).
 */
import { z } from 'zod';
import { safeGetJSON, safeSetJSON } from '@/lib/safeStorage';
import type { MainTab, SubTab } from '@/features/inbox/components/TicketTabs';
import type { FailureCategory } from '@/features/inbox';

const PRESETS_KEY = 'inbox_filter_presets_v1';

export const MAX_INBOX_PRESETS = 20;
export const PRESET_NAME_MAX_LENGTH = 40;
export const PRESET_SEARCH_MAX_LENGTH = 200;

/** Caracteres de controle e separadores invisíveis são rejeitados. */
// eslint-disable-next-line no-control-regex
const CONTROL_CHARS = /[\u0000-\u001F\u007F\u200B-\u200D\uFEFF]/;

export interface InboxFilterPreset {
  id: string;
  name: string;
  createdAt: string;
  mainTab: MainTab;
  subTab: SubTab;
  search: string;
  contactType: string | null;
  queueId: string | null;
  showOnlyRetrying: boolean;
  failureCategory: FailureCategory | 'all';
}

/** Payload aceito ao criar um preset (sem metadados gerados). */
export type InboxFilterPresetInput = Omit<InboxFilterPreset, 'id' | 'createdAt'>;

/** Schema do nome — usado tanto na UI quanto antes de gravar no storage. */
export const presetNameSchema = z
  .string()
  .trim()
  .min(1, { message: 'Informe um nome para o preset.' })
  .max(PRESET_NAME_MAX_LENGTH, {
    message: `O nome deve ter no máximo ${PRESET_NAME_MAX_LENGTH} caracteres.`,
  })
  .refine((v) => !CONTROL_CHARS.test(v), {
    message: 'O nome contém caracteres inválidos.',
  });

export interface PresetNameValidation {
  ok: boolean;
  /** Nome já normalizado (trim) quando válido. */
  value: string;
  error: string | null;
}

/**
 * Valida o nome de um preset: vazio, tamanho, caracteres de controle e
 * duplicidade (case-insensitive) contra a lista atual.
 * `ignoreId` permite revalidar o próprio preset durante a edição.
 */
export function validatePresetName(
  name: string,
  presets: InboxFilterPreset[] = [],
  ignoreId?: string
): PresetNameValidation {
  const parsed = presetNameSchema.safeParse(name ?? '');
  if (!parsed.success) {
    return { ok: false, value: '', error: parsed.error.issues[0]?.message ?? 'Nome inválido.' };
  }

  const value = parsed.data;
  const duplicated = presets.some(
    (p) => p.id !== ignoreId && p.name.trim().toLowerCase() === value.toLowerCase()
  );
  if (duplicated) {
    return { ok: false, value, error: 'Já existe um preset com esse nome.' };
  }

  return { ok: true, value, error: null };
}

/** Schema completo do preset — protege o localStorage contra entradas corrompidas. */
const presetSchema = z.object({
  id: z.string().min(1),
  name: presetNameSchema,
  createdAt: z.string().min(1).catch(() => new Date().toISOString()),
  mainTab: z.enum(['open', 'resolved', 'search', 'unread']),
  subTab: z.enum(['attending', 'waiting']).catch('waiting'),
  search: z.string().max(PRESET_SEARCH_MAX_LENGTH).catch(''),
  contactType: z.string().nullable().catch(null),
  queueId: z.string().nullable().catch(null),
  showOnlyRetrying: z.boolean().catch(false),
  failureCategory: z.string().catch('all'),
});

function parsePreset(value: unknown): InboxFilterPreset | null {
  const parsed = presetSchema.safeParse(value);
  return parsed.success ? (parsed.data as InboxFilterPreset) : null;
}

/** Remove duplicatas por id e por nome (case-insensitive), preservando a ordem. */
function dedupePresets(presets: InboxFilterPreset[]): InboxFilterPreset[] {
  const seenIds = new Set<string>();
  const seenNames = new Set<string>();
  const result: InboxFilterPreset[] = [];
  for (const p of presets) {
    const key = p.name.trim().toLowerCase();
    if (seenIds.has(p.id) || seenNames.has(key)) continue;
    seenIds.add(p.id);
    seenNames.add(key);
    result.push(p);
  }
  return result;
}

/** Lê os presets salvos, ignorando entradas corrompidas. */
export function readInboxPresets(): InboxFilterPreset[] {
  const raw = safeGetJSON<unknown[]>(PRESETS_KEY, []);
  if (!Array.isArray(raw)) return [];
  const valid = raw
    .map(parsePreset)
    .filter((p): p is InboxFilterPreset => p !== null);
  return dedupePresets(valid).slice(0, MAX_INBOX_PRESETS);
}

/** Grava a lista completa de presets, descartando entradas inválidas. */
export function writeInboxPresets(presets: InboxFilterPreset[]): void {
  const valid = presets
    .map(parsePreset)
    .filter((p): p is InboxFilterPreset => p !== null);
  safeSetJSON(PRESETS_KEY, dedupePresets(valid).slice(0, MAX_INBOX_PRESETS));
}


/**
 * Adiciona (ou substitui pelo nome, case-insensitive) um preset e devolve a lista atualizada.
 */
export function upsertInboxPreset(
  presets: InboxFilterPreset[],
  input: InboxFilterPresetInput
): InboxFilterPreset[] {
  // Permite sobrescrever pelo mesmo nome: ignora o próprio registro na checagem de duplicidade.
  const existing = presets.find(
    (p) => p.name.trim().toLowerCase() === (input.name ?? '').trim().toLowerCase()
  );
  const validation = validatePresetName(input.name, presets, existing?.id);
  if (!validation.ok) return presets;
  const name = validation.value;

  const preset: InboxFilterPreset = {
    ...input,
    name,
    id: existing?.id ?? (globalThis.crypto?.randomUUID?.() ?? `preset_${Date.now()}`),
    createdAt: new Date().toISOString(),
  };

  const rest = presets.filter((p) => p.id !== preset.id);
  return [preset, ...rest].slice(0, MAX_INBOX_PRESETS);
}


/** Remove um preset pelo id. */
export function removeInboxPreset(
  presets: InboxFilterPreset[],
  id: string
): InboxFilterPreset[] {
  return presets.filter((p) => p.id !== id);
}

/**
 * Edita um preset existente pelo id, preservando `id`/`createdAt`.
 * O nome é normalizado; conflitos de nome (case-insensitive) são rejeitados.
 * Retorna a lista original quando o id não existe ou o nome é inválido/duplicado.
 */
export function editInboxPreset(
  presets: InboxFilterPreset[],
  id: string,
  changes: Partial<InboxFilterPresetInput>
): InboxFilterPreset[] {
  const target = presets.find((p) => p.id === id);
  if (!target) return presets;

  const validation = validatePresetName(changes.name ?? target.name, presets, id);
  if (!validation.ok) return presets;
  const nextName = validation.value;


  const updated: InboxFilterPreset = {
    ...target,
    ...changes,
    name: nextName,
    id: target.id,
    createdAt: target.createdAt,
  };

  return presets.map((p) => (p.id === id ? updated : p));
}

/**
 * avatarBatchStore — Gerencia o carregamento e cache dos avatares do WhatsApp.
 *
 * Problema: Componentes de conversa e chat montam em paralelo e tentam resolver
 * a URL do avatar (`profile_picture_url`) individualmente via RPC no FATOR X.
 *
 * Solução:
 *  1. Coalesce: Agrupa JIDs solicitados em uma janela de 100ms.
 *  2. Batch RPC: Faz uma única chamada `get_avatars_by_jids_batch(p_jids)`
 *     que retorna `{ jid: url|null }`.
 *  3. Cache: Mantém as URLs em memória (30 min) e propaga via BroadcastChannel
 *     para outras abas evitarem chamadas repetidas.
 *  4. Failover: Se `VITE_EXTERNAL_SUPABASE_*` não estiver configurada (cliente
 *     direto indisponível), cai para o edge function `external-db-proxy`,
 *     que usa service-role secrets server-side. Esse caminho é o que mantém
 *     as fotos aparecendo em deploys sem env client-side (Lovable preview etc.).
 */
import { getExternalSupabase, isExternalConfigured } from '@/integrations/supabase/externalClient';
import { queryExternalProxy } from '@/lib/externalProxy';
import { getLogger } from '@/lib/logger';

const log = getLogger('AvatarBatchStore');

const BATCH_WINDOW_MS = 100;
const CACHE_TTL_MS = 1000 * 60 * 30; // 30 minutos
const NEGATIVE_TTL_MS = 1000 * 60 * 5; // null persiste por 5 min (não 30) para
// dar chance ao backend popular a foto.
const BC_NAME = 'avatar-updates';
const RPC_NAME = 'get_avatars_by_jids_batch';

interface AvatarCacheEntry {
  url: string | null;
  expiresAt: number;
}

// In-memory cache
const avatarCache = new Map<string, AvatarCacheEntry>();
// JIDs aguardando processamento na janela atual
const pendingJids = new Set<string>();
// Promises de resolução para JIDs em voo
const resolvers = new Map<string, Array<(url: string | null) => void>>();
// Timer da janela de batch
let batchTimer: ReturnType<typeof setTimeout> | null = null;
// Canal de broadcast para sync entre abas
let bc: BroadcastChannel | null = null;

if (typeof window !== 'undefined') {
  try {
    bc = new BroadcastChannel(BC_NAME);
    bc.onmessage = (e) => {
      const { jid, url } = e.data;
      if (jid && url !== undefined) {
        avatarCache.set(jid, {
          url,
          expiresAt: Date.now() + (url ? CACHE_TTL_MS : NEGATIVE_TTL_MS),
        });
        const list = resolvers.get(jid);
        if (list) {
          list.forEach((resolve) => resolve(url));
          resolvers.delete(jid);
        }
      }
    };
  } catch {
    /* BroadcastChannel indisponível */
  }
}

/**
 * Resolve a batch via RPC direta (cliente externo) ou via proxy edge function.
 * Sempre retorna `Record<jid, url|null>` — falhas são logadas e viram null.
 */
async function fetchAvatarBatch(jids: string[]): Promise<Record<string, string | null>> {
  if (jids.length === 0) return {};

  // 1. Caminho rápido: cliente externo direto (env vars presentes)
  if (isExternalConfigured) {
    const client = getExternalSupabase();
    if (client) {
      try {
        const { data, error } = await (client.rpc as any)(RPC_NAME, { p_jids: jids });
        if (error) {
          const isMissing = error.code === '42883' || error.message?.includes('does not exist');
          if (isMissing) {
            log.debug('Avatar batch RPC not available, using fallback avatars');
          } else {
            log.warn('Direct RPC failed, falling back to proxy', { error: error.message });
          }
        } else {
          return (data ?? {}) as Record<string, string | null>;
        }
      } catch (err) {
        log.debug('Direct RPC unavailable, falling back to proxy', {
          error: err instanceof Error ? err.message : String(err),
        });
      }
    }
  }

  // 2. Fallback servidor-side via edge function (sem dependência de env client).
  //    O proxy normaliza a resposta para `{ data: T[] }` — para uma RPC que
  //    devolve um único objeto jsonb, isso vira `data[0]`.
  try {
    const result = await queryExternalProxy<Record<string, string | null>>({
      action: 'rpc',
      rpc: RPC_NAME,
      params: { p_jids: jids },
    });
    if (result.error) {
      const errStr = typeof result.error === 'string' ? result.error : JSON.stringify(result.error);
      const isMissing = errStr.includes('42883') || errStr.includes('does not exist');
      if (isMissing) {
        log.debug('Avatar batch RPC not available via proxy, using fallback avatars');
      } else {
        log.error('Proxy RPC error', { error: result.error });
      }
      return {};
    }
    const first = Array.isArray(result.data) ? result.data[0] : result.data;
    return (first ?? {}) as Record<string, string | null>;
  } catch (err) {
    log.debug('Proxy RPC unavailable for avatars', {
      error: err instanceof Error ? err.message : String(err),
    });
    return {};
  }
}

async function processBatch() {
  batchTimer = null;
  const jidsToFetch = Array.from(pendingJids);
  pendingJids.clear();

  if (jidsToFetch.length === 0) return;

  const results = await fetchAvatarBatch(jidsToFetch);

  jidsToFetch.forEach((jid) => {
    const url = results[jid] ?? null;
    resolveJid(jid, url);
    bc?.postMessage({ jid, url });
  });
}

function resolveJid(jid: string, url: string | null) {
  avatarCache.set(jid, {
    url,
    expiresAt: Date.now() + (url ? CACHE_TTL_MS : NEGATIVE_TTL_MS),
  });
  const list = resolvers.get(jid);
  if (list) {
    list.forEach((resolve) => resolve(url));
    resolvers.delete(jid);
  }
}

/**
 * Solicita a URL do avatar de um contato.
 * Retorna do cache se disponível, caso contrário entra no próximo lote.
 * Nunca lança — falhas viram `null` para o caller renderizar fallback.
 */
/** Returns the avatar URL for a contact JID, using cache when valid; otherwise coalesces into the next batch RPC call (100ms window). Never throws — failures return null. */
export async function getContactAvatar(jid: string): Promise<string | null> {
  if (!jid) return null;

  // 1. Check cache
  const cached = avatarCache.get(jid);
  if (cached && cached.expiresAt > Date.now()) {
    return cached.url;
  }

  // 2. Already in-flight?
  return new Promise((resolve) => {
    const list = resolvers.get(jid) || [];
    list.push(resolve);
    resolvers.set(jid, list);

    if (list.length === 1) {
      // First one to ask: add to pending and schedule flush
      pendingJids.add(jid);
      if (!batchTimer) {
        batchTimer = setTimeout(processBatch, BATCH_WINDOW_MS);
      }
    }
  });
}

/** Pre-popula o cache (usado quando a lista de contatos já traz a URL). */
export function seedAvatarCache(jid: string, url: string | null) {
  if (!jid) return;
  avatarCache.set(jid, {
    url,
    expiresAt: Date.now() + (url ? CACHE_TTL_MS : NEGATIVE_TTL_MS),
  });
}

/** Limpa o cache (para testes ou quando o usuário muda de workspace). */
export function clearAvatarCache() {
  avatarCache.clear();
  resolvers.clear();
  pendingJids.clear();
  if (batchTimer) {
    clearTimeout(batchTimer);
    batchTimer = null;
  }
}

import { useEffect } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { safeClient } from '@/integrations/supabase/safeClient';
import { useAuth } from '@/features/auth';
import { queryKeys } from '@/services/api/queryKeys';
import type { TeamConversation, TeamMember, TeamMessage } from './teamChatTypes';

/** Fetches the current agent's team conversations with member profiles and last-message previews, then subscribes to Realtime changes to keep the list current. */
export function useTeamConversations() {
  const { profile } = useAuth();
  const queryClient = useQueryClient();

  const query = useQuery({
    queryKey: queryKeys.teamChat.conversationList(profile?.id),
    queryFn: async () => {
      if (!profile) return [];

      // Fetch conversations directly - RLS will filter to what the user can see
      const { data: conversations, error: convErr } = await supabase
        .from('team_conversations')
        .select('*')
        .order('updated_at', { ascending: false });

      if (convErr) throw convErr;
      if (!conversations?.length) return [];

      const convIds = conversations.map((c) => c.id);

      // Fetch memberships and profiles for these conversations
      const [membershipsResult, membersResult] = await Promise.all([
        supabase
          .from('team_conversation_members')
          .select('conversation_id, last_read_at')
          .eq('profile_id', profile.id)
          .in('conversation_id', convIds),
        safeClient.from('team_conversation_members', (q) =>
          q
            .select('*, profile:profiles(id, name, email, avatar_url, is_active)')
            .in('conversation_id', convIds)
        ),
      ]);

      const lastReadMap = new Map(
        membershipsResult.data?.map((m) => [m.conversation_id, m.last_read_at]) || []
      );
      const allMembers = membersResult.data || [];

      const { data: recentMessages } = await supabase
        .from('team_messages')
        .select('id, conversation_id, content, sender_id, created_at')
        .in('conversation_id', convIds)
        .order('created_at', { ascending: false })
        .limit(convIds.length * 2);

      const lastMessageMap = new Map<
        string,
        {
          id: string;
          conversation_id: string;
          content: string;
          sender_id: string;
          created_at: string;
        }
      >();
      for (const msg of recentMessages || []) {
        if (!lastMessageMap.has(msg.conversation_id)) {
          lastMessageMap.set(msg.conversation_id, msg);
        }
      }

      // Single batch query replaces the former N×COUNT pattern (one per conversation).
      // Fetch all messages not from the current user since 30 days ago and count in-memory,
      // applying each conversation's individual last_read_at cutoff.
      const cutoff = new Date();
      cutoff.setDate(cutoff.getDate() - 30);
      const { data: unreadMessages } = await supabase
        .from('team_messages')
        .select('conversation_id, created_at')
        .in('conversation_id', convIds)
        .neq('sender_id', profile.id)
        .gte('created_at', cutoff.toISOString());

      const unreadMap = new Map<string, number>(convIds.map((cid) => [cid, 0]));
      for (const msg of unreadMessages || []) {
        const lastRead = lastReadMap.get(msg.conversation_id);
        if (!lastRead || msg.created_at > lastRead) {
          unreadMap.set(msg.conversation_id, (unreadMap.get(msg.conversation_id) ?? 0) + 1);
        }
      }

      const enriched: TeamConversation[] = conversations.map((conv) => {
        const members = (allMembers || []).filter(
          (m: any) => m.conversation_id === conv.id
        ) as TeamMember[];
        const lastMsg = lastMessageMap.get(conv.id) || null;

        let displayName = conv.name;
        if (conv.type === 'direct' && !conv.name) {
          const other = members.find((m) => m.profile_id !== profile.id);
          displayName = other?.profile?.name || 'Chat Direto';
        }

        return {
          ...conv,
          type: conv.type as 'direct' | 'group' | 'department',
          name: displayName ?? 'Conversa',
          avatar_url:
            conv.type === 'direct' && !conv.avatar_url
              ? members.find((m) => m.profile_id !== profile.id)?.profile?.avatar_url
              : conv.avatar_url,
          members,
          last_message: lastMsg as TeamMessage | null,
          unread_count: unreadMap.get(conv.id) || 0,
        };
      });

      return enriched;
    },
    enabled: !!profile,
    refetchInterval: 30000,
    staleTime: 10000,
  });

  useEffect(() => {
    if (!profile) return;
    const channel = supabase
      .channel('team-chat-updates')
      // team_messages: tabela física em zapp (migration 000005 moveu de public)
      .on('postgres_changes', { event: '*', schema: 'zapp', table: 'team_messages' }, () => {
        void queryClient.invalidateQueries({ queryKey: queryKeys.teamChat.conversations() });
      })
      // team_conversations + team_conversation_members: tabelas físicas em zapp
      .on('postgres_changes', { event: '*', schema: 'zapp', table: 'team_conversations' }, () => {
        void queryClient.invalidateQueries({ queryKey: queryKeys.teamChat.conversations() });
      })
      .on(
        'postgres_changes',
        { event: '*', schema: 'zapp', table: 'team_conversation_members' },
        () => {
          void queryClient.invalidateQueries({ queryKey: queryKeys.teamChat.conversations() });
        }
      )
      .subscribe();
    return () => {
      channel.unsubscribe();
      supabase.removeChannel(channel);
    };
  }, [profile, queryClient]);

  return query;
}

import { useState, useRef, useCallback, useEffect } from 'react';
import { log } from '@/lib/logger';
import { supabase } from '@/integrations/supabase/client';
import { normalizeMediaUrl } from '@/utils/normalizeMediaUrl';
import { toast } from 'sonner';
import { useEvolutionApi } from '@/hooks/useEvolutionApi';
import { newRequestId } from '@/lib/withRequestId';
import { dbFrom } from '@/integrations/datasource/db';
import type { AudioMemeItem } from '@/hooks/useAudioManagement';
import { evolutionInstanceName } from '@/lib/evolutionInstance';
import { isValidUUID } from '@/utils/uuid';

/**
 * Encapsulates WhatsApp instance resolution and media-message sending
 * (stickers, custom emojis, audio memes) to keep ChatPanel lean.
 *
 * HISTÓRICO:
 * - Audit 02/05/2026: safe-guard em contactPhone, retry no updateMessageStatus.
 * - 2026-07-08: removida referência à tabela fantasma `evolution_contacts`.
 *   Resolução de instância agora usa exclusivamente `contacts.whatsapp_connection_id`
 *   + fallback para primeira conexão ativa.
 */
/** Encapsulates WhatsApp instance resolution and media-message sending (stickers, custom emojis, audio memes) for a given contact. */
export function useChatMediaSending(contactId: string, contactPhone: string | undefined) {
  const [instanceName, setInstanceName] = useState('');
  const [whatsappConnectionId, setWhatsappConnectionId] = useState<string | null>(null);
  const resolvedRef = useRef(false);

  useEffect(() => {
    resolvedRef.current = false;
    setInstanceName('');
    setWhatsappConnectionId(null);
  }, [contactId]);

  const { sendStickerMessage } = useEvolutionApi();

  /** Safely extract digits from phone, returns empty string if undefined */
  const getSafePhone = useCallback((): string => {
    if (!contactPhone) return '';
    return contactPhone.replace(/\D/g, '');
  }, [contactPhone]);

  /** Update message status with error logging and 1 retry */
  const updateMessageStatus = useCallback(
    async (messageId: string, status: string, externalId?: string | null) => {
      const payload: { status: string; external_id?: string | null } = { status };
      if (externalId) payload.external_id = externalId;

      try {
        const { error } = await supabase.from('messages').update(payload).eq('id', messageId);

        if (error) {
          log.error(`[updateMessageStatus] First attempt failed for ${messageId}:`, error.message);
          // Retry once
          const { error: retryError } = await supabase
            .from('messages')
            .update(payload)
            .eq('id', messageId);
          if (retryError) {
            log.error(`[updateMessageStatus] Retry failed for ${messageId}:`, retryError.message);
          }
        }
      } catch (err) {
        log.error(`[updateMessageStatus] Exception for ${messageId}:`, err);
      }
    },
    []
  );

  const resolveInstance = useCallback(async (): Promise<string> => {
    if (instanceName) return instanceName;
    if (!isValidUUID(contactId)) return '';

    try {
      let connectionId: string | null = null;

      const { data: contact } = await supabase
        .from('contacts')
        .select('whatsapp_connection_id')
        .eq('id', contactId)
        .maybeSingle();

      if (contact?.whatsapp_connection_id) {
        connectionId = contact.whatsapp_connection_id;
      }

      if (connectionId) {
        setWhatsappConnectionId(connectionId);
        const { data: conn } = await supabase
          .from('whatsapp_connections')
          .select('instance_id, instance_name')
          .eq('id', connectionId)
          .maybeSingle();
        const resolved = conn ? evolutionInstanceName(conn) : null;
        if (resolved) {
          setInstanceName(resolved);
          return resolved;
        }
        // specific connection exists but has no routable name (UUID-only) — do not fall back
        return '';
      }

      const { data: fallbackConn } = await supabase
        .from('whatsapp_connections')
        .select('id, instance_id, instance_name')
        .eq('status', 'connected')
        .limit(1)
        .maybeSingle();

      const fallbackResolved = fallbackConn ? evolutionInstanceName(fallbackConn) : null;
      if (fallbackResolved) {
        setInstanceName(fallbackResolved);
        const connId = (fallbackConn as unknown as { id?: string }).id;
        if (connId) setWhatsappConnectionId(connId);
        return fallbackResolved;
      }
    } catch (err) {
      log.error('Failed to resolve WhatsApp instance:', err);
    }
    return '';
  }, [contactId, instanceName]);

  const initResolve = useCallback(async () => {
    if (!resolvedRef.current) {
      resolvedRef.current = true;
      await resolveInstance();
    }
  }, [resolveInstance]);

  const ensureInstance = useCallback(async (): Promise<string | null> => {
    const resolved = instanceName || (await resolveInstance());
    if (!resolved || !contactPhone) {
      toast.error('Conexão WhatsApp não disponível.');
      return null;
    }
    return resolved;
  }, [instanceName, resolveInstance, contactPhone]);

  const handleSendSticker = useCallback(
    async (stickerUrl: string) => {
      const inst = await ensureInstance();
      if (!inst) return;

      // BUG 2 FIX: Safe phone extraction instead of non-null assertion
      const phone = getSafePhone();
      if (!phone) {
        toast.error('Telefone do contato não disponível.');
        return;
      }

      try {
        const { data: dbData, error: dbDataErr } = await supabase
          .from('messages')
          .insert({
            contact_id: contactId,
            whatsapp_connection_id: whatsappConnectionId,
            content: '[Sticker]',
            message_type: 'sticker',
            media_url: stickerUrl,
            sender: 'agent',
            status: 'sending',
          })
          .select('id')
          .maybeSingle(); // ✅ fix: maybeSingle evita PGRST116;

        if (dbDataErr) {
          log.error('[Sticker] DB insert failed:', dbDataErr);
        }

        const messageId = dbData?.id;
        let externalId: string | null = null;

        try {
          const result = await sendStickerMessage(inst, phone, stickerUrl);
          externalId = (result as any)?.key?.id || null;
        } catch (err: unknown) {
          if (messageId) await updateMessageStatus(messageId, 'failed');
          toast.error(err instanceof Error ? err.message : 'Erro ao enviar figurinha');
          return;
        }

        if (!externalId) {
          if (messageId) await updateMessageStatus(messageId, 'failed');
          toast.error('Erro ao enviar figurinha: falha na API');
          return;
        }

        // FALHA 5 FIX: Proper error handling on status update
        if (messageId) {
          await updateMessageStatus(messageId, 'sent', externalId);
        }

        // FALHA 6 FIX: Auto-save with error handling
        try {
          const { data: existing, error: _existingErr } = await supabase
            .from('stickers')
            .select('id')
            .eq('image_url', stickerUrl)
            .maybeSingle();

          if (!existing) {
            const {
              data: { user },
            } = await supabase.auth.getUser();
            const { error: saveError } = await supabase.from('stickers').insert({
              name: `Enviada ${new Date().toLocaleDateString('pt-BR')}`,
              image_url: stickerUrl,
              category: 'enviadas',
              is_favorite: false,
              use_count: 1,
              uploaded_by: user?.id || null,
            });
            if (saveError) {
              log.error('[auto-save sticker] Failed:', saveError.message);
            }
          }
        } catch (err) {
          log.error('[auto-save sticker] Exception:', err);
        }

        toast.success('Figurinha enviada!');
      } catch {
        toast.error('Erro ao enviar figurinha');
      }
    },
    [
      ensureInstance,
      contactId,
      whatsappConnectionId,
      sendStickerMessage,
      getSafePhone,
      updateMessageStatus,
    ]
  );

  const handleSendCustomEmoji = useCallback(
    async (emojiUrl: string) => {
      const inst = await ensureInstance();
      if (!inst) return;

      // BUG 2 FIX
      const phone = getSafePhone();
      if (!phone) {
        toast.error('Telefone do contato não disponível.');
        return;
      }

      try {
        const isUrl = emojiUrl.startsWith('http');
        const trace = newRequestId('emoji');

        const apiPromise = isUrl
          ? supabase.functions.invoke('evolution-api', {
              method: 'POST',
              body: {
                action: 'send-media',
                instanceName: inst,
                number: phone,
                mediaUrl: emojiUrl,
                mediaType: 'image',
              },
              headers: trace.headers,
            })
          : supabase.functions.invoke('evolution-api', {
              method: 'POST',
              body: { action: 'send-text', instanceName: inst, number: phone, text: emojiUrl },
              headers: trace.headers,
            });

        const dbPromise = dbFrom('messages')
          .insert({
            contact_id: contactId,
            whatsapp_connection_id: whatsappConnectionId,
            content: isUrl ? '[Emoji]' : emojiUrl,
            message_type: isUrl ? 'image' : 'text',
            media_url: isUrl ? emojiUrl : null,
            sender: 'agent',
            status: 'sending',
            request_id: trace.requestId,
          })
          .select('id')
          .maybeSingle(); // ✅ fix: maybeSingle evita PGRST116;

        const results = await Promise.allSettled([apiPromise, dbPromise]);
        const apiResult =
          results[0].status === 'fulfilled' ? results[0].value : { error: true, data: null };
        const dbResult =
          results[1].status === 'fulfilled' ? results[1].value : { data: null, error: true };

        const messageId = dbResult?.data?.id;
        const externalId = apiResult?.data?.key?.id || null;

        if (results[0].status === 'rejected' || results[1].status === 'rejected') {
          if (messageId) await updateMessageStatus(messageId, 'failed');
          toast.error('Erro ao enviar emoji');
          return;
        }

        if (apiResult?.error || !externalId) {
          if (messageId) await updateMessageStatus(messageId, 'failed');
          toast.error('Erro ao enviar emoji');
          return;
        }

        // FIX: proper await instead of fire-and-forget
        if (messageId) {
          await updateMessageStatus(messageId, 'sent', externalId);
        }
        toast.success('Emoji enviado!');
      } catch {
        toast.error('Erro ao enviar emoji');
      }
    },
    [ensureInstance, contactId, whatsappConnectionId, getSafePhone, updateMessageStatus]
  );

  const handleSendAudioMeme = useCallback(
    async (meme: AudioMemeItem | string) => {
      const inst = await ensureInstance();
      if (!inst) return;

      const phone = getSafePhone();
      if (!phone) {
        toast.error('Telefone do contato não disponível.');
        return;
      }

      try {
        const audioUrl = typeof meme === 'string' ? meme : meme.audio_url;
        const memeId = typeof meme === 'string' ? null : (meme.id ?? null);
        const normalizedAudioUrl = normalizeMediaUrl(audioUrl);
        const trace = newRequestId('audio');

        // DOC ARCHITECTURE COMPLIANCE:
        // We still insert into local 'messages' (Lovable Cloud) for UI persistence,
        // but if we have a memeId, the backend (FATOR X) will handle use_count++ and audio_meme_id linkage
        // when we invoke the edge function.

        const apiPromise = supabase.functions.invoke('evolution-api', {
          body: {
            action: 'send-audio',
            instanceName: inst,
            number: phone,
            audio: normalizedAudioUrl, // Use 'audio' as per evolution-api index.ts
            encoding: true,
            isPtt: true, // Audio memes MUST appear as voice notes (green waveform)
            audio_meme_id: memeId,
          },
          headers: trace.headers,
        });

        const dbPromise = dbFrom('messages')
          .insert({
            contact_id: contactId,
            whatsapp_connection_id: whatsappConnectionId,
            content: '[Áudio Meme]',
            message_type: 'audio',
            media_url: normalizedAudioUrl,
            sender: 'agent',
            status: 'sending',
            request_id: trace.requestId,
            // If your local 'messages' table has audio_meme_id, propagate it
            ...(memeId ? { audio_meme_id: memeId } : {}),
          })
          .select('id')
          .maybeSingle(); // ✅ fix: maybeSingle evita PGRST116;

        const results = await Promise.allSettled([apiPromise, dbPromise]);
        const apiResult =
          results[0].status === 'fulfilled' ? results[0].value : { error: true, data: null };
        const dbResult =
          results[1].status === 'fulfilled' ? results[1].value : { data: null, error: true };

        const messageId = dbResult?.data?.id;

        if (results[0].status === 'rejected' || results[1].status === 'rejected') {
          log.error('Audio meme send failed - rejected promise');
          if (messageId) await updateMessageStatus(messageId, 'failed');
          toast.error('Erro ao enviar áudio meme');
          return;
        }

        if (apiResult?.error || !apiResult?.data?.key?.id) {
          log.error('Audio meme send failed', apiResult?.error);
          if (messageId) await updateMessageStatus(messageId, 'failed');
          toast.error('Erro ao enviar áudio meme');
          return;
        }

        const externalId = apiResult.data.key.id;
        if (messageId) {
          await updateMessageStatus(messageId, 'sent', externalId);
        }
        toast.success('🔊 Áudio meme enviado!');
      } catch (err) {
        log.error('handleSendAudioMeme error', err);
        toast.error('Erro ao enviar áudio meme');
      }
    },
    [ensureInstance, contactId, whatsappConnectionId, getSafePhone, updateMessageStatus]
  );

  return {
    instanceName,
    whatsappConnectionId,
    initResolve,
    resolveInstance,
    handleSendSticker,
    handleSendCustomEmoji,
    handleSendAudioMeme,
  };
}

import { useState, useEffect, useCallback } from 'react';
import { externalSupabase, isExternalConfigured } from '@/integrations/supabase/externalClient';
import { useAuth } from '@/features/auth';
import { getLogger } from '@/lib/logger';
import type { IncomingCall } from '@/types/incomingCall';


const log = getLogger('IncomingCallBroadcast');

const DEFAULT_INSTANCE = 'wpp2';

interface BroadcastPayload {
  remote_jid?: string;
  is_video?: boolean;
  call_status?: string;
  agent_profile_id?: string | null;
  started_at?: string;
  wa_call_id?: string | null;
}

/** Subscribes to incoming WhatsApp call broadcasts on the external Supabase channel for a given Evolution instance. */
export function useIncomingCallBroadcast(instance: string = DEFAULT_INSTANCE) {
  const { profile } = useAuth();
  const [incomingCall, setIncomingCall] = useState<IncomingCall | null>(null);

  const dismissCall = useCallback(() => {
    setIncomingCall(null);
  }, []);

  useEffect(() => {
    if (!isExternalConfigured || !externalSupabase || !profile?.id) return;
    const supabase = externalSupabase;

    const topic = `incoming-calls:${instance}`;
    const channel = supabase
      .channel(topic)
      .on('broadcast', { event: 'call_received' }, async ({ payload }) => {
        const p = (payload ?? {}) as BroadcastPayload;

        if (!p.remote_jid) {
          log.warn('Broadcast received without remote_jid', p);
          return;
        }

        // Defense against status@broadcast and *@broadcast jids
        if (/@broadcast$/i.test(p.remote_jid)) {
          return;
        }

        // Filter by agent (null = global broadcast also accepted)
        if (p.agent_profile_id && p.agent_profile_id !== profile.id) {
          return;
        }

        const phoneFallback = p.remote_jid.replace(/@s\.whatsapp\.net$/, '').replace(/@c\.us$/, '');

        let contactName = phoneFallback;
        let contactPhone = phoneFallback;
        let contactAvatar: string | null = null;
        let contactId: string | null = null;

        try {
          const { data, error } = await supabase.rpc('rpc_get_contact' as any, {
            p_remote_jid: p.remote_jid,
            p_instance: instance,
          });

          if (error) {
            log.error('rpc_get_contact failed, using phone fallback', error);
          } else if (data) {
            type ContactLookup = {
              push_name?: string | null;
              name?: string | null;
              full_name?: string | null;
              phone?: string | null;
              profile_picture_url?: string | null;
              id?: string | null;
            };
            const row = (Array.isArray(data) ? data[0] : data) as ContactLookup | null;
            if (row) {
              contactName = row.push_name || row.name || row.full_name || phoneFallback;
              contactPhone = row.phone || phoneFallback;
              contactAvatar = row.profile_picture_url ?? null;
              contactId = row.id ?? null;
            }
          }
        } catch (err) {
          log.error('Unexpected error resolving contact', err);
        }

        setIncomingCall({
          id: p.wa_call_id || `bcast_${Date.now()}`,
          contact_id: contactId,
          contact_name: contactName,
          contact_phone: contactPhone,
          contact_avatar_url: contactAvatar,
          is_video: !!p.is_video,
          whatsapp_connection_id: null,
          started_at: p.started_at || new Date().toISOString(),
        });

        log.info(`Broadcast incoming ${p.is_video ? 'video' : 'audio'} call from ${contactName}`);
      })
      .subscribe();

    return () => {
      externalSupabase.removeChannel(channel);
    };
  }, [profile?.id, instance]);

  return { incomingCall, dismissCall };
}

import { useState, useCallback, useRef, useEffect } from 'react';
import { getLogger } from '@/lib/logger';
import { v4 as uuidv4 } from 'uuid';
import { toast } from '@/hooks/use-toast';

const log = getLogger('useMessageQueue');

/** Retry and back-off configuration for the outbound message queue. */
export interface QueueConfig {
  maxRetries: number;
  baseDelay: number;
  maxDelay: number;
  jitter: boolean;
}

/** Default queue config: 3 retries with 1s base / 30s max exponential back-off and jitter. */
export const DEFAULT_QUEUE_CONFIG: QueueConfig = {
  maxRetries: 3,
  baseDelay: 1000, // 1s
  maxDelay: 30000, // 30s
  jitter: true,
};

/** Single item in the outbound message queue, carrying lifecycle status, retry counters, progress, and per-attempt timing. */
export interface QueueItem {
  id: string;
  contactId: string;
  content: string;
  type: 'text' | 'attachment' | 'audio';
  attachments?: File[];
  onProgress?: (p: number) => void;
  status: 'pending' | 'sending' | 'failed' | 'confirmed';
  error?: unknown;
  retryCount: number;
  progress?: number;
  externalId?: string;
  createdAt: number;
  completedAt?: number;
  nextRetryAt?: number;
  attempts: Array<{
    timestamp: number;
    error?: string;
    duration?: number;
  }>;
}

/** Aggregate send metrics computed from queue history: totals by type and conversation with raw latency arrays for P50/P95 computation. */
export interface QueueMetrics {
  totalSent: number;
  totalFailed: number;
  totalRetries: number;
  averageLatency: number;
  byType: Record<string, { sent: number; failed: number; latency: number[] }>;
  byConversation: Record<string, { sent: number; failed: number; latency: number[] }>;
}

/** Public API returned by useMessageQueue: queue state plus add/retry/progress/reconcile/metrics/remove operations. */
export interface MessageQueueController {
  queue: QueueItem[];
  addToQueue: (
    contactId: string,
    content: string,
    attachments?: File[],
    type?: QueueItem['type']
  ) => void;
  retryMessage: (id: string) => void;
  updateProgress: (id: string, progress: number) => void;
  reconcileWithDelivery: (
    contactId: string,
    externalId: string,
    status: 'confirmed' | 'failed'
  ) => void;
  getMetrics: () => QueueMetrics;
  removeFromQueue: (id: string) => void;
}

const MAX_CONCURRENT_SENDS = 5;

/** Manages an ordered outbound message queue with exponential back-off retry, per-conversation concurrency cap, localStorage persistence, and send-metric collection. */
export function useMessageQueue(
  processMessage: (item: QueueItem) => Promise<void>,
  configOverrides?: Partial<Record<string, Partial<QueueConfig>>>
): MessageQueueController {
  const [queue, setQueue] = useState<QueueItem[]>([]);
  const isProcessingRef = useRef<Record<string, boolean>>({});
  const activeTimersRef = useRef(new Set<ReturnType<typeof setTimeout>>());
  const processedDeliveriesRef = useRef<Set<string>>(new Set());
  const currentlySendingRef = useRef<number>(0);

  useEffect(() => {
    return () => {
      activeTimersRef.current.forEach(clearTimeout);
      processedDeliveriesRef.current.clear();
      currentlySendingRef.current = 0;
    };
  }, []);
  const QUEUE_STORAGE_KEY = 'chat_message_queue';

  const getConfig = useCallback(
    (contactId: string): QueueConfig => {
      const overrides = configOverrides?.[contactId] || {};
      return { ...DEFAULT_QUEUE_CONFIG, ...overrides };
    },
    [configOverrides]
  );

  const calculateNextRetryDelay = useCallback((retryCount: number, config: QueueConfig) => {
    // Backoff exponencial: baseDelay * 2^retryCount
    let delay = config.baseDelay * Math.pow(2, retryCount);

    if (config.jitter) {
      // Jitter: +/- 20% de variação aleatória para evitar "thundering herd"
      const jitterAmount = delay * 0.2;
      delay = delay + (Math.random() * jitterAmount * 2 - jitterAmount);
    }

    return Math.min(delay, config.maxDelay);
  }, []);

  // Persistência: Carregar fila ao iniciar
  useEffect(() => {
    const savedQueue = localStorage.getItem(QUEUE_STORAGE_KEY);
    if (savedQueue) {
      try {
        const parsed = JSON.parse(savedQueue) as QueueItem[];
        const restored = parsed.map((item) => {
          // Attachments (File/Blob) não são serializáveis e por isso nunca
          // sobrevivem ao localStorage. Para 'text' isso é inofensivo (o
          // conteúdo real É a string). Para 'audio'/'attachment', `content`
          // é só um rótulo de exibição (ex.: "Mensagem de áudio") — resgatar
          // esses itens como 'pending' faz o processador reenviar esse rótulo
          // como se fosse a mensagem real ao cliente. Marcamos como 'failed'
          // para o usuário decidir regravar/reanexar em vez de reenviar.
          const lostMedia =
            (item.type === 'audio' || item.type === 'attachment') && item.status !== 'confirmed';
          return {
            ...item,
            status: lostMedia
              ? ('failed' as const)
              : item.status === 'sending'
                ? ('pending' as const)
                : item.status,
            progress: item.status === 'sending' ? 0 : item.progress,
            error: lostMedia
              ? 'Anexo perdido ao recarregar a página — reenvie manualmente.'
              : item.error,
            attachments: undefined,
          };
        });
        setQueue(restored);
        log.info('Restored message queue from localStorage');
      } catch (e) {
        log.error('Failed to parse saved queue', e);
      }
    }
  }, []);

  // Persistência: Salvar fila ao mudar
  useEffect(() => {
    const queueToSave = queue.map((item) => ({
      ...item,
      attachments: undefined, // Não serializável
    }));
    localStorage.setItem(QUEUE_STORAGE_KEY, JSON.stringify(queueToSave));
  }, [queue]);

  const updateProgress = useCallback((id: string, progress: number) => {
    setQueue((prev) => prev.map((item) => (item.id === id ? { ...item, progress } : item)));
  }, []);

  // Versão corrigida e simplificada do processamento
  const processNextInQueue = useCallback(
    async (contactId: string) => {
      // Controle de concorrência global: máximo de MAX_CONCURRENT_SENDS simultâneos
      if (currentlySendingRef.current >= MAX_CONCURRENT_SENDS) {
        log.debug(
          `[concurrency] Max concurrent sends (${MAX_CONCURRENT_SENDS}) reached, deferring`
        );
        return;
      }

      if (isProcessingRef.current[contactId]) return;

      // Encontrar o próximo item pendente para este contato
      setQueue((currentQueue) => {
        const contactQueue = currentQueue.filter((item) => item.contactId === contactId);
        const itemToProcess = contactQueue.find((item) => item.status === 'pending');

        if (!itemToProcess) return currentQueue;

        // Se achamos um item, marcamos como enviando e iniciamos o processo fora do setQueue
        isProcessingRef.current[contactId] = true;
        currentlySendingRef.current += 1;

        // Iniciamos o processamento assíncrono
        void (async () => {
          const config = getConfig(contactId);
          const startTime = Date.now();

          try {
            // Verificar se o item já passou do tempo de retry se estiver pendente após falha
            if (itemToProcess.nextRetryAt && itemToProcess.nextRetryAt > Date.now()) {
              isProcessingRef.current[contactId] = false;
              currentlySendingRef.current = Math.max(0, currentlySendingRef.current - 1);
              // Agendar verificação para o tempo exato do retry
              const t1 = setTimeout(
                () => {
                  activeTimersRef.current.delete(t1);
                  processNextInQueue(contactId);
                },
                itemToProcess.nextRetryAt - Date.now() + 10
              );
              activeTimersRef.current.add(t1);
              return;
            }

            log.info(
              `Processing message ${itemToProcess.id} for contact ${contactId} (Retry: ${itemToProcess.retryCount})`
            );

            setQueue((q) =>
              q.map((i) =>
                i.id === itemToProcess.id ? { ...i, status: 'sending', progress: 5 } : i
              )
            );

            // Internal tracking for sequential media uploads
            if (itemToProcess.type !== 'text') {
              updateProgress(itemToProcess.id, 15);
            }

            await processMessage(itemToProcess);

            const completedAt = Date.now();
            const duration = completedAt - startTime;
            setQueue((q) =>
              q.map((i) =>
                i.id === itemToProcess.id
                  ? {
                      ...i,
                      status: 'confirmed',
                      progress: 100,
                      completedAt,
                      nextRetryAt: undefined,
                      attempts: [...(i.attempts || []), { timestamp: Date.now(), duration }],
                    }
                  : i
              )
            );

            const t2 = setTimeout(() => {
              activeTimersRef.current.delete(t2);
              setQueue((q) => q.filter((i) => i.id !== itemToProcess.id));
            }, 5000);
            activeTimersRef.current.add(t2);

            log.info(
              `[INBOX_METRIC] action=send_success contact=${contactId} duration=${duration}ms attempt=${itemToProcess.retryCount}`
            );
          } catch (err) {
            const duration = Date.now() - startTime;
            const errorMsg = err instanceof Error ? err.message : String(err);

            // Observability: Telemetry for failures
            log.error(
              `[QUEUE_ERROR] id=${itemToProcess.id} contact=${contactId} attempt=${itemToProcess.retryCount} err=${errorMsg}`
            );

            const analytics = (
              window as Window & {
                analytics?: { track: (event: string, props?: Record<string, unknown>) => void };
              }
            ).analytics;
            const durationMs = Date.now() - startTime;

            // New Monitoring Logs for Dashboard
            log.info(
              `[INBOX_METRIC] action=send_fail contact=${contactId} duration=${durationMs}ms attempt=${itemToProcess.retryCount}`
            );

            if (analytics) {
              analytics.track('Message Queue Failure', {
                messageId: itemToProcess.id,
                contactId,
                attempt: itemToProcess.retryCount,
                error: errorMsg,
                duration,
              });
            }

            const shouldAutoRetry = itemToProcess.retryCount < config.maxRetries;
            const delay = shouldAutoRetry
              ? calculateNextRetryDelay(itemToProcess.retryCount, config)
              : 0;
            const nextRetryAt = shouldAutoRetry ? Date.now() + delay : undefined;

            setQueue((q) =>
              q.map((i) =>
                i.id === itemToProcess.id
                  ? {
                      ...i,
                      status: shouldAutoRetry ? 'pending' : 'failed',
                      retryCount: i.retryCount + (shouldAutoRetry ? 1 : 0),
                      error: err,
                      progress: 0,
                      nextRetryAt,
                      attempts: [
                        ...(i.attempts || []),
                        { timestamp: Date.now(), error: errorMsg, duration },
                      ],
                    }
                  : i
              )
            );

            if (!shouldAutoRetry) {
              toast({
                title: 'Falha definitiva',
                description:
                  'Atingido limite de tentativas. Você pode tentar manualmente ou remover o item.',
                variant: 'destructive',
              });
            } else {
              log.info(`Scheduled retry for ${itemToProcess.id} in ${Math.round(delay / 1000)}s`);
            }
          } finally {
            isProcessingRef.current[contactId] = false;
            currentlySendingRef.current = Math.max(0, currentlySendingRef.current - 1);
            // Tentar processar o próximo após um pequeno delay ou o tempo do retry
            const t3 = setTimeout(() => {
              activeTimersRef.current.delete(t3);
              processNextInQueue(contactId);
            }, 500);
            activeTimersRef.current.add(t3);
          }
        })();

        return currentQueue; // O estado será atualizado dentro do bloco assíncrono
      });
    },
    [processMessage, getConfig, updateProgress, calculateNextRetryDelay]
  );

  // Disparar processamento quando a fila mudar
  useEffect(() => {
    const contactIds = Array.from(
      new Set(queue.filter((i) => i.status === 'pending').map((i) => i.contactId))
    );
    contactIds.forEach((id) => {
      if (!isProcessingRef.current[id]) {
        processNextInQueue(id);
      }
    });
  }, [queue, processNextInQueue]);

  const addToQueue = useCallback(
    (
      contactId: string,
      content: string,
      attachments?: File[],
      type: 'text' | 'attachment' | 'audio' = 'text'
    ) => {
      const newItem: QueueItem = {
        id: `queue:${uuidv4()}`,
        contactId,
        content,
        type,
        attachments,
        status: 'pending',
        retryCount: 0,
        progress: 0,
        createdAt: Date.now(),
        attempts: [],
      };

      setQueue((prev) => [...prev, newItem]);
      log.info(`Added message to queue: ${newItem.id} (type: ${type})`);
    },
    []
  );

  const retryMessage = useCallback((id: string) => {
    setQueue((prev) =>
      prev.map((item) =>
        item.id === id
          ? {
              ...item,
              status: 'pending',
              error: undefined,
              retryCount: 0,
              progress: 0,
            }
          : item
      )
    );
  }, []);

  const reconcileWithDelivery = useCallback(
    (contactId: string, externalId: string, status: 'confirmed' | 'failed') => {
      const dedupeKey = `${contactId}:${externalId}:${status}`;
      if (processedDeliveriesRef.current.has(dedupeKey)) {
        log.debug('[dedup] Already processed delivery event', { contactId, externalId, status });
        return;
      }
      processedDeliveriesRef.current.add(dedupeKey);

      setQueue((prev) => {
        const item = prev.find(
          (i) =>
            i.contactId === contactId && (i.externalId === externalId || i.content === externalId)
        );
        if (!item) return prev;

        if (status === 'confirmed') {
          return prev.filter((i) => i.id !== item.id);
        } else {
          return prev.map((i) =>
            i.id === item.id ? { ...i, status: 'failed', completedAt: Date.now() } : i
          );
        }
      });
    },
    []
  );

  // Compute metrics from the queue items (including those just processed)
  const getMetrics = useCallback((): QueueMetrics => {
    const metrics: QueueMetrics = {
      totalSent: 0,
      totalFailed: 0,
      totalRetries: 0,
      averageLatency: 0,
      byType: {},
      byConversation: {},
    };

    const confirmedItems = queue.filter((i) => i.status === 'confirmed');
    const failedItems = queue.filter((i) => i.status === 'failed');

    metrics.totalSent = confirmedItems.length;
    metrics.totalFailed = failedItems.length;

    const allItems = [...confirmedItems, ...failedItems];
    let totalLatency = 0;
    let latencyCount = 0;

    allItems.forEach((item) => {
      const type = item.type;
      const conv = item.contactId;
      const latency = item.completedAt ? item.completedAt - item.createdAt : 0;

      if (!metrics.byType[type]) metrics.byType[type] = { sent: 0, failed: 0, latency: [] };
      if (!metrics.byConversation[conv])
        metrics.byConversation[conv] = { sent: 0, failed: 0, latency: [] };

      if (item.status === 'confirmed') {
        metrics.byType[type].sent++;
        metrics.byConversation[conv].sent++;
        if (latency > 0) {
          metrics.byType[type].latency.push(latency);
          metrics.byConversation[conv].latency.push(latency);
          totalLatency += latency;
          latencyCount++;
        }
      } else {
        metrics.byType[type].failed++;
        metrics.byConversation[conv].failed++;
      }

      metrics.totalRetries += item.retryCount;
    });

    metrics.averageLatency = latencyCount > 0 ? totalLatency / latencyCount : 0;

    return metrics;
  }, [queue]);

  return {
    queue,
    addToQueue,
    retryMessage,
    updateProgress,
    reconcileWithDelivery,
    getMetrics,
    removeFromQueue: (id: string) => {
      setQueue((prev) => prev.filter((item) => item.id !== id));
    },
  };
}

/**
 * Carrega o histórico completo de envio de uma mensagem para o painel
 * de debug: linha do tempo de tentativas (retry_metrics.retry_reasons),
 * métricas agregadas e entradas relacionadas em audit_logs.
 *
 * Todos os shapes vêm de `messageSendHistory.schemas.ts` (Zod) para
 * garantir tolerância a linhas legadas e derivação consistente de
 * `finalStatus`.
 */
import { queryKeys } from '@/services/api/queryKeys';
import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { fromTable } from '@/lib/supabaseHelpers';
import {
  type AuditEntry,
  type FinalStatus,
  type RetryAttempt,
  dedupeAuditEntries,
  deriveFinalStatus,
  normalizeRetryReasons,
  padRetryAttempts,
} from './messageSendHistory.schemas';

/** Re-exported module members. */
export type { AuditEntry, FinalStatus, RetryAttempt };

/** Aggregated send-history for a single message: retry metrics row plus deduplicated outbound_delivery_audit entries. */
export interface MessageSendHistory {
  metric: {
    id: string;
    action: string;
    method: string;
    finalStatus: FinalStatus;
    finalHttpStatus: number | null;
    attemptCount: number;
    totalDurationMs: number | null;
    instanceName: string | null;
    idempotencyKey: string | null;
    retryReasons: RetryAttempt[];
    createdAt: string;
    rawJson: unknown;
  } | null;
  auditEntries: AuditEntry[];
}

const STALE_MS = 15_000;

/** Fetches the full send-history audit trail for a message (retry metrics + outbound audit log), normalises shapes via Zod, and dedupes entries for the debug sheet. */
export function useMessageSendHistory(messageId: string | undefined, enabled: boolean) {
  return useQuery<MessageSendHistory>({
    queryKey: queryKeys.messageDetails.sendHistory(messageId),
    enabled: Boolean(messageId) && enabled,
    staleTime: STALE_MS,
    queryFn: async (): Promise<MessageSendHistory> => {
      if (!messageId) return { metric: null, auditEntries: [] };

      const idempotencyKey = `msg:${messageId}`;
      const outboundQuery = fromTable('outbound_delivery_audit')
        .select(
          'id, event_type, status, latency_ms, instance_name, error_message, created_at, metadata'
        )
        .eq('idempotency_key', idempotencyKey)
        .order('created_at', { ascending: false })
        .limit(10);
      const [metricRes, auditRes, outboundAuditRes] = await Promise.all([
        supabase
          .from('evolution_retry_metrics')
          .select('*')
          .eq('idempotency_key', idempotencyKey)
          .order('created_at', { ascending: false })
          .limit(1)
          .maybeSingle(),
        supabase
          .from('audit_logs')
          .select('id, action, created_at, details')
          .eq('entity_type', 'message')
          .eq('entity_id', messageId)
          .order('created_at', { ascending: false })
          .limit(20),
        outboundQuery,
      ]);

      const auditEntries: AuditEntry[] = (auditRes.data ?? []).map((e) => ({
        id: e.id,
        action: e.action,
        createdAt: e.created_at ?? new Date(0).toISOString(),
        details: e.details,
      }));

      const outboundEntries: AuditEntry[] = (outboundAuditRes.data ?? []).map((e: any) => ({
        id: e.id,
        action: `OUTBOUND_${(e.event_type ?? 'send').toUpperCase()}`,
        createdAt: e.created_at,
        details: {
          status: e.status,
          latency: e.latency_ms,
          instance: e.instance_name,
          error_message: e.error_message,
          ...(e.metadata && typeof e.metadata === 'object' ? e.metadata : {}),
        },
      }));

      const combinedAudit = dedupeAuditEntries(
        [...auditEntries, ...outboundEntries].sort(
          (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
        )
      );

      const row = metricRes.data;
      if (!row) return { metric: null, auditEntries: combinedAudit };

      // These columns exist on the view but aren't in the generated types yet
      type RowExtra = typeof row & {
        external_message_id?: string | null;
        max_retries?: number | null;
        next_retry_at?: string | null;
      };
      const rowEx = row as RowExtra;

      const attempts = padRetryAttempts(
        normalizeRetryReasons(row.retry_reasons),
        row.attempt_count ?? 0
      );
      const finalStatus = deriveFinalStatus({
        externalMessageId: rowEx.external_message_id ?? null,
        retryCount: row.attempt_count ?? 0,
        maxRetries: rowEx.max_retries ?? attempts.length,
        nextRetryAt: rowEx.next_retry_at ?? null,
        storedFinalStatus: row.final_status,
      });

      return {
        metric: {
          id: row.id,
          action: row.action,
          method: row.method ?? 'unknown',
          finalStatus,
          finalHttpStatus: row.final_http_status,
          attemptCount: row.attempt_count ?? 0,
          totalDurationMs: row.total_duration_ms,
          instanceName: row.instance_name,
          idempotencyKey: row.idempotency_key,
          retryReasons: attempts,
          createdAt: row.created_at ?? new Date(0).toISOString(),
          rawJson: row,
        },
        auditEntries: combinedAudit,
      };
    },
  });
}

import { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { dbFrom, dbTable, dbChannel, dbRemoveChannel } from '@/integrations/datasource/db';
import { RealtimePostgresChangesPayload } from '@supabase/supabase-js';
import { getLogger } from '@/lib/logger';
import { sendMessageToContact } from './realtime/messageSender';
import { subscribeAllSendStatus, getSendStatus } from './realtime/sendStatusBus';
import {
  normalizeMessage,
  buildConversation,
  dedupeContacts,
  buildConversations,
  getUniqueMessageContactIds,
  chunkArray,
} from './realtime/realtimeUtils';
import { useRealtimeNotifications } from './realtime/useRealtimeNotifications';
import { useMessageUpdateBatcher } from './realtime/useMessageUpdateBatcher';
import { logMessagesSubscribe, wrapMessagesHandler } from '@/lib/devRealtimeLogger';
import { isValidUUID } from '@/utils/uuid';
export type { MessageBatcherStatus } from './realtime/useMessageUpdateBatcher';

const log = getLogger('RealtimeMessages');
const SEEDED_CONTACT_LIMIT = 500;
const RECENT_MESSAGES_LIMIT = 1000;
const CONTACT_FETCH_CHUNK_SIZE = 200;
/**
 * Janela de debounce (ms) para agregar múltiplas chamadas simultâneas de
 * hydrateConversationForMessage. Em rajadas de mensagens (campanhas, bots),
 * reduz de N round-trips HTTP para 1 por janela de 50ms.
 */
const HYDRATE_DEBOUNCE_MS = 50;

export interface NewMessageNotification {
  id: string;
  contactId: string;
  contactName: string;
  contactAvatar: string | null;
  message: string;
  timestamp: Date;
}

export interface RealtimeMessage {
  id: string;
  contact_id: string | null;
  agent_id: string | null;
  content: string;
  sender: string;
  message_type: string;
  media_url: string | null;
  is_read: boolean | null;
  status:
    | 'sending'
    | 'retrying'
    | 'sent'
    | 'delivered'
    | 'read'
    | 'played'
    | 'failed'
    | 'failed_auth'
    | 'failed_retries'
    | null;
  status_updated_at: string | null;
  created_at: string;
  updated_at: string;
  external_id: string | null;
  whatsapp_connection_id: string | null;
  transcription: string | null;
  transcription_status: string | null;
  is_deleted: boolean | null;
  /** Timestamp do soft delete (protocolMessage REVOKE). Null = mensagem viva. */
  deleted_at?: string | null;
  retry_attempt?: number | null;
  retry_total?: number | null;
  /** Cache do avatar do contato para mensagens recebidas. Propagado durante a hidratação/reconciliação. */
  contactAvatar?: string | null;
  reactions?: any[] | null; // ignore-audit: reaction shape from Evolution API is untyped
  /** Metadados de mídia (ex: ptt, isPtv). Presente em mensagens de áudio/vídeo. */
  media_meta?: { ptt?: boolean; isPtv?: boolean; [key: string]: unknown } | null;
  /** Referência ao audio meme (soundboard). Presente em mensagens otimistas enviadas via soundboard. */
  audio_meme_id?: string | null;
}

export interface ConversationContact {
  id: string;
  name: string;
  surname: string | null;
  nickname: string | null;
  phone: string;
  email: string | null;
  avatar_url: string | null;
  tags: string[] | null;
  company: string | null;
  job_title: string | null;
  assigned_to: string | null;
  queue_id: string | null;
  created_at: string;
  updated_at: string;
  whatsapp_connection_id: string | null;
  contact_type: string | null;
  group_category: string | null;
  ai_sentiment: string | null;
  channel_type: string | null;
  channel_connection_id: string | null;
  routing_status?: string | null;
  remote_jid?: string | null;
  instance_name?: string | null;
}

export interface ConversationWithMessages {
  contact: ConversationContact;
  messages: RealtimeMessage[];
  unreadCount: number;
  lastMessage: RealtimeMessage | null;
}

export type ConversationSendState = 'idle' | 'retrying' | 'failed';

export function useRealtimeMessages() {
  const [conversations, setConversations] = useState<ConversationWithMessages[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [sendStateTick, setSendStateTick] = useState(0);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'open' | 'closed' | 'unread'>('all');
  const [sortBy, setSortBy] = useState<'lastMessage' | 'name' | 'unread'>('lastMessage');

  const conversationsRef = useRef<ConversationWithMessages[]>([]);

  const {
    newMessageNotification,
    notifyAboutIncomingMessage,
    dismissNotification,
    setSelectedContact,
    setSoundEnabled,
  } = useRealtimeNotifications();

  const commitConversations = useCallback(
    (
      updater:
        | ConversationWithMessages[]
        | ((prev: ConversationWithMessages[]) => ConversationWithMessages[])
    ) => {
      setConversations((prev) => {
        const next =
          typeof updater === 'function'
            ? (updater as (prev: ConversationWithMessages[]) => ConversationWithMessages[])(prev)
            : updater;
        conversationsRef.current = next;
        return next;
      });
    },
    []
  );

  const fetchContactsByIds = useCallback(async (contactIds: string[]) => {
    const uniqueIds = Array.from(new Set(contactIds.filter(Boolean)));
    if (uniqueIds.length === 0) return [] as ConversationContact[];
    const fetchedContacts: ConversationContact[] = [];

    for (const idsChunk of chunkArray(uniqueIds, CONTACT_FETCH_CHUNK_SIZE)) {
      const { data, error: contactsError } = await dbFrom('contacts')
        .select('*')
        .in('id', idsChunk);

      if (contactsError) throw contactsError;
      fetchedContacts.push(...((data ?? []) as ConversationContact[]));
    }
    return dedupeContacts(fetchedContacts);
  }, []);

  /**
   * Micro-buffer de 50ms para hydrateConversationForMessage.
   *
   * PROBLEMA (N+1):
   *   Antes, cada mensagem de um novo contato disparava fetchContactsByIds([id])
   *   individualmente. Em rajadas (campanhas, bots, reconexão de instância),
   *   isso gerava N round-trips HTTP simultâneos — 1 por contato novo.
   *
   * SOLUÇÃO:
   *   Acumulamos as mensagens pendentes no Map abaixo. Após 50ms sem novas
   *   chegadas, disparamos UM único fetchContactsByIds(todosOsIds) e
   *   aplicamos as atualizações de state em lote. O resultado é idêntico
   *   ao comportamento anterior, mas com 1 request em vez de N.
   *
   * SEGURANÇA:
   *   - O timer é limpo no unmount via cleanupHydrateBatchRef.current
   *   - O Map é keyed por contact_id para deduplicar contatos duplicados
   *   - Mensagens para o mesmo contact_id chegadas dentro da janela são
   *     todas processadas (array de mensagens por contact_id)
   */
  const pendingHydrateRef = useRef<Map<string, RealtimeMessage[]>>(new Map());
  const hydrateTimerRef   = useRef<ReturnType<typeof setTimeout> | null>(null);
  const cleanupHydrateBatchRef = useRef<(() => void) | null>(null);

  /** Processa UM contato já buscado contra todas as mensagens pendentes para ele. */
  const applyHydratedContact = useCallback(
    (contact: ConversationContact, messages: RealtimeMessage[]) => {
      commitConversations((prev) => {
        const idx = prev.findIndex((c) => c.contact.id === contact.id);
        if (idx >= 0) {
          // Conversa existente: append de mensagens que ainda não estão lá
          const existing = prev[idx];
          const existingIds = new Set(existing.messages.map((m) => m.id));
          const newMsgs = messages
            .filter((m) => !existingIds.has(m.id))
            .map((m) => ({ ...m, contactAvatar: contact.avatar_url || m.contactAvatar }));
          if (newMsgs.length === 0) return prev;
          const updated = [...prev];
          updated.splice(idx, 1);
          updated.unshift(buildConversation(contact, [...existing.messages, ...newMsgs]));
          return updated;
        }
        // Conversa nova: cria com todas as mensagens pendentes
        const withAvatar = messages.map((m) => ({
          ...m,
          contactAvatar: contact.avatar_url || m.contactAvatar,
        }));
        return [buildConversation(contact, withAvatar), ...prev];
      });
      // Notifica apenas pela mensagem mais recente (evita toast flood)
      const mostRecent = messages.reduce((a, b) =>
        (a.created_at ?? '') >= (b.created_at ?? '') ? a : b
      );
      notifyAboutIncomingMessage(contact, mostRecent);
    },
    [commitConversations, notifyAboutIncomingMessage]
  );

  /** Flush: coleta todos os contact_ids pendentes, busca em BATCH e aplica. */
  const flushHydrateBatch = useCallback(async () => {
    hydrateTimerRef.current = null;
    const pending = pendingHydrateRef.current;
    if (pending.size === 0) return;

    // Snapshot e limpa o buffer ANTES do await para não perder msgs que
    // chegam enquanto o fetch está em curso.
    const snapshot = new Map(pending);
    pendingHydrateRef.current = new Map();

    const contactIds = Array.from(snapshot.keys());
    log.debug(`[hydrate-batch] fetching ${contactIds.length} contact(s) in 1 request`);

    try {
      const contacts = await fetchContactsByIds(contactIds);
      const contactMap = new Map(contacts.map((c) => [c.id, c]));

      for (const [contactId, messages] of snapshot.entries()) {
        const contact = contactMap.get(contactId);
        if (!contact) {
          log.warn('Incoming message received for unknown contact', { contactId });
          continue;
        }
        applyHydratedContact(contact, messages);
      }
    } catch (err) {
      log.error('Error in hydrate batch:', err);
      // Em caso de falha, recoloca as mensagens no buffer para retry na próxima janela
      for (const [k, v] of snapshot.entries()) {
        const existing = pendingHydrateRef.current.get(k) ?? [];
        pendingHydrateRef.current.set(k, [...existing, ...v]);
      }
    }
  }, [fetchContactsByIds, applyHydratedContact]);

  /** Encabeçamento público: enfileira a mensagem e agenda o flush. */
  const hydrateConversationForMessage = useCallback(
    async (message: RealtimeMessage) => {
      if (!message.contact_id) return;

      // Enfileira no buffer
      const q = pendingHydrateRef.current.get(message.contact_id) ?? [];
      q.push(message);
      pendingHydrateRef.current.set(message.contact_id, q);

      // Debounce: cancela o timer anterior e agenda um novo
      if (hydrateTimerRef.current !== null) {
        clearTimeout(hydrateTimerRef.current);
      }
      hydrateTimerRef.current = setTimeout(() => {
        void flushHydrateBatch();
      }, HYDRATE_DEBOUNCE_MS);
    },
    [flushHydrateBatch]
  );

  // Cleanup: cancela o timer pendente ao desmontar o componente
  // (evita setState após unmount e memory leaks)
  useEffect(() => {
    cleanupHydrateBatchRef.current = () => {
      if (hydrateTimerRef.current !== null) {
        clearTimeout(hydrateTimerRef.current);
        hydrateTimerRef.current = null;
      }
      pendingHydrateRef.current = new Map();
    };
    return () => {
      cleanupHydrateBatchRef.current?.();
    };
  }, []);

  const { handleMessageUpdate, batcherStatus } = useMessageUpdateBatcher(
    conversationsRef,
    commitConversations,
    hydrateConversationForMessage
  );

  const handleNewMessage = useCallback(
    (payload: RealtimePostgresChangesPayload<RealtimeMessage>) => {
      const newMessage = normalizeMessage(payload.new as RealtimeMessage);
      if (!newMessage.contact_id) return;

      const existingConversation = conversationsRef.current.find(
        (c) => c.contact.id === newMessage.contact_id
      );
      if (!existingConversation) {
        void hydrateConversationForMessage(newMessage);
        return;
      }

      commitConversations((prev) => {
        const idx = prev.findIndex((c) => c.contact.id === newMessage.contact_id);
        if (idx < 0) return prev;
        const conv = prev[idx];
        if (conv.messages.some((m) => m.id === newMessage.id)) return prev;

        // Atribui o avatar do contato à nova mensagem para cache
        const messageWithAvatar = {
          ...newMessage,
          contactAvatar: conv.contact.avatar_url || newMessage.contactAvatar,
        };

        const updated = [...prev];
        updated.splice(idx, 1);
        updated.unshift(buildConversation(conv.contact, [...conv.messages, messageWithAvatar]));
        return updated;
      });

      notifyAboutIncomingMessage(existingConversation.contact, newMessage);
    },
    [commitConversations, hydrateConversationForMessage, notifyAboutIncomingMessage]
  );

  // Reage a um DELETE real na tabela messages (ex.: moderação via
  // useMonitoringActions). Na fonte evo.evolution_messages a replica identity
  // é default (payload.old só traz a PK) — a guarda abaixo já cobre old
  // incompleto. Recalcula a conversa inteira via buildConversation para manter
  // lastMessage/unreadCount consistentes, sem reordenar a lista.
  const handleMessageDelete = useCallback(
    (payload: RealtimePostgresChangesPayload<RealtimeMessage>) => {
      const deletedMessage = payload.old as RealtimeMessage;
      if (!deletedMessage?.id || !deletedMessage?.contact_id) return;

      commitConversations((prev) => {
        const idx = prev.findIndex((c) => c.contact.id === deletedMessage.contact_id);
        if (idx < 0) return prev;
        const conv = prev[idx];
        if (!conv.messages.some((m) => m.id === deletedMessage.id)) return prev;

        const remainingMessages = conv.messages.filter((m) => m.id !== deletedMessage.id);
        const updated = [...prev];
        updated[idx] = buildConversation(conv.contact, remainingMessages);
        return updated;
      });
    },
    [commitConversations]
  );

  const fetchConversations = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const { data: seededContacts, error: contactsError } = await dbFrom('contacts')
        .select('*')
        .order('updated_at', { ascending: false })
        .limit(SEEDED_CONTACT_LIMIT);

      if (contactsError) throw contactsError;

      const { data: recentMessages, error: messagesError } = await dbFrom('messages')
        .select('*')
        .order('created_at', { ascending: false })
        .limit(RECENT_MESSAGES_LIMIT);

      if (messagesError) throw messagesError;

      const normalizedMessages = ((recentMessages ?? []) as RealtimeMessage[]).map(
        normalizeMessage
      );
      const seededContactRows = (seededContacts ?? []) as ConversationContact[];
      const seededContactIds = new Set(seededContactRows.map((c) => c.id));
      const missingContactIds = getUniqueMessageContactIds(normalizedMessages).filter(
        (id) => !seededContactIds.has(id)
      );
      const messageContacts = await fetchContactsByIds(missingContactIds);
      commitConversations(
        buildConversations([...seededContactRows, ...messageContacts], normalizedMessages)
      );
    } catch (err) {
      log.error('Error fetching conversations:', err);
      setError(err instanceof Error ? err.message : 'Failed to fetch conversations');
    } finally {
      setLoading(false);
    }
  }, [commitConversations, fetchContactsByIds]);

  // ─── HANDLER REFS ──────────────────────────────────────────────────────────
  // Store event handlers in refs so the realtime subscription useEffect only
  // depends on fetchConversations (stable) instead of the full handler chain
  // (which changes whenever notification settings load/update, causing unnecessary
  // re-subscriptions that fetch 500 contacts + 1000 messages each time).
  const handleNewMessageRef = useRef(handleNewMessage);
  handleNewMessageRef.current = handleNewMessage;
  const handleMessageUpdateRef = useRef(handleMessageUpdate);
  handleMessageUpdateRef.current = handleMessageUpdate;
  const handleMessageDeleteRef = useRef(handleMessageDelete);
  handleMessageDeleteRef.current = handleMessageDelete;
  // ───────────────────────────────────────────────────────────────────────────

  useEffect(() => {
    let active = true;
    void fetchConversations();

    log.info('Subscribing to realtime', { source: 'dbTable' });

    const channelName = `messages-realtime-${Math.random().toString(36).slice(2, 9)}`;
    logMessagesSubscribe('useRealtimeMessages', { event: 'INSERT', table: dbTable('messages') });
    logMessagesSubscribe('useRealtimeMessages', { event: 'UPDATE', table: dbTable('messages') });
    logMessagesSubscribe('useRealtimeMessages', { event: 'DELETE', table: dbTable('messages') });

    // FATOR X v6.2: Realtime na TABELA-FONTE evo.evolution_messages (views public não emitem).
    // Adapter: a fonte usa from_me/deleted_at; o shape legado da view usa sender/is_deleted.
    const adaptEvoPayload = (
      p: RealtimePostgresChangesPayload<Record<string, unknown>>
    ): RealtimePostgresChangesPayload<RealtimeMessage> => {
      const map = (r: Record<string, unknown> | undefined) =>
        r && {
          ...r,
          sender: (r as { from_me?: boolean }).from_me ? 'agent' : 'contact',
          is_deleted: (r as { deleted_at?: string | null }).deleted_at != null,
        };
      return {
        ...p,
        new: map(p.new as Record<string, unknown>),
        old: map(p.old as Record<string, unknown>),
      } as unknown as RealtimePostgresChangesPayload<RealtimeMessage>;
    };
    const channel = dbChannel('messages', channelName)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'evo',
          table: 'evolution_messages',
        },
        (payload) => {
          if (active)
            wrapMessagesHandler(
              'useRealtimeMessages',
              // Use ref to avoid stale closure and prevent re-subscription on handler changes
              (p: RealtimePostgresChangesPayload<RealtimeMessage>) => handleNewMessageRef.current(p)
            )(adaptEvoPayload(payload as RealtimePostgresChangesPayload<Record<string, unknown>>));
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'evo',
          table: 'evolution_messages',
        },
        (payload) => {
          if (active)
            wrapMessagesHandler(
              'useRealtimeMessages',
              (p: RealtimePostgresChangesPayload<RealtimeMessage>) => handleMessageUpdateRef.current(p)
            )(adaptEvoPayload(payload as RealtimePostgresChangesPayload<Record<string, unknown>>));
        }
      )
      .on(
        'postgres_changes',
        {
          event: 'DELETE',
          schema: 'evo',
          table: 'evolution_messages',
        },
        (payload) => {
          if (active)
            wrapMessagesHandler(
              'useRealtimeMessages',
              (p: RealtimePostgresChangesPayload<RealtimeMessage>) => handleMessageDeleteRef.current(p)
            )(adaptEvoPayload(payload as RealtimePostgresChangesPayload<Record<string, unknown>>));
        }
      )
      .subscribe((status) => {
        if (active) log.debug('Subscription status', { status });
      });

    return () => {
      active = false;
      void dbRemoveChannel('messages', channel);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fetchConversations]);
  // ^^ Only depend on fetchConversations (stable); handlers are accessed via refs above
  // to prevent re-subscriptions when notification settings load/change.

  const sendMessage = async (
    contactId: string,
    content: string,
    messageType: string = 'text',
    mediaUrl?: string,
    mediaPayload?: string
  ) => {
    const response = await sendMessageToContact(
      contactId,
      content,
      messageType,
      mediaUrl,
      mediaPayload
    );

    // Check if conversation needs routing status update
    try {
      const { data: conv } = await dbFrom('team_conversations')
        .select('id, routing_status')
        .eq('id', contactId)
        .maybeSingle();

      if (conv && conv.routing_status === 'pending') {
        await dbFrom('team_conversations')
          .update({ routing_status: 'assigned' })
          .eq('id', contactId);
      }
    } catch (err) {
      log.error('Error checking routing status on send:', err);
    }

    return response;
  };

  const lastSeenTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const markAsRead = async (contactId: string) => {
    // ── UUID guard ──────────────────────────────────────────────────────────
    // messages.contact_id (and evo.evolution_messages.contact_id) are uuid
    // columns. When USE_EXTERNAL_DB=true the selectedContactId in
    // useRealtimeInbox may be a WhatsApp JID / phone number (e.g. "551146375517")
    // instead of a UUID. Passing it to PostgREST's .eq() on a uuid column
    // causes 400 "invalid input syntax for type uuid".
    // Skip silently — handleSelectConversation already calls evolution-api
    // to mark messages read on the WhatsApp side when USE_EXTERNAL_DB=true.
    if (!isValidUUID(contactId)) {
      log.warn(
        '[markAsRead] contactId is not a valid UUID — skipping to prevent 400 (likely a WhatsApp JID)',
        { contactId }
      );
      return;
    }
    // ────────────────────────────────────────────────────────────────────────

    const { error } = await dbFrom('messages')
      .update({ is_read: true })
      .eq('contact_id', contactId)
      .eq('sender', 'contact')
      .eq('is_read', false);
    if (error) log.error('Error marking messages as read:', error);

    // Debounce last_seen update to avoid flooding DB during active chat
    if (lastSeenTimerRef.current) clearTimeout(lastSeenTimerRef.current);
    lastSeenTimerRef.current = setTimeout(async () => {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (user) {
        // FIX: profiles.id = auth.uid() — use 'id', not 'user_id' (ghost column)
        await supabase
          .from('profiles')
          .update({ last_seen: new Date().toISOString() })
          .eq('id', user.id);
      }
    }, 5000);

    commitConversations((prev) =>
      prev.map((c) =>
        c.contact.id === contactId
          ? { ...c, messages: c.messages.map((m) => ({ ...m, is_read: true })), unreadCount: 0 }
          : c
      )
    );
  };

  // Subscribe to bus to recompute conversationSendState
  useEffect(() => {
    const unsub = subscribeAllSendStatus(() => setSendStateTick((t) => t + 1));
    return unsub;
  }, []);

  // Derive per-contact send state (transient bus + last DB status)
  const conversationSendState: Record<string, ConversationSendState> = {};
  for (const c of conversations) {
    let state: ConversationSendState = 'idle';
    const outbound = c.messages.filter((m) => m.sender === 'agent');
    // Check bus for any retrying/sending in this conversation
    const anyRetrying = outbound.some((m) => {
      const bus = getSendStatus(m.id);
      return bus?.status === 'retrying';
    });
    if (anyRetrying) {
      state = 'retrying';
    } else {
      const lastOutbound = outbound[outbound.length - 1];
      if (lastOutbound) {
        const bus = getSendStatus(lastOutbound.id);
        const effective = bus?.status ?? lastOutbound.status;
        if (
          effective === 'failed' ||
          effective === 'failed_auth' ||
          effective === 'failed_retries'
        ) {
          state = 'failed';
        }
      }
    }
    conversationSendState[c.contact.id] = state;
  }
  void sendStateTick; // ensure dep tracked

  const filteredConversations = useMemo(() => {
    let filtered = [...conversations];

    // 1. Search
    if (search) {
      const q = search.toLowerCase();
      filtered = filtered.filter(
        (conv) =>
          conv.contact.name.toLowerCase().includes(q) ||
          conv.contact.phone.includes(q) ||
          conv.lastMessage?.content?.toLowerCase().includes(q)
      );
    }

    // 2. Status Filter
    if (statusFilter !== 'all') {
      filtered = filtered.filter((conv) => {
        if (statusFilter === 'unread') return conv.unreadCount > 0;
        if (statusFilter === 'open') {
          return (
            !conv.lastMessage ||
            conv.lastMessage.sender === 'contact' ||
            conv.contact.routing_status === 'pending'
          );
        }
        if (statusFilter === 'closed') {
          return conv.lastMessage?.sender === 'agent' && conv.contact.routing_status !== 'pending';
        }
        return true;
      });
    }

    // 3. Sorting
    filtered.sort((a, b) => {
      if (sortBy === 'unread') {
        if (a.unreadCount !== b.unreadCount) return b.unreadCount - a.unreadCount;
      }
      if (sortBy === 'name') {
        return a.contact.name.localeCompare(b.contact.name);
      }
      const aTime = a.lastMessage
        ? new Date(a.lastMessage.created_at).getTime()
        : new Date(a.contact.created_at).getTime();
      const bTime = b.lastMessage
        ? new Date(b.lastMessage.created_at).getTime()
        : new Date(b.contact.created_at).getTime();
      return bTime - aTime;
    });

    return filtered;
  }, [conversations, search, statusFilter, sortBy]);

  return {
    conversations: filteredConversations,
    allConversations: conversations,
    search,
    setSearch,
    statusFilter,
    setStatusFilter,
    sortBy,
    setSortBy,
    loading,
    error,
    sendMessage,
    markAsRead,
    refetch: fetchConversations,
    newMessageNotification,
    dismissNotification,
    setSelectedContact,
    setSoundEnabled,
    conversationSendState,
    batcherStatus,
    /**
     * @deprecated Use the hook directly where needed
     */
    optimistic: {
      pendingCount: 0,
      mergeWithReal: <T>(m: T): T => m,
    },
  };
}

