/**
 * Tests for useRetryOperation().
 *
 * Covered:
 *   - Resolves immediately on first-attempt success
 *   - Retries after transient errors and resolves on a later attempt
 *   - Throws immediately (no retry) for fatal error codes (PGRST116, 23505, etc.)
 *   - Exhausts maxAttempts and then throws the last error
 *   - reset() clears loading/attempt/lastError state
 *   - State transitions (loading, attempt, lastError) are tracked correctly
 *
 * useToast is mocked so no toast UI is rendered.
 * Fake timers prevent real setTimeout delays.
 */
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';

// ── Hoisted mocks ──────────────────────────────────────────────────────────────
const mockToast = vi.hoisted(() => vi.fn());

vi.mock('@/hooks/use-toast', () => ({
  useToast: () => ({ toast: mockToast }),
}));

// ── Import SUT AFTER mocks ─────────────────────────────────────────────────────
import { useRetryOperation } from '../useRetryAndErrorPrevention';

// ── Setup ──────────────────────────────────────────────────────────────────────
beforeEach(() => {
  vi.useFakeTimers();
  vi.clearAllMocks();
});

afterEach(() => {
  vi.useRealTimers();
});

// ── success on first attempt ───────────────────────────────────────────────────
describe('useRetryOperation — first-attempt success', () => {
  it('resolves and returns the value from fn()', async () => {
    const { result } = renderHook(() => useRetryOperation());
    let value: string | undefined;
    await act(async () => {
      value = await result.current.withRetry(async () => 'ok');
    });
    expect(value).toBe('ok');
  });

  it('sets loading=false and attempt=0 after success', async () => {
    const { result } = renderHook(() => useRetryOperation());
    await act(async () => {
      await result.current.withRetry(async () => 'ok');
    });
    expect(result.current.loading).toBe(false);
    expect(result.current.attempt).toBe(0);
    expect(result.current.lastError).toBeNull();
  });
});

// ── fatal errors (no retry) ────────────────────────────────────────────────────
describe('useRetryOperation — fatal error codes', () => {
  const fatalCodes = ['PGRST116', '23505', '23514', 'CONTACT_NOT_FOUND', 'CONFLICT', '401', '403'];

  for (const code of fatalCodes) {
    it(`throws immediately without retrying for code ${code}`, async () => {
      const { result } = renderHook(() => useRetryOperation());
      const fn = vi.fn().mockRejectedValue(new Error(`fatal: ${code} error`));
      await act(async () => {
        await expect(result.current.withRetry(fn)).rejects.toThrow(code);
      });
      expect(fn).toHaveBeenCalledTimes(1);
    });
  }

  it('sets loading=false immediately after a fatal error', async () => {
    const { result } = renderHook(() => useRetryOperation());
    await act(async () => {
      await expect(
        result.current.withRetry(async () => { throw new Error('PGRST116 not found'); })
      ).rejects.toThrow();
    });
    expect(result.current.loading).toBe(false);
    expect(result.current.lastError).toContain('PGRST116');
  });
});

// ── transient retry ────────────────────────────────────────────────────────────
describe('useRetryOperation — transient retry', () => {
  it('succeeds on the second attempt after a transient failure', async () => {
    const { result } = renderHook(() => useRetryOperation(3, 100));
    const fn = vi.fn()
      .mockRejectedValueOnce(new Error('network timeout'))
      .mockResolvedValue('success');

    let value: string | undefined;
    await act(async () => {
      const promise = result.current.withRetry(fn);
      // Advance fake timers past the retry delay
      await vi.runAllTimersAsync();
      value = await promise as any;
    });
    expect(fn).toHaveBeenCalledTimes(2);
    expect(value).toBe('success');
  });

  it('exhausts all attempts and throws on persistent failure (maxAttempts=1)', async () => {
    // With maxAttempts=1 there is no setTimeout delay — the single attempt
    // fails immediately and withRetry throws, no fake-timer wrangling needed.
    const { result } = renderHook(() => useRetryOperation(1, 10));
    const fn = vi.fn().mockImplementation(async () => { throw new Error('persistent error'); });

    let thrown: Error | undefined;
    await act(async () => {
      try {
        await result.current.withRetry(fn);
      } catch (e) {
        thrown = e as Error;
      }
    });
    expect(thrown?.message).toContain('persistent error');
    expect(fn).toHaveBeenCalledTimes(1);
  });

  it('sets lastError after a single-attempt failure', async () => {
    const { result } = renderHook(() => useRetryOperation(1, 10));
    const fn = vi.fn().mockImplementation(async () => { throw new Error('nope'); });

    await act(async () => {
      try {
        await result.current.withRetry(fn);
      } catch {
        // expected
      }
    });
    expect(result.current.lastError).toContain('nope');
    expect(result.current.loading).toBe(false);
  });
});

// ── reset ──────────────────────────────────────────────────────────────────────
describe('useRetryOperation — reset()', () => {
  it('clears loading, attempt, and lastError', async () => {
    const { result } = renderHook(() => useRetryOperation(1, 10));
    await act(async () => {
      try {
        await result.current.withRetry(async () => { throw new Error('PGRST116 err'); });
      } catch {
        // expected: fatal error, throws immediately
      }
    });
    expect(result.current.lastError).not.toBeNull();

    act(() => result.current.reset());
    expect(result.current.loading).toBe(false);
    expect(result.current.attempt).toBe(0);
    expect(result.current.lastError).toBeNull();
  });
});

import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getLogger } from '@/lib/logger';

const log = getLogger('useSentimentData');
import { supabase } from '@/integrations/supabase/client';
import { subDays, startOfDay, endOfDay, isWithinInterval, format } from 'date-fns';
import { ptBR } from 'date-fns/locale';

/** Hook: Sentiment Alert. */
export interface SentimentAlert {
  id: string;
  contactId: string | null;
  createdAt: string;
  contact_name?: string;
  contact_phone?: string;
  sentiment_score?: number;
  consecutive_low?: number;
  agent_name?: string;
  message?: string;
  email_sent?: boolean;
}

/** Hook: Conversation Analysis. */
export interface ConversationAnalysis {
  id: string;
  contact_id: string;
  sentiment: string;
  sentiment_score: number;
  created_at: string;
  analyzed_by: string | null;
  contacts?: { name: string; phone: string };
}

/** Hook: Agent Profile. */
export interface AgentProfile {
  id: string;
  name: string;
  avatar_url: string | null;
}

/** Hook: Agent Sentiment Data. */
export interface AgentSentimentData {
  agent: AgentProfile;
  totalAnalyses: number;
  avgScore: number;
  positive: number;
  neutral: number;
  negative: number;
  trend: number;
}

/** Hook: use Sentiment Data. */
export function useSentimentData(period: string) {
  const { data: alerts = [], isLoading: loadingAlerts, refetch: refetchAlerts } = useQuery({
    queryKey: ['sentiment-alerts', period],
    queryFn: async () => {
      const startDate = startOfDay(subDays(new Date(), parseInt(period))).toISOString();
      const { data, error } = await supabase
        .from('audit_logs')
        .select('*')
        .eq('action', 'sentiment_alert')
        .gte('created_at', startDate)
        .order('created_at', { ascending: false });
      if (error) throw error;
      return ((data || []).map((entry) => ({
        id: entry.id,
        contactId: entry.entity_id,
        createdAt: entry.created_at,
        ...((entry.details || {}) as Record<string, unknown>),
      })) as SentimentAlert[]);
    },
    staleTime: 30_000,
  });

  const { data: analyses = [], isLoading: loadingAnalyses, refetch: refetchAnalyses } = useQuery({
    queryKey: ['sentiment-analyses', period],
    queryFn: async () => {
      const startDate = startOfDay(subDays(new Date(), parseInt(period))).toISOString();
      const { data, error } = await supabase
        .from('conversation_analyses')
        .select('id, contact_id, sentiment, sentiment_score, created_at, analyzed_by')
        .gte('created_at', startDate)
        .order('created_at', { ascending: false });
      if (error) throw error;
      return (data || []) as ConversationAnalysis[];
    },
    staleTime: 30_000,
  });

  const { data: agents = [], isLoading: loadingAgents, refetch: refetchAgents } = useQuery({
    queryKey: ['sentiment-agents'],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('profiles')
        .select('id, name, avatar_url')
        .eq('is_active', true);
      if (error) throw error;
      return (data || []) as AgentProfile[];
    },
    staleTime: 60_000,
  });

  const loading = loadingAlerts || loadingAnalyses || loadingAgents;

  const fetchData = async () => {
    await Promise.all([refetchAlerts(), refetchAnalyses(), refetchAgents()]);
  };

  const stats = useMemo(() => {
    const totalAnalyses = analyses.length;
    const negativeAnalyses = analyses.filter((a) => a.sentiment === 'negativo').length;
    const positiveAnalyses = analyses.filter((a) => a.sentiment === 'positivo').length;
    const neutralAnalyses = analyses.filter((a) => a.sentiment === 'neutro').length;
    const avgSentiment =
      totalAnalyses > 0
        ? Math.round(
            analyses.reduce((sum, a) => sum + (a.sentiment_score || 50), 0) / totalAnalyses
          )
        : 50;
    const criticalAlerts = alerts.filter((a) => (a.sentiment_score || 50) < 20).length;
    const emailsSent = alerts.filter((a) => a.email_sent).length;
    const uniqueContacts = new Set(alerts.map((a) => a.contactId)).size;

    return {
      totalAnalyses,
      negativeAnalyses,
      positiveAnalyses,
      neutralAnalyses,
      avgSentiment,
      totalAlerts: alerts.length,
      criticalAlerts,
      emailsSent,
      uniqueContacts,
      negativeRate: totalAnalyses > 0 ? Math.round((negativeAnalyses / totalAnalyses) * 100) : 0,
    };
  }, [analyses, alerts]);

  const dailyData = useMemo(() => {
    const days = parseInt(period);
    const data: {
      date: string;
      positive: number;
      neutral: number;
      negative: number;
      avgScore: number;
    }[] = [];

    for (let i = days - 1; i >= 0; i--) {
      const date = subDays(new Date(), i);
      const dayAnalyses = analyses.filter((a) =>
        isWithinInterval(new Date(a.created_at), { start: startOfDay(date), end: endOfDay(date) })
      );

      data.push({
        date: format(date, 'dd/MM', { locale: ptBR }),
        positive: dayAnalyses.filter((a) => a.sentiment === 'positivo').length,
        neutral: dayAnalyses.filter((a) => a.sentiment === 'neutro').length,
        negative: dayAnalyses.filter((a) => a.sentiment === 'negativo').length,
        avgScore:
          dayAnalyses.length > 0
            ? Math.round(
                dayAnalyses.reduce((sum, a) => sum + (a.sentiment_score || 50), 0) /
                  dayAnalyses.length
              )
            : 0,
      });
    }
    return data;
  }, [analyses, period]);

  const agentData = useMemo((): AgentSentimentData[] => {
    const days = parseInt(period);
    const halfPeriod = Math.floor(days / 2);

    return agents
      .map((agent) => {
        const agentAnalyses = analyses.filter((a) => a.analyzed_by === agent.id);
        const totalAnalyses = agentAnalyses.length;
        const positive = agentAnalyses.filter((a) => a.sentiment === 'positivo').length;
        const neutral = agentAnalyses.filter((a) => a.sentiment === 'neutro').length;
        const negative = agentAnalyses.filter((a) => a.sentiment === 'negativo').length;
        const avgScore =
          totalAnalyses > 0
            ? Math.round(
                agentAnalyses.reduce((sum, a) => sum + (a.sentiment_score || 50), 0) / totalAnalyses
              )
            : 0;

        const firstHalfStart = subDays(new Date(), days);
        const firstHalfEnd = subDays(new Date(), halfPeriod);
        const secondHalfStart = subDays(new Date(), halfPeriod);

        const firstHalfAnalyses = agentAnalyses.filter((a) => {
          const d = new Date(a.created_at);
          return d >= firstHalfStart && d < firstHalfEnd;
        });
        const secondHalfAnalyses = agentAnalyses.filter((a) => {
          const d = new Date(a.created_at);
          return d >= secondHalfStart;
        });

        const firstHalfAvg =
          firstHalfAnalyses.length > 0
            ? firstHalfAnalyses.reduce((s, a) => s + (a.sentiment_score || 50), 0) /
              firstHalfAnalyses.length
            : 50;
        const secondHalfAvg =
          secondHalfAnalyses.length > 0
            ? secondHalfAnalyses.reduce((s, a) => s + (a.sentiment_score || 50), 0) /
              secondHalfAnalyses.length
            : 50;

        return {
          agent,
          totalAnalyses,
          avgScore,
          positive,
          neutral,
          negative,
          trend: Math.round(secondHalfAvg - firstHalfAvg),
        };
      })
      .filter((a) => a.totalAnalyses > 0)
      .sort((a, b) => b.avgScore - a.avgScore);
  }, [analyses, agents, period]);

  return { alerts, analyses, agents, loading, stats, dailyData, agentData, fetchData };
}

/** Hook: get Sentiment Color. */
export function getSentimentColor(score: number) {
  if (score < 30) return 'text-destructive';
  if (score < 70) return 'text-warning';
  return 'text-success';
}

/** Hook: get Sentiment Bg. */
export function getSentimentBg(score: number) {
  if (score < 30) return 'bg-destructive';
  if (score < 70) return 'bg-warning';
  return 'bg-success';
}

/** Hook: get Sentiment Label. */
export function getSentimentLabel(sentiment: string) {
  switch (sentiment) {
    case 'positivo':
      return 'Positivo';
    case 'negativo':
      return 'Negativo';
    case 'neutro':
      return 'Neutro';
    default:
      return sentiment;
  }
}

import { getLogger } from '@/lib/logger';
import { externalSupabase, isExternalConfigured } from '@/integrations/supabase/externalClient';

const logV237 = getLogger('EvolutionV237');

/** Hook: is Endpoint Unavailable. */
export function isEndpointUnavailable(err: unknown): boolean {
  if (!err) return false;
  const status = (err as { status?: number }).status;
  if (status === 404 || status === 405 || status === 501) return true;
  const msg = err instanceof Error ? err.message : String(err ?? '');
  return /not\s*found|not\s*implemented|method\s+not\s+allowed|404|405|501/i.test(msg);
}

/** Hook: with V237 Fallback. */
export async function withV237Fallback<T>(
  primary: () => Promise<T>,
  fallback: () => Promise<T>,
  label: string
): Promise<T> {
  try {
    const result = await primary();
    if (result && typeof result === 'object') {
      const wrapped = result as { error?: unknown; status?: number };
      if (isEndpointUnavailable(wrapped) || wrapped.error === 'not_found') {
        logV237.warn(`[${label}] primary returned not-found payload; using FATOR X fallback`);
        return await fallback();
      }
    }
    return result;
  } catch (err) {
    if (isEndpointUnavailable(err)) {
      logV237.warn(`[${label}] primary failed (${(err as Error)?.message}); falling back to FATOR X`);
      return await fallback();
    }
    throw err;
  }
}

function ensureExternal() {
  if (!isExternalConfigured || !externalSupabase) {
    throw new Error('FATOR X external client is not configured');
  }
  return externalSupabase;
}

function callExternalRpc(
  client: ReturnType<typeof ensureExternal>,
  fn: string,
  args: Record<string, unknown>
) {
  return (client as unknown as { rpc: typeof client.rpc }).rpc(fn as any, args);
}

/** Hook: fallback Find Chats. */
export async function fallbackFindChats(instanceName: string, limit = 200): Promise<unknown[]> {
  const client = ensureExternal();
  const { data, error } = await callExternalRpc(client, 'rpc_list_conversations', {
    p_instance: instanceName,
    p_status: null,
    p_assigned_to: null,
    p_limit: limit,
  });
  if (error) throw error;
  return Array.isArray(data) ? data : [];
}

/** Hook: fallback Find Contacts. */
export async function fallbackFindContacts(instanceName: string, limit = 500): Promise<unknown[]> {
  const client = ensureExternal();
  const { data, error } = await callExternalRpc(client, 'rpc_list_contacts', {
    p_instance: instanceName,
    p_lead_status: null,
    p_assigned_to: null,
    p_search: null,
    p_limit: limit,
    p_offset: 0,
  });
  if (error) throw error;
  return Array.isArray(data) ? data : [];
}

/** Hook: fallback Fetch Profile. */
export async function fallbackFetchProfile(
  remoteJid: string,
  instanceName: string
): Promise<unknown | null> {
  const client = ensureExternal();
  const { data, error } = await callExternalRpc(client, 'rpc_get_contact', {
