/** Hook: use Monitoring Actions Management. */
export function useMonitoringActionsManagement(
  params: UseMonitoringActionsParams
): UseMonitoringActionsResult {
  const { fetchData } = params;
  const [refreshing, setRefreshing] = useState(false);
  const [webhookTest, setWebhookTest] = useState<WebhookTestResult>({ status: 'idle' });
  const [webhookConfig, setWebhookConfig] = useState<WebhookConfig | null>(null);
  const [reconfiguring, setReconfiguring] = useState(false);
  const [diagnostic, setDiagnostic] = useState<DiagnosticResult | null>(null);
  const [diagnosing, setDiagnosing] = useState(false);

  const runHealthCheck = useCallback(async () => {
    setRefreshing(true);
    try {
      const { data, error } = await supabase.functions.invoke('connection-health-check', {
        method: 'POST',
        body: {},
      });
      if (error) throw error;
      toast.success(`Health check: ${data?.connections?.length || 0} conexões verificadas`);
      await fetchData();
    } catch {
      toast.error('Erro ao executar health check');
    } finally {
      setRefreshing(false);
    }
  }, [fetchData]);

  const testWebhookDelivery = useCallback(async (instanceId: string) => {
    setWebhookTest({ status: 'testing' });
    const testId = `MONITOR_TEST_${Date.now()}`;
    const start = performance.now();
    try {
      const { error: invokeErr } = await supabase.functions.invoke('evolution-webhook', {
        method: 'POST',
        body: {
          event: 'messages.upsert',
          instance: instanceId,
          data: {
            key: { remoteJid: '5500000000000@s.whatsapp.net', fromMe: false, id: testId },
            pushName: '🔧 Monitor Test',
            messageTimestamp: Math.floor(Date.now() / 1000),
            message: { conversation: `[TESTE MONITOR] ${new Date().toLocaleString('pt-BR')}` },
          },
        },
      });
      const latency = Math.round(performance.now() - start);
      if (invokeErr) throw invokeErr;
      await new Promise((r) => setTimeout(r, 1000));
      const { data: msg } = await supabase
        .from('evolution_messages')
        .select('id')
        .eq('message_id', testId)
        .maybeSingle();
      if (msg) await supabase.from('evolution_messages').delete().eq('id', msg.id);
      setWebhookTest({
        status: msg ? 'success' : 'error',
        message: msg
          ? `Webhook processou e persistiu em ${latency}ms`
          : 'Webhook respondeu OK mas mensagem não foi persistida',
        latencyMs: latency,
      });
    } catch (err) {
      setWebhookTest({
        status: 'error',
        message: err instanceof Error ? err.message : 'Erro desconhecido',
      });
    }
  }, []);

  const checkWebhookConfig = useCallback(async (instanceId: string) => {
    if (isUuidLike(instanceId)) {
      toast.error('Nome de instância inválido (UUID detectado).');
      return;
    }
    try {
      const { data, error } = await supabase.functions.invoke('evolution-api/get-webhook', {
        method: 'POST',
        body: { instanceName: instanceId },
      });
      if (error) throw error;
      const webhook = data?.webhook || data;
      setWebhookConfig({
        url: webhook?.url || webhook?.webhookUrl,
        events: webhook?.events || [],
        configured: !!(webhook?.url || webhook?.webhookUrl),
      });
    } catch {
      setWebhookConfig({ configured: false });
      toast.error('Erro ao verificar webhook');
    }
  }, []);

  const reconfigureWebhook = useCallback(
    async (instanceId: string) => {
      if (isUuidLike(instanceId)) {
        toast.error('Nome de instância inválido (UUID detectado).');
        return;
      }
      setReconfiguring(true);
      try {
        const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
        const webhookUrl = `${supabaseUrl}/functions/v1/evolution-webhook`;
        const { error } = await supabase.functions.invoke('evolution-api/set-webhook', {
          method: 'POST',
          body: {
            instanceName: instanceId,
            webhook: {
              url: webhookUrl,
              webhookByEvents: false,
              webhookBase64: true,
              events: [
                'MESSAGES_UPSERT',
                'MESSAGES_UPDATE',
                'MESSAGES_DELETE',
                'MESSAGES_SET',
                'SEND_MESSAGE',
                'CONTACTS_UPSERT',
                'CONTACTS_UPDATE',
                'CONTACTS_SET',
                'PRESENCE_UPDATE',
                'CHATS_UPSERT',
                'CHATS_UPDATE',
                'CHATS_DELETE',
                'CHATS_SET',
                'CONNECTION_UPDATE',
                'LABELS_EDIT',
                'LABELS_ASSOCIATION',
                'GROUPS_UPSERT',
                'GROUP_PARTICIPANTS_UPDATE',
                'CALL',
                'QRCODE_UPDATED',
              ],
            },
          },
        });
        if (error) throw error;
        toast.success('Webhook reconfigurado com sucesso!');
        await checkWebhookConfig(instanceId);
      } catch (err) {
        toast.error(
          'Erro ao reconfigurar: ' + (err instanceof Error ? err.message : 'desconhecido')
        );
      } finally {
        setReconfiguring(false);
      }
    },
    [checkWebhookConfig]
  );

  const runDiagnostic = useCallback(
    async (autoFix = false) => {
      setDiagnosing(true);
      try {
        const { data, error } = await supabase.functions.invoke('webhook-diagnostic', {
          method: 'POST',
          body: { action: autoFix ? 'auto-fix' : 'full-diagnostic' },
        });
        if (error) throw error;
        setDiagnostic(data as DiagnosticResult); // ignore-audit: narrows Supabase query result to local interface
        if (autoFix) {
          toast.success('Diagnóstico + auto-fix concluído!');
          await fetchData();
        } else {
          toast.success('Diagnóstico concluído!');
        }
      } catch {
        toast.error('Erro no diagnóstico');
      } finally {
        setDiagnosing(false);
      }
    },
    [fetchData]
  );

  return {
    refreshing,
    webhookTest,
    webhookConfig,
    reconfiguring,
    diagnostic,
    diagnosing,
    runHealthCheck,
    testWebhookDelivery,
    checkWebhookConfig,
    reconfigureWebhook,
    runDiagnostic,
  };
}

import { useCallback, useRef, useState } from 'react';
import { toast as sonnerToast } from 'sonner';
import type {
  FeedbackType,
  FeedbackOptions,
  WithFeedbackOptions,
  UndoableOptions,
} from './feedback/feedbackTypes';
import {
  FEEDBACK_ICONS,
  FEEDBACK_TITLES,
  FEEDBACK_DURATIONS,
} from './feedback/feedbackTypes';

/** Re-exported module members. */
export type { FeedbackType, FeedbackOptions, WithFeedbackOptions, UndoableOptions };

interface ToastHandle {
  id: string | number;
  dismiss: () => void;
  update: (opts: { description?: string; title?: string }) => void;
}

function makeHandle(id: string | number, title: string | undefined): ToastHandle {
  return {
    id,
    dismiss: () => sonnerToast.dismiss(id),
    update: (opts) => {
      sonnerToast(opts.title ?? title ?? '', { id, description: opts.description });
    },
  };
}

/** Provides feedback notifications for user actions with customizable types and durations. */
export function useActionFeedback() {
  const activeToasts = useRef<Map<string | number, ToastHandle>>(new Map());

  const showFeedback = useCallback(
    (type: FeedbackType, options: FeedbackOptions): ToastHandle => {
      const icon = FEEDBACK_ICONS[type];
      const title = options.title || FEEDBACK_TITLES[type];
      const duration = options.duration ?? FEEDBACK_DURATIONS[type];
      const description = options.action
        ? `${icon} ${options.description} [${options.action.label}]`
        : `${icon} ${options.description}`;

      const emit =
        type === 'error'
          ? sonnerToast.error
          : type === 'warning'
            ? sonnerToast.warning
            : type === 'success'
              ? sonnerToast.success
              : type === 'loading'
                ? sonnerToast.loading
                : sonnerToast.info;

      const id = emit(title, { description, duration });
      const handle = makeHandle(id, title);
      if (options.action) {
        activeToasts.current.set(id, handle);
      }
      return handle;
    },
    []
  );

  const success = useCallback(
    (d: string, t?: string) => showFeedback('success', { description: d, title: t }),
    [showFeedback]
  );
  const error = useCallback(
    (d: string, t?: string) => showFeedback('error', { description: d, title: t }),
    [showFeedback]
  );
  const warning = useCallback(
    (d: string, t?: string) => showFeedback('warning', { description: d, title: t }),
    [showFeedback]
  );
  const info = useCallback(
    (d: string, t?: string) => showFeedback('info', { description: d, title: t }),
    [showFeedback]
  );
  const loading = useCallback(
    (d: string, t?: string) => showFeedback('loading', { description: d, title: t }),
    [showFeedback]
  );

  const withFeedback = useCallback(
    async <T>(
      action: () => Promise<T>,
      options: WithFeedbackOptions<T> = {}
    ): Promise<T | undefined> => {
      const {
        loadingMessage = 'Processando...',
        successMessage = 'Operação concluída com sucesso!',
        errorMessage = 'Ocorreu um erro.',
        showLoading = true,
        onSuccess,
        onError,
      } = options;
      const loadingToast = showLoading ? loading(loadingMessage) : null;
      try {
        const result = await action();
        loadingToast?.dismiss();
        success(typeof successMessage === 'function' ? successMessage(result) : successMessage);
        onSuccess?.(result);
        return result;
      } catch (err) {
        loadingToast?.dismiss();
        const e = err instanceof Error ? err : new Error(String(err));
        error(e.message || errorMessage);
        onError?.(e);
        return undefined;
      }
    },
    [loading, success, error]
  );

  const withUndo = useCallback(
    <T>(
      action: () => Promise<T>,
      options: UndoableOptions<T>
    ): Promise<T | 'undone' | undefined> => {
      return new Promise((resolve) => {
        const { description, undoDuration = 5000, onUndo, onConfirm } = options;
        let undone = false;
        let timeoutId: ReturnType<typeof setTimeout>;
        const toastResult = showFeedback('info', {
          description,
          duration: undoDuration,
          action: {
            label: 'Desfazer',
            onClick: () => {
              undone = true;
              clearTimeout(timeoutId);
              toastResult.dismiss();
              onUndo();
              info('Ação desfeita');
              resolve('undone');
            },
          },
        });
        timeoutId = setTimeout(async () => {
          if (!undone) {
            try {
              const r = await action();
              onConfirm?.(r);
              resolve(r);
            } catch (err) {
              error(err instanceof Error ? err.message : 'Erro');
              resolve(undefined);
            }
          }
        }, undoDuration);
      });
    },
    [showFeedback, info, error]
  );

  const withBatchFeedback = useCallback(
    async <T>(
      actions: (() => Promise<T>)[],
      options: {
        progressMessage?: (c: number, t: number) => string;
        successMessage?: string;
        errorMessage?: string;
        stopOnError?: boolean;
      } = {}
    ): Promise<{ results: T[]; errors: Error[] }> => {
      const {
        progressMessage = (c, t) => `Processando ${c} de ${t}...`,
        successMessage = 'Todas as operações concluídas!',
        errorMessage = 'Algumas operações falharam',
        stopOnError = false,
      } = options;
      const results: T[] = [];
      const errors: Error[] = [];
      const total = actions.length;
      const loadingToast = loading(progressMessage(0, total));
      for (let i = 0; i < actions.length; i++) {
        loadingToast.update({
          description: `⟳ ${progressMessage(i + 1, total)}`,
        });
        try {
          results.push(await actions[i]());
        } catch (err) {
          errors.push(err instanceof Error ? err : new Error(String(err)));
          if (stopOnError) break;
        }
      }
      loadingToast.dismiss();
      if (errors.length === 0) success(successMessage);
      else if (errors.length === total) error(errorMessage);
      else warning(`${results.length} sucesso, ${errors.length} falhas`);
      return { results, errors };
    },
    [loading, success, error, warning]
  );

  const dismissAll = useCallback(() => {
    activeToasts.current.forEach((t) => t.dismiss());
    activeToasts.current.clear();
  }, []);

  return {
    showFeedback,
    success,
    error,
    warning,
    info,
    loading,
    withFeedback,
    withUndo,
    withBatchFeedback,
    dismissAll,
  };
}

/** Executes optimistic updates with automatic rollback and user feedback. */
export function useOptimisticAction<T>() {
  const feedback = useActionFeedback();
  const [isPending, setIsPending] = useState(false);
  const execute = useCallback(
    async (
      optimisticUpdate: () => void,
      serverAction: () => Promise<T>,
      rollback: () => void,
      options?: { successMessage?: string; errorMessage?: string; silent?: boolean }
    ): Promise<T | undefined> => {
      setIsPending(true);
      optimisticUpdate();
      try {
        const r = await serverAction();
        if (!options?.silent) feedback.success(options?.successMessage || 'Alteração salva!');
        return r;
      } catch (err) {
        rollback();
        feedback.error(err instanceof Error ? err.message : options?.errorMessage || 'Erro');
        return undefined;
      } finally {
        setIsPending(false);
      }
    },
    [feedback]
  );
  return { execute, isPending, ...feedback };
}

/** Provides confirmation dialogs for destructive or important user actions. */
export function useConfirmAction() {
  const feedback = useActionFeedback();
  const confirm = useCallback(
    async <T>(
      action: () => Promise<T>,
      options: { message: string; confirmLabel?: string }
    ): Promise<T | 'cancelled' | undefined> => {
      return new Promise((resolve) => {
        const toastResult = feedback.showFeedback('warning', {
          title: 'Confirmação',
          description: options.message,
          duration: 30000,
          action: {
            label: options.confirmLabel || 'Confirmar',
            onClick: async () => {
              toastResult.dismiss();
              try {
                const r = await action();
                feedback.success('Ação confirmada!');
                resolve(r);
              } catch (err) {
                feedback.error(err instanceof Error ? err.message : 'Erro');
                resolve(undefined);
              }
            },
          },
        });
      });
    },
    [feedback]
  );
  return { confirm, ...feedback };
}

// Escape hatch pontual: `webhook_health_checks` e `sentiment_alerts` são
// tabelas do schema `zapp` que ainda não estão nos types gerados pela Lovable
// Cloud (o schema oficial vive na VPS self-hosted). Enquanto o
// gen-types-zapp.mjs não é rodado com acesso à VPS, usamos `db as any` só na
// fronteira dessas tabelas. A superfície pública do hook permanece 100% tipada.
import { useEffect, useRef, useCallback, useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { safeClient } from '@/integrations/supabase/safeClient';
import { usePushNotificationsManagement } from '@/hooks/useNotificationManagement';
import { useNotificationSettingsManagement } from '@/hooks/useNotificationManagement';
