/**
 * useConnectionManagement.ts (v1.0)
 * Unified connection management consolidating:
 * - useConnectionAlertsPush: Connection alerts via push notifications
 * - useConnectionQueues: Queue management for connections
 * - useConnectionPoolMonitor: Supabase connection pool health monitoring
 *
 * Backward compatibility maintained through re-exports of legacy hook names.
 */
import { useState, useEffect, useCallback } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { safeClient } from '@/integrations/supabase/safeClient';
import type { ConnectionMetrics } from '@/integrations/supabase/connectionPool';
import { getLogger } from '@/lib/logger';

const log = getLogger('ConnectionManagement');

// Optional pool telemetry accessors — safeClient may not expose these in all builds.
type PoolTelemetry = {
  getPoolMetrics?: () => ConnectionMetrics;
  getPoolDiagnostics?: () => Record<string, unknown>;
};
const poolClient = safeClient as unknown as PoolTelemetry; // ignore-audit — safeClient (TypedSupabaseClient) has no index signature; bridge to local PoolTelemetry interface is intentional
const EMPTY_METRICS = {
  activeConnections: 0,
  maxConcurrent: 0,
  poolUtilization: 0,
  totalErrors: 0,
} as unknown as ConnectionMetrics; // ignore-audit — literal object lacks ConnectionMetrics index signature; bridge assigns typed fallback constant

// ──────────────────────────────────────────────────────────────────────────
// CONNECTION ALERTS PUSH
// ──────────────────────────────────────────────────────────────────────────

/**
 * Hook for listening to connection alerts via realtime and displaying push notifications.
 * Monitors new connection_alert notifications and shows browser notifications.
 */
export function useConnectionAlertsPush() {
  useEffect(() => {
    if (typeof Notification === 'undefined') return;

    let cancelled = false;
    let channel: ReturnType<typeof supabase.channel> | null = null;

    void (async () => {
      const { data: auth } = await supabase.auth.getUser();
      if (cancelled || !auth.user) return;

      channel = supabase
        .channel(`connection-alerts-${auth.user.id}`)
        .on(
          'postgres_changes',
          {
            event: 'INSERT',
            schema: 'zapp',
            table: 'app_notifications',
            filter: `user_id=eq.${auth.user.id}`,
          },
          (payload) => {
            const n = payload.new as {
              type?: string;
              title?: string;
              message?: string;
              metadata?: { connection_id?: string; reason?: string; [key: string]: unknown };
            };
            if (n?.type !== 'connection_alert') return;
            if (Notification.permission !== 'granted') return;
            try {
              new Notification(n.title ?? 'Alerta de conexão', {
                body: n.message ?? '',
                icon: '/favicon.ico',
                tag: `conn-${n.metadata?.connection_id ?? 'unknown'}`,
                requireInteraction: n.metadata?.reason === 'disconnected',
              });
            } catch {
              /* ignore */
            }
          }
        )
        .subscribe();
    })();

    return () => {
      cancelled = true;
      if (channel) {
        channel.unsubscribe();
        supabase.removeChannel(channel);
      }
    };
  }, []);
}

// ──────────────────────────────────────────────────────────────────────────
// CONNECTION QUEUES
// ──────────────────────────────────────────────────────────────────────────

/** Connection Queue interface definition. */
export interface ConnectionQueue {
  id: string;
  whatsapp_connection_id: string;
  queue_id: string;
  created_at: string;
}

const CONN_QUEUES_KEY = (id: string | undefined) => ['connection-queues', id] as const;

/**
 * Hook for managing queues associated with a WhatsApp connection.
 * Provides CRUD operations for connection queue relationships.
 */
export function useConnectionQueues(connectionId?: string) {
  const queryClient = useQueryClient();

  const {
    data: connectionQueues = [],
    isLoading,
    refetch,
  } = useQuery({
    queryKey: CONN_QUEUES_KEY(connectionId),
    queryFn: async () => {
      const { data, error } = await supabase
        .from('whatsapp_connection_queues')
        .select('*')
        .eq('whatsapp_connection_id', connectionId!);
      if (error) throw error;
      return (data || []) as ConnectionQueue[];
    },
    enabled: !!connectionId,
    staleTime: 30_000,
  });

  const addQueue = useCallback(
    async (queueId: string) => {
      if (!connectionId) return;
      try {
        const { error } = await supabase
          .from('whatsapp_connection_queues')
          .insert({ whatsapp_connection_id: connectionId, queue_id: queueId });
        if (error) throw error;
        void queryClient.invalidateQueries({ queryKey: CONN_QUEUES_KEY(connectionId) });
      } catch (err) {
        log.error('Error adding queue to connection:', err);
        throw err;
      }
    },
    [connectionId, queryClient]
  );

  const removeQueue = useCallback(
    async (queueId: string) => {
      if (!connectionId) return;
      try {
        const { error } = await supabase
          .from('whatsapp_connection_queues')
          .delete()
          .eq('whatsapp_connection_id', connectionId)
          .eq('queue_id', queueId);
        if (error) throw error;
        void queryClient.invalidateQueries({ queryKey: CONN_QUEUES_KEY(connectionId) });
      } catch (err) {
        log.error('Error removing queue from connection:', err);
        throw err;
      }
    },
    [connectionId, queryClient]
  );

  return { connectionQueues, isLoading, addQueue, removeQueue, refetch };
}

// ──────────────────────────────────────────────────────────────────────────
// CONNECTION POOL MONITORING
// ──────────────────────────────────────────────────────────────────────────

/**
 * Hook for monitoring Supabase connection pool health.
 * Provides real-time metrics for dashboard display and alerting.
 */
export function useConnectionPoolMonitor() {
  const [metrics, setMetrics] = useState<ConnectionMetrics | null>(null);
  const [isMonitoring, setIsMonitoring] = useState(false);
  const [pollingInterval, setPollingInterval] = useState(10000); // 10 seconds default

  const updateMetrics = useCallback(() => {
    try {
      const poolMetrics = poolClient.getPoolMetrics?.() ?? EMPTY_METRICS;
      setMetrics(poolMetrics);

      // Alert on critical conditions
      if (poolMetrics.poolUtilization > 0.9) {
        log.warn('High pool utilization detected', {
          utilization: poolMetrics.poolUtilization,
          active: poolMetrics.activeConnections,
          max: poolMetrics.maxConcurrent,
        });
      }

      if (poolMetrics.totalErrors > 10) {
        log.error('Excessive connection errors detected', {
          totalErrors: poolMetrics.totalErrors,
        });
      }

      if (poolMetrics.heapUsageBeforeGc && poolMetrics.heapUsageAfterGc) {
        const heapReduction =
          ((poolMetrics.heapUsageBeforeGc - poolMetrics.heapUsageAfterGc) /
            poolMetrics.heapUsageBeforeGc) *
          100;
        log.info('Garbage collection completed', {
          heapReduction: heapReduction.toFixed(2) + '%',
          before: poolMetrics.heapUsageBeforeGc,
          after: poolMetrics.heapUsageAfterGc,
        });
      }
    } catch (err) {
      log.error('Failed to update pool metrics', err);
    }
  }, []);

  const startMonitoring = useCallback(
    (interval?: number) => {
      if (isMonitoring) return;

      if (interval) {
        setPollingInterval(interval);
      }

      setIsMonitoring(true);
      updateMetrics(); // Initial update
    },
    [isMonitoring, updateMetrics]
  );

  const stopMonitoring = useCallback(() => {
    setIsMonitoring(false);
  }, []);

  // Setup polling interval
  useEffect(() => {
    if (!isMonitoring) return;

    const timerId = setInterval(updateMetrics, pollingInterval);

    return () => clearInterval(timerId);
  }, [isMonitoring, pollingInterval, updateMetrics]);

  return {
    metrics,
    isMonitoring,
    pollingInterval,
    startMonitoring,
    stopMonitoring,
    updateMetrics,
    setPollingInterval,
  };
}

/**
 * Hook for getting pool diagnostics (detailed connection info).
 */
export function useConnectionPoolDiagnostics() {
  const [diagnostics, setDiagnostics] = useState<Record<string, unknown> | null>(null);

  const getDiagnostics = useCallback(() => {
    try {
      const diag = poolClient.getPoolDiagnostics?.() ?? null;
      setDiagnostics(diag);
      return diag;
    } catch (err) {
      log.error('Failed to get pool diagnostics', err);
      return null;
    }
  }, []);

  // Auto-update on mount
  useEffect(() => {
    getDiagnostics();
  }, [getDiagnostics]);

  return {
    diagnostics,
    getDiagnostics,
  };
}

/**
 * Hook for detecting pool exhaustion conditions.
 */
export function useConnectionPoolExhaustionDetector(threshold: number = 0.85) {
  const [isExhausted, setIsExhausted] = useState(false);
  const [alertCount, setAlertCount] = useState(0);
  const { metrics } = useConnectionPoolMonitor();

  useEffect(() => {
    if (!metrics) return;

    const utilization = metrics.poolUtilization;
    const wasExhausted = isExhausted;

    if (utilization >= threshold) {
      setIsExhausted(true);
      if (!wasExhausted) {
        setAlertCount((prev) => prev + 1);
        log.error('Connection pool exhaustion detected', {
          utilization: (utilization * 100).toFixed(2) + '%',
          threshold: (threshold * 100).toFixed(2) + '%',
        });
      }
    } else if (utilization < threshold * 0.8) {
      setIsExhausted(false);
    }
  }, [metrics, threshold, isExhausted]);

  return {
    isExhausted,
    alertCount,
    utilizationRatio: metrics?.poolUtilization ?? 0,
  };
}

// ──────────────────────────────────────────────────────────────────────────
// BACKWARD COMPATIBILITY
// ──────────────────────────────────────────────────────────────────────────

/** Default export. */
export default {
  useConnectionAlertsPush,
  useConnectionQueues,
  useConnectionPoolMonitor,
  useConnectionPoolDiagnostics,
  useConnectionPoolExhaustionDetector,
};

import { useCallback } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { getLogger } from '@/lib/logger';
import { isValidUUID } from '@/utils/uuid';

const log = getLogger('useContactCustomFields');

/** Hook: Contact Custom Field. */
export interface ContactCustomField {
  id?: string;
  contact_id: string;
  field_name: string;
  field_value: string;
  field_type?: string;
}

/** Hook: use Contact Custom Fields. */
export function useContactCustomFields(contactId: string | undefined) {
  const queryClient = useQueryClient();
  const FIELDS_KEY = ['contact-custom-fields', contactId] as const;

  const {
    data: fields = [],
    isLoading,
    refetch,
  } = useQuery({
    queryKey: FIELDS_KEY,
    queryFn: async () => {
      const { data, error } = await supabase
        .from('contact_custom_fields')
        .select('*')
        .eq('contact_id', contactId!)
        .order('field_name', { ascending: true });

      if (error) {
        log.error('Error fetching custom fields:', error);
        throw error;
      }
      return (data || []) as ContactCustomField[];
    },
    enabled: !!contactId && isValidUUID(contactId),
    staleTime: 30_000,
  });

  const addField = useCallback(
    async (fieldName: string, fieldValue: string, fieldType = 'text') => {
      if (!contactId || !isValidUUID(contactId)) return;
      try {
        const { error } = await supabase.from('contact_custom_fields').upsert(
          {
            contact_id: contactId,
            field_name: fieldName,
            field_value: fieldValue,
            field_type: fieldType,
          },
          { onConflict: 'contact_id,field_name' }
        );
        if (error) throw error;
        void queryClient.invalidateQueries({ queryKey: FIELDS_KEY });
      } catch (err) {
        log.error('Error adding custom field:', err);
      }
    },
    [contactId, queryClient]
  );

  const removeField = useCallback(
    async (fieldId: string) => {
      try {
        const { error } = await supabase.from('contact_custom_fields').delete().eq('id', fieldId);
        if (error) throw error;
        void queryClient.invalidateQueries({ queryKey: FIELDS_KEY });
      } catch (err) {
        log.error('Error removing custom field:', err);
      }
    },
    [queryClient, contactId]
  );

  return { fields, isLoading, addField, removeField, refetch };
}

import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { log } from '@/lib/logger';
import type { ContactRow } from '@/integrations/supabase/schema';
import { isValidUUID } from '@/utils/uuid';

interface UseContactDataResult {
  contact: ContactRow | null;
  loading: boolean;
  error: Error | null;
}

/** Fetches contact data by ID with loading and error handling. */
export function useContactData(contactId: string | undefined): UseContactDataResult {
  const {
    data: contact = null,
    isLoading: loading,
    error: queryError,
  } = useQuery({
    queryKey: ['contact', contactId],
    queryFn: async () => {
      try {
        const { data, error: fetchError } = await supabase
          .from('contacts')
          .select('*')
          .eq('id', contactId!)
          .maybeSingle();
        if (fetchError) throw new Error(fetchError.message);
        return data as ContactRow | null;
      } catch (err) {
        const e = err instanceof Error ? err : new Error(String(err));
        log.error('Failed to fetch contact:', e);
        throw e;
      }
    },
    enabled: !!contactId && isValidUUID(contactId),
    staleTime: 30_000,
  });

  return {
    contact,
    loading,
    error:
      queryError instanceof Error ? queryError : queryError ? new Error(String(queryError)) : null,
  };
}

import { useState, useEffect, useCallback } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { queryKeys } from '@/services/api/queryKeys';
import { useMountedRef } from '@/hooks/useMountedRef';
import { supabase } from '@/integrations/supabase/client';
import { externalSupabase, isExternalConfigured } from '@/integrations/supabase/externalClient';
import { safeClient } from '@/integrations/supabase/safeClient';
import { dbList } from '@/integrations/datasource/db';
import { RPC } from '@/integrations/datasource/rpcCatalog';
import { toast } from 'sonner';
import { log } from '@/lib/logger';
import { addHours, startOfTomorrow, startOfDay, addDays, setHours } from 'date-fns';
import { isValidUUID } from '@/utils/uuid';

/* ============================================================================
   SECTION 1: useConversationActions - Pin, favorite, snooze management
   ============================================================================ */

interface FavoriteContact {
  contact_id: string;
}

/** Manages conversation pinning, archiving, and status operations. */
export function useConversationActions() {
  const [pinnedIds, setPinnedIds] = useState<Set<string>>(new Set());
  const [favoriteIds, setFavoriteIds] = useState<Set<string>>(new Set());
  const [snoozedIds, setSnoozedIds] = useState<Set<string>>(new Set());
  const [profileId, setProfileId] = useState<string | null>(null);
  const mountedRef = useMountedRef();

  const loadProfile = useCallback(async () => {
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user || !mountedRef.current) return;
    const { data } = await supabase
      .from('profiles')
      .select('id')
      .eq('user_id', user.id)
      .maybeSingle(); // ✅ fix: maybeSingle evita PGRST116
    if (data && mountedRef.current) setProfileId(data.id);
  }, [mountedRef]);

  const loadPinned = useCallback(
    async (pid: string) => {
      const { data, error } = await supabase
        .from('pinned_conversations')
        .select('contact_id')
        .eq('pinned_by', pid);
      if (error) {
        log.warn('loadPinned failed', error);
        return;
      }
      if (data && mountedRef.current) setPinnedIds(new Set(data.map((p) => p.contact_id)));
    },
    [mountedRef]
  );

  const loadFavorites = useCallback(async () => {
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user || !mountedRef.current) return;
    const { data, error } = await supabase
      .from('favorite_contacts')
      .select('contact_id')
      .eq('user_id', user.id);
    if (error) {
      log.warn('loadFavorites failed', error);
      return;
    }
    if (data && mountedRef.current)
      setFavoriteIds(new Set(data.map((f: FavoriteContact) => f.contact_id)));
  }, [mountedRef]);

  const loadSnoozed = useCallback(
    async (pid: string) => {
      const { data, error } = await supabase
        .from('conversation_snoozes')
        .select('contact_id')
        .eq('snoozed_by', pid)
        .gt('snooze_until', new Date().toISOString());
      if (error) {
        log.warn('loadSnoozed failed', error);
        return;
      }
      if (data && mountedRef.current) setSnoozedIds(new Set(data.map((s) => s.contact_id)));
    },
    [mountedRef]
  );

  useEffect(() => {
    loadProfile();
  }, [loadProfile]);

  useEffect(() => {
    if (profileId) {
      loadPinned(profileId);
      loadFavorites();
      loadSnoozed(profileId);
    }
  }, [profileId, loadPinned, loadFavorites, loadSnoozed]);

  const pinConversation = useCallback(
    async (contactId: string) => {
      if (!profileId || !isValidUUID(contactId)) return;
      const { error } = await supabase
        .from('pinned_conversations')
        .insert({ contact_id: contactId, pinned_by: profileId, position: 0 });
      if (!error) {
        setPinnedIds((prev) => new Set([...prev, contactId]));
        toast.success('Conversa fixada');
      } else {
        toast.error(`Erro ao fixar conversa: ${error.message}`);
      }
    },
    [profileId]
  );

  const unpinConversation = useCallback(
    async (contactId: string) => {
      if (!profileId || !isValidUUID(contactId)) return;
      const { error } = await supabase
        .from('pinned_conversations')
        .delete()
        .eq('contact_id', contactId)
        .eq('pinned_by', profileId);
      if (!error) {
        setPinnedIds((prev) => {
          const n = new Set(prev);
          n.delete(contactId);
          return n;
        });
        toast.success('Conversa desafixada');
      } else {
        toast.error(`Erro ao desafixar conversa: ${error.message}`);
      }
    },
    [profileId]
  );

  const favoriteContact = useCallback(async (contactId: string) => {
    if (!isValidUUID(contactId)) return;
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) return;
    const { error } = await supabase
      .from('favorite_contacts')
      .insert({ contact_id: contactId, user_id: user.id });
    if (!error) {
      setFavoriteIds((prev) => new Set([...prev, contactId]));
      toast.success('Contato favoritado');
    } else {
      toast.error(`Erro ao favoritar contato: ${error.message}`);
    }
  }, []);

  const unfavoriteContact = useCallback(async (contactId: string) => {
    if (!isValidUUID(contactId)) return;
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) return;
    const { error } = await supabase
      .from('favorite_contacts')
      .delete()
      .eq('contact_id', contactId)
      .eq('user_id', user.id);
    if (!error) {
      setFavoriteIds((prev) => {
        const n = new Set(prev);
        n.delete(contactId);
        return n;
      });
      toast.success('Favorito removido');
    } else {
      toast.error(`Erro ao remover favorito: ${error.message}`);
    }
  }, []);

  const snoozeConversation = useCallback(
    async (contactId: string, duration: string) => {
      if (!profileId) return;
      let snoozeUntil: Date;
      const now = new Date();
      switch (duration) {
        case '1h':
          snoozeUntil = addHours(now, 1);
          break;
        case '3h':
          snoozeUntil = addHours(now, 3);
          break;
        case 'tomorrow':
          snoozeUntil = setHours(startOfTomorrow(), 9);
          break;
        case 'nextweek': {
          const daysUntilMonday = (1 - now.getDay() + 7) % 7 || 7;
          snoozeUntil = setHours(startOfDay(addDays(now, daysUntilMonday)), 9);
          break;
        }
        default:
          snoozeUntil = addHours(now, 1);
      }

      const { error } = await supabase.from('conversation_snoozes').upsert(
        {
          contact_id: contactId,
          snoozed_by: profileId,
          snooze_until: snoozeUntil.toISOString(),
        },
        { onConflict: 'contact_id,snoozed_by' }
      );
      if (!error) {
        setSnoozedIds((prev) => new Set([...prev, contactId]));
        toast.success('Conversa adiada');
      } else {
        toast.error(`Erro ao adiar conversa: ${error.message}`);
      }
    },
    [profileId]
  );

  const isPinned = useCallback((contactId: string) => pinnedIds.has(contactId), [pinnedIds]);
  const isFavorite = useCallback((contactId: string) => favoriteIds.has(contactId), [favoriteIds]);
  const isSnoozed = useCallback((contactId: string) => snoozedIds.has(contactId), [snoozedIds]);

  return {
    pinnedIds,
    favoriteIds,
    snoozedIds,
    isPinned,
    isFavorite,
    isSnoozed,
    pinConversation,
    unpinConversation,
    favoriteContact,
    unfavoriteContact,
    snoozeConversation,
    profileId,
  };
}

/* ============================================================================
   SECTION 2: useConversationAnalyses - Conversation analysis & sentiment
   ============================================================================ */

/** Conversation Analysis interface. */
export interface ConversationAnalysis {
  id: string;
  contact_id: string;
  analyzed_by: string | null;
  summary: string;
  status: string;
  key_points: string[];
  next_steps: string[];
  sentiment: 'positivo' | 'neutro' | 'negativo' | 'critico';
  sentiment_score: number;
  topics: string[];
  urgency: 'baixa' | 'media' | 'alta' | 'critica' | null;
  customer_satisfaction: number;
  message_count: number;
  created_at: string;
}

/** Retrieves AI-generated conversation analyses and insights. */
export function useConversationAnalyses(contactId: string | null) {
  const queryClient = useQueryClient();
  const key = ['conversation-analyses', contactId] as const;

  const {
    data: analyses = [],
    isLoading: loading,
    error: queryError,
    refetch,
  } = useQuery({
    queryKey: key,
    queryFn: async () => {
      const { data, error } = await supabase
        .from('conversation_analyses')
        .select('*')
        .eq('contact_id', contactId!)
        .order('created_at', { ascending: false })
        .limit(20);
      if (error) throw error;
      return (data || []) as ConversationAnalysis[];
    },
    enabled: !!contactId && isValidUUID(contactId),
    staleTime: 30_000,
  });

  const error =
    queryError instanceof Error ? queryError.message : queryError ? String(queryError) : null;

  const saveAnalysis = async (
    analysis: Omit<ConversationAnalysis, 'id' | 'created_at' | 'analyzed_by'>
  ) => {
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      let profileId = null;

      if (user) {
        const { data: profile } = await supabase
          .from('profiles')
          .select('id')
          .eq('user_id', user.id)
          .maybeSingle();

        profileId = profile?.id || null;
      }

      const { data, error } = await supabase
        .from('conversation_analyses')
        .insert({
          ...analysis,
          analyzed_by: profileId,
        })
        .select()
        .single();

      if (error) throw error;

      await queryClient.invalidateQueries({ queryKey: key });
      return data as ConversationAnalysis;
    } catch (err) {
      log.error('Error saving analysis:', err);
      throw err;
    }
  };

  const getLatestAnalysis = () => {
    return analyses[0] || null;
  };

  const getSentimentTrend = () => {
    if (analyses.length < 2) return null;

    const recent = analyses.slice(0, 5);
    const avgRecent = recent.reduce((sum, a) => sum + a.sentiment_score, 0) / recent.length;

    const older = analyses.slice(5, 10);
    if (older.length === 0) return null;

    const avgOlder = older.reduce((sum, a) => sum + a.sentiment_score, 0) / older.length;

    const diff = avgRecent - avgOlder;

    if (diff > 5) return 'improving';
    if (diff < -5) return 'declining';
    return 'stable';
  };

  return {
    analyses,
    loading,
    error,
    saveAnalysis,
    getLatestAnalysis,
    getSentimentTrend,
    refetch,
  };
}

/* ============================================================================
   SECTION 3: useConversationSLATimeline - SLA milestones & attribution
   ============================================================================ */

/** SLA Attribution interface. */
export interface SLAAttribution {
  agentId: string | null;
  agentName: string | null;
  queueId: string | null;
  queueName: string | null;
}

/** First Response Attribution Source type alias. */
export type FirstResponseAttributionSource =
  'assign-event' | 'pre-contact-assign' | 'insufficient-events' | 'not-applicable';

/** S L A Timeline Data interface definition. */
export interface SLATimelineData {
  firstContactAt: Date | null;
  firstResponseAt: Date | null;
  firstResponseDurationMs: number | null;
  lastMessageAt: Date | null;
  closedAt: Date | null;
  resolutionDurationMs: number | null;
  reopenedAt: Date | null;
  isAwaitingFirstResponse: boolean;
  awaitingMs: number | null;
  totalMessages: number;
  firstResponseBy: SLAAttribution | null;
  firstResponseAttributionWindow: { from: Date; to: Date } | null;
  firstResponseAttributionSource: FirstResponseAttributionSource;
  resolvedBy: SLAAttribution | null;
}

interface EvolutionMessageRow {
  created_at: string;
  direction: string | null;
  from_me: boolean | null;
}

interface ConversationEventRow {
  event_type: string;
  created_at: string;
  performed_by: string | null;
  from_agent_id: string | null;
  to_agent_id: string | null;
  from_queue_id: string | null;
  to_queue_id: string | null;
  performed_by_profile?: { id: string; name: string | null } | null;
  to_agent?: { id: string; name: string | null } | null;
  to_queue?: { id: string; name: string | null } | null;
}

const EMPTY: SLATimelineData = {
  firstContactAt: null,
  firstResponseAt: null,
  firstResponseDurationMs: null,
  lastMessageAt: null,
  closedAt: null,
  resolutionDurationMs: null,
  reopenedAt: null,
  isAwaitingFirstResponse: false,
  awaitingMs: null,
  totalMessages: 0,
  firstResponseBy: null,
  firstResponseAttributionWindow: null,
  firstResponseAttributionSource: 'not-applicable',
  resolvedBy: null,
};

/** Tracks SLA compliance and timeline events for conversations. */
export function useConversationSLATimeline(remoteJid: string | null, contactId: string | null) {
  const enabled = Boolean(remoteJid && isExternalConfigured);

  return useQuery({
    queryKey: queryKeys.sla.timelineDetailed(remoteJid ?? undefined, contactId ?? undefined),
    enabled,
    staleTime: 30_000,
    refetchInterval: (query) => {
      const data = query.state.data as SLATimelineData | undefined;
      return data?.isAwaitingFirstResponse ? 30_000 : false;
    },
    queryFn: async (): Promise<SLATimelineData> => {
      if (!remoteJid || !externalSupabase) return EMPTY;

      const { data: msgs, error: msgErr } = await dbList(RPC.listMessagesLite, {
        p_remote_jid: remoteJid,
        p_limit: 500,
      });
      if (msgErr) throw msgErr;

      const rows = (msgs || []) as EvolutionMessageRow[];
      const sorted = [...rows].sort(
        (a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime()
      );

      const firstInbound = sorted.find((m) => m.from_me === false || m.direction === 'inbound');
      const firstOutbound = sorted.find((m) => m.from_me === true || m.direction === 'outbound');
      const last = sorted[sorted.length - 1];

      const firstContactAt = firstInbound ? new Date(firstInbound.created_at) : null;
      const firstResponseAt = firstOutbound ? new Date(firstOutbound.created_at) : null;
      const lastMessageAt = last ? new Date(last.created_at) : null;

      const firstResponseDurationMs =
        firstContactAt && firstResponseAt && firstResponseAt > firstContactAt
          ? firstResponseAt.getTime() - firstContactAt.getTime()
          : null;

      const isAwaitingFirstResponse = Boolean(firstContactAt && !firstResponseAt);
      const awaitingMs =
        isAwaitingFirstResponse && firstContactAt ? Date.now() - firstContactAt.getTime() : null;

      let closedAt: Date | null = null;
      let reopenedAt: Date | null = null;
      let resolvedBy: SLAAttribution | null = null;
      let firstResponseBy: SLAAttribution | null = null;
      let firstResponseAttributionWindow: { from: Date; to: Date } | null = null;
      let firstResponseAttributionSource: FirstResponseAttributionSource = firstResponseAt
        ? 'insufficient-events'
        : 'not-applicable';

      if (contactId && isValidUUID(contactId)) {
        const { data: events } = await safeClient.from<ConversationEventRow>(
          'conversation_events',
          (q) =>
            q
              .select(
                `
            event_type, created_at, performed_by, from_agent_id, to_agent_id,
            from_queue_id, to_queue_id,
            performed_by_profile:profiles!conversation_events_performed_by_fkey(id, name),
            to_agent:profiles!conversation_events_to_agent_id_fkey(id, name),
            to_queue:queues!conversation_events_to_queue_id_fkey(id, name)
          `
              )
              .eq('contact_id', contactId)
              .in('event_type', ['close', 'reopen', 'assign'])
              .order('created_at', { ascending: false })
              .limit(50)
        );

        const eventRows = events ?? [];
        const lastClose = eventRows.find((e) => e.event_type === 'close');
        const lastReopen = eventRows.find((e) => e.event_type === 'reopen');

        if (lastClose) {
          closedAt = new Date(lastClose.created_at);
          resolvedBy = {
            agentId: lastClose.performed_by_profile?.id ?? lastClose.performed_by ?? null,
            agentName: lastClose.performed_by_profile?.name ?? null,
            queueId: lastClose.to_queue?.id ?? lastClose.to_queue_id ?? null,
            queueName: lastClose.to_queue?.name ?? null,
          };
        }
        if (lastReopen) reopenedAt = new Date(lastReopen.created_at);

        if (closedAt && reopenedAt && reopenedAt > closedAt) {
          closedAt = null;
          resolvedBy = null;
        }

        if (firstResponseAt) {
          const assignsAsc = eventRows
            .filter((e) => e.event_type === 'assign')
            .sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime());

          const responseTs = firstResponseAt.getTime();
          const contactTs = firstContactAt?.getTime() ?? -Infinity;

          const inWindow = assignsAsc.filter((e) => {
            const ts = new Date(e.created_at).getTime();
            return ts >= contactTs && ts <= responseTs;
          });

          if (inWindow.length > 0) {
            const firstAssign = inWindow[0];
            const lastAssign = inWindow[inWindow.length - 1];
            firstResponseBy = {
              agentId: lastAssign.to_agent?.id ?? lastAssign.to_agent_id ?? null,
              agentName: lastAssign.to_agent?.name ?? null,
              queueId: lastAssign.to_queue?.id ?? lastAssign.to_queue_id ?? null,
              queueName: lastAssign.to_queue?.name ?? null,
            };
            firstResponseAttributionWindow = {
              from: new Date(firstAssign.created_at),
              to: firstResponseAt,
            };
            firstResponseAttributionSource = 'assign-event';
          } else {
            const preContact = [...assignsAsc]
              .reverse()
              .find((e) => new Date(e.created_at).getTime() < contactTs);
            if (preContact) {
              firstResponseBy = {
                agentId: preContact.to_agent?.id ?? preContact.to_agent_id ?? null,
                agentName: preContact.to_agent?.name ?? null,
                queueId: preContact.to_queue?.id ?? preContact.to_queue_id ?? null,
                queueName: preContact.to_queue?.name ?? null,
              };
              firstResponseAttributionSource = 'pre-contact-assign';
            } else {
              firstResponseAttributionSource = 'insufficient-events';
            }
          }
        }
      }

      const resolutionDurationMs =
        firstContactAt && closedAt && closedAt > firstContactAt
          ? closedAt.getTime() - firstContactAt.getTime()
          : null;

      return {
        firstContactAt,
        firstResponseAt,
        firstResponseDurationMs,
        lastMessageAt,
        closedAt,
        resolutionDurationMs,
        reopenedAt,
        isAwaitingFirstResponse,
        awaitingMs,
        totalMessages: sorted.length,
        firstResponseBy,
        firstResponseAttributionWindow,
        firstResponseAttributionSource,
        resolvedBy,
      };
    },
  });
}

import { useMemo, useCallback } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import type {
  DashboardFilters,
  DashboardStats,
  QueueStats,
  RecentActivity,
} from './dashboardTypes';

interface ProfileRow {
  id: string;
  name: string | null;
  is_active: boolean | null;
  role: string | null;
}
interface ContactRow {
  id: string;
  assigned_to: string | null;
  queue_id: string | null;
  updated_at: string;
}
interface QueueMemberRow {
  queue_id: string;
  profile_id: string;
  profile: { is_active: boolean | null } | null;
}
interface QueueRow {
  id: string;
  name: string;
  color: string | null;
  queue_members: QueueMemberRow[];
}

/** Fetches agents, contacts (with name/phone), and queues for the dashboard, computing stats and recent activity. Exposes a refetch callback that invalidates all three query keys. */
export function useDashboardData(filters?: DashboardFilters) {
  const queryClient = useQueryClient();

  const merged = useMemo(() => {
    const now = new Date();
    const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const endOfToday = new Date(startOfToday);
    endOfToday.setDate(endOfToday.getDate() + 1);
    return {
      dateRange: { from: startOfToday, to: endOfToday },
      queueId: null,
      agentId: null,
      ...filters,
    };
  }, [filters]);

  const { data: agentsData, isLoading: loadingAgents } = useQuery({
    queryKey: ['dashboard-agents', merged.agentId],
    queryFn: async () => {
      let query = supabase.from('profiles').select('id, name, is_active, role');
      if (merged.agentId) query = query.eq('id', merged.agentId);
      const { data, error } = await query;
      if (error) throw error;
      return {
        onlineAgents: ((data as ProfileRow[]) || []).filter((p) => p.is_active).length,
        totalAgents: (data || []).length,
      };
    },
  });

  const { data: contactsData, isLoading: loadingContacts } = useQuery({
    queryKey: [
      'dashboard-contacts',
      merged.agentId,
      merged.queueId,
      merged.dateRange.from.toISOString(),
      merged.dateRange.to.toISOString(),
    ],
    queryFn: async () => {
      let query = supabase
        .from('contacts')
        .select('id, name, phone, assigned_to, queue_id, updated_at')
        .gte('updated_at', merged.dateRange.from.toISOString())
        .lte('updated_at', merged.dateRange.to.toISOString());
      if (merged.queueId) query = query.eq('queue_id', merged.queueId);
      if (merged.agentId) query = query.eq('assigned_to', merged.agentId);
      const { data, error } = await query;
      if (error) throw error;
      return data || [];
    },
  });

  const { data: queuesData, isLoading: loadingQueues } = useQuery({
    queryKey: ['dashboard-queues', merged.queueId],
    queryFn: async () => {
      let query = supabase
        .from('queues')
        .select(
          'id, name, color, queue_members(queue_id, profile_id, profile:profiles(is_active))'
        );
      if (merged.queueId) query = query.eq('id', merged.queueId);
      const { data, error } = await query;
      if (error) throw error;
      return data || [];
    },
  });

  const isLoading = loadingAgents || loadingContacts || loadingQueues;

  const stats = useMemo((): DashboardStats | null => {
    if (!contactsData || !agentsData || !queuesData) return null;

    const contacts = contactsData as ContactRow[];
    const queues = queuesData as QueueRow[];

    const openConversations = contacts.filter((c) => c.assigned_to).length;
    const pendingConversations = contacts.filter((c) => !c.assigned_to && c.queue_id).length;
    // contacts table has no status column; resolved count not computable from this dataset
    const resolvedToday = 0;

    const queuesStats: QueueStats[] = queues.map((queue) => {
      const members = queue.queue_members || [];
      const onlineMembers = members.filter((m) => m.profile?.is_active).length;
      const queuePending = contacts.filter((c) => !c.assigned_to && c.queue_id === queue.id).length;
      return {
        id: queue.id,
        name: queue.name,
        color: queue.color,
        waitingCount: queuePending,
        onlineAgents: onlineMembers,
        totalAgents: members.length,
      };
    });

    const recentActivity: RecentActivity[] = contacts.slice(0, 10).map((c) => ({
      id: c.id,
      contactName: (c as { name?: string }).name ?? 'Contact',
      contactPhone: (c as { phone?: string }).phone ?? '',
      contactAvatar: null,
      lastMessage: '',
      timestamp: c.updated_at,
      status: 'unread',
      unreadCount: 0,
    }));

    return {
      openConversations,
      pendingConversations,
      resolvedToday,
      totalConversations: contacts.length,
      onlineAgents: agentsData.onlineAgents,
      totalAgents: agentsData.totalAgents,
      avgResponseTime: null,
      queuesStats,
      recentActivity,
    };
  }, [contactsData, agentsData, queuesData, merged]);

  const refetch = useCallback(() => {
    return Promise.all([
      queryClient.invalidateQueries({ queryKey: ['dashboard-agents'] }),
      queryClient.invalidateQueries({ queryKey: ['dashboard-contacts'] }),
      queryClient.invalidateQueries({ queryKey: ['dashboard-queues'] }),
    ]);
  }, [queryClient]);

  return { stats, isLoading, refetch };
}

/** Converts a nullable seconds value to a human-readable string (e.g. "2min 30s", "1h 5min"). Returns "N/A" when null. */
export const formatResponseTime = (seconds: number | null): string => {
  if (seconds === null) return 'N/A';
  if (seconds < 60) return `${seconds}s`;
  const minutes = Math.floor(seconds / 60);
  const remainingSeconds = seconds % 60;
  if (minutes < 60) return `${minutes}min ${remainingSeconds}s`;
  const hours = Math.floor(minutes / 60);
  const remainingMinutes = minutes % 60;
  return `${hours}h ${remainingMinutes}min`;
};

