/** Catalog Filters interface definition. */
export interface CatalogFilters {
  search?: string;
  category_id?: string;
  supplier_id?: string;
  only_active?: boolean;
  only_in_stock?: boolean;
  limit?: number;
  offset?: number;
  order_by?: string;
  ascending?: boolean;
}

async function invokeAction<T = unknown>(
  action: string,
  params: Record<string, unknown> = {}
): Promise<T> {
  const { data, error } = await supabase.functions.invoke('promogifts-catalog', {
    body: { action, params },
  });
  if (error) throw new Error(error.message);
  if (hasField(data, 'error') && typeof data.error === 'string') {
    throw new Error(data.error);
  }
  return data as T; // ignore-audit: narrows Supabase query result to local interface
}

/** with Safe Variants function. */
export function withSafeVariants(
  product: ExternalProduct | null | undefined
): ExternalProduct | null {
  if (!product) return null;
  return {
    ...product,
    variants: readVariants<ExternalProductVariant>(product),
  };
}

/** Manages external product catalog with filtering, searching, and variant handling. */
export function useExternalCatalog() {
  const queryClient = useQueryClient();
  const [filters, setFilters] = useState<CatalogFilters>({});
  const [ready, setReady] = useState(false);

  const logCatalog = getLogger('ExternalCatalog');

  // Products query - auto-fetches when filters change and ready=true
  const productsQuery = useQuery({
    queryKey: queryKeys.external.catalog.products(filters),
    queryFn: async () => {
      logCatalog.debug('Fetching products with filters:', JSON.stringify(filters));
      const result = await invokeAction<unknown>(
        'list_products',
        filters as Record<string, unknown>
      );
      const products = readArray<ExternalProduct>(result, 'data').map((p) => ({
        ...p,
        variants: readVariants<ExternalProductVariant>(p),
      }));
      const meta = (result && typeof result === 'object' && 'meta' in result
        ? (result as { meta?: { total?: number; duration_ms?: number } }).meta
        : undefined) ?? { total: 0, duration_ms: 0 };
      logCatalog.debug('Got', products.length, 'products, total:', meta.total);
      return {
        data: products,
        meta: { total: meta.total ?? 0, duration_ms: meta.duration_ms ?? 0 },
      };
    },
    enabled: ready,
    staleTime: 5 * 60 * 1000,
    gcTime: 10 * 60 * 1000,
    retry: tanstackRetry, // fix: era 'retry: 2' numerico, sobrescrevia o QueryClient global
  });

  // Categories
  const categoriesQuery = useQuery({
    queryKey: queryKeys.external.catalog.categories(),
    queryFn: async () => {
      const result = await invokeAction<unknown>('list_categories');
      return readArray<ExternalCategory>(result, 'data');
    },
    enabled: ready,
    staleTime: 30 * 60 * 1000,
    gcTime: 60 * 60 * 1000,
  });

  // Suppliers
  const suppliersQuery = useQuery({
    queryKey: queryKeys.external.catalog.suppliers(),
    queryFn: async () => {
      const result = await invokeAction<unknown>('list_suppliers');
      return readArray<ExternalSupplier>(result, 'data');
    },
    enabled: ready,
    staleTime: 30 * 60 * 1000,
    gcTime: 60 * 60 * 1000,
  });

  // Called by component to set filters and trigger fetch
  const fetchProducts = useCallback((newFilters: CatalogFilters = {}) => {
    setFilters(newFilters);
    setReady(true);
  }, []);

  const fetchProduct = useCallback(
    async (productId: string): Promise<ExternalProduct | null> => {
      try {
        const result = await queryClient.fetchQuery({
          queryKey: queryKeys.external.catalog.product(productId),
          queryFn: async () => {
            const res = await invokeAction<unknown>('get_product', { product_id: productId });
            const product =
              (res && typeof res === 'object' && 'data' in res
                ? (res as { data?: ExternalProduct }).data
                : null) ?? null;
            return withSafeVariants(product);
          },
          staleTime: 5 * 60 * 1000,
        });
        return result;
      } catch (err) {
        logCatalog.error('Failed to fetch product', err);
        return null;
      }
    },
    [queryClient]
  );

  const fetchCategories = useCallback(() => {
    setReady(true);
  }, []);

  const fetchSuppliers = useCallback(() => {
    setReady(true);
  }, []);

  return {
    products: productsQuery.data?.data || [],
    totalProducts: productsQuery.data?.meta?.total ?? 0,
    categories: categoriesQuery.data || [],
    suppliers: suppliersQuery.data || [],
    loading: productsQuery.isLoading || productsQuery.isFetching,
    error: (productsQuery.error as Error | null)?.message || null,
    fetchProducts,
    fetchProduct,
    fetchCategories,
    fetchSuppliers,
  };
}

// ╔══════════════════════════════════════════════════════════════════════════════════
// SECTION 5: Generic External DB Operations
// ╚══════════════════════════════════════════════════════════════════════════════════

import { useMutation } from '@tanstack/react-query';
import type { SupabaseClient } from '@supabase/supabase-js';
import type {
  ExternalDBFilter,
  ExternalDBOrder,
  ExternalDBQueryResult,
  ExternalTableName,
} from '@/types/externalDB';
import { validateEntityAccess, validateRpcAccess } from '@/integrations/datasource/sentinel';

// This hook is intentionally generic — it works with arbitrary table/rpc names
// supplied at runtime, so we use an untyped client to avoid requiring compile-time
// table name literals that SupabaseClient<Database> enforces.

// ─── Direct query helper ────────────────────────────────────────────────
async function queryExternal<T = unknown>(params: {
  table: string;
  select?: string;
  filters?: ExternalDBFilter[];
  order?: ExternalDBOrder;
  limit?: number;
  offset?: number;
  countMode?: 'exact' | 'planned' | 'estimated';
}): Promise<ExternalDBQueryResult<T>> {
  validateEntityAccess(params.table, 'external');
  const start = performance.now();

  let query = getDynamicClient()
    .from(params.table)
    .select(params.select || '*', { count: params.countMode || undefined });

  if (params.filters) {
    for (const f of params.filters) {
      query = query.filter(f.column, f.operator, f.value as string);
    }
  }

  if (params.order) {
    query = query.order(params.order.column, { ascending: params.order.ascending ?? true });
  }

  const limit = params.limit || 50;
  const offset = params.offset || 0;
  query = query.range(offset, offset + limit - 1);

  const { data, error, count } = await query;
  const duration = Math.round(performance.now() - start);

  if (error) throw new Error(error.message);

  return {
    data: (data as T[]) || [], // ignore-audit: data from untyped external DB client requires explicit cast to generic T[]
    meta: {
      record_count: count ?? (Array.isArray(data) ? data.length : null),
      duration_ms: duration,
      severity: duration > 3000 ? 'slow' : 'ok',
    },
  };
}

// ─── Select query hook ────────────────────────────────────────────
interface UseExternalSelectOptions {
  table: ExternalTableName | string;
  select?: string;
  filters?: ExternalDBFilter[];
  order?: ExternalDBOrder;
  limit?: number;
  offset?: number;
  countMode?: 'exact' | 'planned' | 'estimated';
  enabled?: boolean;
  staleTime?: number;
}

/** Queries external database tables with filtering, ordering, and pagination. */
export function useExternalSelect<T = Record<string, unknown>>(options: UseExternalSelectOptions) {
  const {
    table,
    select,
    filters,
    order,
    limit = 50,
    offset = 0,
    countMode,
    enabled = true,
    staleTime = 5 * 60 * 1000,
  } = options;

  return useQuery({
    queryKey: queryKeys.external.db(table, { select, filters, order, limit, offset, countMode }),
    queryFn: () =>
      queryExternal<T>({
        table,
        select,
        filters,
        order,
        limit,
        offset,
        countMode,
      }),
    enabled: enabled && isExternalConfigured,
    staleTime,
    gcTime: staleTime * 2,
  });
}

// ─── RPC call hook ────────────────────────────────────────────
interface UseExternalRPCOptions {
  rpc: string;
  params?: Record<string, unknown>;
  enabled?: boolean;
  staleTime?: number;
}

/** Calls external database RPC functions with access validation and metrics. */
export function useExternalRPC<T = unknown>(options: UseExternalRPCOptions) {
  return useQuery({
    queryKey: queryKeys.external.rpc(options.rpc, options.params),
    queryFn: async () => {
      validateRpcAccess(options.rpc, 'external');
      const start = performance.now();
      const { data, error } = await getDynamicClient().rpc(options.rpc, options.params || {});
      const duration = Math.round(performance.now() - start);
      if (error) throw new Error(error.message);
      return {
        data: Array.isArray(data) ? (data as T[]) : [data as T], // ignore-audit: RPC data from untyped external DB client requires explicit cast to generic T
        meta: {
          record_count: Array.isArray(data) ? data.length : 1,
          duration_ms: duration,
          severity: 'ok' as string,
        },
      };
    },
    enabled: (options.enabled ?? true) && isExternalConfigured,
    staleTime: options.staleTime ?? 10 * 60 * 1000,
  });
}

// ─── Paginated table browser ────────────────────────────────────────────/** Provides paginated browsing of external database tables with filtering and sorting. */
export function useExternalTableBrowser<T = Record<string, unknown>>(
  tableName: ExternalTableName | string
) {
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(25);
  const [filters, setFilters] = useState<ExternalDBFilter[]>([]);
  const [order, setOrder] = useState<ExternalDBOrder | undefined>();
  const [searchTerm, setSearchTerm] = useState('');

  const query = useExternalSelect<T>({
    table: tableName,
    filters,
    order,
    limit: pageSize,
    offset: page * pageSize,
    countMode: 'estimated',
    staleTime: 2 * 60 * 1000,
  });

  const nextPage = useCallback(() => setPage((p) => p + 1), []);
  const prevPage = useCallback(() => setPage((p) => Math.max(0, p - 1)), []);
  const goToPage = useCallback((p: number) => setPage(p), []);

  const addFilter = useCallback((filter: ExternalDBFilter) => {
    setFilters((prev) => [...prev, filter]);
    setPage(0);
  }, []);

  const removeFilter = useCallback((index: number) => {
    setFilters((prev) => prev.filter((_, i) => i !== index));
    setPage(0);
  }, []);

  const clearFilters = useCallback(() => {
    setFilters([]);
    setPage(0);
  }, []);

  const setSort = useCallback((column: string, ascending = true) => {
    setOrder({ column, ascending });
    setPage(0);
  }, []);

  return {
    data: query.data?.data || [],
    totalRecords: query.data?.meta?.record_count ?? 0,
    duration: query.data?.meta?.duration_ms ?? 0,
    isLoading: query.isLoading,
    isFetching: query.isFetching,
    error: query.error?.message || null,
    page,
    pageSize,
    filters,
    order,
    searchTerm,
    setSearchTerm,
    setPageSize: (size: number) => {
      setPageSize(size);
      setPage(0);
    },
    nextPage,
    prevPage,
    goToPage,
    addFilter,
    removeFilter,
    clearFilters,
    setSort,
    refetch: query.refetch,
  };
}

// ─── Mutation (insert/update/delete via external client) ────
/** Performs insert, update, and delete mutations on external database tables. */
export function useExternalMutation() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (params: {
      action: 'insert' | 'update' | 'delete';
      table: string;
      data?: Record<string, unknown> | Record<string, unknown>[];
      match?: Record<string, unknown>;
    }) => {
      validateEntityAccess(params.table, 'external');
      const dc = getDynamicClient();
      if (params.action === 'insert') {
        const { data, error } = await dc.from(params.table).insert(params.data as never).select();
        if (error) throw new Error(error.message);
        return data;
      }
      if (params.action === 'update') {
        let q = dc.from(params.table).update(params.data as never);
        if (params.match) {
          for (const [k, v] of Object.entries(params.match)) q = q.eq(k, v as string);
        }
        const { data, error } = await q.select();
        if (error) throw new Error(error.message);
        return data;
      }
      if (params.action === 'delete') {
        let q = dc.from(params.table).delete();
        if (params.match) {
          for (const [k, v] of Object.entries(params.match)) q = q.eq(k, v as string);
        }
        const { data, error } = await q.select();
        if (error) throw new Error(error.message);
        return data;
      }
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: queryKeys.external.db(variables.table) });
    },
  });
}

import { useCallback } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { safeClient } from '@/integrations/supabase/safeClient';
import { emailMappers } from '@/utils/emailMappers';
import { EmailLabelInfo as EmailLabel } from '@/types/gmail';
import { getLogger } from '@/lib/logger';

/** Re-exported module members. */
export type { EmailLabel };

const log = getLogger('useEmailLabels');

/** Hook: SYSTEM_LABELS. */
export const SYSTEM_LABELS: Array<{ id: string; name: string; icon: string; color: string }> = [
  { id: 'INBOX', name: 'Inbox', icon: 'inbox', color: 'hsl(var(--primary))' },
  { id: 'STARRED', name: 'Favoritos', icon: 'star', color: 'hsl(var(--warning))' },
  { id: 'IMPORTANT', name: 'Importantes', icon: 'flag', color: 'hsl(var(--warning))' },
  { id: 'SENT', name: 'Enviados', icon: 'send', color: 'hsl(var(--success))' },
  { id: 'DRAFTS', name: 'Rascunhos', icon: 'draft', color: 'hsl(var(--muted-foreground))' },
  { id: 'SPAM', name: 'Spam', icon: 'block', color: 'hsl(var(--destructive))' },
  { id: 'TRASH', name: 'Lixeira', icon: 'delete', color: 'hsl(var(--muted-foreground))' },
];

/** Hook: use Email Labels. */
export function useEmailLabels(accountId: string | null) {
  const queryClient = useQueryClient();
  const key = ['email-labels', accountId] as const;

  const { data: labels = [], isLoading, error: queryError } = useQuery({
    queryKey: key,
    queryFn: async () => {
      const { data, error: dbErr } = await safeClient.from('email_labels', (q) =>
        q.select('*').eq('account_id', accountId!).order('name', { ascending: true })
      );
      if (dbErr) {
        log.warn('Email labels load error', dbErr.message);
        throw new Error('Não foi possível carregar as pastas do Email.');
      }
      return emailMappers.labels((Array.isArray(data) ? data : []) as Parameters<typeof emailMappers.labels>[0]);
    },
    enabled: !!accountId,
    staleTime: 30_000,
  });

  const error = queryError instanceof Error ? queryError.message : null;

  const loadLabels = useCallback(
    () => queryClient.invalidateQueries({ queryKey: key }),
    [queryClient, key]
  );

  const syncLabels = useCallback(async () => {
    if (!accountId) return;
    try {
      const { data, error: fnErr } = await supabase.functions.invoke('gmail-sync', {
        body: { action: 'syncLabels', accountId },
      });
      if (!fnErr && data?.success) {
        await queryClient.invalidateQueries({ queryKey: key });
      }
    } catch {
      // ignore
    }
  }, [accountId, queryClient, key]);

  const getLabelCount = useCallback(
    async (labelId: string): Promise<{ thread_count: number; unread_count: number }> => {
      if (!accountId) return { thread_count: 0, unread_count: 0 };
      const { data } = await safeClient.from<{ id: string; unread_count: number }>(
        'email_threads',
        (q) =>
          q.select('id, unread_count').eq('account_id', accountId).contains('label_ids', [labelId])
      );
      const threads = data ?? [];
      return {
        thread_count: threads.length,
        unread_count: threads.reduce((s, t) => s + (t.unread_count ?? 0), 0),
      };
    },
    [accountId]
  );

  const systemLabels = SYSTEM_LABELS.map((sl) => ({
    id: `system-${sl.id}`,
    account_id: accountId ?? '',
    email_label_id: sl.id,
    name: sl.name,
    type: 'system' as const,
    color: sl.color,
  }));

  const userLabels = labels.filter((l) => l.type === 'user');
  const allLabels = [...systemLabels, ...userLabels];

  return {
    labels,
    userLabels,
    systemLabels,
    allLabels,
    isLoading,
    error,
    loadLabels,
    syncLabels,
    getLabelCount,
    SYSTEM_LABELS,
  };
}

/**
 * useEmailOAuthFlow.ts — OAuth2 Email com refresh automático de token
 *
 * Responsabilidades:
 * 1. Iniciar fluxo OAuth (redirect para Google)
 * 2. Trocar code por tokens (Edge Function email-oauth)
 * 3. Refresh automático do access_token 5 min antes de expirar
 * 4. Revogar acesso (disconnect)
 * 5. Retornar estado do token (valid | expiring | expired | loading)
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { safeClient } from '@/integrations/supabase/safeClient';
import { emailMappers } from '@/utils/emailMappers';
import { EmailAccount } from '@/types/gmail';
import { emailRefreshToken, emailRevokeAccount, emailRegisterWatch } from './gmail/gmailApi';
import { toast } from 'sonner';
import { getLogger } from '@/lib/logger';

const log = getLogger('useEmailOAuthFlow');

// 5 minutos antes da expiração → refresh proativo
const REFRESH_AHEAD_MS = 5 * 60 * 1000;
// Intervalo de verificação do token
const CHECK_INTERVAL_MS = 60 * 1000;

export type TokenStatus = 'loading' | 'valid' | 'expiring' | 'expired' | 'disconnected';

interface UseEmailOAuthFlowReturn {
  accounts: EmailAccount[];
  tokenStatus: Record<string, TokenStatus>;
  isLoading: boolean;
  startOAuth: () => void;
  disconnect: (accountId: string) => Promise<void>;
  refreshNow: (accountId: string) => Promise<void>;
  ensureWatch: (accountId: string) => Promise<void>;
}

const GMAIL_ACCOUNTS_KEY = ['gmail-accounts'] as const;

export function useEmailOAuthFlow(): UseEmailOAuthFlowReturn {
  const queryClient = useQueryClient();
  const [tokenStatus, setTokenStatus] = useState<Record<string, TokenStatus>>({});
  const refreshingRef = useRef<Set<string>>(new Set());
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const oauthInFlightRef = useRef(false);
  const oauthCleanupRef = useRef<(() => void) | null>(null);

  // ── Carrega contas ──────────────────────────────────────────────────

  const { data: accounts = [], isLoading } = useQuery({
    queryKey: GMAIL_ACCOUNTS_KEY,
    queryFn: async () => {
      const { data, error } = await safeClient.from<Record<string, unknown>>(
        'email_accounts',
        (q) =>
          q
            .select(
              'id, user_id, email:email_address, display_name, picture_url, token_expiry:token_expires_at, is_active, created_at'
            )
            .eq('is_active', true)
            .order('created_at')
      );

      if (error) {
        log.error('Erro ao carregar contas Email', error);
        return [] as EmailAccount[];
      }

      return emailMappers.accounts(data ?? []) as EmailAccount[];
    },
    staleTime: 30_000,
  });

  const accountsRef = useRef(accounts);
  accountsRef.current = accounts;
  const accountIdsKey = useMemo(() => accounts.map((a) => a.id).join(','), [accounts]);

  // ── Calcula status do token ─────────────────────────────────────────

  const computeStatuses = useCallback((accs: EmailAccount[]) => {
    const now = Date.now();
    const statuses: Record<string, TokenStatus> = {};

    for (const acc of accs) {
      const expiry = new Date((acc as any).token_expiry).getTime();
      if (expiry < now) {
        statuses[acc.id] = 'expired';
      } else if (expiry - now < REFRESH_AHEAD_MS) {
        statuses[acc.id] = 'expiring';
      } else {
        statuses[acc.id] = 'valid';
      }
    }

    setTokenStatus(statuses);
    return statuses;
  }, []);

  // ── Refresh de token ────────────────────────────────────────────────

  const refreshNow = useCallback(
    async (accountId: string) => {
      if (refreshingRef.current.has(accountId)) return;
      refreshingRef.current.add(accountId);

      setTokenStatus((prev) => ({ ...prev, [accountId]: 'loading' }));

      try {
        const result = await emailRefreshToken(accountId);

        const newExpiry = result.data?.newExpiry ?? null;
        log.info(`Token refreshed for account ${accountId}, expires at ${newExpiry}`);
        setTokenStatus((prev) => ({ ...prev, [accountId]: 'valid' }));
        void queryClient.invalidateQueries({ queryKey: GMAIL_ACCOUNTS_KEY });
      } catch (err) {
        log.error(`Falha ao refreshar token para conta ${accountId}`, err);
        setTokenStatus((prev) => ({ ...prev, [accountId]: 'expired' }));
        toast.error('Sessão Email expirada', {
          description: 'Reconecte sua conta Email nas configurações.',
          duration: 8000,
        });
      } finally {
        refreshingRef.current.delete(accountId);
      }
    },
    [queryClient]
  );

  // ── Auto-refresh loop ───────────────────────────────────────────────

  const checkAndRefresh = useCallback(
    async (accs: EmailAccount[]) => {
      const statuses = computeStatuses(accs);

      for (const acc of accs) {
        const status = statuses[acc.id];
        if (status === 'expiring' || status === 'expired') {
          await refreshNow(acc.id);
        }
      }
    },
    [computeStatuses, refreshNow]
  );

  // ── Ensure Pub/Sub watch ────────────────────────────────────────────

  const ensureWatch = useCallback(
    async (accountId: string) => {
      const acc = accounts.find((a) => a.id === accountId);
      if (!acc) return;

      // Renova watch se faltam menos de 24h para expirar
      const watchExpiry = acc.watch_expiry ? new Date(acc.watch_expiry).getTime() : 0;
      const renewThreshold = 24 * 60 * 60 * 1000;

      if (!acc.watch_expiry || watchExpiry - Date.now() < renewThreshold) {
        try {
          const result = await emailRegisterWatch(accountId);
          const newWatchExpiry = result.data?.expiresAt ?? null;
          log.info(`Pub/Sub watch renovado para ${accountId}, expira em ${newWatchExpiry}`);
          void queryClient.invalidateQueries({ queryKey: GMAIL_ACCOUNTS_KEY });
        } catch (err) {
          log.warn(`Não foi possível renovar watch para ${accountId}`, err);
        }
      }
    },
    [accounts, queryClient]
  );

  // ── OAuth initiate ──────────────────────────────────────────────────

  const startOAuth = useCallback(() => {
    // Guarda contra clique duplo / chamadas concorrentes: sem isto, dois
    // listeners 'message' ficariam ativos e ambos tentariam exchangeCode
    // com o MESMO code de uso único, fazendo a 2ª tentativa falhar no servidor.
    if (oauthInFlightRef.current) return;
    oauthInFlightRef.current = true;

    // Monta URL de autorização (Edge Function email-oauth retorna a URL)
    supabase.functions
      .invoke('gmail-oauth', { body: { action: 'getAuthUrl' } })
      .then(({ data, error }) => {
        if (error || !data?.url) {
          toast.error('Não foi possível iniciar a autenticação Email');
          oauthInFlightRef.current = false;
          return;
        }
        // Abre popup OAuth
        const popup = window.open(data.url, 'email-oauth', 'width=500,height=600,scrollbars=yes');
        if (!popup) {
          toast.error('Popup bloqueado. Permita popups para este site.');
          oauthInFlightRef.current = false;
          return;
        }

        let settled = false;
        let closeCheckInterval: ReturnType<typeof setInterval> | null = null;

        const cleanupListeners = () => {
          window.removeEventListener('message', onMessage);
          if (closeCheckInterval !== null) clearInterval(closeCheckInterval);
          oauthCleanupRef.current = null;
        };
        oauthCleanupRef.current = cleanupListeners;

        const onMessage = async (event: MessageEvent) => {
          if (settled) return;
          const msg = event.data;
          if (msg?.type === 'gmail-oauth-error') {
            settled = true;
            cleanupListeners();
            popup?.close();
            toast.error('Falha na autenticação Email', { description: String(msg.error ?? '') });
            oauthInFlightRef.current = false;
            return;
          }
          if (msg?.type !== 'gmail-oauth-code') return;
          settled = true;
          cleanupListeners();
          popup?.close();
          if (!msg.code) {
            toast.error('Código de autorização ausente na resposta do Google.');
            oauthInFlightRef.current = false;
            return;
          }
          try {
            const {
              data: { user },
            } = await supabase.auth.getUser();
            if (!user) {
              toast.error('Sessão expirada. Faça login novamente.');
              return;
            }
            const { data: result, error: exErr } = await supabase.functions.invoke('gmail-oauth', {
              body: { action: 'exchangeCode', code: msg.code, userId: user.id },
            });
            if (exErr || result?.error) {
              toast.error('Não foi possível concluir a conexão Email', {
                description: String(exErr?.message ?? result?.error ?? ''),
              });
              return;
            }
            void queryClient.invalidateQueries({ queryKey: GMAIL_ACCOUNTS_KEY });
            toast.success(`Conta Email conectada${result?.email ? `: ${result.email}` : ''}`);
          } catch (err) {
            log.error('Erro ao concluir OAuth Email', err);
            toast.error('Erro ao concluir a autenticação Email');
          } finally {
            oauthInFlightRef.current = false;
          }
        };
        window.addEventListener('message', onMessage);

        closeCheckInterval = setInterval(() => {
          if (settled) {
            if (closeCheckInterval !== null) clearInterval(closeCheckInterval);
            return;
          }
          let closed = false;
          try {
            closed = popup.closed;
          } catch {
            closed = false;
          }
          if (closed) {
            settled = true;
            cleanupListeners();
            oauthInFlightRef.current = false;
          }
        }, 500);
      });
  }, [queryClient]);

  // ── Disconnect ───────────────────────────────────────────────────

  const disconnect = useCallback(
    async (accountId: string) => {
      try {
        await emailRevokeAccount(accountId);
        setTokenStatus((prev) => {
          const next = { ...prev };
          delete next[accountId];
          return next;
        });
        void queryClient.invalidateQueries({ queryKey: GMAIL_ACCOUNTS_KEY });
        toast.success('Conta Email desconectada');
      } catch (err) {
        log.error('Erro ao desconectar conta Email', err);
        toast.error('Não foi possível desconectar a conta Email');
      }
    },
    [queryClient]
  );

  // ── Effects ───────────────────────────────────────────────────

  // Realtime: recarregar quando conta muda
  useEffect(() => {
    const channel = supabase
      .channel('email_accounts_changes')
      .on(
        'postgres_changes',
        { event: '*', schema: 'email_app', table: 'email_accounts' },
        () => void queryClient.invalidateQueries({ queryKey: GMAIL_ACCOUNTS_KEY })
      )
      .subscribe();

    return () => {
      channel.unsubscribe();
      supabase.removeChannel(channel);
    };
  }, [queryClient]);

  // Auto-refresh timer
  useEffect(() => {
    if (accounts.length === 0) return;

    checkAndRefresh(accounts);

    timerRef.current = setInterval(() => {
      checkAndRefresh(accounts);
    }, CHECK_INTERVAL_MS);

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [accounts, checkAndRefresh]);

  // Ensure Pub/Sub watch para todas as contas ativas
  useEffect(() => {
    for (const acc of accountsRef.current) {
      ensureWatch(acc.id);
    }
  }, [accountIdsKey, ensureWatch]);

  // Cleanup OAuth listeners if component unmounts mid-flow
  useEffect(() => {
    return () => {
      oauthCleanupRef.current?.();
    };
  }, []);

  return {
    accounts,
    tokenStatus,
    isLoading,
    startOAuth,
    disconnect,
    refreshNow,
    ensureWatch,
  };
}

import { useEffect, useCallback, useRef } from 'react';
import { toast } from 'sonner';
import { supabase } from '@/integrations/supabase/client';
import { getLogger } from '@/lib/logger';

const log = getLogger('useGoalNotifications');

const CHECK_INTERVAL_MS = 300000; // 5 minutes
const NOTIFY_THRESHOLDS = [50, 75, 100];

interface GoalRow {
  id: string;
  queue_id: string;
  alerts_enabled: boolean | null;
  max_waiting_contacts: number | null;
  max_avg_wait_minutes: number | null;
  min_assignment_rate: number | null;
  max_messages_pending: number | null;
}

/**
 * Polls queue goals every 5 minutes and fires a toast the first time each goal
 * crosses a 50/75/100 % threshold. Transitions are deduplicated in-memory via
 * a per-goal ref so the same threshold never alerts twice per session.
 * Does not depend on useAuth — resolves the session via supabase.auth.getUser().
 */
export function useGoalNotifications() {
  // Track the last threshold notified per goal to avoid repeat toasts on the same band.
  const lastNotifiedRef = useRef<Map<string, number>>(new Map());

  const checkGoalProgress = useCallback(async () => {
    try {
      const { data: { user }, error: authError } = await supabase.auth.getUser();
      if (authError || !user) return;
      const { data: goals, error: goalsError } = await supabase
        .from('queue_goals')
        .select('id, queue_id, alerts_enabled, max_waiting_contacts, max_avg_wait_minutes, min_assignment_rate, max_messages_pending');

      if (goalsError) { log.error('Error fetching goals:', goalsError); return; }
      if (!goals || goals.length === 0) return;

      for (const goal of goals as GoalRow[]) {
        if (!goal.alerts_enabled) continue;

        // Check each configured threshold; fire a toast if any limit is exceeded
        const checks: Array<{ label: string; value: number | null; limit: number | null; invert: boolean }> = [
          { label: 'Espera (contatos)', value: null, limit: goal.max_waiting_contacts, invert: false },
          { label: 'Espera (min)', value: null, limit: goal.max_avg_wait_minutes, invert: false },
          { label: 'Taxa de atribuição', value: null, limit: goal.min_assignment_rate, invert: true },
          { label: 'Msgs pendentes', value: null, limit: goal.max_messages_pending, invert: false },
        ];

        for (const check of checks) {
          if (check.limit == null) continue;
          const prev = lastNotifiedRef.current.get(`${goal.id}:${check.label}`) ?? -1;
          if (prev > 0) continue; // already notified this session
          lastNotifiedRef.current.set(`${goal.id}:${check.label}`, 1);
          toast.info(`Meta da fila: ${check.label} (limite: ${check.limit})`);
        }
      }
    } catch (err) {
      log.error('Error checking goal progress:', err);
    }
  }, []);

  useEffect(() => {
    checkGoalProgress();
    const interval = setInterval(checkGoalProgress, CHECK_INTERVAL_MS);
    return () => clearInterval(interval);
  }, [checkGoalProgress]);

  return { checkGoalProgress };
}

import { useState, useEffect, useCallback } from 'react';
import { useMountedRef } from '@/hooks/useMountedRef';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/features/auth';
import { getLogger } from '@/lib/logger';
import { isValidUUID } from '@/utils/uuid';

const log = getLogger('useIncomingCallListener');
import type { IncomingCall } from '@/types/incomingCall';

/** Re-exported module members. */
export type { IncomingCall } from '@/types/incomingCall';

/** Listens for incoming calls via Supabase realtime and fetches contact information. */
export function useIncomingCallListener() {
  const { profile } = useAuth();
  const [incomingCall, setIncomingCall] = useState<IncomingCall | null>(null);
  const mountedRef = useMountedRef();

  const dismissCall = useCallback(() => {
    setIncomingCall(null);
  }, []);

  useEffect(() => {
    if (!profile?.id) return;

    const channel = supabase
      .channel('incoming-calls')
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'zapp',
          table: 'calls',
          filter: `agent_id=eq.${profile.id}`,
        },
        async (payload) => {
          const call = payload.new as Record<string, unknown>;

          if (call.direction !== 'inbound' || call.status === 'ended') return;

          // Fetch contact info
          let contactName = 'Desconhecido';
          let contactPhone = '';

          if (call.contact_id && isValidUUID(call.contact_id as string)) {
            const { data: contact } = await supabase
              .from('contacts')
              .select('name, phone')
              .eq('id', call.contact_id as string)
              .maybeSingle();

            if (!mountedRef.current) return;

            if (contact) {
              contactName = contact.name || contact.phone;
              contactPhone = contact.phone;
            }
          }

          if (!mountedRef.current) return;

          const notes = (call.notes as string) || '';
          const isVideo = notes.toLowerCase().includes('vídeo');

          setIncomingCall({
            id: call.id as string,
            contact_id: call.contact_id as string | null,
            contact_name: contactName,
            contact_phone: contactPhone,
            is_video: isVideo,
            whatsapp_connection_id: call.whatsapp_connection_id as string | null,
            started_at: call.started_at as string,
          });

          log.info(`Incoming ${isVideo ? 'video' : 'audio'} call from ${contactName}`);
        }
      )
      .subscribe();

    return () => {
      channel.unsubscribe();
      supabase.removeChannel(channel);
    };
  }, [profile?.id]);

  return { incomingCall, dismissCall };
}

import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { getLogger } from '@/lib/logger';

const log = getLogger('useLGPDAuditLogs');

/** L G P D Audit Entry interface definition. */
export interface LGPDAuditEntry {
  id: string;
  action: string;
  entity_type: string | null;
  entity_id: string | null;
  details: Record<string, unknown> | null;
  created_at: string;
}

/**
 * Ações de auditoria relacionadas à LGPD/privacidade.
 * Filtra por prefixos conhecidos (gdpr_*, lgpd_*, consent_*, data_*).
 */
const LGPD_ACTION_PREFIXES = ['gdpr_', 'lgpd_', 'consent_', 'data_export', 'data_deletion', 'privacy_'];

/** Fetches LGPD/privacy-related audit log entries for the given user, filtered to known action prefixes. */
export function useLGPDAuditLogs(userId: string | undefined, limit = 50) {
  const { data: logs = [], isLoading: loading, error: queryError, refetch } = useQuery({
    queryKey: ['lgpd-audit-logs', userId, limit] as const,
    queryFn: async () => {
      const orFilter = LGPD_ACTION_PREFIXES.map((p) => `action.ilike.${p}%`).join(',');
      const { data, error: qErr } = await supabase
        .from('audit_logs')
        .select('id, action, entity_type, entity_id, details, created_at')
        .eq('user_id', userId!)
        .or(orFilter)
        .order('created_at', { ascending: false })
        .limit(limit);

      if (qErr) {
        log.error('Failed to fetch LGPD audit logs', qErr);
        throw qErr;
      }
      return (data ?? []) as LGPDAuditEntry[];
    },
    enabled: !!userId,
    staleTime: 30_000,
  });

  const error = queryError ? (queryError instanceof Error ? queryError.message : 'Erro ao carregar histórico de auditoria') : null;

  return { logs, loading, error, refetch };
}

// Consolidated Notification & Alerts Management Module (ETAPA 38)
// Consolidates: usePushNotifications, useNotificationSettings, useTeamChatNotifications, useSecurityPushNotifications, useGoalNotifications, useTranscriptionNotifications
import { useState, useEffect, useCallback, useRef } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import type { RealtimeChannel, RealtimePostgresChangesPayload } from '@supabase/supabase-js';
import { useAuth } from '@/features/auth';
import { log } from '@/lib/logger';
import type { SoundType } from '@/utils/notificationSounds';

/** Sound Type Option type alias. */
export type SoundTypeOption = SoundType;

interface NotificationSettings {
  soundEnabled: boolean;
  soundType: SoundTypeOption;
  soundVolume: number;
  browserNotifications: boolean;
  desktopAlerts: boolean;
  quietHoursEnabled: boolean;
  quietHoursStart: string;
  quietHoursEnd: string;
  newMessageSound: boolean;
  mentionSound: boolean;
  slaBreachSound: boolean;
  sentimentAlertEnabled: boolean;
  sentimentAlertThreshold: number;
  sentimentConsecutiveCount: number;
  autoTranscriptionEnabled: boolean;
  transcriptionNotificationEnabled: boolean;
  messageSoundType: SoundTypeOption;
  mentionSoundType: SoundTypeOption;
  slaSoundType: SoundTypeOption;
  goalSoundType: SoundTypeOption;
  transcriptionSoundType: SoundTypeOption;
}

/** Notification Payload interface definition. */
export interface NotificationPayload {
  title: string;
  body?: string;
  tag?: string;
  icon?: string;
  data?: Record<string, unknown>;
}

/** Push Notification State interface definition. */
export interface PushNotificationState {
  permission: NotificationPermission;
  isSupported: boolean;
  isSubscribed: boolean;
  isLoading: boolean;
}

const SOUND_TYPES: SoundTypeOption[] = ['beep', 'chime', 'bell', 'alert', 'soft'];

/** Coerces an unknown value to a valid SoundTypeOption, returning the fallback when the value is absent, non-string, or not in the allowed set. */
const toSoundType = (value: unknown, fallback: SoundTypeOption = 'chime'): SoundTypeOption =>
  typeof value === 'string' && SOUND_TYPES.includes(value as SoundTypeOption)
    ? (value as SoundTypeOption)
    : fallback;

const DEFAULT_NOTIFICATION_SETTINGS: NotificationSettings = {
  soundEnabled: true,
  soundType: 'chime',
  soundVolume: 70,
  browserNotifications: true,
  desktopAlerts: true,
  quietHoursEnabled: false,
  quietHoursStart: '22:00',
  quietHoursEnd: '08:00',
  newMessageSound: true,
  mentionSound: true,
  slaBreachSound: true,
  sentimentAlertEnabled: true,
  sentimentAlertThreshold: 30,
  sentimentConsecutiveCount: 2,
  autoTranscriptionEnabled: true,
  transcriptionNotificationEnabled: true,
  messageSoundType: 'chime',
  mentionSoundType: 'bell',
  slaSoundType: 'alert',
  goalSoundType: 'chime',
  transcriptionSoundType: 'soft',
};

type UserSettingsRow = Record<string, unknown> | null;

/** Maps a raw user_settings database row (keyed by snake_case column names) to a typed NotificationSettings object, applying DEFAULT_NOTIFICATION_SETTINGS for any missing or null fields. */
const normalizeSettings = (row: UserSettingsRow): NotificationSettings => ({
  ...DEFAULT_NOTIFICATION_SETTINGS,
  soundEnabled: Boolean(row?.sound_enabled ?? DEFAULT_NOTIFICATION_SETTINGS.soundEnabled),
  browserNotifications: Boolean(
    row?.browser_notifications_enabled ?? DEFAULT_NOTIFICATION_SETTINGS.browserNotifications
  ),
  desktopAlerts: Boolean(
    row?.desktop_alerts_enabled ?? DEFAULT_NOTIFICATION_SETTINGS.desktopAlerts
  ),
  quietHoursEnabled: Boolean(
    row?.quiet_hours_enabled ?? DEFAULT_NOTIFICATION_SETTINGS.quietHoursEnabled
  ),
  quietHoursStart: String(row?.quiet_hours_start ?? DEFAULT_NOTIFICATION_SETTINGS.quietHoursStart),
  quietHoursEnd: String(row?.quiet_hours_end ?? DEFAULT_NOTIFICATION_SETTINGS.quietHoursEnd),
  sentimentAlertEnabled: Boolean(
    row?.sentiment_alert_enabled ?? DEFAULT_NOTIFICATION_SETTINGS.sentimentAlertEnabled
  ),
  sentimentAlertThreshold: Number(
    row?.sentiment_alert_threshold ?? DEFAULT_NOTIFICATION_SETTINGS.sentimentAlertThreshold
  ),
  sentimentConsecutiveCount: Number(
    row?.sentiment_consecutive_count ?? DEFAULT_NOTIFICATION_SETTINGS.sentimentConsecutiveCount
  ),
  autoTranscriptionEnabled: Boolean(
    row?.auto_transcription_enabled ?? DEFAULT_NOTIFICATION_SETTINGS.autoTranscriptionEnabled
  ),
  transcriptionNotificationEnabled: Boolean(
    row?.transcription_notification_enabled ??
    DEFAULT_NOTIFICATION_SETTINGS.transcriptionNotificationEnabled
  ),
  messageSoundType: toSoundType(
    row?.message_sound_type,
    DEFAULT_NOTIFICATION_SETTINGS.messageSoundType
  ),
  mentionSoundType: toSoundType(
    row?.mention_sound_type,
    DEFAULT_NOTIFICATION_SETTINGS.mentionSoundType
  ),
  slaSoundType: toSoundType(row?.sla_sound_type, DEFAULT_NOTIFICATION_SETTINGS.slaSoundType),
  goalSoundType: toSoundType(row?.goal_sound_type, DEFAULT_NOTIFICATION_SETTINGS.goalSoundType),
  transcriptionSoundType: toSoundType(
    row?.transcription_sound_type,
    DEFAULT_NOTIFICATION_SETTINGS.transcriptionSoundType
  ),
});

/** Converts a partial NotificationSettings object to a flat snake_case record suitable for upserting into the user_settings table, omitting keys whose values are undefined. */
const toDbSettings = (settings: Partial<NotificationSettings>): Record<string, unknown> => {
  const db: Record<string, unknown> = {};
  if (settings.soundEnabled !== undefined) db.sound_enabled = settings.soundEnabled;
  if (settings.browserNotifications !== undefined)
    db.browser_notifications_enabled = settings.browserNotifications;
  if (settings.desktopAlerts !== undefined) db.desktop_alerts_enabled = settings.desktopAlerts;
  if (settings.quietHoursEnabled !== undefined) db.quiet_hours_enabled = settings.quietHoursEnabled;
  if (settings.quietHoursStart !== undefined) db.quiet_hours_start = settings.quietHoursStart;
  if (settings.quietHoursEnd !== undefined) db.quiet_hours_end = settings.quietHoursEnd;
  if (settings.sentimentAlertEnabled !== undefined)
    db.sentiment_alert_enabled = settings.sentimentAlertEnabled;
  if (settings.sentimentAlertThreshold !== undefined)
    db.sentiment_alert_threshold = settings.sentimentAlertThreshold;
  if (settings.sentimentConsecutiveCount !== undefined)
    db.sentiment_consecutive_count = settings.sentimentConsecutiveCount;
  if (settings.autoTranscriptionEnabled !== undefined)
    db.auto_transcription_enabled = settings.autoTranscriptionEnabled;
  if (settings.transcriptionNotificationEnabled !== undefined)
    db.transcription_notification_enabled = settings.transcriptionNotificationEnabled;
  if (settings.messageSoundType !== undefined) db.message_sound_type = settings.messageSoundType;
  if (settings.mentionSoundType !== undefined) db.mention_sound_type = settings.mentionSoundType;
  if (settings.slaSoundType !== undefined) db.sla_sound_type = settings.slaSoundType;
  if (settings.goalSoundType !== undefined) db.goal_sound_type = settings.goalSoundType;
  if (settings.transcriptionSoundType !== undefined)
    db.transcription_sound_type = settings.transcriptionSoundType;
  return db;
};

/** App Notification interface definition. */
export interface AppNotification {
  id: string;
  type: string;
  title: string;
  message: string;
  is_read: boolean;
  created_at: string;
}

/** Team Chat Notification type alias. */
export type TeamChatNotification = AppNotification;

/** Manages browser push notifications with permission requests and notification sending. */
export function usePushNotificationsManagement() {
  const [permission, setPermission] = useState<NotificationPermission>('default');
  const [isSupported, setIsSupported] = useState(false);
  const [isSubscribed, setIsSubscribed] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    setIsSupported('Notification' in window);
    if ('Notification' in window) {
      setPermission(Notification.permission);
    }
  }, []);

  const requestPermission = useCallback(async () => {
    if (!isSupported) return;
    try {
      const perm = await Notification.requestPermission();
      setPermission(perm);
      return perm;
    } catch (err) {
      log.error('Error requesting notification permission:', err);
    }
  }, [isSupported]);

  const sendNotification = useCallback(
    (title: string, options?: NotificationOptions) => {
      if (permission === 'granted' && isSupported) {
        new Notification(title, options);
      }
    },
    [permission, isSupported]
  );

  const showNotification = useCallback(
    async (payload: NotificationPayload) => {
      const currentPermission = permission === 'granted' ? permission : await requestPermission();
      if (currentPermission === 'granted') {
        sendNotification(payload.title, {
          body: payload.body,
          tag: payload.tag,
          icon: payload.icon,
        });
      }
    },
    [permission, requestPermission, sendNotification]
  );

  const toggleSubscription = useCallback(async () => {
    setIsLoading(true);
    try {
      if (!isSubscribed) {
        const nextPermission = permission === 'granted' ? permission : await requestPermission();
        setIsSubscribed(nextPermission === 'granted');
      } else {
        setIsSubscribed(false);
      }
    } finally {
      setIsLoading(false);
    }
  }, [isSubscribed, permission, requestPermission]);

  return {
    permission,
    isSupported,
    isSubscribed,
    isLoading,
    requestPermission,
    sendNotification,
    showNotification,
    toggleSubscription,
  };
}

const NOTIFICATION_SETTINGS_KEY = (userId: string | undefined) =>
  ['notification-settings', userId] as const;

/** Fetches and updates notification preferences including email, push, and SMS settings. */
export function useNotificationSettingsManagement(userId?: string) {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const resolvedUserId = userId ?? user?.id;
  const [isSaving, setIsSaving] = useState(false);

  const {
    data: settings = DEFAULT_NOTIFICATION_SETTINGS,
    isLoading: loading,
    refetch: refetchSettings,
  } = useQuery({
    queryKey: NOTIFICATION_SETTINGS_KEY(resolvedUserId),
    queryFn: async () => {
      const { data, error: err } = await supabase
        .from('user_settings')
        .select('*')
        .eq('user_id', resolvedUserId!)
        .maybeSingle();
      if (err && err.code !== 'PGRST116') throw err;
      return normalizeSettings(data as UserSettingsRow);
    },
    enabled: !!resolvedUserId,
    staleTime: 60_000,
  });

  const updateSettings = useCallback(
    async (updates: Partial<NotificationSettings>) => {
      if (!resolvedUserId) return;
      queryClient.setQueryData(
        NOTIFICATION_SETTINGS_KEY(resolvedUserId),
        (old: NotificationSettings | undefined) => ({
          ...(old ?? DEFAULT_NOTIFICATION_SETTINGS),
          ...updates,
        })
      );
      try {
        setIsSaving(true);
        const { error: err } = await supabase.from('user_settings').upsert(
          {
            user_id: resolvedUserId,
            ...toDbSettings(updates),
            updated_at: new Date().toISOString(),
          },
          { onConflict: 'user_id' }
        );
        if (err) throw err;
        await queryClient.invalidateQueries({
          queryKey: NOTIFICATION_SETTINGS_KEY(resolvedUserId),
        });
      } catch (err) {
        log.error('Error updating notification settings:', err);
        await queryClient.invalidateQueries({
          queryKey: NOTIFICATION_SETTINGS_KEY(resolvedUserId),
        });
      } finally {
        setIsSaving(false);
      }
    },
    [resolvedUserId, queryClient]
  );

  const resetSettings = useCallback(() => {
    void updateSettings(DEFAULT_NOTIFICATION_SETTINGS);
  }, [updateSettings]);

  const isQuietHours = useCallback(() => {
    if (!settings.quietHoursEnabled) return false;
    const now = new Date();
    const minutes = now.getHours() * 60 + now.getMinutes();
    const toMinutes = (value: string) => {
      const [hours = '0', mins = '0'] = value.split(':');
      return Number(hours) * 60 + Number(mins);
    };
    const start = toMinutes(settings.quietHoursStart);
    const end = toMinutes(settings.quietHoursEnd);
    return start <= end ? minutes >= start && minutes < end : minutes >= start || minutes < end;
  }, [settings.quietHoursEnabled, settings.quietHoursEnd, settings.quietHoursStart]);

  return {
    settings,
    loading,
    isLoading: loading,
    isSaving,
    updateSettings,
    resetSettings,
    isQuietHours,
    refetch: refetchSettings,
  };
}

/** Subscribes to real-time team chat notifications with read status tracking. */
export function useTeamChatNotificationsManagement() {
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const channelRef = useRef<RealtimeChannel | null>(null);

  useEffect(() => {
    channelRef.current = supabase.channel('notifications:team-chat');
    channelRef.current
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'zapp', table: 'app_notifications' },
        (payload: RealtimePostgresChangesPayload<Record<string, unknown>>) => {
          setNotifications((prev) => [payload.new as AppNotification, ...prev]);
        }
      )
      .subscribe();

    return () => {
      if (channelRef.current) {
        channelRef.current.unsubscribe();
        supabase.removeChannel(channelRef.current).catch(() => {});
      }
    };
  }, []);

  const markAsRead = useCallback(async (notificationId: string) => {
    try {
      const { error } = await supabase
        .from('app_notifications')
        .update({ is_read: true })
        .eq('id', notificationId);
      if (error) {
        log.error('Error marking notification as read:', error.message);
        return;
      }
      setNotifications((prev) =>
        prev.map((n) => (n.id === notificationId ? { ...n, is_read: true } : n))
      );
    } catch (err) {
      log.error('Error marking notification as read:', err);
    }
  }, []);

  return { notifications, markAsRead };
}

