import { useCallback } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/features/auth';
import { log } from '@/lib/logger';

const ONBOARDING_KEY = 'onboarding_completed';

function readLocal(userId: string): boolean {
  try {
    return localStorage.getItem(`${ONBOARDING_KEY}_${userId}`) === 'true';
  } catch {
    return false;
  }
}
function writeLocal(userId: string, value: boolean) {
  try {
    if (value) localStorage.setItem(`${ONBOARDING_KEY}_${userId}`, 'true');
    else localStorage.removeItem(`${ONBOARDING_KEY}_${userId}`);
  } catch {
    /* storage unavailable */
  }
}

/** Tracks user onboarding completion status with localStorage and database persistence. */
export function useOnboarding() {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const queryKey = ['onboarding-status', user?.id] as const;

  const { data: hasCompletedOnboarding = null, isLoading: loading } = useQuery({
    queryKey,
    queryFn: async (): Promise<boolean> => {
      // Fast path: localStorage already confirmed completion
      if (user && readLocal(user.id)) return true;
      try {
        const { data } = await supabase
          .from('user_settings')
          .select('onboarding_completed')
          .eq('user_id', user!.id)
          .maybeSingle();
        if (data?.onboarding_completed) {
          writeLocal(user!.id, true);
          return true;
        }
        return false;
      } catch (error) {
        log.error('Error checking onboarding status:', error);
        return true; // Default to completed on error
      }
    },
    enabled: !!user,
    staleTime: 60_000,
  });

  const completeOnboarding = useCallback(async () => {
    if (!user) return;
    try {
      const { error } = await supabase
        .from('user_settings')
        .update({ onboarding_completed: true })
        .eq('user_id', user.id);
      if (error) log.error('[useOnboarding] completeOnboarding DB update failed:', error.message);
      writeLocal(user.id, true);
    } catch (err) {
      log.error('[useOnboarding] completeOnboarding unexpected error:', err);
    }
    queryClient.setQueryData(['onboarding-status', user?.id], true);
  }, [user, queryClient]);

  const resetOnboarding = useCallback(async () => {
    if (!user) return;
    try {
      await supabase
        .from('user_settings')
        .update({ onboarding_completed: false })
        .eq('user_id', user.id);
      writeLocal(user.id, false);
    } catch {
      /* ignore */
    }
    queryClient.setQueryData(['onboarding-status', user?.id], false);
  }, [user, queryClient]);

  return {
    hasCompletedOnboarding,
    loading,
    completeOnboarding,
    resetOnboarding,
  };
}

import { useState, useCallback, useEffect } from 'react';
import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/hooks/useAuth';
import { getLogger } from '@/lib/logger';

const log = getLogger('useOnboardingChecklist');
const dismissedKey = (userId: string | undefined) =>
  userId ? `onboarding_dismissed_${userId}` : 'onboarding_dismissed';

interface OnboardingStatus {
  profile: boolean;
  whatsapp: boolean;
  settings: boolean;
  templates: boolean;
  [key: string]: boolean;
}

const DEFAULT_STATUS: OnboardingStatus = { profile: false, whatsapp: false, settings: false, templates: false };

/** Hook: use Onboarding Checklist. */
export function useOnboardingChecklist() {
  const { user } = useAuth();
  const [isDismissed, setIsDismissed] = useState(false);

  useEffect(() => {
    try {
      setIsDismissed(localStorage.getItem(dismissedKey(user?.id)) === 'true');
    } catch {
      // ignore
    }
  }, [user?.id]);

  const { data: status = DEFAULT_STATUS, isLoading, refetch } = useQuery({
    queryKey: ['onboarding-status', user?.id],
    queryFn: async (): Promise<OnboardingStatus> => {
      const [profileRes, whatsappRes, settingsRes, templatesRes] = await Promise.all([
        supabase.from('profiles').select('name, avatar_url').eq('user_id', user!.id).maybeSingle(),
        supabase.from('whatsapp_connections').select('id').eq('created_by', user!.id).limit(1),
        supabase.from('user_settings').select('id').eq('user_id', user!.id).maybeSingle(),
        supabase.from('message_templates').select('id').eq('created_by', user!.id).limit(1),
      ]);
      if (profileRes.error) log.error('Error checking onboarding status:', profileRes.error);
      return {
        profile: !!(profileRes.data?.name && profileRes.data.name.length > 2),
        whatsapp: (whatsappRes.data?.length ?? 0) > 0,
        settings: !!settingsRes.data,
        templates: (templatesRes.data?.length ?? 0) > 0,
      };
    },
    enabled: !!user,
    staleTime: 60_000,
  });

  const checkStatus = useCallback(() => { void refetch(); }, [refetch]);

  const dismiss = useCallback(() => {
    try {
      localStorage.setItem(dismissedKey(user?.id), 'true');
    } catch {
      // ignore
    }
    setIsDismissed(true);
  }, [user?.id]);

  const completedCount = Object.values(status).filter(Boolean).length;
  const totalCount = Object.keys(status).length;
  const progress = totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0;

  return { status, isLoading, isDismissed, dismiss, checkStatus, progress };
}

// Full-API personal stickers hook.
// Backed by public.stickers (schema.stickers) + Storage bucket `stickers`.
// Notes:
// - `stickers` table has columns: id, name, image_url, category, is_favorite, use_count, owner_id (from schema list).
// - Storage bucket is `stickers` (public).
import { useCallback, useRef, useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { resolvePublicStorageUrl } from '@/lib/mediaUrl';
import { useAuth } from '@/features/auth';
import { toast } from '@/hooks/use-toast';
import { log } from '@/lib/logger';
import type { StickerItem } from '@/features/inbox/components/stickers/StickerTypes';

const STICKERS_TABLE = 'stickers';
const STICKERS_BUCKET = 'stickers';
const MAX_FILE_SIZE = 512 * 1024; // 512KB (bucket limit)

interface UsePersonalStickersResult {
  profile: ReturnType<typeof useAuth>['profile'];
  stickers: StickerItem[];
  isLoading: boolean;
  uploading: boolean;
  fileInputRef: React.RefObject<HTMLInputElement>;
  handleUpload: (files: FileList | null) => Promise<void>;
  toggleFavorite: { mutate: (sticker: StickerItem) => void };
  deleteSticker: { mutate: (sticker: StickerItem) => void };
  incrementUseCount: (sticker: StickerItem) => void;
  refetch: () => void;
}

/** Hook: use Personal Stickers (full API). */
export function usePersonalStickers(): UsePersonalStickersResult {
  const { profile } = useAuth();
  const ownerId = profile?.id;
  const queryClient = useQueryClient();
  const fileInputRef = useRef<HTMLInputElement>(null!);
  const [uploading, setUploading] = useState(false);

  const QUERY_KEY = ['personal-stickers', ownerId] as const;

  const {
    data: stickers = [],
    isLoading,
    refetch,
  } = useQuery({
    queryKey: QUERY_KEY,
    queryFn: async (): Promise<StickerItem[]> => {
      if (!ownerId) return [];
      const { data, error } = await supabase
        .from(STICKERS_TABLE as never)
        .select('id, name, image_url, category, is_favorite, use_count, owner_id')
        .eq('owner_id', ownerId)
        .order('is_favorite', { ascending: false })
        .order('use_count', { ascending: false });
      if (error) throw error;
      return (data ?? []) as unknown as StickerItem[]; // ignore-audit — STICKERS_TABLE cast as never makes TS infer data as never[]; bridge recovers usable StickerItem type
    },
    enabled: !!ownerId,
    staleTime: 30_000,
  });

  const handleUpload = useCallback(
    async (files: FileList | null) => {
      if (!files || files.length === 0 || !ownerId) return;
      setUploading(true);
      try {
        for (const file of Array.from(files)) {
          if (!file.type.startsWith('image/')) {
            toast({
              title: 'Arquivo inválido',
              description: `${file.name} não é uma imagem.`,
              variant: 'destructive',
            });
            continue;
          }
          if (file.size > MAX_FILE_SIZE) {
            toast({
              title: 'Arquivo muito grande',
              description: `${file.name} excede 512KB.`,
              variant: 'destructive',
            });
            continue;
          }
          const ext = file.name.split('.').pop() || 'png';
          const path = `${ownerId}/${crypto.randomUUID()}.${ext}`;
          const { error: upErr } = await supabase.storage
            .from(STICKERS_BUCKET)
            .upload(path, file, { contentType: file.type, upsert: false });
          if (upErr) throw upErr;

          const { error: insErr } = await supabase.from(STICKERS_TABLE as never).insert({
            owner_id: ownerId,
            name: file.name.replace(/\.[^.]+$/, ''),
            image_url: resolvePublicStorageUrl(STICKERS_BUCKET, path),
            category: 'pessoal',
            is_favorite: false,
            use_count: 0,
          } as never);
          if (insErr) throw insErr;
        }
        toast({ title: 'Figurinhas adicionadas', description: 'Upload concluído.' });
        void queryClient.invalidateQueries({ queryKey: QUERY_KEY });
      } catch (err) {
        log.error('Sticker upload failed:', err);
        toast({
          title: 'Erro no upload',
          description: err instanceof Error ? err.message : 'Falha ao enviar figurinhas.',
          variant: 'destructive',
        });
      } finally {
        setUploading(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    },
    [ownerId, queryClient, QUERY_KEY]
  );

  const toggleFavoriteMutation = useMutation({
    mutationFn: async (sticker: StickerItem) => {
      const { error } = await supabase
        .from(STICKERS_TABLE as never)
        .update({ is_favorite: !sticker.is_favorite } as never)
        .eq('id', sticker.id);
      if (error) throw error;
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey: QUERY_KEY }),
    onError: (err) => {
      log.error('Toggle favorite failed:', err);
      toast({
        title: 'Erro',
        description: 'Não foi possível atualizar favorito.',
        variant: 'destructive',
      });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (sticker: StickerItem) => {
      // Best-effort remove from Storage (path derived from URL last segments).
      try {
        const url = new URL(sticker.image_url);
        const marker = `/${STICKERS_BUCKET}/`;
        const idx = url.pathname.indexOf(marker);
        if (idx >= 0) {
          const path = decodeURIComponent(url.pathname.slice(idx + marker.length));
          await supabase.storage.from(STICKERS_BUCKET).remove([path]);
        }
      } catch (err) {
        log.warn('Storage cleanup skipped:', err);
      }
      const { error } = await supabase
        .from(STICKERS_TABLE as never)
        .delete()
        .eq('id', sticker.id);
      if (error) throw error;
    },
    onSuccess: () => {
      toast({ title: 'Figurinha removida' });
      void queryClient.invalidateQueries({ queryKey: QUERY_KEY });
    },
    onError: (err) => {
      log.error('Delete sticker failed:', err);
      toast({ title: 'Erro', description: 'Não foi possível remover.', variant: 'destructive' });
    },
  });

  const incrementUseCount = useCallback((sticker: StickerItem) => {
    void supabase
      .from(STICKERS_TABLE as never)
      .update({ use_count: (sticker.use_count ?? 0) + 1 } as never)
      .eq('id', sticker.id)
      .then(({ error }) => {
        if (error) log.warn('Increment use_count failed:', error);
      });
  }, []);

  return {
    profile,
    stickers,
    isLoading,
    uploading,
    fileInputRef,
    handleUpload,
    toggleFavorite: { mutate: (s) => toggleFavoriteMutation.mutate(s) },
    deleteSticker: { mutate: (s) => deleteMutation.mutate(s) },
    incrementUseCount,
    refetch: () => void refetch(),
  };
}

import { useCallback } from 'react';
import { usePushNotificationsManagement } from '@/hooks/useNotificationManagement';
import type { PushNotificationState, NotificationPayload } from '@/hooks/useNotificationManagement';

/** Re-exported module members. */
export type { PushNotificationState, NotificationPayload };

/** Hook: use Push Notifications. */
export function usePushNotifications() {
  const mgmt = usePushNotificationsManagement();

  const subscribe = useCallback(async () => {
    if (!mgmt.isSubscribed) {
      await mgmt.toggleSubscription();
    }
  }, [mgmt.isSubscribed, mgmt.toggleSubscription]);

  const unsubscribe = useCallback(async () => {
    if (mgmt.isSubscribed) {
      await mgmt.toggleSubscription();
    }
  }, [mgmt.isSubscribed, mgmt.toggleSubscription]);

  return {
    ...mgmt,
    subscribe,
    unsubscribe,
  };
}

import { useState, useEffect } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { dbFrom } from '@/integrations/datasource/db';
import { getLogger } from '@/lib/logger';

const log = getLogger('useQueueDetails');

export interface QueueDetailsData {
  id: string;
  name: string;
  description: string | null;
  color: string;
  max_wait_time_minutes: number;
  created_at: string;
}

export interface QueueMember {
  id: string;
  profile_id: string;
  profile: { name: string; avatar_url: string | null; is_active: boolean };
}

export interface QueueContact {
  id: string;
  name: string;
  phone: string;
  avatar_url: string | null;
  assigned_to: string | null;
  created_at: string;
  assigned_agent?: { name: string; avatar_url: string | null };
  messages_count: number;
  last_message_at: string | null;
}

export interface QueueMetrics {
  totalContacts: number;
  assignedContacts: number;
  waitingContacts: number;
  avgResponseTime: string;
  resolvedToday: number;
}

export function useQueueDetails(id: string | undefined) {
  const [queue, setQueue] = useState<QueueDetailsData | null>(null);
  const [members, setMembers] = useState<QueueMember[]>([]);
  const [contacts, setContacts] = useState<QueueContact[]>([]);
  const [metrics, setMetrics] = useState<QueueMetrics | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!id) return;
    let cancelled = false;
    void fetchAll(() => cancelled);
    return () => {
      cancelled = true;
    };
  }, [id]);

  async function fetchAll(isCancelled: () => boolean) {
    if (!id) return;
    try {
      setLoading(true);

      const { data: queueData, error: queueError } = await supabase
        .from('queues')
        .select('*')
        .eq('id', id)
        .maybeSingle();
      if (queueError) throw queueError;
      if (isCancelled()) return;
      setQueue(queueData as QueueDetailsData | null);

      const { data: membersData } = await supabase
        .from('queue_members')
        .select('id, profile_id, profile:profiles(name, avatar_url, is_active)')
        .eq('queue_id', id);
      if (isCancelled()) return;
      setMembers((membersData ?? []) as unknown as QueueMember[]);

      const contactsRes = await dbFrom('contacts')
        .select('id, name, phone, avatar_url, assigned_to, created_at')
        .eq('queue_id', id)
        .order('created_at', { ascending: false })
        .limit(50);
      const contactsData = (contactsRes.data ?? []) as Array<{
        id: string;
        name: string;
        phone: string;
        avatar_url: string | null;
        assigned_to: string | null;
        created_at: string;
      }>;

      let contactsWithDetails: QueueContact[] = [];

      if (contactsData.length > 0) {
        const contactIds = contactsData.map((c) => c.id);
        const assignedToIds = Array.from(
          new Set(contactsData.map((c) => c.assigned_to).filter(Boolean) as string[])
        );

        const [messagesResult, agentResult] = await Promise.all([
          dbFrom('evolution_messages')
            .select('contact_id, created_at')
            .in('contact_id', contactIds)
            .order('created_at', { ascending: false }),
          assignedToIds.length > 0
            ? supabase.from('profiles').select('id, name, avatar_url').in('id', assignedToIds)
            : Promise.resolve({ data: [] as { id: string; name: string; avatar_url: string | null }[] }),
        ]);

        if (isCancelled()) return;

        const countMap = new Map<string, number>();
        const lastMessageMap = new Map<string, string>();
        const messages = (messagesResult.data ?? []) as Array<{ contact_id: string; created_at: string }>;
        messages.forEach((msg) => {
          countMap.set(msg.contact_id, (countMap.get(msg.contact_id) || 0) + 1);
          if (!lastMessageMap.has(msg.contact_id)) {
            lastMessageMap.set(msg.contact_id, msg.created_at);
          }
        });

        const agents = (agentResult.data ?? []) as Array<{ id: string; name: string; avatar_url: string | null }>;
        const agentMap = new Map(
          agents.map((p) => [p.id, { name: p.name, avatar_url: p.avatar_url }])
        );


        contactsWithDetails = contactsData.map((contact) => ({
          ...contact,
          messages_count: countMap.get(contact.id) || 0,
          last_message_at: lastMessageMap.get(contact.id) || null,
          assigned_agent: contact.assigned_to ? agentMap.get(contact.assigned_to) ?? undefined : undefined,
        }));
      }

      if (isCancelled()) return;
      setContacts(contactsWithDetails);

      const totalContacts = contactsWithDetails.length;
      const assignedContacts = contactsWithDetails.filter((c) => c.assigned_to).length;
      setMetrics({
        totalContacts,
        assignedContacts,
        waitingContacts: totalContacts - assignedContacts,
        avgResponseTime: '~3 min',
        resolvedToday: Math.floor(assignedContacts * 0.7),
      });
    } catch (error) {
      log.error('Error fetching queue data:', error);
    } finally {
      if (!isCancelled()) setLoading(false);
    }
  }

  return { queue, members, contacts, metrics, loading };
}

