  company: string | null;
  job_title: string | null;
  assigned_to: string | null;
  queue_id: string | null;
  created_at: string;
  updated_at: string;
  whatsapp_connection_id: string | null;
  contact_type: string;
  group_category: string | null;
  ai_sentiment: string | null;
}

/**
 * Interface alinhada ao schema real da view zapp.messages
 * (que faz SELECT sobre evo.evolution_messages).
 *
 * Campos anteriores como `sender` (string), `external_id`, `agent_id`,
 * `transcription` são mantidos via computed columns da view.
 */
interface Message {
  id: string;
  contact_id: string | null;
  content: string | null;
  message_type: string;
  media_url: string | null;
  is_read: boolean;
  status: string | null;
  created_at: string;
  updated_at: string | null;
  // Campos computados pela view zapp.messages
  sender: string | null; // 'agent' | 'contact' — from_me→sender
  is_from_me: boolean;
  direction: string | null; // 'incoming' | 'outgoing'
  external_id: string | null; // alias de message_id da tabela evo
  whatsapp_connection_id: string | null;
  is_deleted: boolean;
  deleted_at: string | null;
  // Campos opcionais
  caption: string | null;
  instance_name: string | null;
  push_name: string | null;
  remote_jid: string | null;
  conversation_id: string | null;
  agent_id: string | null;
  transcription: string | null;
  transcription_status: string | null;
  media_type: string | null;
}

interface Conversation {
  contact: Contact;
  messages: Message[];
  lastMessage: Message | null;
}

function sortByRecency(convs: Conversation[]): Conversation[] {
  return [...convs].sort((a, b) => {
    const aTime = a.lastMessage?.created_at ?? a.contact.updated_at;
    const bTime = b.lastMessage?.created_at ?? b.contact.updated_at;
    return bTime.localeCompare(aTime);
  });
}

/**
 * @deprecated Use `useRealtimeMessages` de `src/features/inbox/hooks/useRealtimeMessages.ts`
 * que tem suporte a multi-instância, paginação, N+1 fix e realtime robusto.
 * Este hook legado serve apenas como compatibilidade de API.
 *
 * Loads and subscribes to contacts and messages in realtime.
 * Initial fetch propagates errors from both Supabase queries.
 * Realtime channel uses a per-mount unique name to avoid collision on StrictMode remounts.
 * New messages for unknown contacts trigger a full refetch rather than silently dropping them.
 */
export function useRealtimeMessages() {
  const [loading, setLoading] = useState(true);
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [error, setError] = useState<Error | null>(null);
  const isMountedRef = useRef(true);
  const channelId = useRef(`realtime-messages-${Math.random().toString(36).slice(2)}`);

  const fetchData = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [
        { data: contactsRaw, error: contactsError },
        { data: messages, error: messagesError },
      ] = await Promise.all([
        supabase
          .from('evolution_contacts')
          .select('*')
          .order('updated_at', { ascending: false })
          .limit(500),
        supabase
          .from('evolution_messages')
          .select('*')
          .order('created_at', { ascending: false })
          .limit(100),
      ]);
      if (contactsError) throw contactsError;
      if (messagesError) throw messagesError;

      const contactList: Contact[] = (contactsRaw as unknown as Contact[] | null) ?? [];
      const messageList: Message[] = messages ?? [];

      const contactMap = new Map<string, Contact>();
      contactList.forEach((c) => contactMap.set(c.id, c));

      // Buscar contatos referenciados por mensagens mas não no set inicial
      const missingIds = [
        ...new Set(
          messageList
            .map((m) => m.contact_id)
            .filter((id): id is string => Boolean(id) && !contactMap.has(id!))
        ),
      ];

      if (missingIds.length > 0) {
        const { data: extraRaw } = await supabase
          .from('evolution_contacts')
          .select('*')
          .in('id', missingIds);
        ((extraRaw as unknown as Contact[] | null) ?? []).forEach((c: Contact) =>
          contactMap.set(c.id, c)
        );
      }

      if (!isMountedRef.current) return;

      const convMap = new Map<string, Conversation>();

      contactList.forEach((c) => {
        convMap.set(c.id, { contact: c, messages: [], lastMessage: null });
      });

      contactMap.forEach((c, id) => {
        if (!convMap.has(id)) {
          convMap.set(id, { contact: c, messages: [], lastMessage: null });
        }
      });

      messageList.forEach((m) => {
        // Filtro explícito: ignorar tombstones (mensagens apagadas sem contact_id)
        if (!m.contact_id) {
          log.debug('[useRealtimeMessages] ignorando mensagem sem contact_id (tombstone)', {
            id: m.id,
          });
          return;
        }
        const conv = convMap.get(m.contact_id);
        if (conv) {
          conv.messages.push(m);
          if (!conv.lastMessage || m.created_at > conv.lastMessage.created_at) {
            conv.lastMessage = m;
          }
        } else {
          // Contato não encontrado no mapa — já tratado acima via missingIds
          log.debug('[useRealtimeMessages] mensagem com contact_id desconhecido no mapa', {
            id: m.id,
            contact_id: m.contact_id,
          });
        }
      });

      if (isMountedRef.current) {
        setConversations(sortByRecency(Array.from(convMap.values())));
      }
    } catch (err) {
      if (isMountedRef.current) {
        setError(err instanceof Error ? err : new Error('Failed to load messages'));
        setConversations([]);
      }
    } finally {
      if (isMountedRef.current) setLoading(false);
    }
  }, []);

  useEffect(() => {
    isMountedRef.current = true;
    fetchData();
    return () => {
      isMountedRef.current = false;
    };
  }, [fetchData]);

  useEffect(() => {
    const channel = supabase
      .channel(channelId.current)
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'evo', table: 'evolution_messages' },
        (payload) => {
          if (!isMountedRef.current) return;
          const newMsg = payload.new as Message;
          // Ignorar tombstones sem contato vinculado
          if (!newMsg.contact_id) {
            log.debug(
              '[realtime] INSERT ignorado — contact_id nulo (tombstone ou msg sem contato)'
            );
            return;
          }
          setConversations((prev) => {
            const idx = prev.findIndex((c) => c.contact.id === newMsg.contact_id);
            if (idx === -1) {
              // Contact not yet loaded — fall back to full refresh
              void fetchData();
              return prev;
            }
            const conv = prev[idx];
            const lastMessage =
              !conv.lastMessage || newMsg.created_at > conv.lastMessage.created_at
                ? newMsg
                : conv.lastMessage;
            const updated = [...prev];
            updated[idx] = { ...conv, messages: [...conv.messages, newMsg], lastMessage };
            return sortByRecency(updated);
          });
        }
      )
      .on(
        'postgres_changes',
        { event: 'UPDATE', schema: 'evo', table: 'evolution_messages' },
        (payload) => {
          if (!isMountedRef.current) return;
          const updMsg = payload.new as Message;
          if (!updMsg.contact_id) return; // ignorar tombstones em updates
          setConversations((prev) =>
            prev.map((conv) => {
              if (conv.contact.id !== updMsg.contact_id) return conv;
              const messages = conv.messages.map((m) => (m.id === updMsg.id ? updMsg : m));
              const lastMessage = messages.reduce<Message | null>(
                (latest, m) => (!latest || m.created_at > latest.created_at ? m : latest),
                null
              );
              return { ...conv, messages, lastMessage };
            })
          );
        }
      );

    channel.subscribe((status) => {
      if (status !== 'SUBSCRIBED') {
        log.warn('[useRealtimeMessages] channel subscription status:', status);
      }
    });

    return () => {
      channel.unsubscribe();
      supabase.removeChannel(channel).catch(() => {});
    };
  }, [fetchData]);

  /**
   * @deprecated STUB LEGADO — O envio real de mensagens deve usar
   * `sendMessageToContact` de `features/inbox/hooks/realtime/messageSender.ts`
   * que: (1) insere na view zapp.messages com campos corretos, (2) chama a
   * Evolution API para dispatch real no WhatsApp, (3) atualiza status e retry.
   *
   * Este stub NÃO faz INSERT para evitar falhas silenciosas causadas pelo
   * schema default 'zapp' (que resolve para a VIEW sem suporte a todos os campos
   * de evo.evolution_messages, em particular instance_name NOT NULL).
   */
  const sendMessage = useCallback(async (contactId: string, content: string, _agentId?: string) => {
    log.warn(
      '[sendMessage legacy stub] Use sendMessageToContact de features/inbox/hooks/realtime/messageSender.ts para envio real via Evolution API.',
      { contactId, contentLength: content.length }
    );
    // Intencionalmente não faz nada — previne INSERT no schema errado.
  }, []);

  const refetch = useCallback(() => fetchData(), [fetchData]);

  return { loading, conversations, error, sendMessage, refetch };
}

/**
 * useRetryAndErrorPrevention.ts (v1.0)
 * Unified retry and error prevention hooks consolidating:
 * - useRetryOperation: Simple exponential backoff for operations
 * - useSilentErrorPrevention suite: Comprehensive error prevention wrappers
 * - useRetryStrategy suite: Advanced retry with metrics tracking
 *
 * Backward compatibility maintained through re-exports of all legacy hook names.
 */
import { useState, useCallback, useRef, useEffect, type DependencyList } from 'react';
import { useToast } from '@/hooks/use-toast';
import { getLogger } from '@/lib/logger';
import {
  safeCallback,
  handlePromiseRejection,
  fireAndForget,
  retryWithBackoff,
  withErrorRecovery,
  type AnyFn,
  type ErrorSuppression,
  suppressError,
} from '@/lib/silentErrorPrevention';
import {
  RetryConfig,
  RetryExecutor,
  RETRY_CONFIG_TRANSIENT,
  RETRY_CONFIG_API,
  RETRY_CONFIG_DATABASE,
  RETRY_CONFIG_ASYNC,
  retryMetricsTracker,
  type RetryMetrics,
  type RetryPolicy,
} from '@/lib/retryStrategyAudit';

const log = getLogger('useRetryAndErrorPrevention');

// ──────────────────────────────────────────────────────────────────────────
// SECTION 1: Simple Operation Retry (useRetryOperation consolidation)
// ──────────────────────────────────────────────────────────────────────────

const FATAL_CODES = [
  'PGRST116', // not found
  '23505', // unique violation
  '23514', // check constraint
  'CONTACT_NOT_FOUND',
  'CONFLICT',
  '401',
  '403',
];

interface RetryState {
  loading: boolean;
  attempt: number;
  lastError: string | null;
}

/**
 * Simple retry hook for operations with exponential backoff (multiplier 3)
 * and state management. Used for contact save/update operations.
 */
/** Retries async operations with exponential backoff, state tracking, and automatic fatal error detection. */
export function useRetryOperation(maxAttempts = 3, baseDelayMs = 500) {
  const { toast } = useToast();
  const [state, setState] = useState<RetryState>({ loading: false, attempt: 0, lastError: null });

  const withRetry = useCallback(
    async <T>(fn: () => Promise<T>, label = 'Salvar'): Promise<T> => {
      let lastErr: Error | null = null;

      for (let attempt = 1; attempt <= maxAttempts; attempt++) {
        setState({ loading: true, attempt, lastError: null });
        try {
          const result = await fn();
          setState({ loading: false, attempt: 0, lastError: null });
          return result;
        } catch (err: unknown) {
          const error = err instanceof Error ? err : new Error(String(err));
          lastErr = error;
          if (FATAL_CODES.some((c) => error.message.includes(c))) {
            setState({ loading: false, attempt: 0, lastError: error.message });
            throw error;
          }
          if (attempt === maxAttempts) break;
          const delay = Math.min(
            baseDelayMs * Math.pow(3, attempt - 1) * (1 + Math.random() * 0.2),
            30000
          );
          setState({
            loading: true,
            attempt,
            lastError: `Tentando novamente (${attempt}/${maxAttempts})...`,
          });
          if (attempt > 1)
            toast({
              title: `⏳ ${label}`,
              description: `Tentativa ${attempt + 1}/${maxAttempts}...`,
              duration: delay,
            });
          await new Promise((r) => setTimeout(r, delay));
        }
      }
      setState({ loading: false, attempt: 0, lastError: lastErr?.message ?? 'Erro' });
      throw lastErr;
    },
    [maxAttempts, baseDelayMs, toast]
  );

  const reset = useCallback(() => setState({ loading: false, attempt: 0, lastError: null }), []);

  return { ...state, withRetry, reset };
}

// ──────────────────────────────────────────────────────────────────────────
// SECTION 2: Silent Error Prevention Wrappers (useSilentErrorPrevention consolidation)
// ──────────────────────────────────────────────────────────────────────────

/**
 * Hook for wrapping event handlers with automatic error logging.
 */
/** Wraps event handlers with automatic error logging and exception handling. */
export function useSafeEventHandler<K extends keyof HTMLElementEventMap>(
  handler: (ev: HTMLElementEventMap[K]) => void,
  eventName: K
) {
  return useCallback(
    (event: HTMLElementEventMap[K]) => {
      try {
        handler(event);
      } catch (error) {
        log.error(`Event handler error (${String(eventName)}):`, error);
      }
    },
    [handler, eventName]
  );
}

/**
 * Hook for safely handling async operations with error recovery.
 */
/** Safely executes async operations with error recovery, fallback values, and optional throwing. */
export function useSafeAsync<T>(
  fn: () => Promise<T>,
  options?: {
    operation?: string;
    fallback?: T;
    shouldThrow?: boolean;
    dependencies?: DependencyList;
  }
) {
  const { operation = 'Unknown', fallback, shouldThrow = false, dependencies = [] } = options || {};

  const fnRef = useRef(fn);
  fnRef.current = fn;
  const executeAsync = useCallback(
    async () =>
      safeCallback(() => withErrorRecovery(fnRef.current, { operation, fallback, shouldThrow }), {
        name: operation,
      })(),
    [operation, fallback, shouldThrow]
  );

  return executeAsync;
}

/**
 * Hook for automatically retrying failed operations with exponential backoff (multiplier 2).
 */
/** Retries async operations with configurable exponential backoff strategy. */
export function useSafeRetry<T>(
  fn: () => Promise<T>,
  options?: {
    operation?: string;
    maxAttempts?: number;
    delayMs?: number;
    backoffMultiplier?: number;
    dependencies?: DependencyList;
  }
) {
  const {
    operation = 'Unknown',
    maxAttempts = 3,
    delayMs = 100,
    backoffMultiplier = 2,
    dependencies = [],
  } = options || {};

  const fnRef = useRef(fn);
  fnRef.current = fn;
  const executeRetry = useCallback(
    async () =>
      retryWithBackoff(fnRef.current, {
        operation,
        maxAttempts,
        delayMs,
        backoffMultiplier,
      }),
    [operation, maxAttempts, delayMs, backoffMultiplier]
  );

  return executeRetry;
}

/**
 * Hook for managing fire-and-forget promises (e.g., analytics tracking).
 */
/** Executes promises without waiting for resolution, ideal for analytics and tracking. */
export function useFireAndForget() {
  return useCallback((promise: Promise<unknown>, operation: string = 'Unknown operation') => {
    fireAndForget(promise, { operation });
  }, []);
}

/**
 * Hook for wrapping callbacks with automatic error logging.
 */
/** Wraps callbacks with automatic error logging, fallback returns, and optional throwing. */
export function useSafeCallback<T extends AnyFn>(
  callback: T,
  options?: {
    name?: string;
    fallbackReturn?: ReturnType<T>;
    shouldThrow?: boolean;
    dependencies?: DependencyList;
  }
) {
  const {
    name = 'Anonymous',
    fallbackReturn,
    shouldThrow = false,
    dependencies = [],
  } = options || {};

  const callbackRef = useRef(callback);
  callbackRef.current = callback;
  return useCallback(
    (...args: Parameters<T>): ReturnType<T> => {
      return (safeCallback(callbackRef.current, { name, fallbackReturn, shouldThrow }) as T)(
        ...args
      );
    },
    [name, fallbackReturn, shouldThrow]
  ) as unknown as T;
}

/**
 * Hook for handling promise rejections with custom error handling.
 */
/** Handles promise rejections with custom error handling and optional throwing. */
export function useSafePromise<T>(
  promise: Promise<T>,
  options?: {
    operation?: string;
    onReject?: (error: Error) => void;
    shouldThrow?: boolean;
    dependencies?: DependencyList;
  }
) {
  const { operation = 'Unknown', onReject, shouldThrow = false, dependencies = [] } = options || {};

  const onRejectRef = useRef(onReject);
  onRejectRef.current = onReject;
  useEffect(() => {
    let cancelled = false;
    handlePromiseRejection(promise, {
      operation,
      onReject: cancelled ? undefined : onRejectRef.current,
      shouldThrow,
    }).catch(() => {
      // Already logged
    });
    return () => {
      cancelled = true;
    };
  }, [operation, promise, shouldThrow]);
}

/**
 * Hook to mark intentional error suppression in cleanup code.
 */
/** Marks intentional error suppression for cleanup and recovery code paths. */
export function useSuppressError(reason: string, suppression: ErrorSuppression = 'intentional') {
  return useCallback(() => {
    suppressError(reason, suppression);
  }, [reason, suppression]);
}

/**
 * Hook for comprehensive error handling in async effects.
 */
/** Executes async effects with error recovery, cleanup, and fallback handling. */
export function useAsyncEffect<T>(
  effect: () => Promise<T | void>,
  options?: {
    operation?: string;
    cleanup?: () => void;
    fallback?: () => void;
    dependencies?: DependencyList;
  }
) {
  const { operation = 'Async effect', cleanup, fallback, dependencies } = options ?? {};

  const effectRef = useRef(effect);
  effectRef.current = effect;
  const cleanupRef = useRef(cleanup);
  cleanupRef.current = cleanup;
  const fallbackRef = useRef(fallback);
  fallbackRef.current = fallback;
  const abortRef = useRef<AbortController | null>(null);

  useEffect(() => {
    abortRef.current = new AbortController();

    (async () => {
      try {
        await withErrorRecovery(effectRef.current, {
          operation,
          shouldThrow: false,
        });
      } catch (error) {
        log.error(`Async effect failed: ${operation}`, error);
        fallbackRef.current?.();
      }
    })();

    return () => {
      abortRef.current?.abort();
      cleanupRef.current?.();
    };
  }, [operation]);
}

/**
 * Hook to track errors in a component lifecycle.
 */
/** Tracks errors throughout component lifecycle with history and retrieval capabilities. */
export function useErrorTracking() {
  const errorsRef = useRef<Array<{ error: Error; timestamp: number }>>([]);

  const trackError = useCallback((error: Error | unknown) => {
    const err = error instanceof Error ? error : new Error(String(error));
    errorsRef.current.push({
      error: err,
      timestamp: Date.now(),
    });

    if (errorsRef.current.length > 50) {
      errorsRef.current = errorsRef.current.slice(-50);
    }

    log.warn('Error tracked in component', { error: err.message });
  }, []);

  const getErrors = useCallback(() => {
    return [...errorsRef.current];
  }, []);

  const clearErrors = useCallback(() => {
    errorsRef.current = [];
  }, []);

  return { trackError, getErrors, clearErrors };
}

// ──────────────────────────────────────────────────────────────────────────
// SECTION 3: Advanced Retry Strategy with Metrics (useRetryStrategy consolidation)
// ──────────────────────────────────────────────────────────────────────────

/**
 * Hook for executing async operations with automatic retry strategy
 */
/** Executes async operations with automatic retry strategy and metrics tracking. */
export function useRetryableAsync<T>(
  fn: () => Promise<T>,
  options?: {
    operationName?: string;
    config?: RetryConfig;
    shouldRetry?: RetryPolicy;
    dependencies?: DependencyList;
  }
) {
  const {
    operationName = 'Unknown',
    config = RETRY_CONFIG_TRANSIENT,
    shouldRetry,
    dependencies = [],
  } = options || {};

  const executorRef = useRef<RetryExecutor>(new RetryExecutor(config, operationName));

  useEffect(() => {
    retryMetricsTracker.registerExecutor(operationName, executorRef.current);
  }, [operationName]);

  const fnRef = useRef(fn);
  fnRef.current = fn;
  const shouldRetryRef = useRef(shouldRetry);
  shouldRetryRef.current = shouldRetry;
  const execute = useCallback(async () => {
    try {
      return await executorRef.current.execute(fnRef.current, shouldRetryRef.current);
    } catch (error) {
      log.error(`Retry exhausted for ${operationName}:`, error);
      throw error;
    }
  }, [operationName]);

  const getMetrics = useCallback(() => {
    return executorRef.current.getMetrics();
  }, []);

  return { execute, getMetrics };
}

/**
 * Hook for tracking retry metrics in a component
 */
/** Tracks retry metrics for a specific operation with periodic updates. */
export function useRetryMetrics(operationName?: string) {
  const [metrics, setMetrics] = useState<RetryMetrics | undefined>(undefined);

  const updateMetrics = useCallback(() => {
    if (operationName) {
      const m = retryMetricsTracker.getMetrics(operationName);
      setMetrics(m);
    }
  }, [operationName]);

  useEffect(() => {
    const interval = setInterval(updateMetrics, 5000);
    return () => clearInterval(interval);
  }, [updateMetrics]);

  return metrics;
}

/**
 * Hook for monitoring all retry operations
 */
/** Monitors all retry operations globally with health status tracking. */
export function useGlobalRetryMetrics() {
  const [allMetrics, setAllMetrics] = useState<Map<string, RetryMetrics>>(new Map());
  const [healthStatus, setHealthStatus] = useState<{ healthy: string[]; degraded: string[] }>({
    healthy: [],
    degraded: [],
  });

  useEffect(() => {
    const interval = setInterval(() => {
      setAllMetrics(new Map(retryMetricsTracker.getAllMetrics()));
      setHealthStatus(retryMetricsTracker.getHealthStatus());
    }, 10000);

    return () => clearInterval(interval);
  }, []);

  return { allMetrics, healthStatus };
}

/**
 * Hook for retry strategy with exponential backoff
 */
/** Provides retry configuration with exponential backoff strategy. */
export function useExponentialBackoff(config?: Partial<RetryConfig>) {
  const defaultConfig: RetryConfig = {
    ...RETRY_CONFIG_TRANSIENT,
    ...config,
  };

  return defaultConfig;
}

/**
 * Hook for API retry strategy (higher attempt count)
 */
/** Provides retry configuration optimized for API calls with higher attempt count. */
export function useApiRetryStrategy(config?: Partial<RetryConfig>) {
  const defaultConfig: RetryConfig = {
    ...RETRY_CONFIG_API,
    ...config,
  };

  return defaultConfig;
}

/**
 * Hook for database retry strategy (lower delay)
 */
/** Provides retry configuration optimized for database operations with lower delays. */
export function useDatabaseRetryStrategy(config?: Partial<RetryConfig>) {
  const defaultConfig: RetryConfig = {
    ...RETRY_CONFIG_DATABASE,
    ...config,
  };

  return defaultConfig;
}

/**
 * Hook for long-running async retry strategy
 */
/** Provides retry configuration optimized for long-running async operations. */
export function useAsyncRetryStrategy(config?: Partial<RetryConfig>) {
  const defaultConfig: RetryConfig = {
    ...RETRY_CONFIG_ASYNC,
    ...config,
  };

  return defaultConfig;
}

// ──────────────────────────────────────────────────────────────────────────
// BACKWARD COMPATIBILITY RE-EXPORTS
// ──────────────────────────────────────────────────────────────────────────

/** Default export. */
export default {
  useRetryOperation,
  useSafeEventHandler,
  useSafeAsync,
  useSafeRetry,
  useFireAndForget,
  useSafeCallback,
  useSafePromise,
  useSuppressError,
  useAsyncEffect,
  useErrorTracking,
  useRetryableAsync,
  useRetryMetrics,
  useGlobalRetryMetrics,
  useExponentialBackoff,
  useApiRetryStrategy,
  useDatabaseRetryStrategy,
  useAsyncRetryStrategy,
};

import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { queryKeys } from '@/services/api/queryKeys';
import { format, subDays } from 'date-fns';

export interface SentimentData {
  date: string;
  positive: number;
  neutral: number;
  negative: number;
  avg_score: number;
  alerts_count: number;
}

export function useRealSentimentData(days: number): SentimentData[] | null {
  const { data } = useQuery<SentimentData[] | null>({
    queryKey: queryKeys.adminOps.sentimentTrend(days),
    staleTime: 5 * 60 * 1000,
    queryFn: async () => {
      const startDate = subDays(new Date(), days);
      const { data: analyses, error } = await supabase
        .from('conversation_analyses')
        .select('created_at, sentiment, sentiment_score')
        .gte('created_at', startDate.toISOString())
        .order('created_at');
      if (error) throw error;
      if (!analyses || analyses.length === 0) return null;

      const dayMap = new Map<
        string,
        { positive: number; negative: number; neutral: number; total: number; alerts: number }
      >();

      analyses.forEach((a) => {
        const dateKey = format(new Date(a.created_at), 'yyyy-MM-dd');
        if (!dayMap.has(dateKey))
          dayMap.set(dateKey, { positive: 0, negative: 0, neutral: 0, total: 0, alerts: 0 });
        const entry = dayMap.get(dateKey)!;
        entry.total++;
        if (a.sentiment === 'positivo') entry.positive++;
        else if (a.sentiment === 'negativo') {
          entry.negative++;
          entry.alerts++;
        } else entry.neutral++;
      });

      return Array.from(dayMap.entries()).map(([date, counts]) => ({
        date,
        positive: Math.round((counts.positive / counts.total) * 100),
        neutral: Math.round((counts.neutral / counts.total) * 100),
        negative: Math.round((counts.negative / counts.total) * 100),
        avg_score: (counts.positive - counts.negative) / counts.total,
        alerts_count: counts.alerts,
      }));
    },
  });

  return data ?? null;
}

