import { useMemo, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { AlertTriangle, Clock, ShieldAlert, TrendingUp } from 'lucide-react';
import { useTransfersPaginated } from '@/features/admin/hooks/monitoring/useTransfersPaginated';

const PAGE_SIZE = 25;

/** Ops Transfers Tab. */
export function OpsTransfersTab() {
  const [page, setPage] = useState(0);
  const [status, setStatus] = useState<string | null>(null);
  const [priority, setPriority] = useState<number | null>(null);

  const { data, isLoading, isError, error } = useTransfersPaginated({
    status,
    priority,
    page,
    pageSize: PAGE_SIZE,
  });

  const rows = data?.rows ?? [];
  const total = data?.total ?? 0;
  const deniedReason = data?.deniedReason ?? null;

  const totals = useMemo(
    () =>
      rows.reduce(
        (acc, r) => ({
          pending: acc.pending + (r.status === 'pending' ? 1 : 0),
          escalated: acc.escalated + (r.status === 'escalated' ? 1 : 0),
          expired: acc.expired + (r.sla_deadline && new Date(r.sla_deadline) < new Date() ? 1 : 0),
        }),
        { pending: 0, escalated: 0, expired: 0 }
      ),
    [rows]
  );

  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));

  if (isLoading) return <Skeleton className="h-96" />;

  return (
    <div className="space-y-4">
      {deniedReason && (
        <Alert variant="destructive">
          <ShieldAlert className="h-4 w-4" />
          <AlertTitle>Acesso restrito</AlertTitle>
          <AlertDescription>{deniedReason}</AlertDescription>
        </Alert>
      )}

      {isError && !deniedReason && (
        <Alert variant="destructive">
          <AlertTriangle className="h-4 w-4" />
          <AlertTitle>Falha ao carregar transferências</AlertTitle>
          <AlertDescription>
            {error instanceof Error ? error.message : 'Erro desconhecido.'}
          </AlertDescription>
        </Alert>
      )}

      <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">Pendentes (página)</CardTitle>
            <Clock className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{totals.pending}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">Escalados (página)</CardTitle>
            <TrendingUp className="h-4 w-4 text-warning-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{totals.escalated}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">SLA Estourado (página)</CardTitle>
            <AlertTriangle className="h-4 w-4 text-destructive" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-destructive">{totals.expired}</div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
          <CardTitle>Transferências ({total})</CardTitle>
          <div className="flex flex-wrap items-center gap-2">
            <Select
              value={status ?? 'all'}
              onValueChange={(v) => {
                setPage(0);
                setStatus(v === 'all' ? null : v);
              }}
            >
              <SelectTrigger className="w-40">
                <SelectValue placeholder="Status" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todos os status</SelectItem>
                <SelectItem value="pending">Pendente</SelectItem>
                <SelectItem value="accepted">Aceita</SelectItem>
                <SelectItem value="completed">Concluída</SelectItem>
                <SelectItem value="rejected">Recusada</SelectItem>
                <SelectItem value="expired">Expirada</SelectItem>
              </SelectContent>
            </Select>
            <Select
              value={priority?.toString() ?? 'all'}
              onValueChange={(v) => {
                setPage(0);
                setPriority(v === 'all' ? null : Number(v));
              }}
            >
              <SelectTrigger className="w-40">
                <SelectValue placeholder="Prioridade" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todas as prioridades</SelectItem>
                <SelectItem value="4">P1 — Urgente</SelectItem>
                <SelectItem value="3">P2 — Alta</SelectItem>
                <SelectItem value="2">P3 — Normal</SelectItem>
                <SelectItem value="1">P4 — Baixa</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b text-left text-muted-foreground">
                  <th scope="col" className="py-2 pr-4">
                    Contato
                  </th>
                  <th scope="col" className="py-2 pr-4">
                    Origem → Destino
                  </th>
                  <th scope="col" className="py-2 pr-4">
                    Status
                  </th>
                  <th scope="col" className="py-2 pr-4">
                    Prioridade
                  </th>
                  <th scope="col" className="py-2 pr-4">
                    SLA
                  </th>
                  <th scope="col" className="py-2 pr-4">
                    Criada
                  </th>
                </tr>
              </thead>
              <tbody>
                {rows.length === 0 ? (
                  <tr>
                    <td colSpan={6} className="py-6 text-center text-muted-foreground">
                      {deniedReason
                        ? 'Sem acesso a esta lista.'
                        : 'Nenhuma transferência encontrada.'}
                    </td>
                  </tr>
                ) : (
                  rows.map((r) => {
                    const expired = r.sla_deadline && new Date(r.sla_deadline) < new Date();
                    return (
                      <tr key={r.id} className="border-b hover:bg-muted/40">
                        <td className="py-2 pr-4">{r.contact_name ?? r.remote_jid ?? '—'}</td>
                        <td className="py-2 pr-4">
                          {r.source_instance ?? '—'} → {r.target_instance ?? '—'}
                        </td>
                        <td className="py-2 pr-4">
                          <Badge variant="secondary">{r.status}</Badge>
                        </td>
                        <td className="py-2 pr-4">{r.priority ?? '—'}</td>
                        <td className="py-2 pr-4">
                          {expired ? (
                            <Badge variant="destructive">Estourado</Badge>
                          ) : (
                            (r.sla_deadline ?? '—')
                          )}
                        </td>
                        <td className="py-2 pr-4">
                          {new Date(r.created_at).toLocaleString('pt-BR')}
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>

          <div className="mt-4 flex items-center justify-between text-sm text-muted-foreground">
            <span>
              Página {page + 1} de {totalPages}
            </span>
            <div className="flex gap-2">
              <Button
                variant="outline"
                size="sm"
                disabled={page === 0}
                onClick={() => setPage((p) => Math.max(0, p - 1))}
              >
                Anterior
              </Button>
              <Button
                variant="outline"
                size="sm"
                disabled={page + 1 >= totalPages}
                onClick={() => setPage((p) => p + 1)}
              >
                Próxima
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

/**
 * Contacts Repository
 *
 * Data access layer for contacts.
 * Encapsulates all Supabase queries for contacts.
 * Can be easily mocked for testing.
 */

import { supabase } from '@/integrations/supabase/client';
import { sanitizePostgrestFilter } from '@/lib/sanitize';
import { applyRetry, createService } from '@/services/api/genericService';
import type { ListResponse, QueryParams } from '@/services/api/types';

// Temporary type - replace with actual type from your schema
export interface Contact {
  id: string;
  name: string;
  email?: string;
  phone?: string;
  deleted_at?: string | null;
  deleted_by?: string | null;
  deleted_reason?: string | null;
  created_at?: string;
  updated_at?: string;
  [key: string]: any;
}

/**
 * Base contacts service created from generic factory
 */
const baseContactsService = createService<Contact>('contacts', {
  orderBy: 'created_at',
  orderDirection: 'desc',
});

/**
 * Contacts repository with specialized methods
 * Combines generic operations with domain-specific queries
 */
export const contactsRepository = {
  /**
   * List all contacts
   */
  list: async (filters?: Partial<Contact> & QueryParams): Promise<ListResponse<Contact>> => {
    return baseContactsService.list(filters);
  },

  /**
   * Get a single contact by ID
   */
  getById: async (id: string): Promise<Contact | null> => {
    return baseContactsService.get(id);
  },

  /**
   * Search contacts by name or email
   */
  search: async (query: string): Promise<Contact[]> => {
    const safe = sanitizePostgrestFilter(query);
    const { data: byName, error: nameError } = await supabase
      .from('contacts')
      .select('*')
      .ilike('name', `%${safe}%`)
      .limit(20);

    if (nameError && nameError.code !== 'PGRST116') throw nameError;

    const { data: byEmail, error: emailError } = await supabase
      .from('contacts')
      .select('*')
      .ilike('email', `%${safe}%`)
      .limit(20);

    if (emailError && emailError.code !== 'PGRST116') throw emailError;

    // Combine and deduplicate results
    const combined = [...(byName || []), ...(byEmail || [])];
    const uniqueIds = new Set();
    return combined.filter((contact) => {
      if (uniqueIds.has(contact.id)) return false;
      uniqueIds.add(contact.id);
      return true;
    });
  },

  /**
   * Create a new contact
   */
  create: async (contact: Partial<Contact>): Promise<Contact> => {
    return baseContactsService.create(contact);
  },

  /**
   * Create multiple contacts
   */
  createBulk: async (contacts: Partial<Contact>[]): Promise<Contact[]> => {
    return baseContactsService.createBulk(contacts);
  },

  /**
   * Update a contact
   */
  update: async (id: string, updates: Partial<Contact>): Promise<Contact> => {
    return baseContactsService.update(id, updates);
  },

  /**
   * Delete a contact
   */
  delete: async (id: string): Promise<{ id: string }> => {
    return baseContactsService.delete(id);
  },

  /**
   * Delete multiple contacts
   */
  deleteMany: async (ids: string[]): Promise<number> => {
    return baseContactsService.deleteMany({ id: ids });
  },

  /**
   * Archive a contact (soft delete via deleted_at)
   */
  archive: async (id: string): Promise<Contact> => {
    return baseContactsService.update(id, {
      deleted_at: new Date().toISOString(),
      deleted_reason: 'archived',
    });
  },

  /**
   * Restore an archived contact (clear deleted_at)
   */
  restore: async (id: string): Promise<Contact> => {
    return baseContactsService.update(id, {
      deleted_at: null,
      deleted_by: null,
      deleted_reason: null,
    });
  },

  /**
   * Get contacts by archive status (active = not deleted, archived = soft-deleted)
   */
  getByStatus: async (
    status: 'active' | 'archived',
    params?: Partial<QueryParams>
  ): Promise<ListResponse<Contact>> => {
    // contacts table has no status column; filter via deleted_at.
    // genericService.list() treats the string 'null' as IS NULL and 'not_null' as IS NOT NULL.
    if (status === 'archived') {
      return baseContactsService.list({ deleted_at: 'not_null' as unknown as string, ...params });
    }
    return baseContactsService.list({ deleted_at: 'null' as unknown as string, ...params });
  },

  /**
   * Bulk archive contacts (soft delete)
   */
  updateStatusBulk: async (ids: string[], status: 'active' | 'archived'): Promise<Contact[]> => {
    const patch =
      status === 'archived'
        ? { deleted_at: new Date().toISOString(), deleted_reason: 'archived' }
        : { deleted_at: null, deleted_by: null, deleted_reason: null };
    return baseContactsService.updateMany({ id: ids }, patch as Partial<Contact>);
  },

  /**
   * Get total contacts count
   */
  count: async (): Promise<number> => {
    return baseContactsService.count();
  },

  /**
   * Check if contact exists
   */
  exists: async (id: string): Promise<boolean> => {
    return baseContactsService.exists(id);
  },

  /**
   * Subscribe to contact changes
   */
  subscribe: (callback: (contact: Contact) => void) => {
    return baseContactsService.subscribe(callback);
  },

  /**
   * Advanced search with retry
   */
  searchWithRetry: async (query: string, maxRetries = 3): Promise<Contact[]> => {
    return applyRetry(() => contactsRepository.search(query), maxRetries);
  },
};

/**
 * Messages Repository
 *
 * Data access layer for messages and conversations.
 */

import { supabase } from '@/integrations/supabase/client';
import { createService } from '@/services/api/genericService';
import type { QueryParams } from '@/services/api/types';

/** Message interface — matches evo.evolution_messages physical columns. */
export interface Message {
  id: string;
  instance_name?: string;
  remote_jid?: string;
  message_id?: string;
  from_me?: boolean;
  push_name?: string;
  message_type?: string;
  content?: string;
  media_url?: string;
  status?: string;
  timestamp?: string;
  raw?: Record<string, any>;
  created_at: string;
  updated_at: string;
  contact_id?: string;
  conversation_id?: string;
  direction?: 'inbound' | 'outbound';
  is_read?: boolean;
  is_starred?: boolean;
  is_important?: boolean;
  follow_up_at?: string | null;
  follow_up_done?: boolean;
  category?: string | null;
  sentiment?: string | null;
  tags?: string[];
  notes?: string | null;
  deleted_at?: string | null;
  agent_id?: string | null;
  transcription?: string | null;
  transcription_status?: string | null;
  ptt?: boolean;
  media_meta?: Record<string, any> | null;
  reactions?: any[];
  caption?: string | null;
  full_name?: string | null;
  phone_number?: string | null;
}

/**
 * Conversation interface — matches evo.evolution_conversations physical columns.
 * status values are Portuguese per the CHECK constraint: 'aberta' | 'arquivada'.
 * assigned_to is the correct column name (not assigned_agent_id).
 */
export interface Conversation {
  id: string;
  instance_name?: string;
  remote_jid?: string;
  contact_id?: string;
  last_message_at?: string;
  last_message_preview?: string;
  unread_count?: number;
  assigned_to?: string | null;
  status?: 'aberta' | 'arquivada';
  raw?: Record<string, any>;
  created_at: string;
  updated_at: string;
}

// Base services — evolution_messages / evolution_conversations are the physical tables
// in the zapp schema (auto-updatable views over evo.evolution_messages root partition)
const messagesBaseService = createService<Message>('evolution_messages');
const conversationsBaseService = createService<Conversation>('evolution_conversations');

/** messages Repository constant. */
export const messagesRepository = {
  // Messages
  listMessages: (filters?: Partial<Message> & QueryParams) => messagesBaseService.list(filters),

  getMessage: (id: string) => messagesBaseService.get(id),

  createMessage: (data: Partial<Message>) => messagesBaseService.create(data),

  updateMessage: (id: string, updates: Partial<Message>) => messagesBaseService.update(id, updates),

  deleteMessage: (id: string) => messagesBaseService.delete(id),

  // Conversation messages
  async listConversationMessages(conversationId: string, filters?: Partial<QueryParams>) {
    const limit = filters?.pageSize ?? 50;
    const page = filters?.page ?? 1;
    const from = (page - 1) * limit;
    const to = from + limit - 1;
    const { data, error, count } = await supabase
      .from('evolution_messages')
      .select('*', { count: 'exact' })
      .eq('conversation_id', conversationId)
      .order('created_at', { ascending: false })
      .range(from, to);

    return { data: data || [], error, count };
  },

  // Conversations
  listConversations: (filters?: Partial<Conversation> & QueryParams) =>
    conversationsBaseService.list(filters),

  getConversation: (id: string) => conversationsBaseService.get(id),

  createConversation: (data: Partial<Conversation>) => conversationsBaseService.create(data),

  updateConversation: (id: string, updates: Partial<Conversation>) =>
    conversationsBaseService.update(id, updates),

  deleteConversation: (id: string) => conversationsBaseService.delete(id),

  // Unread messages count
  async getUnreadMessagesCount(conversationId: string) {
    const { count, error } = await supabase
      .from('evolution_messages')
      .select('id', { count: 'exact', head: true })
      .eq('conversation_id', conversationId)
      .eq('is_read', false);

    return { count: count || 0, error };
  },

  // Mark as read
  async markMessagesAsRead(conversationId: string, _userId: string) {
    const { error } = await supabase
      .from('evolution_messages')
      .update({ is_read: true })
      .eq('conversation_id', conversationId)
      .eq('is_read', false);

    return { error };
  },
};

/**
 * Schemas de validação Zod para inputs críticos do ZAPP Web.
 *
 * Centraliza validação para:
 * - Mensagens (envio, edição, deleção)
 * - Contatos (criação, edição, merge)
 * - Campanhas (disparo, audience)
 * - Webhooks (payloads Evolution)
 * - Settings (retry config, theme, etc.)
 */
import { z } from 'zod';

// ─────────────────────────────────────────────────────────────────────────────
// Mensagens
// ─────────────────────────────────────────────────────────────────────────────

export const messageContentSchema = z
  .string()
  .min(1, 'Mensagem não pode ser vazia')
  .max(4096, 'Mensagem excede limite de 4096 caracteres')
  .refine((val) => val.trim().length > 0, 'Mensagem não pode ser só espaços');

export const sendMessageSchema = z.object({
  contactId: z.string().uuid('ID de contato inválido'),
  content: messageContentSchema,
  messageType: z.enum(['text', 'image', 'audio', 'video', 'document', 'sticker']).default('text'),
  mediaUrl: z.string().url().optional().nullable(),
  mediaPayload: z.string().optional().nullable(),
});

// ─────────────────────────────────────────────────────────────────────────────
// Contatos
// ─────────────────────────────────────────────────────────────────────────────

const brazilianPhoneRegex = /^(\+?55)?[1-9]{2}9?[0-9]{8}$/;

export const contactPhoneSchema = z
  .string()
  .min(10, 'Telefone muito curto')
  .max(20, 'Telefone muito longo')
  .refine((val) => {
    const cleaned = val.replace(/\D/g, '');
    return cleaned.length >= 10 && cleaned.length <= 13;
  }, 'Telefone inválido');

export const contactEmailSchema = z
  .string()
  .email('E-mail inválido')
  .max(255, 'E-mail muito longo')
  .optional()
  .nullable();

export const createContactSchema = z.object({
  name: z.string().min(1, 'Nome é obrigatório').max(200, 'Nome muito longo'),
  phone: contactPhoneSchema,
  email: contactEmailSchema,
  company: z.string().max(200).optional().nullable(),
  jobTitle: z.string().max(100).optional().nullable(),
  tags: z.array(z.string().uuid()).max(50, 'Máximo 50 tags').optional().default([]),
  notes: z.string().max(2000).optional().nullable(),
});

export const updateContactSchema = createContactSchema.partial().extend({
  version: z.number().int().min(0).optional(),
});

// ─────────────────────────────────────────────────────────────────────────────
// Campanhas
// ─────────────────────────────────────────────────────────────────────────────

export const campaignTargetSchema = z.object({
  contactIds: z.array(z.string().uuid()).min(1, 'Pelo menos um contato').max(10000, 'Máximo 10k contatos'),
  scheduledAt: z.string().datetime().optional().nullable(),
  templateId: z.string().uuid('Template inválido'),
});

// ─────────────────────────────────────────────────────────────────────────────
// Webhooks Evolution
// ─────────────────────────────────────────────────────────────────────────────

const jidRegex = /^[^@\s]+@[^@\s]+$/;

export const evolutionMessageKeySchema = z.object({
  id: z.string().min(1),
  remoteJid: z.string().regex(jidRegex).optional(),
  fromMe: z.boolean().optional().default(false),
  participant: z.string().regex(jidRegex).optional(),
});

export const evolutionUpsertPayloadSchema = z.object({
  event: z.literal('messages.upsert'),
  instance: z.string().min(1),
  data: z.object({
    key: evolutionMessageKeySchema,
    message: z.unknown().optional(),
    messageType: z.string().optional(),
    messageTimestamp: z.union([z.number(), z.string()]).optional(),
    pushName: z.string().optional(),
  }),
});

// ─────────────────────────────────────────────────────────────────────────────
// Settings (Retry Config)
// ─────────────────────────────────────────────────────────────────────────────

export const retryConfigSchema = z
  .object({
    maxRetries: z.number().int().min(1).max(10),
    baseBackoffMs: z.number().int().min(100).max(10_000),
    maxBackoffMs: z.number().int().min(1000).max(60_000),
    timeoutMs: z.number().int().min(5_000).max(120_000),
  })
  .refine((c) => c.maxBackoffMs >= c.baseBackoffMs, {
    message: 'maxBackoffMs deve ser >= baseBackoffMs',
    path: ['maxBackoffMs'],
  })
  .refine((c) => c.timeoutMs >= c.baseBackoffMs, {
    message: 'timeoutMs deve ser >= baseBackoffMs',
    path: ['timeoutMs'],
  });

// ─────────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────────

export type SendMessageInput = z.infer<typeof sendMessageSchema>;
export type CreateContactInput = z.infer<typeof createContactSchema>;
export type UpdateContactInput = z.infer<typeof updateContactSchema>;
export type CampaignTargetInput = z.infer<typeof campaignTargetSchema>;
export type RetryConfigInput = z.infer<typeof retryConfigSchema>;

/**
 * Valida um input e retorna o resultado tipado ou lança erro com mensagem clara.
 */
export function validateInput<T>(schema: z.ZodType<T>, input: unknown): T {
  const result = schema.safeParse(input);
  if (!result.success) {
    const issues = result.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`).join('; ');
    throw new Error(`Validação falhou: ${issues}`);
  }
  return result.data;
}

/**
 * Valida um input e retorna { ok, data, error } sem throw.
 */
export function safeValidateInput<T>(
  schema: z.ZodType<T>,
  input: unknown
): { ok: true; data: T } | { ok: false; error: string } {
  const result = schema.safeParse(input);
  if (!result.success) {
    const error = result.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`).join('; ');
    return { ok: false, error };
  }
  return { ok: true, data: result.data };
}
